from typing import *
from collections import *
from math import *

def diffWaysToCompute(expression):
    if expression.isdigit():
        return [int(expression)]
    res = []
    for i in range(len(expression)):
        if expression[i] in '+-*':
            left = diffWaysToCompute(expression[:i])
            right = diffWaysToCompute(expression[i + 1:])
            for l in left:
                for r in right:
                    if expression[i] == '+':
                        res.append(l + r)
                    elif expression[i] == '-':
                        res.append(l - r)
                    else:
                        res.append(l * r)
    return res
class Solution(object):

    def diffWaysToCompute(self, expression):
        result = []

        def helper(s, memo):
            result = []
            if s in memo:
                return memo[s]
            if s.isdigit():
                return [int(s)]
            symbols = ['+', '-', '*']
            for i in range(len(s)):
                cur = s[i]
                if cur in symbols:
                    left, right = (helper(s[:i], memo), helper(s[i + 1:], memo))
                    for l in left:
                        for r in right:
                            if s[i] == '+':
                                result.append(l + r)
                            elif s[i] == '-':
                                result.append(l - r)
                            else:
                                result.append(l * r)
            memo[s] = result
            return result
        ans = helper(expression, {})
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert diffWaysToCompute('2-1-1') == solution_instance.diffWaysToCompute('2-1-1')
def test_edge_case():
    solution_instance = Solution()
    assert diffWaysToCompute('2*3-4*5') == solution_instance.diffWaysToCompute('2*3-4*5')
def test_difficult_case():
    solution_instance = Solution()
    assert diffWaysToCompute('3+5*2') == solution_instance.diffWaysToCompute('3+5*2')

