def k_radius_average(nums, k):
    avgs = []
    for i in range(len(nums)):
        total = 0
        count = 0
        for j in range(i-k, i+k+1):
            if j < 0 or j >= len(nums):
                total += -1
            else:
                total += nums[j]
                count += 1
        avgs.append(total // count)
    return avgs

