from math import *

def k_radius_average(nums, k):
    avgs = []
    for i in range(len(nums)):
        total = 0
        count = 0
        for j in range(i - k, i + k + 1):
            if j < 0 or j >= len(nums):
                total += -1
            else:
                total += nums[j]
                count += 1
        avgs.append(total // count)
    return avgs
class Solution:

    def getAverages(self, nums: List[int], k: int) -> List[int]:
        k = 2 * k + 1
        res = [-1] * len(nums)
        l, curr = (0, 0)
        for r, num in enumerate(nums):
            curr += num
            if r - l + 1 > k:
                curr -= nums[l]
                l += 1
            if r - l + 1 == k:
                ind = (l + r) // 2
                res[ind] = curr // k
        return res
def test_simple_case():
    solution_instance = Solution()
    assert k_radius_average([1, 3, 4, 1, 2, 3], 2) == solution_instance.getAverages([1, 3, 4, 1, 2, 3], 2)
def test_edge_case():
    solution_instance = Solution()
    assert k_radius_average([100000], 0) == solution_instance.getAverages([100000], 0)
def test_difficult_case():
    solution_instance = Solution()
    assert k_radius_average([8], 3) == solution_instance.getAverages([8], 3)

