def longest_well_performing_interval(hours):
    cum_sum = 0
    d = {}
    res = 0
    for i, hour in enumerate(hours):
        cum_sum += 1 if hour > 8 else -1
        if cum_sum > 0:
            res = i + 1
        else:
            d.setdefault(cum_sum, i)
            if cum_sum - 1 in d:
                res = max(res, i - d[cum_sum - 1])
    return res

