from typing import *
from collections import *
from math import *

def longest_well_performing_interval(hours):
    cum_sum = 0
    d = {}
    res = 0
    for i, hour in enumerate(hours):
        cum_sum += 1 if hour > 8 else -1
        if cum_sum > 0:
            res = i + 1
        else:
            d.setdefault(cum_sum, i)
            if cum_sum - 1 in d:
                res = max(res, i - d[cum_sum - 1])
    return res
class Solution:

    def longestWPI(self, hours: List[int]) -> int:
        n = len(hours)
        ans = 0
        prefix_sum = [0] * n
        d = {}
        for i in range(n):
            prefix_sum[i] = 1 if hours[i] > 8 else -1
            prefix_sum[i] += prefix_sum[i - 1]
            if prefix_sum[i] > 0:
                ans = i + 1
            elif prefix_sum[i] - 1 in d:
                j = d[prefix_sum[i] - 1]
                if i - j > ans:
                    ans = i - j
            if prefix_sum[i] not in d:
                d[prefix_sum[i]] = i
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert longest_well_performing_interval([9, 6, 6, 8]) == solution_instance.longestWPI([9, 6, 6, 8])
def test_edge_case():
    solution_instance = Solution()
    assert longest_well_performing_interval([6, 6, 6, 8]) == solution_instance.longestWPI([6, 6, 6, 8])
def test_difficult_case():
    solution_instance = Solution()
    assert longest_well_performing_interval([9, 6, 7, 9, 5, 4, 8, 6, 4]) == solution_instance.longestWPI([9, 6, 7, 9, 5, 4, 8, 6, 4])

