from typing import *
from collections import *
from math import *

def getStrongest(arr, k):
    arr.sort()
    median = arr[(len(arr) - 1) // 2]
    arr.sort(key=lambda x: (abs(x - median), x), reverse=True)
    return arr[:k]
class Solution:

    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        n = len(arr)
        if n == 1:
            return arr[:k]
        elif n == k:
            return arr
        arr.sort()
        m = arr[(n - 1) // 2]
        res = []
        i, j = (0, n - 1)
        while i < j:
            if abs(arr[i] - m) > abs(arr[j] - m):
                res.append(arr[i])
                i += 1
            elif abs(arr[i] - m) < abs(arr[j] - m):
                res.append(arr[j])
                j -= 1
            elif arr[i] > arr[j]:
                res.append(arr[i])
                i += 1
            elif arr[i] < arr[j]:
                res.append(arr[j])
                j -= 1
            else:
                res.append(arr[i])
                i += 1
            if len(res) == k:
                return res
def test_simple_case():
    solution_instance = Solution()
    assert getStrongest([1, 2, 3, 4, 5], 2) == solution_instance.getStrongest([1, 2, 3, 4, 5], 2)
def test_edge_case():
    solution_instance = Solution()
    assert getStrongest([4, 5, 9, 3, 1], 3) == solution_instance.getStrongest([4, 5, 9, 3, 1], 3)
def test_difficult_case():
    solution_instance = Solution()
    assert getStrongest([-7, -5, -3, -1, 1], 4) == solution_instance.getStrongest([-7, -5, -3, -1, 1], 4)

