from typing import *
from collections import *
from math import *

def findKthNumber(m: int, n: int, k: int) -> int:
    left, right = (1, m * n)
    while left < right:
        mid = (left + right) // 2
        count = 0
        for i in range(1, m + 1):
            count += min(mid // i, n)
        if count >= k:
            right = mid
        else:
            left = mid + 1
    return left
class Solution:

    def findKthNumber(self, m: int, n: int, k: int) -> int:
        if k == 1:
            return 1
        if k == m * n:
            return m * n
        if n >= m:
            m, n = (n, m)
        left = 1
        right = m * n
        while right - left > 1:
            mid = (left + right) // 2
            mid_rank = 0
            num_cols = (mid - 1) // m
            residual = mid - num_cols * m
            mid_rank += num_cols * m
            flag = 0
            for i in range(num_cols + 1, n + 1):
                if i == mid:
                    mid_rank += 1
                    break
                else:
                    mid_rank += mid // i
                    if mid % i == 0:
                        flag = 1
            if flag == 1:
                if mid_rank == k:
                    return mid
                elif mid_rank > k:
                    right = mid
                else:
                    left = mid
            elif mid_rank >= k:
                right = mid
            else:
                left = mid
        return right
def test_middle_value():
    solution_instance = Solution()
    assert findKthNumber(3, 3, 5) == solution_instance.findKthNumber(3, 3, 5)
def test_edge_value():
    solution_instance = Solution()
    assert findKthNumber(2, 3, 6) == solution_instance.findKthNumber(2, 3, 6)
def test_bigger_range():
    solution_instance = Solution()
    assert findKthNumber(3, 4, 4) == solution_instance.findKthNumber(3, 4, 4)

