def carFleet(target: int, position: List[int], speed: List[int]) -> int:
    cars = sorted(zip(position, speed))
    time = [(target - p) / s for p, s in cars]
    fleet = 0
    while len(time) > 1:
        lead = time.pop()
        if lead < time[-1]:
            fleet += 1
        else:
            time[-1] = lead
    return fleet + bool(time)

