def min_moves(seats, students):
    seat_to_student = {}
    for i, seat in enumerate(seats):
        if seat not in seat_to_student:
            seat_to_student[seat] = []
        seat_to_student[seat].append(students[i])
    sorted_students = sorted(students)
    sorted_seats = sorted(seats)
    num_moves = 0
    for i in range(len(sorted_students)):
        student_pos = students.index(sorted_students[i])
        seat_pos = seats.index(sorted_seats[i])
        if student_pos != seat_pos:
            num_moves += 1
            students[student_pos] = sorted_students[seat_pos]
            seats[seat_pos] = sorted_seats[i]
    return num_moves

