def min_moves(seats, students):
    seat_to_student = {}
    for i, seat in enumerate(seats):
        if seat not in seat_to_student:
            seat_to_student[seat] = []
        seat_to_student[seat].append(students[i])
    sorted_students = sorted(students)
    sorted_seats = sorted(seats)
    num_moves = 0
    for i in range(len(sorted_students)):
        student_pos = students.index(sorted_students[i])
        seat_pos = seats.index(sorted_seats[i])
        if student_pos != seat_pos:
            num_moves += 1
            students[student_pos] = sorted_students[seat_pos]
            seats[seat_pos] = sorted_seats[i]
    return num_moves
class Solution:

    def minMovesToSeat(self, seats: List[int], students: List[int]) -> int:
        total_moves = 0
        sorted_seats = sorted(seats)
        sorted_students = sorted(students)
        diff_1 = []
        for i in range(len(seats)):
            diff = abs(sorted_seats[i] - sorted_students[i])
            diff_1.append(diff)
        for i in diff_1:
            total_moves += i
        return total_moves
def test_simple_case():
    sol_instance = Solution()
    assert min_moves([1, 2, 3], [3, 2, 1]) == sol_instance.minMovesToSeat([1, 2, 3], [3, 2, 1])
def test_edge_case():
    sol_instance = Solution()
    assert min_moves([2, 2, 6], [1, 3, 2]) == sol_instance.minMovesToSeat([2, 2, 6], [1, 3, 2])
def test_difficult_case():
    sol_instance = Solution()
    assert min_moves([4, 1, 5, 9], [1, 3, 2, 8]) == sol_instance.minMovesToSeat([4, 1, 5, 9], [1, 3, 2, 8])

