def countWays(startPos: int, endPos: int, k: int) -> int:
    MOD = 1000000007
    dp = [[0 for _ in range(k+1)] for _ in range(2*(endPos-startPos)+1)]
    dp[startPos-endPos+k][k] = 1
    for i in range(k-1,-1,-1):
        for j in range(2*(endPos-startPos)+1):
            if j == 0:
                dp[j][i] = dp[j+1][i+1] % MOD
            elif j == 2*(endPos-startPos):
                dp[j][i] = dp[j-1][i+1] % MOD
            else:
                dp[j][i] = (dp[j-1][i+1] + dp[j+1][i+1]) % MOD
    return dp[startPos-endPos+k][0] % MOD

