def countWays(startPos: int, endPos: int, k: int) -> int:
    MOD = 1000000007
    dp = [[0 for _ in range(k + 1)] for _ in range(2 * (endPos - startPos) + 1)]
    dp[startPos - endPos + k][k] = 1
    for i in range(k - 1, -1, -1):
        for j in range(2 * (endPos - startPos) + 1):
            if j == 0:
                dp[j][i] = dp[j + 1][i + 1] % MOD
            elif j == 2 * (endPos - startPos):
                dp[j][i] = dp[j - 1][i + 1] % MOD
            else:
                dp[j][i] = (dp[j - 1][i + 1] + dp[j + 1][i + 1]) % MOD
    return dp[startPos - endPos + k][0] % MOD
class Solution:
    MOD = 1000000007

    def top_down(self, step: int, dist: int) -> int:
        if dist >= step:
            return int(step == dist)
        if self.memo[step][dist] == 0:
            self.memo[step][dist] = 1 + self.top_down(step - 1, abs(dist - 1)) + self.top_down(step - 1, dist + 1)
            self.memo[step][dist] = self.memo[step][dist] % Solution.MOD
        return self.memo[step][dist] - 1

    def bottom_up(self, steps: int, dist: int) -> int:
        prev, curr = (None, [])
        for k in range(steps + 1):
            for d in range(k + 1):
                if d == k:
                    curr.append(1)
                elif d == 0:
                    num_ways = 2 * prev[1] if k > 1 else 0
                    curr.append(num_ways % Solution.MOD)
                elif d <= k:
                    num_ways = prev[d - 1]
                    num_ways += prev[d + 1] if d + 1 < len(prev) else 0
                    curr.append(num_ways % Solution.MOD)
            prev = curr
            curr = []
        res = prev[dist] if dist <= k else 0
        return res

    def numberOfWays(self, startPos: int, endPos: int, k: int, is_top_down: bool=False) -> int:
        if is_top_down:
            self.memo = [[0] * 1001 for _ in range(1001)]
            res = self.top_down(k, abs(endPos - startPos))
        else:
            res = self.bottom_up(k, abs(endPos - startPos))
        return res
def test_simple_case():
    solution_instance = Solution()
    assert countWays(1, 2, 3) == solution_instance.numberOfWays(1, 2, 3, False)
def test_edge_case():
    solution_instance = Solution()
    assert countWays(0, 6, 3) == solution_instance.numberOfWays(0, 6, 3, False)
def test_difficult_case():
    solution_instance = Solution()
    assert countWays(3, 7, 10) == solution_instance.numberOfWays(3, 7, 10, False)

