def countPrimeSetBits(left, right):
    count = 0
    for num in range(left, right+1):
        bit_count = bin(num).count('1')
        if bit_count == 2: # 2 is the smallest prime
            count += 1
        elif bit_count > 2:
            is_prime = True
            for i in range(2, bit_count):
                if bit_count % i == 0:
                    is_prime = False
                    break
            if is_prime:
                count += 1
    return count

