def apply_operation(s, b, num_operations):
    for i in range(num_operations):
        new_s = ""
        for j in range(len(s)):
            if j % 2 == 1:
                new_digit = (int(s[j]) + b) % 10
                new_s += str(new_digit)
            else:
                new_s += s[j]
        s = new_s[b:] + new_s[:b]
    return s

def find_smallest_string(s, b, num_operations):
    min_s = s
    for i in range(num_operations):
        s_add = apply_operation(s, b, i+1)
        s_rotate = apply_operation(s[::-1], b, i+1)[::-1]
        min_s = min(min_s, s_add, s_rotate)
    return min_s

