    assert smallestDistancePair([1, 1, 1], 2) == solution_instance.smallestDistancePair([1, 1, 1], 2)
def test_difficult_case():
    solution_instance = Solution()
    assert smallestDistancePair([1, 6, 1], 3) == solution_instance.smallestDistancePair([1, 6, 1], 3)

