class Solution:

    def stoneGameVI(self, alice: List[int], bob: List[int]) -> int:
        n = len(alice)
        arr = [alice[i] + bob[i] for i in range(n)]
        s = sum(bob)
        res = 0
        k = (n + 1) // 2
        arr.sort(reverse=True)
        for i in range(0, n, 2):
            res += arr[i]
        if res > s:
            return 1
        elif res == s:
            return 0
        else:
            return -1
