def minOperations(nums1: List[int], nums2: List[int]) -> int:
    sum1 = sum(nums1)
    sum2 = sum(nums2)
    if sum1 == sum2:
        return 0
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
        sum1, sum2 = sum2, sum1
    diff = abs(sum1 - sum2)
    if diff > (len(nums2) - len(nums1)) * 6:
        return -1
    res = 0
    freq = [0] * 7
    for val in nums1 + nums2:
        freq[val] += 1
    for i in range(5, 0, -1):
        while diff > 0 and freq[i]:
            diff -= i - 1
            freq[i] -= 1
            res += 1
    return res + (diff + 5) // 6

