    return result
class Solution:

    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:

        class Trie:

            def __init__(self):
                self.root = {'leaf': False, 'child': {}}

            def add(self, word):
                cur = self.root
                for i, c in enumerate(word):
                    if not c in cur['child']:
                        if i < len(word) - 1:
                            cur['child'][c] = {'leaf': False, 'child': {}}
                            cur = cur['child'][c]
                        else:
                            cur['child'][c] = {'leaf': True, 'child': {}}
                            cur = cur['child'][c]
                    elif i < len(word) - 1:
                        cur = cur['child'][c]
                    else:
                        cur = cur['child'][c]
                        cur['leaf'] = True

            def query(self, word):
                cur = self.root
                res = []
                for i, c in enumerate(word):
                    if not c in cur['child']:
                        break
                    else:
                        cur = cur['child'][c]
                        if cur['leaf'] is True:
                            res.append(i)
                return res

            def print_node(self, cur, depth):
                l = 'leaf:' + str(cur['leaf']) + '\n'
                for c in cur['child']:
                    l += '  ' * depth + c + ' ' + self.print_node(cur['child'][c], depth + 1)
                return l

            def __repr__(self):
                return self.print_node(self.root, 0)
        trie = Trie()
        for w in words:
            trie.add(w)

        def judge(w, depth):
            if len(w) == 0:
                return depth > 1
            leafs = trie.query(w)
            if len(leafs) == 0:
                return False
            else:
                for i in leafs:
                    if judge(w[i + 1:], depth + 1):
                        return True
                return False
        res = []
        for w in words:
            if judge(w, 0):
                res.append(w)
        return res
def test_simple_case():
    words = ['cat', 'cats', 'catsdogcats', 'dog', 'dogcatsdog', 'dogcatscat']
    solution_instance = Solution()
    assert concatenatedWords(words) == solution_instance.findAllConcatenatedWordsInADict(words)
def test_edge_case():
    words = ['cat', 'dog', 'catdog']
    solution_instance = Solution()
    assert concatenatedWords(words) == solution_instance.findAllConcatenatedWordsInADict(words)
def test_difficult_case():
    words = ['hello', 'leetcode', 'hellohello']
    solution_instance = Solution()
    assert concatenatedWords(words) == solution_instance.findAllConcatenatedWordsInADict(words)

