class Solution:

    def bitwiseComplement(self, n: int) -> int:
        get_binary = lambda n: format(n, 'b')
        input_b = get_binary(n)
        output_b = ''
        for i in input_b:
            if i == '1':
                output_b += '0'
            else:
                output_b += '1'
        get_int = lambda n: int(n, 2)
        result = get_int(output_b)
        return result
