def escape_possible(ghosts, xtarget, ytarget):

    def manhattan_distance(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    def is_safe(x, y):
        for g in ghosts:
            if manhattan_distance(x, y, g[0], g[1]) <= 1:
                return False
        return True
    queue = [(0, 0)]
    seen = {(0, 0)}
    while queue:
        x, y = queue.pop(0)
        if x == xtarget and y == ytarget:
            return True
        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1), (0, 0)]:
            nx, ny = (x + dx, y + dy)
            if (nx, ny) not in seen and is_safe(nx, ny):
                queue.append((nx, ny))
                seen.add((nx, ny))
    return False
class Solution:

    def escapeGhosts(self, ghosts: List[List[int]], target: List[int]) -> bool:
        t_x, t_y = target
        m_x, m_y = (abs(t_x), abs(t_y))
        for x, y in ghosts:
            manhattan = abs(t_x - x) + abs(t_y - y)
            if manhattan <= m_x + m_y:
                return False
        return True
def test_simple_case():
    s = Solution()
    assert escape_possible([[1, 0], [0, 3]], 4, -2) == s.escapeGhosts([[1, 0], [0, 3]], [4, -2])
def test_edge_case():
    s = Solution()
    assert escape_possible([[1, 2], [2, 2]], 5, -3) == s.escapeGhosts([[1, 2], [2, 2]], [5, -3])
def test_difficult_case():
    s = Solution()
    assert escape_possible([[2, 2], [1, 1]], -8, 8) == s.escapeGhosts([[2, 2], [1, 1]], [-8, 8])

