from typing import *
from collections import *
from math import *

def frequencySort(nums):
    freq = Counter(nums)
    return sorted(nums, key=lambda x: (freq[x], -x))
class Solution:

    def frequencySort(self, nums: List[int]) -> List[int]:
        dict2 = self.dict1(nums)
        keys = list(self.dict1(nums).keys())
        revers = {}
        for i in range(0, len(keys)):
            if dict2[keys[i]] not in revers:
                revers[dict2[keys[i]]] = [keys[i]]
            else:
                revers[dict2[keys[i]]].extend([keys[i]])
        serve = list(sorted(list(revers.keys()), reverse=False))
        temper = []
        for i in range(0, len(serve)):
            something = revers[serve[i]]
            if len(something) == 1:
                temper.extend(something * serve[i])
            else:
                temper.extend(sorted(something * serve[i], reverse=True))
        return temper

    def dict1(self, nums):
        new = {}
        for i in range(0, len(nums)):
            if nums[i] not in new:
                new[nums[i]] = 1
            else:
                new[nums[i]] += 1
        return new
def test_simple_case():
    solution_instance = Solution()
    assert frequencySort([1, 1, 2, 2, 2, 3]) == solution_instance.frequencySort([1, 1, 2, 2, 2, 3])
def test_edge_case():
    solution_instance = Solution()
    assert frequencySort([2, 3, 1, 3, 2]) == solution_instance.frequencySort([2, 3, 1, 3, 2])
def test_difficult_case():
    solution_instance = Solution()
    assert frequencySort([-1, 1, -6, 4, 5, 6, 1, 4, 1]) == solution_instance.frequencySort([-1, 1, -6, 4, 5, 6, 1, 4, 1])

