def steps_to_water(plants, capacity):
    steps = 0
    current_water = 0
    for i in range(len(plants)):
        if plants[i] > capacity:
            return -1
        if current_water < plants[i]:
            steps += 2*(i) #Move to the plant and back to the river
            current_water = capacity
        current_water -= plants[i]
    return steps

