def steps_to_water(plants, capacity):
    steps = 0
    current_water = 0
    for i in range(len(plants)):
        if plants[i] > capacity:
            return -1
        if current_water < plants[i]:
            steps += 2 * i
            current_water = capacity
        current_water -= plants[i]
    return steps
class Solution:

    def wateringPlants(self, plants: List[int], capacity: int) -> int:
        steps = 0
        curCapacity = capacity
        for i in range(len(plants)):
            if curCapacity >= plants[i]:
                steps += 1
                curCapacity -= plants[i]
            else:
                curCapacity = capacity
                curCapacity -= plants[i]
                steps += 2 * i + 1
        return steps
def test_simple_case():
    solution_instance = Solution()
    assert steps_to_water([1, 2, 3], 4) == solution_instance.wateringPlants([1, 2, 3], 4)
def test_edge_case():
    solution_instance = Solution()
    assert steps_to_water([0, 0, 0], 5) == solution_instance.wateringPlants([0, 0, 0], 5)
def test_difficult_case():
    solution_instance = Solution()
    assert steps_to_water([2, 4, 2], 5) == solution_instance.wateringPlants([2, 4, 2], 5)

