def suggestedProducts(products: List[str], searchWord: str) -> List[List[str]]:
    products.sort()
    res = []
    prefix = ""
    for c in searchWord:
        prefix += c
        match = []
        for product in products:
            if product.startswith(prefix):
                match.append(product)
            if len(match) == 3:
                break
        res.append(match)
    return res

