class Solution:

    def suggestedProducts(self, products: List[str], searchWord: str) -> List[List[str]]:
        products.sort()
        prefixToProducts = defaultdict(list)
        prefix = ''
        for word in products:
            for character in word:
                prefix += character
                prefixToProducts[prefix].append(word)
            prefix = ''
        results = []
        for character in searchWord:
            prefix += character
            results.append(prefixToProducts[prefix][:3])
        return results
def test_simple_case():
    solution_instance = Solution()
    assert suggestedProducts(['mobile', 'mouse', 'moneypot', 'monitor'], 'mouse') == solution_instance.suggestedProducts(['mobile', 'mouse', 'moneypot', 'monitor'], 'mouse')
def test_difficult_case():
    solution_instance = Solution()
    assert suggestedProducts(['havana'], 'havana') == solution_instance.suggestedProducts(['havana'], 'havana')
def test_edge_case():
    solution_instance = Solution()
    assert suggestedProducts(['havana'], 'havano') == solution_instance.suggestedProducts(['havana'], 'havano')

