def maxSubset(nums):
    max_bitwise = 0
    n = len(nums)
    for i in range(2**n):
        bitwise = 0
        for j in range(n):
            if i & (1 << j):
                bitwise |= nums[j]
        max_bitwise = max(max_bitwise, bitwise)
    return bin(max_bitwise).count('1')

