from typing import *
from collections import *
from math import *

def maxSubset(nums):
    max_bitwise = 0
    n = len(nums)
    for i in range(2 ** n):
        bitwise = 0
        for j in range(n):
            if i & 1 << j:
                bitwise |= nums[j]
        max_bitwise = max(max_bitwise, bitwise)
    return bin(max_bitwise).count('1')
class Solution:

    def countMaxOrSubsets(self, nums: List[int]) -> int:

        def calculate_BWOR(arr):
            if len(arr) == 1:
                return arr[0]
            else:
                n = len(arr)
                res = arr[0]
                for i in range(1, n):
                    res = res | arr[i]
                return res
        ans = []
        n = len(nums)
        maximum = 1

        def helper(i, cur):
            nonlocal nums, ans, maximum, n
            if i == n:
                if not cur:
                    return
                current = calculate_BWOR(cur)
                if current > maximum:
                    maximum = current
                    ans = [cur[:]]
                    return
                elif current == maximum:
                    ans.append(cur[:])
                    return
                else:
                    return
            cur.append(nums[i])
            helper(i + 1, cur)
            cur.pop()
            helper(i + 1, cur)
        helper(0, [])
        return len(ans)
def test_simple_case():
    solution_instance = Solution()
    assert maxSubset([1, 2, 3]) == solution_instance.countMaxOrSubsets([1, 2, 3])
def test_edge_case():
    solution_instance = Solution()
    assert maxSubset([2, 2, 2]) == solution_instance.countMaxOrSubsets([2, 2, 2])
def test_difficult_case():
    solution_instance = Solution()
    assert maxSubset([3, 2, 1, 5]) == solution_instance.countMaxOrSubsets([3, 2, 1, 5])

