from typing import *
from collections import *
from math import *

def get_recipes_to_create(recipes, ingredients, supplies):
    recipes_to_create = []
    for i in range(len(recipes)):
        recipe_ingredients = ingredients[i]
        for ingredient in recipe_ingredients:
            if ingredient not in supplies:
                recipes_to_create.append(recipes[i])
                break
        else:
            supplies.extend(recipe_ingredients)
    return recipes_to_create
class Solution:

    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        s = set()
        for sup in supplies:
            s.add(sup)
        adjList = {}
        newIngreds = []
        for arr in ingredients:
            toKeep = []
            for sup in arr:
                if sup not in s:
                    toKeep.append(sup)
            newIngreds.append(toKeep)
        queue = []
        for r, i in zip(recipes, newIngreds):
            adjList[r] = i
            if i == []:
                queue.append(r)
        res = []
        while queue:
            visitNext = queue.pop()
            res.append(visitNext)
            for node in adjList:
                if visitNext in adjList[node]:
                    adjList[node].remove(visitNext)
                    if adjList[node] == []:
                        queue.append(node)
        return res
def test_simple_case():
    supplies = ['meat']
    recipes = ['burger']
    ingredients = [['meat']]
    sol_instance = Solution()
    assert get_recipes_to_create(recipes, ingredients, supplies[:]) == sol_instance.findAllRecipes(recipes, ingredients, supplies[:])
def test_edge_case():
    supplies = ['meat', 'tomato']
    recipes = ['burger', 'pizza']
    ingredients = [['meat'], ['meat', 'tomato']]
    sol_instance = Solution()
    assert get_recipes_to_create(recipes, ingredients, supplies[:]) == sol_instance.findAllRecipes(recipes, ingredients, supplies[:])
def test_difficult_case():
    supplies = ['meat', 'flour']
    recipes = ['burger', 'pizza', 'bread']
    ingredients = [['meat'], ['meat', 'tomato'], ['flour']]
    sol_instance = Solution()
    assert get_recipes_to_create(recipes, ingredients, supplies[:]) == sol_instance.findAllRecipes(recipes, ingredients, supplies[:])

