def check_strictly_increasing(lst):
    for i in range(1, len(lst)):
        if lst[i] <= lst[i-1]:
            break
    else:
        return True

    for j in range(len(lst)):
        temp = lst[:j] + lst[j+1:]
        for k in range(1, len(temp)):
            if temp[k] <= temp[k-1]:
                break
        else:
            return True

    return False

