def check_strictly_increasing(lst):
    for i in range(1, len(lst)):
        if lst[i] <= lst[i - 1]:
            break
    else:
        return True
    for j in range(len(lst)):
        temp = lst[:j] + lst[j + 1:]
        for k in range(1, len(temp)):
            if temp[k] <= temp[k - 1]:
                break
        else:
            return True
    return False
def almost_increasing_sequence(sequence):
    if len(sequence) < 3:
        return True
    a, b, *sequence = sequence
    skipped = 0
    for c in sequence:
        if a < b < c:
            a, b = (b, c)
            continue
        elif b < c:
            a, b = (b, c)
        elif a < c:
            a, b = (a, c)
        skipped += 1
        if skipped == 2:
            return False
    return a < b
def test_simple_case():
    assert check_strictly_increasing([2, 3, 4]) == almost_increasing_sequence([2, 3, 4])
def test_edge_case():
    assert check_strictly_increasing([2, 3, 1, 4]) == almost_increasing_sequence([2, 3, 1, 4])
def test_difficult_case():
    assert check_strictly_increasing([1, 2, 5, 3, 4]) == almost_increasing_sequence([1, 2, 5, 3, 4])

