from typing import *
from collections import *
from math import *

def findAndReplacePattern(words, pattern):
    res = []
    for word in words:
        if len(word) != len(pattern):
            continue
        mapping = {}
        used = set()
        match = True
        for i in range(len(word)):
            if pattern[i] not in mapping:
                if word[i] in used:
                    match = False
                    break
                else:
                    mapping[pattern[i]] = word[i]
                    used.add(word[i])
            elif mapping[pattern[i]] != word[i]:
                match = False
                break
        if match:
            res.append(word)
    return res
class Solution:

    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:
        ans = []
        for j in words:
            if len(j) == len(pattern):
                if len(set(j)) == len(set(pattern)):
                    pe = {}
                    we = {}
                    h = 0
                    for i in range(1, len(pattern)):
                        if pattern[i] == pattern[i - 1]:
                            if j[i - 1] != j[i]:
                                h += 1
                                break
                        elif pattern[i] != pattern[i - 1]:
                            if j[i - 1] == j[i]:
                                h += 1
                                break
                        if pattern[i] not in pe:
                            pe[pattern[i]] = 1
                            if j[i] in we:
                                h += 1
                                break
                            else:
                                we[j[i]] = 1
                        if pattern[i] in pe:
                            pe[pattern[i]] += 1
                            if j[i] not in we:
                                h += 1
                                break
                            else:
                                we[j[i]] += 1
                    if h == 0 and sorted(list(we.values())) == sorted(list(pe.values())):
                        ans.append(j)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert findAndReplacePattern(['abc', 'deq', 'mee', 'aqq'], 'abb') == solution_instance.findAndReplacePattern(['abc', 'deq', 'mee', 'aqq'], 'abb')
def test_complex_case():
    solution_instance = Solution()
    assert findAndReplacePattern(['a', 'b', 'c', 'ab', 'ac', 'bc', 'abc'], 'abc') == solution_instance.findAndReplacePattern(['a', 'b', 'c', 'ab', 'ac', 'bc', 'abc'], 'abc')
def test_corner_case():
    solution_instance = Solution()
    assert findAndReplacePattern(['z', 'x', 'z'], ['a', 'b', 'c']) == solution_instance.findAndReplacePattern(['z', 'x', 'z'], ['a', 'b', 'c'])

