            continue
        mapping = {}
        used = set()
        match = True
        for i in range(len(word)):
            if pattern[i] not in mapping:
                if word[i] in used:
                    match = False
                    break
                else:
                    mapping[pattern[i]] = word[i]
                    used.add(word[i])
            elif mapping[pattern[i]] != word[i]:
                match = False
                break
        if match:
            res.append(word)
    return res

