from typing import *
from collections import *
from math import *

def license_key_formatting(s, k):
    s = s.upper().replace('-', '')
    dash_count = len(s) // k - (len(s) % k == 0)
    if dash_count <= 0:
        return s
    result = ''
    first_group_len = len(s) % k
    if first_group_len > 0:
        result += s[:first_group_len] + '-'
    for i in range(dash_count):
        result += s[first_group_len + i * k:first_group_len + (i + 1) * k] + '-'
    return result[:-1]
class Solution:

    def licenseKeyFormatting(self, s: str, k: int) -> str:
        uppercase_s = ''
        for char in s:
            if char.isalnum():
                uppercase_s += char.upper()
        len_upper = len(uppercase_s)
        if len_upper <= k:
            return uppercase_s
        if len_upper % k == 0:
            res = [0 for _ in range(len_upper + len_upper // k - 1)]
        else:
            res = [0 for _ in range(len_upper + len_upper // k)]
        section_1st = len_upper % k
        res[:section_1st] = uppercase_s[:section_1st]
        dash_counter = 0
        if section_1st > 0:
            res[section_1st] = '-'
            dash_counter += 1
        i = section_1st + dash_counter
        while i <= len(res):
            res[i:i + k] = uppercase_s[i - dash_counter:i - dash_counter + k]
            if i + k < len(res) - 1:
                res[i + k] = '-'
                dash_counter += 1
            i += k + 1
        return ''.join(res)
def test_simple_case():
    solution_instance = Solution()
    assert license_key_formatting('5F3Z-2e-9-w', 4) == solution_instance.licenseKeyFormatting('5F3Z-2e-9-w', 4)
