class Solution:

    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:
        levels = [[0] * i for i in range(1, query_row + 2)]
        levels[0] = [poured]
        for i in range(len(levels) - 1):
            for j in range(len(levels[i])):
                if levels[i][j] - 1 <= 0:
                    continue
                temp = (levels[i][j] - 1) / 2.0
                levels[i + 1][j] = levels[i + 1][j] + temp
                levels[i + 1][j + 1] = levels[i + 1][j + 1] + temp
        return min(1, levels[query_row][query_glass])
def test_simple_case():
    solution_instance = Solution()
    assert champagneTower(1, 1, 1) == solution_instance.champagneTower(1, 1, 1)
def test_edge_case():
    solution_instance = Solution()
    assert champagneTower(100000009, 99, 49) == solution_instance.champagneTower(100000009, 99, 49)
def test_difficult_case():
    solution_instance = Solution()
    assert champagneTower(25, 6, 1) == solution_instance.champagneTower(25, 6, 1)

