def count_prefix_aligned(n: int, flips: List[int]) -> int:
    prefix_aligned = 0
    ones = 0
    zeros = n
    res = 0

    for i in range(len(flips)):
        index = flips[i]
        if ones <= index-1-zeros:
            res += prefix_aligned + 1
        else:
            res += prefix_aligned
        if index <= ones:
            ones -= 1
        else:
            ones += 1
        zeros = n - ones
        prefix_aligned = (ones == zeros)

    return res

