class Solution:

    def checkWays(self, pairs: List[List[int]]) -> int:
        nodes = set()
        graph = {}
        degree = {}
        for x, y in pairs:
            nodes |= {x, y}
            graph.setdefault(x, set()).add(y)
            graph.setdefault(y, set()).add(x)
            degree[x] = 1 + degree.get(x, 0)
            degree[y] = 1 + degree.get(y, 0)
        if max(degree.values()) < len(nodes) - 1:
            return 0
        for n in nodes:
            if degree[n] < len(nodes) - 1:
                nei = set()
                for nn in graph[n]:
                    if degree[n] >= degree[nn]:
                        nei |= graph[nn]
                if nei - {n} - graph[n]:
                    return 0
        for n in nodes:
            if any((degree[n] == degree[nn] for nn in graph[n])):
                return 2
        return 1
