class Solution:

    def memLeak(self, memory1: int, memory2: int) -> List[int]:
        count = 0
        while memory1 or memory2:
            count += 1
            if memory1 >= memory2:
                if memory1 - count >= 0:
                    memory1 -= count
                else:
                    return [count, memory1, memory2]
            elif memory2 - count >= 0:
                memory2 -= count
            else:
                return [count, memory1, memory2]
        return [1, 0, 0]
def test_simple_case():
    solution_instance = Solution()
    assert faulty_program(8, 11) == solution_instance.memLeak(8, 11)
