def find_hills_and_valleys(nums):
    hills = 0
    valleys = 0
    for i in range(len(nums)):
        hill_neighbor = None
        valley_neighbor = None
        for j in range(i-1, -1, -1):
            if nums[j] < nums[i]:
                hill_neighbor = j
                break
        for j in range(i+1, len(nums)):
            if nums[j] < nums[i]:
                valley_neighbor = j
                break
        if hill_neighbor is not None and valley_neighbor is not None:
            hills += 1
            valleys += 1
        elif hill_neighbor is not None:
            hills += 1
        elif valley_neighbor is not None:
            valleys += 1
    return hills + valleys

