class Solution:

    def reverseVowels(self, s: str) -> str:
        arr = list(s)
        n = len(arr)
        vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
        i = 0
        j = n - 1
        while i < j:
            if arr[i] not in vowels:
                i += 1
            if arr[j] not in vowels:
                j -= 1
            if arr[i] in vowels and arr[j] in vowels:
                arr[i], arr[j] = (arr[j], arr[i])
                i += 1
                j -= 1
        answer = ''
        for i in arr:
            answer += i
        return answer
