def closest_two_integers(num):
    r = ceil(sqrt(num + 2))
    closest_diff = float('inf')
    closest_x, closest_y = (0, 0)
    for x in range(1, r + 1):
        y = (num + x) / x - 1
        if y.is_integer():
            diff = abs(x - y)
            if diff < closest_diff:
                closest_diff = diff
                closest_x, closest_y = (x, int(y))
    if closest_x <= closest_y:
        return (closest_x, closest_y)
    else:
        return (closest_y, closest_x)
class Solution:

    def closestDivisors(self, num: int) -> List[int]:
        if num == 1:
            return [1, 2]
        if num == 2:
            return [2, 2]
        res = [-float('inf'), float('inf')]
        for i in range(1, int(num ** 0.5) + 2):
            a, b = ((num + 1) // i, (num + 2) // i)
            diff_r, diff_s_r = (abs(res[0] - res[1]), min(abs(res[0] * res[1] - num - 1), abs(res[0] * res[1] - num - 2)))
            diff_a, diff_s_a = (abs(a - i), abs(a * i - num - 1))
            diff_b, diff_s_b = (abs(b - i), abs(b * i - num - 2))
            if diff_s_a < diff_s_r or (diff_s_a == diff_s_r and diff_a < diff_r):
                res = [i, a]
            if diff_s_b < diff_s_r or (diff_s_b == diff_s_r and diff_b < diff_r):
                res = [i, b]
        return res
def test_simple_case():
    solution_instance = Solution()
    assert closest_two_integers(11) == solution_instance.closestDivisors(11)
def test_edge_case():
    solution_instance = Solution()
