class Solution:

    def minimizeArrayValue(self, nums: List[int]) -> int:

        def isPossible(arr, mid):
            n = len(arr)
            if arr[0] > mid:
                return False
            p = arr[0]
            for i in range(1, n):
                d = mid - p
                p = arr[i] - d
                if p > mid:
                    return False
            return True
        l, h = (1, max(nums))
        ans = h
        while l <= h:
            mid = (l + h) // 2
            if isPossible(nums, mid):
                ans = min(mid, ans)
                h = mid - 1
            else:
                l = mid + 1
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert min_value([3, 7, 1, 6]) == solution_instance.minimizeArrayValue([3, 7, 1, 6])
def test_edge_case():
    solution_instance = Solution()
    assert min_value([10, 1]) == solution_instance.minimizeArrayValue([10, 1])
def test_difficult_case():
    solution_instance = Solution()
    assert min_value([8, 5, 12, 11]) == solution_instance.minimizeArrayValue([8, 5, 12, 11])

