class Solution:

    def isEscapePossible(self, blocked: List[List[int]], source: List[int], target: List[int]) -> bool:
        blocked = set(map(tuple, blocked))

        def fn(x, y, tx, ty):
            """Return True if (x, y) is not looped from (tx, ty)."""
            seen = {(x, y)}
            queue = [(x, y)]
            level = 0
            while queue:
                level += 1
                if level > 200:
                    return True
                newq = []
                for x, y in queue:
                    if (x, y) == (tx, ty):
                        return True
                    for xx, yy in ((x - 1, y), (x, y - 1), (x, y + 1), (x + 1, y)):
                        if 0 <= xx < 1000000.0 and 0 <= yy < 1000000.0 and ((xx, yy) not in blocked) and ((xx, yy) not in seen):
                            seen.add((xx, yy))
                            newq.append((xx, yy))
                queue = newq
            return False
        return fn(*source, *target) and fn(*target, *source)
def test_within_bounds():
    solution_instance = Solution()
    assert is_reachable([0, 0], [3, 3], []) == solution_instance.isEscapePossible([], [0, 0], [3, 3])
def test_blocked_path():
    solution_instance = Solution()
    assert is_reachable([0, 0], [3, 3], [[1, 1]]) == solution_instance.isEscapePossible([[1, 1]], [0, 0], [3, 3])
def test_large_distance():
    solution_instance = Solution()
    assert is_reachable([10, 10], [1000, 1000], []) == solution_instance.isEscapePossible([], [10, 10], [1000, 1000])

