from typing import *
from collections import *
from math import *

def rotatedDigits(n: int) -> int:
    count = 0
    for i in range(1, n + 1):
        s = str(i)
        if '3' in s or '4' in s or '7' in s:
            continue
        if '2' in s or '5' in s or '6' in s or ('9' in s):
            count += 1
    return count
class Solution:

    def rotatedDigits(self, N: int) -> int:
        smallSet = {0, 1, 8}
        bigSet = {2, 5, 6, 9}
        smallNum = [0, 0, 1, 1, 1, 2, 3, 3, 3, 4][N % 10]
        bigNum = [1, 2, 3, 3, 3, 4, 5, 5, 6, 7][N % 10]
        N = N // 10
        smInc, bgInc = (4, 7)
        while N:
            x = N % 10
            N = N // 10
            sm, bg = (0, 0)
            for i in range(x):
                if i in smallSet:
                    sm += smInc
                    bg += bgInc
                elif i in bigSet:
                    sm += bgInc
                    bg += bgInc
            if x in smallSet:
                smallNum += sm
                bigNum += bg
            elif x in bigSet:
                smallNum = bigNum + sm
                bigNum += bg
            else:
                smallNum = sm
                bigNum = bg
            smInc, bgInc = (4 * bgInc + 3 * smInc, bgInc * 7)
        return smallNum
def test_simple_case():
    solution_instance = Solution()
    assert rotatedDigits(10) == solution_instance.rotatedDigits(10)
def test_edge_case():
    solution_instance = Solution()
    assert rotatedDigits(3) == solution_instance.rotatedDigits(3)
def test_difficult_case():
    solution_instance = Solution()
    assert rotatedDigits(857) == solution_instance.rotatedDigits(857)

