class Solution:

    def brokenCalc(self, startValue: int, target: int) -> int:
        if startValue >= target:
            return startValue - target
        queue = [(target, 0)]
        visited = {}
        while queue:
            val, count = queue.pop(0)
            if val + 1 == startValue or (val // 2 == startValue and val % 2 == 0):
                return count + 1
            if val + 1 not in visited:
                visited[val + 1] = True
                queue.append((val + 1, count + 1))
            if val % 2 == 0 and val // 2 not in visited:
                if val // 2 < startValue:
                    return count + startValue - val // 2 + 1
                else:
                    visited[val // 2] = True
                    queue.append((val // 2, count + 1))
def test_simple_case():
    solution_instance = Solution()
    assert brokenCalc(2, 3) == solution_instance.brokenCalc(2, 3)
