def nthUglyNumber(n: int, a: int, b: int, c: int) -> int:
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    def lcm(x, y):
        return x * y // gcd(x, y)
    def count(x):
        return x // a + x // b + x // c - x // ab - x // ac - x // bc + x // abc
    ab, ac, bc = lcm(a, b), lcm(a, c), lcm(b, c)
    abc = lcm(a, bc)
    left, right = 1, 2 * 10**9
    while left < right:
        mid = (left + right) // 2
        if count(mid) >= n:
            right = mid
        else:
            left = mid + 1
    return left


print(nthUglyNumber(3,2,3,5)) # should return 4
print(nthUglyNumber(4,2,3,4)) # should return 6

