    assert nthUglyNumber(1, 2, 3, 5) == solution_instance.nthUglyNumber(1, 2, 3, 5)
def test_difficult_case():
    solution_instance = Solution()
    assert nthUglyNumber(10, 2, 3, 5) == solution_instance.nthUglyNumber(10, 2, 3, 5)

