class Solution:

    def isPrefixString(self, s: str, words: List[str]) -> bool:
        start = 0
        s_length = len(s)
        for word in words:
            if start >= s_length:
                return True
            if s[start:start + len(word)] != word:
                return False
            start += len(word)
        if start >= s_length:
            return True
        else:
            return False
