    def is_palindrome(sub: str) -> bool:
        return sub == sub[::-1]

    def dfs(start: int, groups: int) -> int:
        if start == len(s):
            return 0 if groups == k else float('inf')
        if (start, groups) in memo:
            return memo[(start, groups)]
        if groups == k:
