class Solution:

    def palindromePartition(self, s: str, k: int) -> int:

        def Cost(s):
            i, j, c = (0, len(s) - 1, 0)
            while i < j:
                if s[i] != s[j]:
                    c += 1
                j -= 1
                i += 1
            return c
        dp = {}

        def A(s, k):
            if (s, k) in dp:
                return dp[s, k]
            if k == 1:
                return Cost(s)
            f = float('inf')
            for x in range(1, len(s) + 1):
                if len(s[:x]) and len(s[x:]):
                    f = min(f, Cost(s[:x]) + A(s[x:], k - 1))
            dp[s, k] = f
            return dp[s, k]
        return A(s, k)
def test_simple_case():
    solution_instance = Solution()
    assert min_changes('abc', 2) == solution_instance.palindromePartition('abc', 2)
def test_edge_case():
    solution_instance = Solution()
    assert min_changes('aabbc', 3) == solution_instance.palindromePartition('aabbc', 3)
def test_difficult_case():
    solution_instance = Solution()
    assert min_changes('ddkjhb', 1) == solution_instance.palindromePartition('ddkjhb', 1)

