class Solution:

    def maxWidthRamp(self, nums: List[int]) -> int:
        if not nums:
            return 0
        max_vals = self.create_max_vals(nums)
        max_width = 0
        i = 0
        while i + max_width < len(nums):
            j = i + max_width
            while j < len(nums) and nums[i] <= max_vals[j]:
                j += 1
            max_width = max(max_width, j - i - 1)
            i += 1
        return max_width

    def create_max_vals(self, nums: List[int]) -> List[int]:
        max_val = 0
        max_vals = [0] * len(nums)
        for i in range(len(nums) - 1, -1, -1):
            max_val = max(max_val, nums[i])
            max_vals[i] = max_val
        return max_vals
def test_simple_case():
    solution_instance = Solution()
    nums = [6, 0, 8, 2, 1, 5]
    assert maximum_width_ramp(nums) == solution_instance.maxWidthRamp(nums)
