class Solution:

    def getNoZeroIntegers(self, n: int) -> List[int]:
        if n % 2 == 0:
            for i in range(n // 2 + 1):
                if str(n // 2 - i).count('0') == 0 and str(n // 2 + i).count('0') == 0:
                    return [n // 2 - i, n // 2 + i]
        else:
            for i in range(n // 2 + 1):
                if str(n // 2 - i).count('0') == 0 and str(n // 2 + 1 + i).count('0') == 0:
                    return [n // 2 - i, n // 2 + i + 1]
