def min_cost(n, cuts):
    cuts = [0] + sorted(cuts) + [n]
    m = len(cuts)
    dp = [[0] * m for _ in range(m)]
    for l in range(2, m):
        for i in range(m - l):
            j = i + l
            dp[i][j] = float('inf')
            for k in range(i + 1, j):
