class Solution:

    def minCost(self, n: int, cuts: List[int]) -> int:

        def makeCut(start, end, t=dict()):
            key = (start, end)
            if key not in t:
                currMin = float('inf')
                for cut in cuts:
                    if start < cut < end:
                        cost = end - start
                        currMin = min(currMin, cost + makeCut(start, cut, t) + makeCut(cut, end, t))
                t[key] = currMin if currMin != float('inf') else 0
            return t[key]
        return makeCut(0, n)
def test_simple_case():
    sol_instance = Solution()
    assert min_cost(7, [1, 3, 4, 5]) == sol_instance.minCost(7, [1, 3, 4, 5])
def test_edge_case():
    sol_instance = Solution()
    assert min_cost(9, [5, 6, 1, 4, 2]) == sol_instance.minCost(9, [5, 6, 1, 4, 2])
def test_difficult_case():
    sol_instance = Solution()
    assert min_cost(5, [1, 3, 4]) == sol_instance.minCost(5, [1, 3, 4])

