from typing import *
from collections import *
from math import *

def search_matrix(matrix, target):
    if not matrix:
        return False
    row, col = (0, len(matrix[0]) - 1)
    while row < len(matrix) and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1
    return False
class Solution:

    def searchMatrix(self, matrix, target):
        """
        :type matrix: List[List[int]]
        :type target: int
        :rtype: bool
        """
        if not matrix:
            return False
        state = {'found': False}
        memory = set()

        def valid(l_x, l_y, r_x, r_y):
            if not 0 <= l_x < r_x <= len(matrix):
                return False
            if not 0 <= l_y < r_y <= len(matrix[0]):
                return False
            return True

        def bs(l_x, l_y, r_x, r_y):
            if state['found']:
                return
            if (l_x, l_y, r_x, r_y) in memory:
                return
            memory.add((l_x, l_y, r_x, r_y))
            if not valid(l_x, l_y, r_x, r_y):
                return
            m_x = (l_x + r_x) // 2
            m_y = (l_y + r_y) // 2
            if matrix[m_x][m_y] == target:
                state['found'] = True
                return
            if target < matrix[m_x][m_y]:
                bs(l_x, l_y, m_x, m_y)
                bs(l_x, l_y, r_x, m_y)
                bs(l_x, l_y, m_x, r_y)
            else:
                bs(m_x + 1, m_y + 1, r_x, r_y)
                bs(m_x + 1, l_y, r_x, r_y)
                bs(l_x, m_y + 1, r_x, r_y)
        bs(0, 0, len(matrix), len(matrix[0]))
        return state['found']
def test_simple_case():
    solution_instance = Solution()
    matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    target = 5
    assert search_matrix(matrix, target) == solution_instance.searchMatrix(matrix, target)
def test_target_not_found():
    solution_instance = Solution()
    matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    target = 10
    assert search_matrix(matrix, target) == solution_instance.searchMatrix(matrix, target)
def test_large_matrix():
    solution_instance = Solution()
    matrix = [[1, 3, 5, 7], [10, 11, 16, 20], [23, 30, 34, 50]]
    target = 3
    assert search_matrix(matrix, target) == solution_instance.searchMatrix(matrix, target)

