def maxOccurrence(s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
    max_count = 0
    substr_count = {}
    for i in range(len(s)-minSize+1):
        substr = s[i:i+minSize]
        unique_chars = len(set(substr))
        if unique_chars <= maxLetters and minSize <= len(substr) <= maxSize:
            if substr not in substr_count:
                substr_count[substr] = 1
            else:
                substr_count[substr] += 1
            max_count = max(max_count, substr_count[substr])
    return max_count

