class Solution:

    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        freq = {}
        temp = {}
        for i in range(len(s)):
            temp[s[i]] = 1 + temp.get(s[i], 0)
            if i >= minSize:
                temp[s[i - minSize]] -= 1
                if temp[s[i - minSize]] == 0:
                    temp.pop(s[i - minSize])
            if i >= minSize - 1 and len(temp) <= maxLetters:
                key = s[i - minSize + 1:i + 1]
                freq[key] = 1 + freq.get(key, 0)
        return max(freq.values(), default=0)
def test_simple_case():
    solution_instance = Solution()
    assert maxOccurrence('aabababb', 3, 2, 3) == solution_instance.maxFreq('aabababb', 3, 2, 3)
def test_edge_case():
    solution_instance = Solution()
    assert maxOccurrence('abcde', 2, 1, 2) == solution_instance.maxFreq('abcde', 2, 1, 2)
def test_difficult_case():
    solution_instance = Solution()
    assert maxOccurrence('abcdabcdabcd', 2, 2, 3) == solution_instance.maxFreq('abcdabcdabcd', 2, 2, 3)

