def add_lists(list1, list2):
    len1 = len(list1)
    len2 = len(list2)
    if len1 < len2:
        list1 = [0] * (len2 - len1) + list1
    else:
        list2 = [0] * (len1 - len2) + list2
    result = []
    carry = 0
    for i in range(len(list1) - 1, -1, -1):
        temp_sum = list1[i] + list2[i] + carry
        result.append(temp_sum % 10)
        carry = temp_sum // 10
    if carry:
        result.append(carry)
    result.reverse()
    return result
def elementswise_right_join(l1, l2):
    f_len = len(l1) - (len(l2) - 1)
    for i in range(len(l1), 0, -1):
        if i - f_len < 0:
            break
        else:
            l1[i - 1] = l1[i - 1] + l2[i - f_len]
    return l1
def test_simple_case():
    list1 = [1, 2, 3]
    list2 = [4, 5]
    assert add_lists(list1, list2) == elementswise_right_join(list1 + [0], list2)
def test_edge_case():
    list1 = [0]
    list2 = [1, 2, 3]
    assert add_lists(list1, list2) == elementswise_right_join(list1 + [0, 0], list2)
def test_difficult_case():
    list1 = [9, 8, 7]
    list2 = [1, 2, 3]
    assert add_lists(list1, list2) == elementswise_right_join(list1, list2)

