from typing import List

def kSimilarity(s1: str, s2: str) -> int:
    if s1 == s2:
        return 0

    def find_next_char_index(s: str, start: int, target: str) -> int:
        # Helper function to find the next index of the target character in the string
        for i in range(start, len(s)):
            if s[i] == target:
                return i
        return -1

    def swap(s: str, i: int, j: int) -> str:
        # Helper function to swap characters in a string
        s_list = list(s)
        s_list[i], s_list[j] = s_list[j], s_list[i]
        return "".join(s_list)

    def dfs(curr: str, target: str, index: int, k: int, memo: List[List[int]]) -> int:
        # Depth-first search to find the smallest k for s1 and s2 to be k-similar
        if curr == target:
            return 0

        if memo[index][k] != -1:
            return memo[index][k]

        while curr[index] == target[index]:
            index += 1

        count = float("inf")
        for i in range(index + 1, len(curr)):
            if curr[i] == target[index]:
                next_curr = swap(curr, index, i)
                count = min(count, dfs(next_curr, target, index + 1, k - 1, memo) + 1)

        memo[index][k] = count
        return count

    memo = [[-1] * (len(s2) + 1) for _ in range(len(s1))]
    return dfs(s1, s2, 0, len(s1), memo)

