def maxSubsequence(nums, queries):
    n = len(nums)
    m = len(queries)

    dp = [[0 for _ in range(n+1)] for _ in range(n+1)]

    for i in range(1, n+1):
        dp[i][i] = nums[i-1]

    for i in range(2, n+1):
        for j in range(1, n-i+2):
            dp[j][j+i-1] = dp[j][j+i-2] + nums[j+i-2]

    ans = []
    for q in queries:
        res = 0
        for i in range(1, n+1):
            for j in range(i, n+1):
                if dp[i][j] <= q:
                    res = max(res, j-i+1)
        ans.append(res)

    return ans

