class Solution:

    def customSortString(self, order: str, s: str) -> str:
        sDict = defaultdict(int)
        for c in s:
            sDict[c] += 1
        ans = ''
        for c in order:
            if c in sDict:
                for count in range(sDict[c]):
                    ans += c
                sDict[c] = 0
        for key, value in sDict.items():
            if value != 0:
                for count in range(value):
                    ans += key
        return ans
