class Solution:

    def find132pattern(self, nums: List[int]) -> bool:
        n = len(nums)
        st = []
        mini = nums[0]
        for num in nums:
            while st and st[-1][0] <= num:
                st.pop()
            if st and st[-1][1] < num:
                return True
            st.append([num, mini])
            mini = min(mini, num)
        return False
