def canPartitionKSubsets(nums: List[int], k: int) -> bool:

    def dfs(pos, subsets):
        if pos == -1:
            return len(set(subsets)) == k
        for i in range(k):
            if subsets[i] + nums[pos] <= target_sum:
                subsets[i] += nums[pos]
                if dfs(pos - 1, subsets):
                    return True
                subsets[i] -= nums[pos]
        return False
    total_sum = sum(nums)
    if total_sum % k != 0:
        return False
    target_sum = total_sum // k
    nums.sort()
    if nums[-1] > target_sum:
        return False
    return dfs(len(nums) - 1, [0] * k)
class Solution:

    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        if k > len(nums):
            return False
        s = sum(nums)
        if s % k:
            return False
        target = int(s / k)
        buckets = [0 for _ in range(k)]
        used = [False for _ in range(len(nums))]
        memo = {}
        nums = sorted(nums, reverse=True)

        def backtrack(k, bucket, start):
            if k == 0:
                return True
            state = str(used)
            if bucket == target:
                temp = backtrack(k - 1, 0, 0)
                memo[state] = temp
                return temp
            if state in memo:
                return memo[state]
            for i in range(start, len(nums)):
                if used[i]:
                    continue
                if nums[i] + bucket > target:
                    continue
                used[i] = True
                bucket += nums[i]
                if backtrack(k, bucket, i + 1):
                    return True
                used[i] = False
                bucket -= nums[i]
            return False
        res = backtrack(k, 0, 0)
        return res
def test_simple_case():
    solution_instance = Solution()
    nums = [4, 3, 2, 1]
    k = 2
    assert canPartitionKSubsets(nums, k) == solution_instance.canPartitionKSubsets(nums, k)
