def append_uniq_integers(nums, k):
    set_nums = set(nums)
    i = 1
    while k > 0:
        if i not in set_nums:
            nums.append(i)
            set_nums.add(i)
            k -= 1
        i += 1
    return sum(nums[len(nums)-k:])

