class Solution:

    def countVowelSubstrings(self, word: str) -> int:
        v = list('aeiou')
        counter = {i: 0 for i in v}
        count = 0
        for i in range(len(word)):
            if i + 5 > len(word):
                break
            dic = dict.copy(counter)
            for j in range(i, len(word)):
                if word[j] in v:
                    dic[word[j]] += 1
                else:
                    dic = dict.copy(counter)
                    break
                val = dic.values()
                if list(val).count(0) == 0 and sum(val) >= 5:
                    count += 1
        return count
