def minKBitFlips(nums, k):
    n = len(nums)
    flip = [0] * n
    res = cnt = 0

    for i in range(n):
        if i >= k:
            cnt -= flip[i-k]
        if cnt % 2 == nums[i]:
            if i + k > n:
                return -1
            res += 1
            cnt += 1
            flip[i] = 1

    return res

