def min_moves(s):
    n = len(s)
    count = 0
    for i in range(n - 2):
        if s[i:i + 3] == 'XXX' or s[i:i + 3] == 'OOO':
            continue
        else:
            count += 1
            s = s[:i + 1] + 'O' + s[i + 2:]
    return count
class Solution:

    def safe_val_by_index(self, arr, start, end):
        try:
            val = arr[start:end]
        except IndexError:
            return []
        return val

    def minimumMoves(self, s: str) -> int:
        a = list(s)
        n = len(a)
        p = 'X'
        template = ['O'] * 3
        ans = 0
        idx = a.index(p) if p in a else -1
        while idx >= 0:
            moves = [[(max(0, idx), min(len(a), idx + 3)), -1], [(max(0, idx - 1), min(len(a), idx + 2)), -1], [(max(0, idx - 2), min(len(a), idx + 1)), -1]]
            best_move = moves[0]
            for move in moves:
                move[1] = self.safe_val_by_index(a, *move[0]).count('X')
                if move[1] >= best_move[1]:
                    best_move = move
            a[best_move[0][0]:best_move[0][1]] = template
            ans += 1
            idx = a.index(p) if p in a else -1
        return ans
def test_simple_case():
    s = 'XXX'
    solution_instance = Solution()
    assert min_moves(s) == solution_instance.minimumMoves(s)
def test_edge_case():
    s = 'OOO'
    solution_instance = Solution()
    assert min_moves(s) == solution_instance.minimumMoves(s)
def test_difficult_case():
    s = 'XXOOXX'
