class Solution:

    def numRabbits(self, answers: List[int]) -> int:
        nums = {}
        for num in answers:
            if num in nums:
                nums[num] -= 1
                if nums[num] == 0:
                    del nums[num]
            elif num != 0:
                nums[num] = num
        return sum(nums.values()) + len(answers)
