from typing import *
from collections import *
from math import *

def largest_palindrome(num):
    digits = list(num)
    digits.sort(reverse=True)
    for i in range(int(num), int(''.join(digits)) + 1):
        if str(i) == str(i)[::-1]:
            return str(i)
    return '0'
class Solution:

    def largestPalindromic(self, num: str) -> str:
        dict_frequency = {}
        for char in num:
            if char in dict_frequency:
                dict_frequency[char] += 1
            else:
                dict_frequency[char] = 1
        left_str = ''
        right_str = ''
        odd_digit = 0
        for i in range(10, 0, -1):
            digit = str(i - 1)
            if digit not in dict_frequency:
                continue
            count = dict_frequency[digit]
            if count % 2 == 0:
                freq = count // 2
                for j in range(freq):
                    left_str += digit
                    right_str = digit + right_str
                dict_frequency[digit] = 0
            else:
                if odd_digit == 0:
                    odd_digit = digit
                freq = count // 2
                for j in range(freq):
                    left_str += digit
                    right_str = digit + right_str
                dict_frequency[digit] = 1
        final = ''
        if odd_digit:
            final = left_str + odd_digit + right_str
        else:
            final = left_str + right_str
        final = final.strip('0')
        if not len(final):
            final = '0'
        return str(int(final))
def test_simple_case():
    solution_instance = Solution()
    assert largest_palindrome('44494713') == solution_instance.largestPalindromic('44494713')
