def split_fibonacci(num):
    res = []
    for i in range(1, len(num)):
        if num[0] == '0' and i > 1:
            break
        a = int(num[:i])
        for j in range(i + 1, len(num)):
            if num[i] == '0' and j > i + 1:
                break
            b = int(num[i:j])
            res = [a, b]
            k = j
            while k < len(num):
                c = res[-1] + res[-2]
                if c > 2 ** 31 - 1:
                    break
