                if num[k:].startswith(c_str):
                    res.append(c)
                    k += len(c_str)
                else:
                    break
            if k == len(num) and len(res) >= 3:
                return res
    return []
class Solution:

    def splitIntoFibonacci(self, S: str) -> List[int]:
        res = []
        current = []

        def backtrack(cursor, current):
            if len(current) >= 3 and cursor == len(S):
                res.append(current)
                return
            if len(current) < 2:
                for index in range(cursor, len(S)):
                    avai = S[cursor:index + 1]
                    if avai[0] == '0' and len(avai) > 1 or int(avai) > 2 ** 31 - 1:
                        return
                    backtrack(index + 1, current + [int(avai)])
            else:
                a = current[-1]
                b = current[-2]
                seek = str(a + b)
                if S[cursor:cursor + len(seek)] == seek and int(seek) < 2 ** 31 - 1:
                    backtrack(cursor + len(seek), current + [int(seek)])
                else:
                    return
        backtrack(0, current)
        if res:
            return res[0]
        else:
            return res
def test_simple_case():
    sol_instance = Solution()
    assert split_fibonacci('123456579') == sol_instance.splitIntoFibonacci('123456579')
