from typing import *
from collections import *
from math import *

def minScoreTriangulation(values):
    n = len(values)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            dp[i][j] = float('inf')
            for k in range(i + 1, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j] + values[i] * values[j] * values[k])
    return dp[0][n - 1]
class Solution:

    def recursion(self, start, end):
        if start >= end:
            return 0
        if self.dp[start][end] != -1:
            return self.dp[start][end]
        best = float('inf')
        for mid in range(start, end):
            tmp = self.recursion(start, mid) + self.recursion(mid + 1, end) + self.values[start - 1] * self.values[mid] * self.values[end]
            if tmp < best:
                best = tmp
        self.dp[start][end] = best
        return best

    def minScoreTriangulation(self, values: List[int]) -> int:
        n = len(values)
        self.dp = [[-1 for i in range(n)] for j in range(n)]
        self.values = values
        return self.recursion(1, n - 1)
def test_simple_case():
    sol_instance = Solution()
    sol_instance.values = [1, 2, 3]
    assert minScoreTriangulation([1, 2, 3]) == sol_instance.minScoreTriangulation([1, 2, 3])
