from math import *

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True
def is_palindrome(num):
    return str(num) == str(num)[::-1]
def prime_palindrome(n):
    while True:
        if is_prime(n) and is_palindrome(n):
            return n
        n += 1
class Solution:

    def primePalindrome(self, N: int) -> int:
        """
        1. If N<=11, then the result is the first prime number greater than or equal N
        2. If 11<N<=101, then the result is 101
        3. Otherwise, there are no prime palindromes of even length
        4. Let N is a x' digit number. If x' is even, then set N=10^x'. Now N is x=x'+1 digit number where x is odd. If x' is odd, then don't change N and here x=x'.
        5. Starting from N, generate palindromes and check if it is prime
        6. If not, then set N = value of first floor(x//2) digits + 1, and go back to step 4 and generate new palindromes from new N.
        """

        def isPrime(n):
            i = 3
            while i * i <= n:
                if n % i == 0:
                    return False
                i += 2
            return True
        if N == 1 or N == 2:
            return 2
        elif N == 3:
            return 3
        elif N == 4 or N == 5:
            return 5
        elif N == 6 or N == 7:
            return 7
        elif N > 7 and N <= 11:
            return 11
        elif N > 11 and N <= 101:
            return 101
        start = (N + 1) * (N % 2 == 0) + N * (N % 2 == 1)
        len_string = len(str(start))
        str_N = str(start)
        if str_N == str_N[::-1] and isPrime(start):
            return start
        else:
            while True:
                if len_string % 2 == 0:
                    start = 10 ** len_string
                    str_N = str(start)
                if int(str_N[0]) % 2 == 0:
                    start += 10 ** (len_string - 1)
                    str_N = str(start)
                if int(str_N[0]) == 5:
                    start = 7 * 10 ** (len_string - 1)
                    str_N = str(start)
                str_N = str_N[0:len_string // 2] + str_N[len_string // 2] + str_N[0:len_string // 2][::-1]
                if int(str_N) >= N and isPrime(int(str_N)):
                    return int(str_N)
                else:
                    start = int(str_N[0:len_string // 2 + 1]) + 1
                    start *= 10 ** (len_string // 2)
                    str_N = str(start)
                    len_string = len(str_N)
def test_simple_case():
    solution_instance = Solution()
    assert prime_palindrome(2) == solution_instance.primePalindrome(2)
def test_edge_case():
    solution_instance = Solution()
    assert prime_palindrome(10) == solution_instance.primePalindrome(10)
def test_difficult_case():
    solution_instance = Solution()
    assert prime_palindrome(101) == solution_instance.primePalindrome(101)

