def isCircleRectangleOverlap(radius, xCenter, yCenter, x1, y1, x2, y2):
    closestX = max(x1, min(xCenter, x2))
    closestY = max(y1, min(yCenter, y2))
    distance = pow(closestX - xCenter, 2) + pow(closestY - yCenter, 2)
    return distance <= pow(radius, 2)

