class Solution:

    def countLargestGroup(self, n: int) -> int:

        def get_sum(value):
            res = 0
            while value:
                res += value % 10
                value //= 10
            return res
        d = {}
        for i in range(1, n + 1):
            temp = get_sum(i)
            if temp not in d:
                d[temp] = 1
            else:
                d[temp] += 1
        maxSize = max(d.values())
        ans = 0
        for i in d:
            if d[i] == maxSize:
                ans += 1
        return ans
def test_small_n_case():
    solution_instance = Solution()
    assert group_numbers(13) == solution_instance.countLargestGroup(13)
