from typing import *
from collections import *
from math import *

def min_time_to_remove_illegal_cars(s):
    l, r = (0, len(s) - 1)
    while l <= r and s[l] == '0':
        l += 1
    while r >= l and s[r] == '0':
        r -= 1
    if l > r:
        return 0
    ones = 0
    for i in range(l, r + 1):
        if s[i] == '1':
            ones += 1
    if ones == 0:
        return 0
    if ones == r - l + 1:
        return r - l + 1
    res = float('inf')
    for i in range(l, r + 1):
        j = i
        while j <= r and s[j] == '1':
            j += 1
        res = min(res, j - i - 1 + min(i - l, r - j))
        i = j
    return res
class Solution:

    def minimumTime(self, s: str) -> int:
        costL2R = [None] * len(s)
        cost = 0 if s[0] == '0' else 1
        costL2R[0] = cost
        for i in range(1, len(s)):
            if s[i] == '1':
                cost = min(cost + 2, i + 1)
            costL2R[i] = cost
        costR2L = [None] * len(s)
        cost = 0 if s[-1] == '0' else 1
        costR2L[-1] = cost
        for i in range(len(s) - 2, -1, -1):
            if s[i] == '1':
                cost = min(cost + 2, len(s) - (i + 1) + 1)
            costR2L[i] = cost
        costR2L.append(0)
        minCost = len(s)
        for i in range(len(s)):
            minCost = min(minCost, costL2R[i] + costR2L[i + 1])
        return minCost
def test_simple_case():
    assert min_time_to_remove_illegal_cars('010') == Solution().minimumTime('010')
def test_all_ones():
    assert min_time_to_remove_illegal_cars('111') == Solution().minimumTime('111')
def test_all_zeros():
    assert min_time_to_remove_illegal_cars('000') == Solution().minimumTime('000')

