solution_code:
def cut_trees_forest(matrix):
    trees = []
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] > 1:
                trees.append((i, j, matrix[i][j]))
    trees = sorted(trees, key=lambda x: x[2])
    steps = 0
    current_position = (0, 0)
    for tree in trees:
        path = bfs(matrix, current_position, (tree[0], tree[1]))
        if path is None:
            return -1
        steps += len(path)
        current_position = (tree[0], tree[1])
        matrix[tree[0]][tree[1]] = 1
    return steps

def bfs(matrix, start, end):
    queue = [(start, [start])]
    visited = set()
    while queue:
        vertex, path = queue.pop(0)
        if vertex == end:
            return path
        if vertex not in visited:
            visited.add(vertex)
            for neighbor in get_neighbors(matrix, vertex):
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
    return None

def get_neighbors(matrix, vertex):
    i, j = vertex
    neighbors = []
    if i > 0 and matrix[i-1][j] != 0:
        neighbors.append((i-1, j))
    if j > 0 and matrix[i][j-1] != 0:
        neighbors.append((i, j-1))
    if i < len(matrix)-1 and matrix[i+1][j] != 0:
        neighbors.append((i+1, j))
    if j < len(matrix[0])-1 and matrix[i][j+1] != 0:
        neighbors.append((i, j+1))
    return neighbors

