        steps += len(path)
        current_position = (tree[0], tree[1])
        matrix[tree[0]][tree[1]] = 1
    return steps
def bfs(matrix, start, end):
    queue = [(start, [start])]
    visited = set()
    while queue:
        vertex, path = queue.pop(0)
        if vertex == end:
            return path
        if vertex not in visited:
            visited.add(vertex)
            for neighbor in get_neighbors(matrix, vertex):
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
    return None
def get_neighbors(matrix, vertex):
    i, j = vertex
    neighbors = []
    if i > 0 and matrix[i - 1][j] != 0:
        neighbors.append((i - 1, j))
    if j > 0 and matrix[i][j - 1] != 0:
        neighbors.append((i, j - 1))
    if i < len(matrix) - 1 and matrix[i + 1][j] != 0:
        neighbors.append((i + 1, j))
    if j < len(matrix[0]) - 1 and matrix[i][j + 1] != 0:
        neighbors.append((i, j + 1))
    return neighbors
class Solution:

    def cutOffTree(self, forest: List[List[int]]) -> int:
        forest.append([0] * len(forest[0]))
        for row in forest:
            row.append(0)

        def distance(i, j, I, J):
            manhattan = abs(i - I) + abs(j - J)
            detour = 0
            good, bad = ([(i, j)], [])
            visited = set()
            while True:
                if not good:
                    good, bad = (bad, [])
                    detour += 1
                i, j = good.pop()
                if i == I and j == J:
                    return manhattan + detour * 2
                if (i, j) in visited:
                    continue
                visited.add((i, j))
                for i, j, closer in ((i - 1, j, i > I), (i + 1, j, i < I), (i, j + 1, j < J), (i, j - 1, j > J)):
                    if forest[i][j]:
                        (good if closer else bad).append((i, j))
        trees = [(height, r, c) for r, row in enumerate(forest) for c, height in enumerate(row) if forest[r][c] > 1]
        queue = [(0, 0)]
        reached = set()
        reached.add((0, 0))
        while queue:
            r, c = queue.pop()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                row, col = (r + dr, c + dc)
                if forest[row][col] and (row, col) not in reached:
                    queue.append((row, col))
                    reached.add((row, col))
        if not all([(i, j) in reached for height, i, j in trees]):
            return -1
        trees.sort()
        return sum([distance(i, j, I, J) for (_, i, j), (_, I, J) in zip([(0, 0, 0)] + trees, trees)])
def test_simple_case():
    matrix1 = [[2], [1], [3]]
    assert cut_trees_forest(matrix1) == Solution().cutOffTree(matrix1)
def test_edge_case():
    matrix2 = [[1, 2, 3], [0, 0, 4], [5, 6, 7]]
    assert cut_trees_forest(matrix2) == Solution().cutOffTree(matrix2)
def test_difficult_case():
    matrix3 = [[1, 1, 3], [2, 2, 4], [3, 3, 1]]
    assert cut_trees_forest(matrix3) == Solution().cutOffTree(matrix3)

