class Solution:

    def canSeePersonsCount(self, heights: List[int]) -> List[int]:
        next_max = [-1 for i in range(len(heights))]
        res = [0 for i in range(len(heights))]
        for i in range(len(heights) - 2, -1, -1):
            temp = i + 1
            vis = 0
            while temp != -1:
                if heights[i] > heights[temp]:
                    vis += 1
                    temp = next_max[temp]
                else:
                    next_max[i] = temp
                    vis += 1
                    break
            res[i] = vis
        return res
def test_simple_case():
    sol_instance = Solution()
    assert count_people([7, 4, 8, 2, 9]) == sol_instance.canSeePersonsCount([7, 4, 8, 2, 9])
def test_medium_case():
    sol_instance = Solution()
    assert count_people([7, 12, 9, 6, 10, 8, 11, 5, 3, 2]) == sol_instance.canSeePersonsCount([7, 12, 9, 6, 10, 8, 11, 5, 3, 2])
def test_difficult_case():
    sol_instance = Solution()
    assert count_people([5, 1, 2, 3, 10]) == sol_instance.canSeePersonsCount([5, 1, 2, 3, 10])

