class Solution:

    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:
        n = len(graph)
        ans = []

        def dfs(node, cur_path):
            nonlocal ans
            if node == n - 1:
                ans.append(cur_path + [node])
                return
            else:
                neighbors = graph[node]
                for neighbor in neighbors:
                    dfs(neighbor, cur_path + [node])
                return
        dfs(0, [])
        return ans
def test_simple_case():
    s = Solution()
    graph = [[1], [3], [2], [4], []]
    assert all_paths(graph, 0, len(graph) - 1) == s.allPathsSourceTarget(graph)
