class Solution:

    def kthFactor(self, n: int, k: int) -> int:
        factors = dict()
        count = 0
        for i in range(1, int(n ** 0.5) + 1):
            if n % i == 0:
                if not factors.get(i):
                    factors[i] = 1
        for i in range(int(n ** 0.5), 0, -1):
            if n % i == 0:
                if not factors.get(n // i):
                    count += 1
                    factors[n // i] = count
        factors = list(factors.keys())
        if len(factors) < k:
            return -1
        return factors[k - 1]
def test_simple_case():
    solution_instance = Solution()
    assert kth_factor(12, 3) == solution_instance.kthFactor(12, 3)
