from typing import *
from collections import *
from math import *

def reverse_string_integer_k(string, k):
    result = ''
    for i in range(0, len(string), 2 * k):
        result += string[i:i + k][::-1]
        if len(string[i:i + k]) < k:
            break
        result += string[i + k:i + 2 * k]
    return result
class Solution:

    def reverseStr(self, s: str, k: int) -> str:
        counter = 0
        ans = [c for c in s]
        iterations = len(s) // (2 * k)
        if len(s) % (2 * k):
            iterations += 1
        while counter < iterations:
            left = counter * (2 * k)
            right = left + 2 * k - 1
            if right >= len(s):
                right = len(s) - 1
            if right - left + 1 < k:
                while left < right:
                    ans[left], ans[right] = (ans[right], ans[left])
                    left += 1
                    right -= 1
            elif k <= right - left + 1 <= 2 * k:
                right = left + k - 1
                while left < right:
                    ans[left], ans[right] = (ans[right], ans[left])
                    left += 1
                    right -= 1
            counter += 1
        return ''.join(ans)
def test_simple_case():
    solution_instance = Solution()
    assert reverse_string_integer_k('abcdefg', 2) == solution_instance.reverseStr('abcdefg', 2)
def test_edge_case():
    solution_instance = Solution()
    assert reverse_string_integer_k('abcd', 2) == solution_instance.reverseStr('abcd', 2)
def test_difficult_case():
    solution_instance = Solution()
    assert reverse_string_integer_k('abcd', 3) == solution_instance.reverseStr('abcd', 3)

