from typing import *
from collections import *
from math import *

def triplets(nums1, nums2):
    result = []
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            for k in range(j + 1, len(nums2)):
                if nums1[i] ** 2 == nums2[j] * nums2[k]:
                    result.append((i, j, k))
    for i in range(len(nums2)):
        for j in range(len(nums1)):
            for k in range(j + 1, len(nums1)):
                if nums2[i] ** 2 == nums1[j] * nums1[k]:
                    result.append((j, k, i))
    return result
class Solution:

    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()

        def lowerbound(target, left, right, nums):
            while left < right:
                mid = left + (right - left) // 2
                if nums[mid] == target:
                    right = mid
                elif nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid
            return left

        def higherbound(target, left, right, nums):
            while left < right:
                mid = left + (right - left) // 2
                if nums[mid] == target:
                    left = mid + 1
                elif nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid
            return left

        def helper(n, nums, memo):
            if n in memo:
                return memo[n]
            result = 0
            for i in range(len(nums)):
                if n % nums[i] != 0:
                    continue
                target = n // nums[i]
                lower = lowerbound(target, i + 1, len(nums), nums)
                higher = higherbound(target, i + 1, len(nums), nums)
                result += higher - lower
            memo[n] = result
            return result
        result = 0
        memo1 = {}
        for n in nums1:
            result += helper(n * n, nums2, memo1)
        memo2 = {}
        for n in nums2:
            result += helper(n * n, nums1, memo2)
        return result
def test_simple_case():
    nums1 = [5, 3, 1]
    nums2 = [9, 1, 16]
    solution = Solution()
    assert triplets(nums1, nums2) == solution.numTriplets(nums1, nums2)
def test_edge_case():
    nums1 = [1, 4]
    nums2 = [1, 1]
    solution = Solution()
    assert triplets(nums1, nums2) == solution.numTriplets(nums1, nums2)
def test_difficult_case():
    nums1 = [7, 4]
    nums2 = [16, 4]
    solution = Solution()
    assert triplets(nums1, nums2) == solution.numTriplets(nums1, nums2)

