def digit_sum(num):
    sum = 0
    while(num > 0):
        sum += num % 10
        num //= 10
    return sum

def even_digit_sum(num):
    count = 0
    for i in range(1, num+1):
        if(digit_sum(i) % 2 == 0):
            count += 1
    return count

