class Solution:

    def countEven(self, num: int) -> int:
        count = 0
        for i in range(1, num + 1):
            check = self.sum_digits(i)
            if check % 2 == 0:
                count += 1
        return count

    def sum_digits(self, n):
        sum_ = 0
        while n > 0:
            digit = n % 10
            sum_ += digit
            n = n // 10
        return sum_
