from typing import *
from collections import *
from math import *

def triangular_sum(nums):
    while len(nums) > 1:
        new_nums = []
        for i in range(len(nums) - 1):
            new_nums.append((nums[i] + nums[i + 1]) % 10)
        nums = new_nums
    return sum(nums)
class Solution:

    def triangularSum(self, nums: List[int]) -> int:
        return self.solOne(nums)
        return self.solTwo(nums)

    def solOne(self, nums):
        if len(nums) == 1:
            return nums[0]
        for i in reversed(range(len(nums))):
            for x in range(i):
                nums[x] = (nums[x] + nums[x + 1]) % 10
        return nums[0]

    def solTwo(self, nums):
        if len(nums) == 1:
            return nums[0]
        return helper(len(nums) - 1, nums)
def helper(size, array):
    dp = [0] * (size + 1)
    if size == 0:
        return array[0]
    for i in range(1, size + 1):
        dp[i - 1] = (array[i - 1] + array[i]) % 10
    return helper(size - 1, dp)
def test_simple_case():
    solution_instance = Solution()
    assert triangular_sum([1, 2, 3, 4, 5]) == solution_instance.triangularSum([1, 2, 3, 4, 5])
def test_edge_case():
    solution_instance = Solution()
    assert triangular_sum([5]) == solution_instance.triangularSum([5])
def test_difficult_case():
    solution_instance = Solution()
    assert triangular_sum([0, 1, 2, 3, 4, 5]) == solution_instance.triangularSum([0, 1, 2, 3, 4, 5])

