class Solution:

    def getMaximumGenerated(self, n: int) -> int:
        if n < 2:
            return n
        dp = [0] * (n + 1)
        dp[1] = 1
        idx, res = (1, 0)
        for i in range(2, n + 1):
            if i % 2 != 0:
                dp[i] = dp[idx] + dp[idx + 1]
                idx += 1
            else:
                dp[i] = dp[idx]
            res = max(res, dp[i])
        return res
def test_simple_case():
    solution_instance = Solution()
    assert max_nums(6) == solution_instance.getMaximumGenerated(6)
