class Solution:

    def finalPrices(self, prices: List[int]) -> List[int]:
        stack = []
        for index, price in enumerate(prices):
            while stack and prices[stack[-1]] >= price:
                prices[stack.pop()] -= price
            stack.append(index)
        return prices

    def finalPrices(self, prices: List[int]) -> List[int]:
        answer = []
        for i in range(len(prices)):
            for j in range(i + 1, len(prices)):
                if prices[j] <= prices[i]:
                    answer.append(prices[i] - prices[j])
                    break
            if len(answer) < i + 1:
                answer.append(prices[i])
        return answer
def test_simple_case():
    solution_instance = Solution()
    assert finalPrices([10, 2, 8, 1]) == solution_instance.finalPrices([10, 2, 8, 1])
def test_edge_case():
    solution_instance = Solution()
    assert finalPrices([9, 8, 4, 2, 3]) == solution_instance.finalPrices([9, 8, 4, 2, 3])
