def minTotalDistance(houses: List[int], k: int) -> int: 
    houses.sort() 

    def minDistance(left, right, mid): 
        return (houses[mid] - houses[left]) + (houses[right] - houses[mid]) 

    n = len(houses) 

    # dp[i][j] = minimum total 
    # distance when i, j houses 
    # have same mailbox. 
    dp = [[0] * (n + 1) for i in range(k + 1)] 

    # initialize the dp matrix 
    for i in range(n): 
        dp[1][i + 1] = minDistance(0, n - 1, i) 

    for i in range(2, k + 1): 
        for j in range(i, n + 1): 
            ans = 10**18 

            # iterate through all possible  
            # positions to divide i-1 mailboxes 
            # for j houses 
            for p in range(i - 1, j): 
                ans = min(ans, dp[i - 1][p] + minDistance(p, j - 1, (p + j) // 2)) 

            dp[i][j] = ans 

    return dp[k][n]

