from typing import *
from collections import *
from math import *

def minTotalDistance(houses: List[int], k: int) -> int:
    houses.sort()

    def minDistance(left, right, mid):
        return houses[mid] - houses[left] + (houses[right] - houses[mid])
    n = len(houses)
    dp = [[0] * (n + 1) for i in range(k + 1)]
    for i in range(n):
        dp[1][i + 1] = minDistance(0, n - 1, i)
    for i in range(2, k + 1):
        for j in range(i, n + 1):
            ans = 10 ** 18
            for p in range(i - 1, j):
                ans = min(ans, dp[i - 1][p] + minDistance(p, j - 1, (p + j) // 2))
            dp[i][j] = ans
    return dp[k][n]
class Solution:

    def minDistance(self, houses: List[int], k: int) -> int:
        houses.sort()
        len_houses = len(houses)
        if k == len_houses:
            return 0
        cost = {**{(i, i): 0 for i in range(len_houses)}, **{(i, i + 1): houses[i + 1] - houses[i] for i in range(len_houses - 1)}}
        for i in range(len_houses):
            for r in range(1, min(i + 1, len_houses - i)):
                cost[i - r, i + r] = cost[i - r + 1, i + r - 1] + houses[i + r] - houses[i - r]
                if i + r + 1 < len_houses:
                    cost[i - r, i + r + 1] = cost[i - r + 1, i + r] + houses[i + r + 1] - houses[i - r]
        dp = {(j, 1): cost[0, j] for j in range(len_houses)}
        for box in range(2, k + 1):
            for j in range(box - 1, len_houses):
                dp[j, box] = min((dp[i, box - 1] + cost[i + 1, j] for i in range(box - 2, j)))
        return dp[len_houses - 1, k]
def test_simple_case():
    solution_instance = Solution()
    assert minTotalDistance([1, 4, 8, 10], 2) == solution_instance.minDistance([1, 4, 8, 10], 2)
def test_edge_case():
    solution_instance = Solution()
    assert minTotalDistance([2, 3, 4, 9], 2) == solution_instance.minDistance([2, 3, 4, 9], 2)
def test_difficult_case():
    solution_instance = Solution()
    assert minTotalDistance([1, 6, 7, 11], 2) == solution_instance.minDistance([1, 6, 7, 11], 2)

