def largestMerge(word1: str, word2: str) -> str:
    if len(word1) == 0:
        return word2
    if len(word2) == 0:
        return word1
    if word1[0] > word2[0]:
        return word1[0] + largestMerge(word1[1:], word2)
    elif word2[0] > word1[0]:
        return word2[0] + largestMerge(word1, word2[1:])
    else:
