class Solution:

    def largestMerge(self, word1: str, word2: str) -> str:
        M = len(word1)
        N = len(word2)
        p1 = 0
        p2 = 0
        mergeList = []
        while p1 < M and p2 < N:
            if word1[p1] > word2[p2]:
                mergeList.append(word1[p1])
                p1 += 1
            elif word1[p1] < word2[p2]:
                mergeList.append(word2[p2])
                p2 += 1
            else:
                temp1, temp2 = (p1, p2)
                while word1[temp1] == word2[temp2]:
                    temp1 += 1
                    temp2 += 1
                    if temp2 == N:
                        if temp1 == M:
                            mergeList.append(word1[p1])
                            p1 += 1
                            break
                        elif word1[temp1] < word2[p2]:
                            mergeList.append(word2[p2])
                            p2 += 1
                        else:
                            mergeList.append(word1[p1])
                            p1 += 1
                        break
                    elif temp1 == M:
                        if temp2 == N:
                            mergeList.append(word1[p1])
                            p1 += 1
                        elif word2[temp2] < word1[p1]:
                            mergeList.append(word1[p1])
                            p1 += 1
                        else:
                            mergeList.append(word2[p2])
                            p2 += 1
                        break
                    elif word1[temp1] != word2[temp2]:
                        if word1[temp1] > word2[temp2]:
                            mergeList.append(word1[p1])
                            p1 += 1
                        else:
                            mergeList.append(word2[p2])
                            p2 += 1
                        break
        if p1 == M and p2 != N:
            mergeList.append(word2[p2:])
        elif p1 != M and p2 == N:
            mergeList.append(word1[p1:])
        return ''.join(mergeList)
def test_simple_case():
    solution_instance = Solution()
    assert largestMerge('cabaa', 'bcaaa') == solution_instance.largestMerge('cabaa', 'bcaaa')
def test_edge_case():
    solution_instance = Solution()
    assert largestMerge('abcd', 'abcde') == solution_instance.largestMerge('abcd', 'abcde')
def test_difficult_case():
    solution_instance = Solution()
    assert largestMerge('acbd', 'bacd') == solution_instance.largestMerge('acbd', 'bacd')

