class Solution:

    def peopleIndexes(self, favoriteCompanies: List[List[str]]) -> List[int]:
        favoriteCompanies = [(idx, set(ele)) for idx, ele in enumerate(favoriteCompanies)]
        favoriteCompanies = sorted(favoriteCompanies, key=lambda x: len(x[1]), reverse=True)
        result = []
        for index, (idx, companies) in enumerate(favoriteCompanies):
            companies_length = len(companies)
            add_to_list = True
            for other_index, (other_idx, other_companies) in enumerate(favoriteCompanies):
                if index == other_index:
                    continue
                if companies.issubset(other_companies):
                    add_to_list = False
                    break
                if len(other_companies) < companies_length:
                    break
            if add_to_list:
                result.append(idx)
        return sorted(result)
def test_simple_case():
    solution_instance = Solution()
    assert peopleIndexes([['leetcode', 'google', 'facebook'], ['google', 'microsoft'], ['google', 'facebook'], ['google'], ['amazon']]) == sorted(solution_instance.peopleIndexes([['leetcode', 'google', 'facebook'], ['google', 'microsoft'], ['google', 'facebook'], ['google'], ['amazon']]))
def test_edge_case():
    solution_instance = Solution()
    assert peopleIndexes([['a'], ['b'], ['a', 'b'], ['a', 'b']]) == sorted(solution_instance.peopleIndexes([['a'], ['b'], ['a', 'b'], ['a', 'b']]))
def test_complex_case():
    solution_instance = Solution()
    assert peopleIndexes([['a', 'b', 'c', 'd'], ['b', 'c', 'd', 'e'], ['c', 'd', 'e', 'f'], ['d', 'e', 'f', 'g'], ['e', 'f', 'g', 'h'], ['f', 'g', 'h', 'i']]) == sorted(solution_instance.peopleIndexes([['a', 'b', 'c', 'd'], ['b', 'c', 'd', 'e'], ['c', 'd', 'e', 'f'], ['d', 'e', 'f', 'g'], ['e', 'f', 'g', 'h'], ['f', 'g', 'h', 'i']]))

