class Solution:

    def longestContinuousSubstring(self, s: str) -> int:
        codes = list()
        codes.append(ord(s[0]))
        longest_ever = 1
        longest_this = 1
        for c in s[1:]:
            codes.append(ord(c))
            if codes[-1] == codes[-2] + 1:
                longest_this += 1
            else:
                longest_ever = max(longest_ever, longest_this)
                longest_this = 1
        return max(longest_ever, longest_this)
