def get_maximum_consecutive_values(coins, n, x):
    dp = [float('-inf')] * (x+1)
    dp[0] = 0

    for i in range(1, x+1):
        for j in range(n):
            if i-coins[j] >= 0:
                dp[i] = max(dp[i], dp[i-coins[j]]+1)

    max_consec = 0
    consec = 0
    for i in range(x+1):
        if dp[i] >= float('inf'):
            consec = 0
        elif i-dp[i]*max(coins) > 0:
            consec = 0
        else:
            consec += 1
            max_consec = max(max_consec, consec)

    return max_consec

