class Solution:

    def getMaximumConsecutive(self, coins: List[int]) -> int:
        coins.sort()
        ans = 0
        for i in range(len(coins)):
            if coins[i] <= ans + 1:
                ans += coins[i]
            else:
                break
        return ans + 1
