from typing import *
from collections import *
from math import *

def minCost(grid):
    m, n = (len(grid), len(grid[0]))
    dp = [[float('inf')] * n for _ in range(m)]
    dp[0][0] = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and j < n - 1:
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + 1)
            if grid[i][j] == 2 and j > 0:
                dp[i][j - 1] = min(dp[i][j - 1], dp[i][j] + 1)
            if grid[i][j] == 3 and i < m - 1:
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + 1)
            if grid[i][j] == 4 and i > 0:
                dp[i - 1][j] = min(dp[i - 1][j], dp[i][j] + 1)
    return dp[-1][-1] if dp[-1][-1] != float('inf') else -1
class Solution:

    def dfs(self, grid: List[List[int]]) -> int:
        size_y = len(grid)
        size_x = len(grid[0])
        src = (0, 0)
        des = (size_y - 1, size_x - 1)
        stack = [(src, 0)]
        costs = {src: 0}
        while stack:
            cur, cost = stack.pop()
            sign = grid[cur[0]][cur[1]]
            for neighbor, neighbor_sign in self.iter_neighbors(cur, size_y, size_x):
                neighbor_cost = cost
                if sign != neighbor_sign:
                    neighbor_cost += 1
                known_neighbor_cost = costs.get(neighbor)
                if known_neighbor_cost is None or known_neighbor_cost > neighbor_cost:
                    costs[neighbor] = neighbor_cost
                    stack.append((neighbor, neighbor_cost))
        return costs[des]

    def bfs(self, grid: List[List[int]]) -> int:
        size_y = len(grid)
        size_x = len(grid[0])
        src = (0, 0)
        des = (size_y - 1, size_x - 1)
        queue = [(src, 0)]
        costs = {src: 0}
        while queue:
            cur, cost = queue.pop(0)
            sign = grid[cur[0]][cur[1]]
            for neighbor, neighbor_sign in self.iter_neighbors(cur, size_y, size_x):
                neighbor_cost = cost
                if sign != neighbor_sign:
                    neighbor_cost += 1
                known_neighbor_cost = costs.get(neighbor)
                if known_neighbor_cost is None or known_neighbor_cost > neighbor_cost:
                    costs[neighbor] = neighbor_cost
                    queue.append((neighbor, neighbor_cost))
        return costs[des]

    def dijkstra(self, grid: List[List[int]]) -> int:
        import heapq

        class Node:

            def __init__(self, y, x, sign, distance=0, via=None):
                self.coord = (y, x)
                self.distance = distance
                self.via = via
                self.sign = sign

            def __lt__(self, other):
                return self.distance < other.distance
        size_y = len(grid)
        size_x = len(grid[0])
        start = Node(0, 0, grid[0][0])
        node_map = {(0, 0): start}
        visited_coords = {(0, 0)}
        heap = [start]
        des_coord = (size_y - 1, size_x - 1)
        while heap:
            cur = heapq.heappop(heap)
            visited_coords.add(cur.coord)
            y, x = cur.coord
            for neighbor_coord, neighbor_sign in self.iter_neighbors(cur.coord, size_y, size_x):
                if neighbor_coord != cur.coord and neighbor_coord not in visited_coords:
                    if cur.sign == neighbor_sign:
                        nd = cur.distance
                    else:
                        nd = cur.distance + 1
                    node = node_map.get(neighbor_coord)
                    if node:
                        if node.distance > nd:
                            node.distance = nd
                            node.via = cur
                            heapq.heapify(heap)
                    else:
                        node = Node(*neighbor_coord, grid[neighbor_coord[0]][neighbor_coord[1]], distance=nd, via=cur)
                        node_map[neighbor_coord] = node
                        heapq.heappush(heap, node)
        des_node = node_map[des_coord]
        return des_node.distance

    def iter_neighbors(self, coord: tuple, size_y: int, size_x: int):
        y, x = coord
        for sign in range(1, 5):
            if sign == 1:
                if x < size_x - 1:
                    yield ((y, x + 1), sign)
            elif sign == 2:
                if x > 0:
                    yield ((y, x - 1), sign)
            elif sign == 3:
                if y < size_y - 1:
                    yield ((y + 1, x), sign)
            elif y > 0:
                yield ((y - 1, x), sign)

    def minCost(self, grid: List[List[int]]) -> int:
        return self.dijkstra(grid)
def test_simple_case():
    solution_instance = Solution()
    grid = [[1, 2, 3], [3, 4, 2], [1, 2, 1]]
    assert minCost(grid) == solution_instance.minCost(grid)
def test_edge_case():
    solution_instance = Solution()
    grid = [[1, 1, 1], [3, 1, 4], [4, 1, 4]]
    assert minCost(grid) == solution_instance.minCost(grid)
def test_difficult_case():
    solution_instance = Solution()
    grid = [[1, 3, 2], [4, 2, 3], [3, 1, 1]]
    assert minCost(grid) == solution_instance.minCost(grid)

