class Solution:

    def reverseString(self, num):
        res = ''
        while num > 0:
            num, mo = divmod(num, 10)
            res += str(mo)
            num = num
        return int(res.lstrip())

    def countDistinctIntegers(self, nums: List[int]) -> int:
        for i in range(len(nums)):
            nums.append(self.reverseString(nums[i]))
        return len(set(nums))
