class Solution(object):

    def reconstructMatrix(self, upper, lower, colsum):
        """
        :type upper: int
        :type lower: int
        :type colsum: List[int]
        :rtype: List[List[int]]
        """
        if sum(colsum) != lower + upper:
            return []
        n = len(colsum)
        if colsum.count(0) > n - max(lower, upper):
            return []
        res = [[0 for _ in range(n)] for _ in range(2)]
        for i in range(n):
            if colsum[i] == 0:
                res[0][i] = 0
                res[1][i] = 0
            elif upper > 0 and lower == 0:
                res[0][i] = 1
                upper -= 1
                colsum[i] -= 1
                res[1][i] = 0
            elif upper == 0 and lower > 0:
                res[0][i] = 0
                res[1][i] = 1
                lower -= 1
                colsum[i] -= 1
            elif upper == 0 and lower == 0:
                res[0][i] = 0
                res[1][i] = 0
            elif colsum[i] >= 2:
                res[0][i] = 1
                res[1][i] = 1
                lower -= 1
                upper -= 1
            elif upper > lower:
                res[0][i] = 1
                res[1][i] = 0
                upper -= 1
            elif upper < lower:
                res[0][i] = 0
                res[1][i] = 1
                lower -= 1
            else:
                res[0][i] = 1
                res[1][i] = 0
                upper -= 1
        return res
