            if dp[indx1][indx2] != -1:
                return dp[indx1][indx2]

            if s[indx1] == t[indx2]:
                dp[indx1][indx2] = 1 + check(indx1-1, indx2-1)
                return dp[indx1][indx2]

            dp[indx1][indx2] = 0 + max(check(indx1-1, indx2), check(indx1, indx2-1))
            return dp[indx1][indx2]

        t = s[::-1]
        m = len(s)
        n = len(t)
        dp = [[-1 for j in range(n)] for i in range(m)]
        #print(dp)
        check(m-1, n-1)
        return len(s) - dp[m-1][n-1]
