            if indx1 < 0 or indx2 < 0:
                return 0
            if s[indx1] == t[indx2]:
                return 1 + check(indx1-1, indx2-1)

            return 0 + max(check(indx1-1, indx2), check(indx1, indx2-1))

        t = s[::-1]
        m = len(s)
        n = len(t)
        return len(s) - check(m-1, n-1)
