    solution_instance = Solution()
    assert num_appeal_substrings('abca', 3) == solution_instance.appealSum('abca')
def test_complex_case():
    solution_instance = Solution()
    assert num_appeal_substrings('aabcbaa', 3) == solution_instance.appealSum('aabcbaa')

