class Solution:

    def removeAnagrams(self, words: List[str]) -> List[str]:
        curr = words[-1]
        for i in range(len(words) - 2, -1, -1):
            if sorted(words[i]) == sorted(curr):
                words.pop(i + 1)
            curr = words[i]
        return words
