def remove_outer_parentheses(s):
    ans = ''
    opened = 0
    for c in s:
        if c == '(' and opened > 0:
            ans += c
        if c == ')' and opened > 1:
            ans += c
        opened += 1 if c == '(' else -1
    return ans
class Solution:

    def removeOuterParentheses(self, s: str) -> str:
        collect_primitives = []
        counter = 0
        start = 0
        end = 0
        for i in range(0, len(s)):
            if s[i] == '(':
                if counter == 0:
                    start = i
                counter += 1
            elif s[i] == ')':
                counter -= 1
                if counter == 0:
                    end = i
            if counter == 0:
                collect_primitives.append(s[start + 1:end])
                start = 0
                end = 0
        return ''.join(collect_primitives)
def test_simple_case():
    solution_instance = Solution()
    assert remove_outer_parentheses('()()') == solution_instance.removeOuterParentheses('()()')
