def kthGrammar(n: int, k: int) -> int:
    if n == 1:
        return 0
    else:
        parent = kthGrammar(n-1, (k+1)//2)
        if parent == 0:
            return 1 if k%2 == 0 else 0
        else:
            return 0 if k%2 == 0 else 1

