class Solution:

    def kthGrammar(self, n: int, k: int) -> int:
        if n == 1:
            return 0
        if n == 2 and k == 1:
            return 0
        if n == 2 and k == 2:
            return 1
        hashmap = {}
        hashmap[0] = ''
        hashmap[1] = '0'
        for i in range(2, n + 1, 1):
            prev = hashmap[i - 1]
            nxt = ''
            for j in range(1, i - 1):
                nxt += hashmap[j]
            hashmap[i] = prev + '1' + nxt
            prev = ''
            nxt = ''
        current = hashmap[n]
        print(current)
        ans = current[k - 1]
        return int(ans)
