class Solution:

    def equalFrequency(self, word: str) -> bool:

        def getCharFreqs(word: str) -> int:
            counts = [0 for i in range(26)]
            for n in range(len(word)):
                counts[ord(word[n]) - 97] += 1
            return counts

        def checkCounts(counts: list) -> bool:
            freq = 0
            for i in range(26):
                if counts[i] == 0:
                    continue
                if counts[i] != 0 and freq == 0:
                    freq = counts[i]
                if counts[i] == freq:
                    continue
                if counts[i] != freq:
                    return False
            return True
        counts = getCharFreqs(word)
        for i in range(26):
            if counts[i] > 0:
                counts[i] -= 1
                if checkCounts(counts):
                    return True
                counts[i] += 1
        return False
