from typing import *
from collections import *
from math import *

def select_ith_largest_element(lst, i):
    n = len(lst)
    if i < 1 or i > n:
        return None
    pivot = lst[0]
    lower = [x for x in lst if x < pivot]
    upper = [x for x in lst if x > pivot]
    equal = [x for x in lst if x == pivot]
    if i <= len(upper):
        return select_ith_largest_element(upper, i)
    elif i > len(upper) + len(equal):
        return select_ith_largest_element(lower, i - len(upper) - len(equal))
    else:
        return pivot
def select(alist, start, end, i):
    """Find ith largest element in alist[start... end-1]."""
    if end - start <= 1:
        return alist[start]
    pivot = partition(alist, start, end)
    k = end - pivot
    if i < k:
        return select(alist, pivot + 1, end, i)
    elif i > k:
        return select(alist, start, pivot, i - k)
    return alist[pivot]
def partition(alist, start, end):
    pivot = alist[start]
    i = start + 1
    j = end - 1
    while True:
        while i <= j and alist[i] <= pivot:
            i = i + 1
        while i <= j and alist[j] >= pivot:
            j = j - 1
        if i <= j:
            alist[i], alist[j] = (alist[j], alist[i])
        else:
            alist[start], alist[j] = (alist[j], alist[start])
            return j
def test_simple_case():
    assert select_ith_largest_element([3, 1, 2, 4, 5], 2) == select([3, 1, 2, 4, 5], 0, 5, 2)
def test_edge_case():
    assert select_ith_largest_element([100], 1) == select([100], 0, 1, 0)
def test_difficult_case():
    assert select_ith_largest_element([-5, -1, -3, -4, 0], 3) == select([-5, -1, -3, -4, 0], 0, 5, 2)

