            return binary_search(arr, low, mid - 1, x)
        else:
            return binary_search(arr, mid + 1, high, x)
    else:
        return -1
def binary_search(alist, start, end, key):
    """Search key in alist[start... end - 1]."""
    if not start < end:
        return -1
    mid = (start + end) // 2
    if alist[mid] < key:
        return binary_search(alist, mid + 1, end, key)
    elif alist[mid] > key:
        return binary_search(alist, start, mid, key)
    else:
        return mid
def test_simple_case():
    assert binary_search([1, 2, 3, 4, 5], 0, 5, 3) == binary_search([1, 2, 3, 4, 5], 0, 5, 3)
def test_edge_case():
    assert binary_search([10, 22, 30, 45, 55, 60], 0, 6, 45) == binary_search([10, 22, 30, 45, 55, 60], 0, 6, 45)
def test_difficult_case():
    assert binary_search([1, 3, 5, 7, 9], 0, 5, 8) == binary_search([1, 3, 5, 7, 9], 0, 5, 8)

