class Solution:

    def numSubarraysWithSum(self, nums: List[int], goal: int) -> int:
        count = {0: 1, 1: 0}
        count[nums[0]] += 1
        ans = 1 if goal == nums[0] else 0
        n = len(nums)
        for i in range(1, n):
            nums[i] += nums[i - 1]
            if nums[i] - goal in count:
                ans += count[nums[i] - goal]
            if nums[i] in count:
                count[nums[i]] += 1
            else:
                count[nums[i]] = 1
        return ans
def test_simple_case():
    sol_instance = Solution()
    nums = [1, 0, 1, 0, 1]
    goal = 2
    assert numSubarrays(nums, goal) == sol_instance.numSubarraysWithSum(nums, goal)
