from typing import *
from collections import *
from math import *

def maxLines(nums1, nums2):
    dp = [[0 for j in range(len(nums2) + 1)] for i in range(len(nums1) + 1)]
    for i in range(1, len(nums1) + 1):
        for j in range(1, len(nums2) + 1):
            if nums1[i - 1] == nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[-1][-1]
class Solution:

    def maxUncrossedLines(self, nums1: List[int], nums2: List[int]) -> int:
        """
        @cache
        def dp(l1=0,l2=0):
            #if no numbers left on any then no possible moves
            if l1 == len(nums1) or l2 == len(nums2):
                return 0
            #see example 1 image
            if nums1[l1] == nums2[l2]:
                return 1+dp(l1+1,l2+1)
            #select which one to skip
            return max(dp(l1+1,l2),dp(l1,l2+1))

        return dp()
        """
        m, n = (len(nums1), len(nums2))
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if nums1[i] == nums2[j]:
                    dp[i][j] = 1 + dp[i + 1][j + 1]
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
        return dp[0][0]
def test_simple_case():
    solution_instance = Solution()
    nums1 = [1, 4, 2]
    nums2 = [1, 2, 4]
    assert maxLines(nums1, nums2) == solution_instance.maxUncrossedLines(nums1, nums2)
def test_edge_case():
    solution_instance = Solution()
    nums1 = [1, 3, 7, 1]
    nums2 = [1, 3, 7, 1, 7, 5]
    assert maxLines(nums1, nums2) == solution_instance.maxUncrossedLines(nums1, nums2)
def test_difficult_case():
    solution_instance = Solution()
    nums1 = [1, 8, 5, 2]
    nums2 = [2, 1, 5, 8]
    assert maxLines(nums1, nums2) == solution_instance.maxUncrossedLines(nums1, nums2)

