def permutation_lexicographic_order(s):
    if len(s) == 1:
        return [s]

    perms = []
    for i in range(len(s)):
        sub_perm = permutation_lexicographic_order(s[:i] + s[i+1:])
        for p in sub_perm:
            perms.append(s[i] + p)

    perms.sort()
    return perms

