class Solution:

    def openLock(self, deadends: List[str], target: str) -> int:
        deadends = set(deadends)
        if '0000' in deadends:
            return -1
        target_list = list(map(int, target))

        def get_distance(source):
            distance = 0
            for i in range(4):
                distance += min(abs(target_list[i] - source[i]), source[i] + (10 - target_list[i]))
            return distance
        distance = get_distance([0, 0, 0, 0])
        primary = [[[0, 0, 0, 0], '0000', distance]]
        secondary = []
        detour = 0
        visited = set()
        while primary or secondary:
            if not primary:
                primary, secondary = (secondary, [])
                detour += 1
            code, code_str, prev_dist = primary.pop()
            if code_str == target:
                return distance + detour * 2
            visited.add(code_str)
            for i, num in enumerate(code):
                for k in range(-1, 2, 2):
                    next_code = list(code[:])
                    next_code[i] += k
                    if next_code[i] < 0:
                        next_code[i] = 9
                    elif next_code[i] >= 10:
                        next_code[i] = 0
                    next_code_str = ''.join(map(str, next_code))
                    if next_code_str in visited or next_code_str in deadends:
                        continue
                    next_dist = get_distance(next_code)
                    visited.add(next_code_str)
                    if prev_dist < next_dist:
                        secondary.append([next_code, next_code_str, next_dist])
                    else:
                        primary.append([next_code, next_code_str, next_dist])
        return -1
def test_simple_case():
    solution_instance = Solution()
    assert open_lock(['0201', '0101', '0102', '1212', '2002'], '0202') == solution_instance.openLock(['0201', '0101', '0102', '1212', '2002'], '0202')
def test_edge_case():
    solution_instance = Solution()
    assert open_lock(['8888'], '0009') == solution_instance.openLock(['8888'], '0009')
def test_difficult_case():
    solution_instance = Solution()
    assert open_lock(['8888'], '0000') == solution_instance.openLock(['8888'], '0000')

