def alice_wins(num):
    first_half = num[:len(num) // 2]
    second_half = num[len(num) // 2:]
    if '?' not in num:
        return sum(map(int, first_half)) == sum(map(int, second_half))
    i = num.index('?')
    alice_wins_if_0 = alice_wins(num[:i] + '0' + num[i + 1:])
    alice_wins_if_9 = alice_wins(num[:i] + '9' + num[i + 1:])
    if first_half.count('?') > second_half.count('?'):
        return not alice_wins_if_0 or not alice_wins_if_9
    else:
        return alice_wins_if_0 or alice_wins_if_9
class Solution:

    def sumGame(self, num: str) -> bool:
        n = len(num)
        q_cnt_1 = s1 = 0
        for i in range(n // 2):
            if num[i] == '?':
                q_cnt_1 += 1
            else:
                s1 += int(num[i])
        q_cnt_2 = s2 = 0
        for i in range(n // 2, n):
            if num[i] == '?':
                q_cnt_2 += 1
            else:
                s2 += int(num[i])
        s_diff = s1 - s2
        q_diff = q_cnt_2 - q_cnt_1
        return not (q_diff % 2 == 0 and q_diff // 2 * 9 == s_diff)
def test_simple_case():
    solution_instance = Solution()
    assert alice_wins('??') == solution_instance.sumGame('??')
def test_edge_case():
    solution_instance = Solution()
    assert alice_wins('1?54') == solution_instance.sumGame('1?54')
def test_difficult_case():
    solution_instance = Solution()
    assert alice_wins('3??7??') == solution_instance.sumGame('3??7??')

