class Solution:

    def repeatedSubstringPattern(self, s: str) -> bool:
        base = 123
        h = 0
        n = len(s)
        total = [-1] * n
        ha = [-1] * n
        for i in range(n):
            if i == 0:
                ha[0] = 1
            else:
                ha[i] = ha[i - 1] * base
                ha[i] %= 10 ** 9 + 7
            h = h * base + (ord(s[i]) - ord('a'))
            h %= 10 ** 9 + 7
            total[i] = h
        isGood = True
        for length in range(1, n):
            cnt = 1
            h = total[length - 1]
            if n % length == 0:
                for j in range(length, n, length):
                    newH = total[j + length - 1] - total[j - 1] * ha[length]
                    newH = (newH % (10 ** 9 + 7) + 10 ** 9 + 7) % (10 ** 9 + 7)
                    if h != newH:
                        isGood = False
                if isGood == True:
                    return True
            isGood = True
        return False
def test_simple_case():
