def canThreePartsEqualSum(arr):
    total_sum = sum(arr)
    if total_sum % 3 != 0:
        return False
    target_sum = total_sum // 3
    current_sum, count = 0, 0
    for i in arr:
        current_sum += i
        if current_sum == target_sum:
            count += 1
            current_sum = 0
    return count == 3

