def box_blur(image):
    height = len(image)
    width = len(image[0])
    blur_image = [[0 for i in range(width)] for j in range(height)]

    for i in range(height):
        for j in range(width):
            # sum up 9 pixels in 3x3 kernel
            val_sum = 0
            for m in range(i - 1, i + 2):
                for n in range(j - 1, j + 2):
                    if 0 <= m < height and 0 <= n < width:
                        val_sum += image[m][n]

            # calculate average and set to current pixel
            blur_image[i][j] = int(val_sum / 9)

    return blur_image

