    return '{:,}'.format(n)
class Solution:

    def thousandSeparator(self, n: int) -> str:
        x = str(n)
        ss = ''
        res = ''
        ct = 0
        temp = []
        if len(x) > 3 and len(x) % 3 != 0:
            i = len(x) - 1
            while i >= 0:
                if i not in temp:
                    ct = ct + 1
                    if ct < 3:
                        temp.append(x[i])
                    elif ct == 3:
                        temp.append(x[i])
                        temp.append('.')
                        ct = 0
                i = i - 1
            ss = ''.join(temp)
            ss = ss[::-1]
            return ss
        elif len(x) > 3 and len(x) % 3 == 0:
            i = len(x) - 1
            while i >= 0:
                if i not in temp:
                    ct = ct + 1
                    if ct < 3:
                        temp.append(x[i])
                    elif ct == 3:
                        temp.append(x[i])
                        temp.append('.')
                        ct = 0
                i = i - 1
            ss = ''.join(temp)
            ss = ss[::-1]
            res = ss[1:]
            return res
        else:
            return x
