from typing import *
from collections import *
from math import *

def secret_meetings(n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
    secrets = [0] * n
    secrets[firstPerson] = 0
    for meeting in meetings:
        x, y, t = meeting
        secrets[x] ^= secrets[y]
        secrets[y] ^= secrets[x]
        secrets[x] ^= secrets[y]
    return [secrets[i] for i in range(n)]
class Solution:

    def findAllPeople(self, n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
        secretHolders = set()
        secretHolders.add(0)
        secretHolders.add(firstPerson)
        tupleMeetings = {}
        for meeting in meetings:
            time = meeting[2]
            if time in tupleMeetings:
                tupleMeetings[time].append((meeting[0], meeting[1]))
            else:
                tupleMeetings[time] = [(meeting[0], meeting[1])]
        for key in sorted(tupleMeetings):
            edgeList = tupleMeetings[key]
            adjacencyList = {}
            for edge in edgeList:
                if edge[0] not in adjacencyList:
                    adjacencyList[edge[0]] = set()
                adjacencyList[edge[0]].add(edge[1])
                if edge[1] not in adjacencyList:
                    adjacencyList[edge[1]] = set()
                adjacencyList[edge[1]].add(edge[0])
            frontier = set()
            for edgeNode in adjacencyList:
                if edgeNode in secretHolders:
                    frontier.add(edgeNode)
            while len(frontier) > 0:
                newFrontier = set()
                for item in frontier:
                    if item in adjacencyList:
                        for neighbor in adjacencyList[item]:
                            if neighbor not in secretHolders:
                                secretHolders.add(neighbor)
                                newFrontier.add(neighbor)
                frontier = newFrontier
        return list(secretHolders)
def test_simple_case():
    solution_instance = Solution()
    meetings = [[0, 1, 5], [1, 2, 4], [2, 3, 2], [0, 3, 1], [0, 4, 3]]
    assert secret_meetings(5, meetings, 1) == solution_instance.findAllPeople(5, meetings, 1)
def test_edge_case():
    solution_instance = Solution()
    meetings = [[0, 2, 1], [1, 2, 5], [0, 1, 4], [2, 3, 6]]
    assert secret_meetings(4, meetings, 2) == solution_instance.findAllPeople(4, meetings, 2)
def test_difficult_case():
    solution_instance = Solution()
    meetings = [[3, 4, 2], [1, 2, 1], [2, 3, 1], [1, 4, 3]]
    assert secret_meetings(5, meetings, 1) == solution_instance.findAllPeople(5, meetings, 1)

