def palindromePairs(words):
    def isPalindrome(word):
        return word == word[::-1]

    wordDict = {word: i for i, word in enumerate(words)}
    results = []

    for i, word in enumerate(words):
        for j in range(len(word)+1):
            prefix = word[:j]
            suffix = word[j:]

            if isPalindrome(prefix):
                reverse_suffix = suffix[::-1]
                if reverse_suffix != word and reverse_suffix in wordDict:
                    results.append([wordDict[reverse_suffix], i])

            if j != len(word) and isPalindrome(suffix):
                reverse_prefix = prefix[::-1]
                if reverse_prefix != word and reverse_prefix in wordDict:
                    results.append([i, wordDict[reverse_prefix]])

    return results

