class Solution:

    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        ans = []
        dictionary = {}
        n = len(words)
        for i in range(n):
            dictionary[words[i]] = i
        for i in range(n):
            w1 = words[i]
            if dictionary.get(w1[::-1], -1) != -1:
                ind = dictionary.get(w1[::-1])
                if i != ind:
                    ans.append([i, ind])
            if w1 != '' and dictionary.get('', -1) != -1 and (w1 == w1[::-1]):
                ind = dictionary.get('')
                ans.append([i, ind])
                ans.append([ind, i])
            for j in range(1, len(w1)):
                if dictionary.get(w1[j:][::-1], -1) != -1 and w1[:j] == w1[:j][::-1]:
                    ind = dictionary.get(w1[j:][::-1])
                    if ind != i:
                        ans.append([ind, i])
                if dictionary.get(w1[:j][::-1], -1) != -1 and w1[j:] == w1[j:][::-1]:
                    ind = dictionary.get(w1[:j][::-1])
                    if ind != i:
                        ans.append([i, ind])
        return ans
