class Solution:

    def maxAscendingSum(self, nums: List[int]) -> int:
        summ = 0
        max_summ = 0
        start = 0
        while start < len(nums) - 1:
            if nums[start] < nums[start + 1]:
                summ += nums[start]
            else:
                max_summ = max(max_summ, summ + nums[start])
                summ = 0
            start += 1
        if nums[start - 1] < nums[len(nums) - 1]:
            return max(max_summ, summ + nums[len(nums) - 1])
        else:
            return max(max_summ, summ, nums[len(nums) - 1])
def test_simple_case():
    solution_instance = Solution()
    assert max_sum_asc_subarray([10, 20, 30]) == solution_instance.maxAscendingSum([10, 20, 30])
