def highest_rotation(nums):
    max_score = -1
    max_index = 0
    n = len(nums)
    for i in range(n):
        score = 0
        rotated_nums = nums[i:] + nums[:i]
        for j in range(n):
            if rotated_nums[j] <= j:
                score += 1
        if score > max_score:
            max_score = score
            max_index = i
    return max_index
class Solution:

    def bestRotation(self, nums: List[int]) -> int:
        diff = [0] * (len(nums) + 1)
        for i, x in enumerate(nums):
            diff[i + 1] += 1
            if x <= i:
                diff[0] += 1
            diff[(i - x) % len(nums) + 1] -= 1
        ans = prefix = 0
        mx = -inf
        for i, x in enumerate(diff):
            prefix += x
            if prefix > mx:
                mx, ans = (prefix, i)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert highest_rotation([4, 3, 2, 6]) == solution_instance.bestRotation([4, 3, 2, 6])
