    solution_instance = Solution()
    assert highest_rotation([2, 3, 1, 4]) == solution_instance.bestRotation([2, 3, 1, 4])
def test_difficult_case():
    solution_instance = Solution()
    assert highest_rotation([1, 3, 0, 2, 4]) == solution_instance.bestRotation([1, 3, 0, 2, 4])

