from typing import *
from collections import *
from math import *

def num_common_strings(words1: List[str], words2: List[str]) -> int:
    return len(set(words1) & set(words2))
class Solution:

    def countWords(self, words1: List[str], words2: List[str]) -> int:
        counter = 0
        count_words_1 = convert(words1)
        count_words_2 = convert(words2)
        count_words_1 = remove_multipel_occurences(count_words_1)
        count_words_2 = remove_multipel_occurences(count_words_2)
        for i in count_words_2.keys():
            if i in count_words_1:
                counter += 1
        return counter
def convert(array: List[str]):
    d = dict()
    for i in array:
        if i in d:
            d[i] += 1
        else:
            d[i] = 1
    return d
def remove_multipel_occurences(dict):
    for key in list(dict.keys()):
        if dict[key] != 1:
            del dict[key]
    return dict
def test_simple_case():
    solution_instance = Solution()
    assert num_common_strings(['a', 'b', 'c'], ['b', 'c', 'd']) == solution_instance.countWords(['a', 'b', 'c'], ['b', 'c', 'd'])
