    solution_instance = Solution()
    assert num_common_strings(['cat', 'dog', 'bird'], ['dog', 'cat', 'fish', 'bird']) == solution_instance.countWords(['cat', 'dog', 'bird'], ['dog', 'cat', 'fish', 'bird'])

