from typing import *
from collections import *
from math import *

def sum_of_subarrays(arr):
    MOD = 10 ** 9 + 7
    n = len(arr)
    stack = []
    left = [0] * n
    right = [0] * n
    for i in range(n):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if not stack:
            left[i] = -1
        else:
            left[i] = stack[-1]
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if not stack:
            right[i] = n
        else:
            right[i] = stack[-1]
        stack.append(i)
    ans = 0
    for i in range(n):
        ans = (ans + arr[i] * (i - left[i]) * (right[i] - i)) % MOD
    return ans
class Solution:

    def nsr(self, nums):
        n = len(nums)
        stack, index, res = ([], [], [])
        i = len(nums) - 1
        while i >= 0:
            if len(stack) == 0:
                res.append(n - i)
            elif len(stack) > 0 and stack[-1] < nums[i]:
                res.append(index[-1] - i)
            elif len(stack) > 0 and stack[-1] >= nums[i]:
                stack.pop()
                index.pop()
                while len(stack) > 0 and stack[-1] >= nums[i]:
                    stack.pop()
                    index.pop()
                if len(stack) == 0:
                    res.append(n - i)
                elif len(stack) > 0 and stack[-1] < nums[i]:
                    res.append(index[-1] - i)
            stack.append(nums[i])
            index.append(i)
            i = i - 1
        return res[::-1]

    def nsl(self, nums):
        temp = -1
        stack, index, res = ([], [], [])
        for i in range(len(nums)):
            if len(stack) == 0:
                res.append(i - temp)
            elif len(stack) > 0 and stack[-1] <= nums[i]:
                res.append(i - index[-1])
            elif len(stack) > 0 and stack[-1] > nums[i]:
                stack.pop()
                index.pop()
                while len(stack) > 0 and stack[-1] > nums[i]:
                    stack.pop()
                    index.pop()
                if len(stack) == 0:
                    res.append(i - temp)
                elif len(stack) > 0 and stack[-1] <= nums[i]:
                    res.append(i - index[-1])
            stack.append(nums[i])
            index.append(i)
        return res

    def sumSubarrayMins(self, arr: List[int]) -> int:
        right = self.nsr(arr)
        left = self.nsl(arr)
        ans = 0
        for i in range(len(arr)):
            ans += left[i] * right[i] * arr[i]
        return ans % (10 ** 9 + 7)
def test_simple_case():
    solution_instance = Solution()
    assert sum_of_subarrays([3, 1, 2, 4]) == solution_instance.sumSubarrayMins([3, 1, 2, 4])
def test_edge_case():
    solution_instance = Solution()
    assert sum_of_subarrays([1]) == solution_instance.sumSubarrayMins([1])
def test_difficult_case():
    solution_instance = Solution()
    assert sum_of_subarrays([10, 5, 1, 8]) == solution_instance.sumSubarrayMins([10, 5, 1, 8])

