class Solution:

    def romanToInt(self, s: str) -> int:
        value_list = []
        for symbol in s:
            if symbol == 'M':
                value_list.append(1000)
            elif symbol == 'D':
                value_list.append(500)
            elif symbol == 'C':
                value_list.append(100)
            elif symbol == 'L':
                value_list.append(50)
            elif symbol == 'X':
                value_list.append(10)
            elif symbol == 'V':
                value_list.append(5)
            elif symbol == 'I':
                value_list.append(1)
        for value in range(len(value_list) - 1):
            if value_list[value] < value_list[value + 1]:
                value_list[value] = -value_list[value]
        number = sum(value_list)
        return number
def test_simple_case():
    solution_instance = Solution()
    assert romanToInt('III') == solution_instance.romanToInt('III')
def test_edge_case():
    solution_instance = Solution()
    assert romanToInt('IV') == solution_instance.romanToInt('IV')
def test_difficult_case():
    solution_instance = Solution()
    assert romanToInt('MCMXCIV') == solution_instance.romanToInt('MCMXCIV')

