def longest_word(dict, string):
    longest = ''
    for word in dict:
        if all((char in word for char in string)) and len(word) > len(longest):
            longest = word
        if all((char in word for char in string)) and len(word) == len(longest) and (word < longest):
            longest = word
    return longest.translate({ord(char): None for char in string}) if longest else ''
class Solution:

    def findLongestWord(self, s: str, dictionary: List[str]) -> str:
        ans = ''
        wordmap = defaultdict(list)
        for i, word in enumerate(dictionary):
            wordmap[word[0]].append((i, 0))
        for c in s:
            candidates = wordmap[c]
            wordmap[c] = []
            for candidate in candidates:
                word_idx, word_pos = candidate
                word_pos += 1
                if word_pos == len(dictionary[word_idx]):
                    if word_pos > len(ans) or (word_pos == len(ans) and dictionary[word_idx] < ans):
                        ans = dictionary[word_idx]
                else:
                    wordmap[dictionary[word_idx][word_pos]].append((word_idx, word_pos))
        return ans
def test_simple_case():
    solution_instance = Solution()
    dictionary = ['apple', 'dog', 'google', 'facebook']
    string = 'leetcodedogooglefacebookcode'
    assert longest_word(dictionary, string) == solution_instance.findLongestWord(string, dictionary)
def test_edge_case():
    solution_instance = Solution()
    dictionary = ['app', 'application', 'apple', 'a']
    string = 'application'
    assert longest_word(dictionary, string) == solution_instance.findLongestWord(string, dictionary)
def test_difficult_case():
    solution_instance = Solution()
    dictionary = ['app', 'apple', 'ape', 'ae']
    string = 'apple'
    assert longest_word(dictionary, string) == solution_instance.findLongestWord(string, dictionary)

