from typing import *
from collections import *
from math import *

def good_days_to_rob_bank(security, time):
    good_days = []
    for i in range(time, len(security) - time):
        if security[i] == max(security[i - time:i + time + 1]) and security[i - time:i] >= security[i - time + 1:i + 1] and (security[i:i + time] <= security[i + 1:i + time + 1]):
            good_days.append(i)
    return good_days
class Solution:

    def goodDaysToRobBank(self, sec: List[int], time: int) -> List[int]:
        result = []
        n = len(sec) - 1
        if time == 0:
            copied = sec
            copied.sort()
            if copied == sec:
                return list(range(n + 1))
        if n <= time:
            return
        else:
            t = time
            while t - time >= 0 and t + time <= n:
                temp = time
                s = t - time
                u = t + time
                flag = True
                while temp:
                    if sec[s] < sec[s + 1]:
                        flag = False
                        break
                    else:
                        s += 1
                    if sec[u] < sec[u - 1]:
                        flag = False
                        break
                    else:
                        u -= 1
                    temp -= 1
                if flag == True:
                    result.append(t)
                t += 1
        return result
def test_simple_case():
    solution_instance = Solution()
    assert good_days_to_rob_bank([1, 2, 3, 4, 5, 4], 2) == solution_instance.goodDaysToRobBank([1, 2, 3, 4, 5, 4], 2)
def test_edge_case():
    solution_instance = Solution()
    assert good_days_to_rob_bank([1, 1, 1, 1, 1], 0) == solution_instance.goodDaysToRobBank([1, 1, 1, 1, 1], 0)
def test_difficult_case():
    solution_instance = Solution()
    assert good_days_to_rob_bank([5, 3, 3, 3, 5], 2) == solution_instance.goodDaysToRobBank([5, 3, 3, 3, 5], 2)

from typing import *
from collections import *
from math import *

def findSmallestNum(pattern):
    n = len(pattern)
    low = 1
    high = n + 1
    result = ''
    for i in range(n):
        if pattern[i] == 'I':
            result += str(low)
            low += 1
        else:
            result += str(high)
            high -= 1
    result += str(low)
    return result
class Solution:

    def smallestNumber(self, pattern: str) -> str:
        n = len(pattern)
        ans = ''
        for i in range(n):
            ans += '9'

        def helper(i, cur, pre, s):
            nonlocal n, pattern, ans
            if i == n:
                if cur < ans:
                    ans = cur[:]
                    return
                else:
                    return
            cp = pattern[i]
            if cp == 'I':
                for a in range(pre + 1, 10, 1):
                    if a in s:
                        cur += str(a)
                        s.remove(a)
                        helper(i + 1, cur, a, s)
                        s.add(a)
                        cur = cur[:len(cur) - 1]
                        continue
                    else:
                        continue
            else:
                for b in range(pre - 1, 0, -1):
                    if b in s:
                        cur += str(b)
                        s.remove(b)
                        helper(i + 1, cur, b, s)
                        s.add(b)
                        cur = cur[:len(cur) - 1]
                        continue
                    else:
                        continue
        initial_pre = 0 if pattern[0] == 'I' else 10
        initial_set = set()
        for c in range(1, 10):
            initial_set.add(c)
        if pattern[0] == 'I':
            for d in range(1, 9, 1):
                copy = initial_set
                copy.remove(d)
                helper(0, str(d), initial_pre, initial_set)
        else:
            for e in range(9, 1, -1):
                copy2 = initial_set
                copy2.remove(e)
                helper(0, str(e), initial_pre, initial_set)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert findSmallestNum('IDID') == solution_instance.smallestNumber('IDID')
def test_edge_case():
    solution_instance = Solution()
    assert findSmallestNum('III') == solution_instance.smallestNumber('III')
def test_difficult_case():
    solution_instance = Solution()
    assert findSmallestNum('DDI') == solution_instance.smallestNumber('DDI')

