def convertToTitle(columnNumber: int) -> str:
    result = ''
    while columnNumber:
        columnNumber -= 1
        result = chr(columnNumber % 26 + 65) + result
        columnNumber //= 26
    return result
class Solution:
    a_to_z = {1: 'A', 2: 'B', 3: 'C', 4: 'D', 5: 'E', 6: 'F', 7: 'G', 8: 'H', 9: 'I', 10: 'J', 11: 'K', 12: 'L', 13: 'M', 14: 'N', 15: 'O', 16: 'P', 17: 'Q', 18: 'R', 19: 'S', 20: 'T', 21: 'U', 22: 'V', 23: 'W', 24: 'X', 25: 'Y', 26: 'Z'}

    def convertToTitle(self, columnNumber: int) -> str:
        ret_val = ''
        if columnNumber <= 26:
            ret_val = Solution.a_to_z.get(columnNumber, 0)
        else:
            rem = columnNumber % 26
            if rem == 0:
                first = self.convertToTitle(columnNumber // 26 - 1)
                second = self.convertToTitle(26)
            else:
                second = self.convertToTitle(rem)
                first = self.convertToTitle(columnNumber // 26)
            ret_val = first + second
        return ret_val
def test_simple_case():
    solution_instance = Solution()
    assert convertToTitle(1) == solution_instance.convertToTitle(1)
def test_mid_range_case():
    solution_instance = Solution()
    assert convertToTitle(28) == solution_instance.convertToTitle(28)
def test_high_range_case():
    solution_instance = Solution()
    assert convertToTitle(701) == solution_instance.convertToTitle(701)

