class Solution:

    def maxDistance(self, nums1: List[int], nums2: List[int]) -> int:
        ans = 0
        for i in range(len(nums1)):
            L, R = (i, len(nums2) - 1)
            while L <= R:
                mid = (L + R) // 2
                mid_e = nums2[mid]
                if mid_e >= nums1[i]:
                    L = mid + 1
                    continue
                else:
                    R = mid - 1
                    continue
            if R < 0:
                continue
            else:
                ans = max(ans, R - i)
        return ans
def test_simple_case():
    s = Solution()
    assert max_distance([5, 4, 3], [9, 8, 7, 6, 5]) == s.maxDistance([5, 4, 3], [9, 8, 7, 6, 5])
