    s = Solution()
    assert max_distance([2, 1], [1, 0]) == s.maxDistance([2, 1], [1, 0])
def test_difficult_case():
    s = Solution()
    assert max_distance([10, 9, 8], [6, 5, 4]) == s.maxDistance([10, 9, 8], [6, 5, 4])

