def make_palindrome(palindrome):
    for i in range(len(palindrome) // 2):
        j = -1 - i
        if palindrome[i] != palindrome[j]:
            removed_i = palindrome[:i] + palindrome[i+1:]
            removed_j = palindrome[:j] + palindrome[j+1:]
            if removed_i == removed_i[::-1]:
                return removed_i
            elif removed_j == removed_j[::-1]:
                return removed_j
            else:
                return ""
    return palindrome[:-1] + "a" if palindrome[:-1] != "a"*len(palindrome[:-1]) else ""

