class Solution:

    def maxUniqueSplit(self, s: str) -> int:
        ans = 0

        def helper(cur, seen):
            nonlocal ans
            if cur == '':
                ans = max(ans, len(seen))
                return
            substring = ''
            for i in range(0, len(cur)):
                substring += cur[i]
                flag = False
                if substring not in seen:
                    flag = True
                    seen.add(substring)
                    remainder = cur[i + 1:]
                    helper(remainder, seen)
                if flag:
                    seen.remove(substring)
        helper(s, set())
        return ans
def test_simple_case():
