class Solution(object):

    def dayOfYear(self, date):
        """
        :type date: str
        :rtype: int
        """
        month = int(date[5:7])
        day = int(date[8:])
        year = int(date[:4])
        total = 0
        for i in range(1, month):
            if i <= 7:
                if i % 2 != 0:
                    total += 31
                elif year % 4 == 0 and i == 2:
                    if year % 100 == 0:
                        if year % 400 == 0:
                            total += 29
                        else:
                            total += 28
                    else:
                        total += 29
                elif year % 4 != 0 and i == 2:
                    total += 28
                else:
                    total += 30
            elif i % 2 == 0:
                total += 31
            else:
                total += 30
        return total + day
