def min_squared_difference(nums1, nums2, k1, k2):
    n = len(nums1)
    diff = [0] * n

    for i in range(n):
        diff[i] = (nums1[i] - nums2[i])**2

    for i in range(k1):
        max_diff_index = diff.index(max(diff))
        nums1[max_diff_index] -= 1
        diff[max_diff_index] = (nums1[max_diff_index] - nums2[max_diff_index])**2

    for i in range(k2):
