class Solution:

    def minimumRounds(self, tasks: List[int]) -> int:
        counter = Counter(tasks)
        steps = 0
        for key, value in counter.items():
            cur_step = self.composedBy(value)
            if cur_step == -1:
                return -1
            else:
                steps += cur_step
        return steps

    def composedBy(self, num):
        final_step = -1
        tmp_step = 0
        while num > 0:
            if num % 3 == 0:
                final_step = num // 3 + tmp_step
                return final_step
            else:
                num -= 2
                tmp_step += 1
        if num == 0:
            return tmp_step
        else:
            return final_step
def test_simple_case():
    solution_instance = Solution()
    tasks = [2, 2, 3, 3, 2]
    assert min_rounds(tasks) == solution_instance.minimumRounds(tasks)
def test_edge_case():
    solution_instance = Solution()
    tasks = [4, 4, 4, 4]
    assert min_rounds(tasks) == solution_instance.minimumRounds(tasks)
def test_difficult_case():
    solution_instance = Solution()
    tasks = [1, 3, 5, 3, 1, 3, 1]
    assert min_rounds(tasks) == solution_instance.minimumRounds(tasks)

