def sort_2d_array(nums):
    res = []
    for row in nums:
        for val in row:
            res.append(val)
    return sorted(res)
class Solution:

    def intersection(self, nums: List[List[int]]) -> List[int]:
        return self.solTwo(nums)

    def solOne(self, nums):
        n = len(nums)
        count = [0] * 1001
        for i in range(len(nums)):
            self.countingSort(nums[i], count)
        return [num for num in range(1, 1001) if count[num] >= n]

    def countingSort(self, nums, count):
        for i in nums:
            count[i] += 1

    def solTwo(self, nums):
        n = len(nums)
        hashMap = {}
        for i in range(len(nums)):
            for j in range(len(nums[i])):
                num = nums[i][j]
                hashMap[num] = hashMap.get(num, 0) + 1
        return sorted([key for key in hashMap.keys() if hashMap[key] >= n])
def test_simple_case():
    solution_instance = Solution()
    assert sort_2d_array([[1, 3], [2, 4, 6]]) == solution_instance.solTwo([[1, 3], [2, 4, 6]])
