from typing import *
from collections import *
from math import *

def ladderLength(beginWord: str, endWord: str, wordList: List[str]) -> int:
    wordSet = set(wordList)
    if endWord not in wordSet:
        return 0
    queue = deque([(beginWord, 1)])
    while queue:
        current_word, level = queue.popleft()
        if current_word == endWord:
            return level
        for i in range(len(current_word)):
            for j in range(97, 123):
                new_word = current_word[:i] + chr(j) + current_word[i + 1:]
                if new_word in wordSet:
                    queue.append((new_word, level + 1))
                    wordSet.remove(new_word)
    return 0
class Solution:

    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        vstd = set()
        pattern_map = {}

        def buildPattern() -> None:
            addWordPattern(beginWord)
            for word in wordList:
                addWordPattern(word)

        def addWordPattern(word: str) -> None:
            patterns = getPatterns(word)
            for pattern in patterns:
                if pattern not in pattern_map.keys():
                    pattern_map[pattern] = []
                pattern_map[pattern].append(word)

        def getPatterns(word: str) -> List[str]:
            patterns = []
            for i in range(len(word)):
                pattern = word[:i] + '#' + word[i + 1:]
                patterns.append(pattern)
            return patterns

        def getNeighbours(root_word: str) -> List[str]:
            neighbours = []
            patterns = getPatterns(root_word)
            for pattern in patterns:
                words = pattern_map[pattern]
                for word in words:
                    if word != root_word:
                        neighbours.append(word)
            return neighbours

        def bfs(root_word: str) -> int:
            qu = deque()
            qu.append(root_word)
            depth = 0
            while qu:
                n = len(qu)
                depth += 1
                for i in range(n):
                    root_word = qu.popleft()
                    if root_word in vstd:
                        continue
                    if root_word == endWord:
                        return depth
                    vstd.add(root_word)
                    neighbours = getNeighbours(root_word)
                    for nb in neighbours:
                        qu.append(nb)
            return 0
        buildPattern()
        ans = bfs(beginWord)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert ladderLength('hit', 'cog', ['hot', 'dot', 'dog', 'cog']) == solution_instance.ladderLength('hit', 'cog', ['hot', 'dot', 'dog', 'cog'])
def test_edge_case():
    solution_instance = Solution()
    assert ladderLength('hit', 'cog', ['hot', 'dot', 'dog', 'cog', 'lot', 'log']) == solution_instance.ladderLength('hit', 'cog', ['hot', 'dot', 'dog', 'cog', 'lot', 'log'])
def test_no_solution_case():
    solution_instance = Solution()
    assert ladderLength('hot', 'cog', ['hot', 'dot', 'dog', 'lot', 'log']) == solution_instance.ladderLength('hot', 'cog', ['hot', 'dot', 'dog', 'lot', 'log'])

