from typing import *
from collections import *
from math import *

def lcp(s1, s2):
    """
    Returns the length of longest common prefix of s1 and s2
    """
    lcp_len = 0
    for i in range(min(len(s1), len(s2))):
        if s1[i] != s2[i]:
            break
        lcp_len += 1
    return lcp_len
def build_strings(s):
    """
    Returns a list of all strings of increasing length
    """
    strings = [s[:1]]
    for i in range(1, len(s)):
        strings.append(s[:i + 1])
    return strings
def score(s, sn):
    """
    Returns the score of a string s based on its longest common
    prefix with string sn
    """
    return lcp(s, sn)
def sum_scores(s):
    """
    Returns the sum of scores for all strings of increasing length
    """
    strings = build_strings(s)
    sn = strings[-1]
    sum_of_scores = 0
    for i in range(len(strings)):
        sum_of_scores += score(strings[i], sn)
    return sum_of_scores
class Solution:

    def sumScores(self, s: str) -> int:
        mod = 119218851371
        hs = 0
        vals = [0]
        for i, ch in enumerate(s):
            hs = (hs * 26 + ord(ch) - 97) % mod
            vals.append(hs)
        p26 = [1]
        for _ in range(len(s)):
            p26.append(p26[-1] * 26 % mod)
        ans = 0
        for i in range(len(s)):
            if s[0] == s[i]:
                lo, hi = (i, len(s))
                while lo < hi:
                    mid = lo + hi + 1 >> 1
                    hs = (vals[mid] - vals[i] * p26[mid - i]) % mod
                    if hs == vals[mid - i]:
                        lo = mid
                    else:
                        hi = mid - 1
                ans += lo - i
        return ans
def test_simple_case():
    s = 'abc'
    assert sum_scores(s) == Solution().sumScores(s)
def test_medium_case():
    s = 'banana'
    assert sum_scores(s) == Solution().sumScores(s)
def test_long_case():
    s = 'abracadabra'
    assert sum_scores(s) == Solution().sumScores(s)

