class Solution:

    def isNStraightHand(self, hand: List[int], W: int) -> bool:
        if not hand and W > 0:
            return False
        if W > len(hand):
            return False
        if W == 0 or W == 1:
            return True
        expectation_map = {}
        self.count = 0
        handLength = len(hand)
        sortedHand = sorted(hand)
        "\n        This method updates the expectation map in the following way:\n            a) If the len(l) == W\n                    => We've completed a straight of length W, add it towards the final count\n            b) if the next expected number (num+1) is already in the map \n                    => add the list to a queue of hands waiting to make a straight\n            c) if expected number (num+1) not in the map \n                    => Add a new expectation key with value as a new queue with this list \n        "

        def update_expectation_with_list(expectation_map, num, l, W):
            if len(l) == W:
                self.count += W
            else:
                exp = num + 1
                if exp in expectation_map:
                    expectation_map[exp].append(l)
                else:
                    expectation_map[exp] = [l]
        '\n        Very similar to update_expectation_with_list. The difference here is we have the first card of the straight and thus we need to handle it correctly (set the value as a list of lists)\n        '

        def update_expectation_with_integer(expectation_map, num):
            exp = num + 1
            if exp in expectation_map:
                expectation_map[exp].append([num])
            else:
                expectation_map[exp] = [[num]]
        for idx, num in enumerate(sortedHand):
            if num in expectation_map:
                if len(expectation_map[num]) > 1:
                    l = expectation_map[num].pop(0)
                    l.append(num)
                    update_expectation_with_list(expectation_map, num, l, W)
                else:
                    l = expectation_map[num].pop(0)
                    l.append(num)
                    expectation_map.pop(num)
                    update_expectation_with_list(expectation_map, num, l, W)
            else:
                update_expectation_with_integer(expectation_map, num)
        return self.count == handLength
def test_simple_case():
    solution_instance = Solution()
    hand = [1, 2, 3, 6, 2, 3]
    groupSize = 2
    assert rearrangeCards(hand, groupSize) == solution_instance.isNStraightHand(hand, groupSize)
def test_edge_case():
    solution_instance = Solution()
    hand = [1, 2, 3, 4, 5, 6]
    groupSize = 6
    assert rearrangeCards(hand, groupSize) == solution_instance.isNStraightHand(hand, groupSize)
def test_difficult_case():
    solution_instance = Solution()
