def equal_substring(s: str, t: str, maxCost: int) -> int:
    n = len(s)
    cost = [abs(ord(s[i]) - ord(t[i])) for i in range(n)]
    left, right = (0, 0)
    curr_cost = 0
    max_len = 0
    while right < n:
        curr_cost += cost[right]
        while curr_cost > maxCost:
            curr_cost -= cost[left]
            left += 1
        max_len = max(max_len, right - left + 1)
        right += 1
    return max_len
class Solution:

    def equalSubstring(self, s: str, t: str, maxCost: int) -> int:
        n = len(s)
        cost, start, ans = (0, 0, 0)
        for i in range(n):
            diff = abs(ord(s[i]) - ord(t[i]))
            if cost + diff <= maxCost:
                cost += diff
            else:
                ans = max(ans, i - start)
                while True:
                    cost -= abs(ord(s[start]) - ord(t[start]))
                    start += 1
                    if cost + diff <= maxCost:
                        break
                if cost + diff > maxCost:
                    start = i + 1
                else:
                    cost += diff
        ans = max(ans, n - start)
        return ans
def test_simple_case():
    solInstance = Solution()
    assert equal_substring('abcd', 'bcdf', 3) == solInstance.equalSubstring('abcd', 'bcdf', 3)
