    assert equal_substring('abcd', 'cdef', 3) == solInstance.equalSubstring('abcd', 'cdef', 3)
def test_edge_case():
    solInstance = Solution()
    assert equal_substring('abcd', 'acde', 0) == solInstance.equalSubstring('abcd', 'acde', 0)

