def minCost(days: List[int], costs: List[int]) -> int:
    dp = [0] * (len(days) + 1)
    for i in range(1, len(dp)):
        dp[i] = dp[i-1] + costs[0]
        j = i - 1
        while j >= 0 and days[j] > days[i-1] - 7:
            j -= 1
        dp[i] = min(dp[i], dp[j+1] + costs[1])
        j = i - 1
        while j >= 0 and days[j] > days[i-1] - 30:
            j -= 1
        dp[i] = min(dp[i], dp[j+1] + costs[2])
    return dp[-1]

