class Solution:

    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        cost_map = {1: costs[0], 7: costs[1], 30: costs[2]}
        travelling_days = set(days)
        dp_costs = [0 for x in range(days[-1] + 1)]
        for i in range(days[-1] + 1):
            if i not in travelling_days:
                dp_costs[i] = dp_costs[i - 1]
                continue
            possible_costs = []
            for ticket, cost in cost_map.items():
                day_diff = i - ticket
                if day_diff <= 0:
                    possible_costs.append(cost)
                else:
                    possible_costs.append(cost + dp_costs[day_diff])
            dp_costs[i] = min(possible_costs)
        return dp_costs[-1]
def test_simple_case():
    solution_instance = Solution()
    assert minCost([1, 4, 6, 7, 8, 20], [2, 7, 15]) == solution_instance.mincostTickets([1, 4, 6, 7, 8, 20], [2, 7, 15])
