def check_rotation(nums):
    n = len(nums)
    if n <= 1:
        return True

    i = 0
    while i < n - 1 and nums[i] <= nums[i+1]:
        i += 1

    if i == n - 1:
        return True

    j = (i + 1) % n
    while j != i:
        if nums[j] < nums[(j-1+n)%n]:
            return False
        j = (j + 1) % n

    return True

