class Solution:

    def maxBuilding(self, n: int, restrictions: List[List[int]]) -> int:
        if not restrictions:
            return n - 1
        restrictions.append([1, 0])
        restrictions.sort(key=lambda x: x[1] + x[0])
        idx = 0
        max_height = 0
        while idx < len(restrictions):
            pos, h = restrictions[idx]
            idx += 1
            while idx < len(restrictions) and restrictions[idx][1] - restrictions[idx][0] >= h - pos:
                idx += 1
            if idx == len(restrictions):
                max_height = max(max_height, h + n - pos)
                break
            next_pos, next_h = restrictions[idx]
            max_height = max(max_height, (h + next_h + next_pos - pos) // 2)
        return max_height
def test_simple_case():
    solution_instance = Solution()
    assert max_building_height(5, [[2, 1], [4, 1]]) == solution_instance.maxBuilding(5, [[2, 1], [4, 1]])
def test_edge_case():
    solution_instance = Solution()
    assert max_building_height(6, []) == solution_instance.maxBuilding(6, [])
def test_difficult_case():
    solution_instance = Solution()
    assert max_building_height(10, [[5, 3], [2, 2], [6, 1], [7, 4]]) == solution_instance.maxBuilding(10, [[5, 3], [2, 2], [6, 1], [7, 4]])

