from typing import *
from collections import *
from math import *

def islandPerimeter(grid):
    """
    :type grid: List[List[int]]
    :rtype: int
    """
    rows, cols = (len(grid), len(grid[0]))
    perimeter = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                if i == 0 or grid[i - 1][j] == 0:
                    perimeter += 1
                if i == rows - 1 or grid[i + 1][j] == 0:
                    perimeter += 1
                if j == 0 or grid[i][j - 1] == 0:
                    perimeter += 1
                if j == cols - 1 or grid[i][j + 1] == 0:
                    perimeter += 1
    return perimeter
class Solution:

    def islandPerimeter(self, grid: List[List[int]]) -> int:

        def findfirst():
            for i in range(len(grid)):
                for j in range(len(grid[0])):
                    if grid[i][j] == 1:
                        return [i, j]
            return [-1, -1]
        arr = grid

        def checkneighbors(i, j):
            cnt = 0
            if i - 1 >= 0:
                if arr[i - 1][j] != 0:
                    cnt += 1
            if i + 1 <= len(arr) - 1:
                if arr[i + 1][j] != 0:
                    cnt += 1
            if j - 1 >= 0:
                if arr[i][j - 1] != 0:
                    cnt += 1
            if j + 1 <= len(arr[i]) - 1:
                if arr[i][j + 1] != 0:
                    cnt += 1
            return 4 - cnt

        def counting(arr, i, j, tot, cal):
            cal += 1
            neigh = checkneighbors(i, j)
            if arr[i][j] == -1:
                return tot
            arr[i][j] = -1
            tot += neigh
            if i - 1 >= 0:
                if arr[i - 1][j] != -1:
                    if arr[i - 1][j] == 1:
                        tot = counting(arr, i - 1, j, tot, cal)
            if i + 1 <= len(arr) - 1:
                if arr[i + 1][j] != -1:
                    if arr[i + 1][j] == 1:
                        tot = counting(arr, i + 1, j, tot, cal)
            if j - 1 >= 0:
                if arr[i][j - 1] != -1:
                    if arr[i][j - 1] == 1:
                        tot = counting(arr, i, j - 1, tot, cal)
            if j + 1 <= len(arr[0]) - 1:
                if arr[i][j + 1] != -1:
                    if arr[i][j + 1] == 1:
                        tot = counting(arr, i, j + 1, tot, cal)
            return tot
        tot = 0
        land = findfirst()
        if land[0] == -1:
            return 0
        tot += counting(arr, land[0], land[1], tot, cal=0)
        return tot
def test_simple_case():
    grid = [[0, 1, 0, 0], [1, 1, 1, 0], [0, 1, 0, 0], [1, 1, 0, 0]]
    solution_instance = Solution()
