class Solution:

    def mostFrequent(self, nums: List[int], key: int) -> int:
        uniqueInts = max(nums)
        length = len(nums)
        freqs = [0 for i in range(uniqueInts + 1)]
        for i in range(len(nums)):
            if nums[i] == key:
                if i + 1 < length:
                    freqs[nums[i + 1]] += 1
        maximum = 0
        value = -1
        for i in range(uniqueInts + 1):
            if freqs[i] > maximum:
                maximum = freqs[i]
                value = i
        return value
def test_simple_case():
    sol_instance = Solution()
    assert max_target_count([0, 1, 2, 3, 1, 2, 2, 1], 1) == sol_instance.mostFrequent([0, 1, 2, 3, 1, 2, 2, 1], 1)
