            arr = arr_left + arr_right
            if direction == 'up':
                arr = arr[::-1]
        return arr
    if len(arr) > 1:
        half = len(arr) // 2
        arr_left = arr[:half]
        arr_right = arr[half:]
        if direction == 'up':
            arr_left = bitonic_sort(arr_left, 'up')
            arr_right = bitonic_sort(arr_right, 'down')
        else:
            arr_left = bitonic_sort(arr_left, 'down')
            arr_right = bitonic_sort(arr_right, 'up')
        arr = merge(arr_left + arr_right, direction)
    return arr
def compAndSwap(a, i, j, dire):
    if dire == 1 and a[i] > a[j] or (dire == 0 and a[i] < a[j]):
        a[i], a[j] = (a[j], a[i])
def bitonicMerge(a, low, cnt, dire):
    if cnt > 1:
        k = int(cnt / 2)
        for i in range(low, low + k):
            compAndSwap(a, i, i + k, dire)
        bitonicMerge(a, low, k, dire)
        bitonicMerge(a, low + k, k, dire)
def bitonicSort(a, low, cnt, dire):
    if cnt > 1:
        k = int(cnt / 2)
        bitonicSort(a, low, k, 1)
        bitonicSort(a, low + k, k, 0)
        bitonicMerge(a, low, cnt, dire)
def sort(a, N, up):
    bitonicSort(a, 0, N, up)
def test_simple_sort():
    arr1 = [3, 7, 4, 8, 6, 2, 1, 5]
    arr2 = [3, 7, 4, 8, 6, 2, 1, 5]
    assert bitonic_sort(arr1, 'up') == sort(arr2, len(arr2), 1)
def test_sort_reverse():
    arr1 = [5, 1, 8, 7, 4, 3, 6, 2]
    arr2 = [5, 1, 8, 7, 4, 3, 6, 2]
    assert bitonic_sort(arr1, 'down') == sort(arr2, len(arr2), 0)
