from typing import *
from collections import *
from math import *

def num_ways(n: int, corridor: str) -> int:
    MOD = 10 ** 9 + 7
    num_plants = corridor.count('P')
    dp = [[0 for _ in range(num_plants + 1)] for _ in range(n - 1)]
    dp[0][1] = 1
    for i in range(1, n - 1):
        for j in range(min(i + 1, num_plants), 0, -1):
            dp[i][j] = dp[i - 1][j - 1] if corridor[i] == 'P' else 0
            dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
    num_ways = 0
    for i in range(1, num_plants):
        num_ways = (num_ways + dp[n - 2][i] * dp[n - 2][num_plants - i]) % MOD
    return num_ways
class Solution:

    def numberOfWays(self, corridor: str) -> int:
        chairs = 0
        positions = 1
        plants = 1
        for idx, element in enumerate(corridor):
            if chairs > 0 and chairs % 2 == 0:
                if element == 'S':
                    positions *= plants
                    plants = 1
                elif element == 'P':
                    plants += 1
            if element == 'S':
                chairs += 1
        return positions % 1000000007 if chairs > 0 and chairs % 2 == 0 else 0
def test_simple_case():
    sol_instance = Solution()
    corridor = 'SSPPSPS'
    assert num_ways(len(corridor), corridor) == sol_instance.numberOfWays(corridor)
def test_edge_case():
    sol_instance = Solution()
    corridor = 'SPSPSPS'
    assert num_ways(len(corridor), corridor) == sol_instance.numberOfWays(corridor)
def test_difficult_case():
    sol_instance = Solution()
    corridor = 'SSPPSPSPSSSS'
    assert num_ways(len(corridor), corridor) == sol_instance.numberOfWays(corridor)

