def odd_string(n: int) -> str:
    output = []
    for i in range(97, 123):
        count = n // 2
        if n % 2 != 0:
            count += 1
        output.append(chr(i) * count)
    return ''.join(output)
class Solution:

    def generateTheString(self, n: int) -> str:
        s = ''
        g = 'abcdefghijklmnopqrs'
        i = 0
        while not n == 1:
            if n % 2 == 0:
                if n // 2 % 2 == 0:
                    s += (n // 2 + 1) * g[i]
                    i += 1
                    n = n // 2 - 1
                else:
                    s += n // 2 * g[i]
                    i += 1
                    n = n // 2
            elif n // 2 % 2 == 0:
                s += (n // 2 + 1) * g[i]
                i += 1
                n = n // 2
            else:
                s += n // 2 * g[i]
                i += 1
                n = n // 2 + 1
        s += 1 * g[i]
        return s
def test_odd_string():
    solution_instance = Solution()
    assert odd_string(7) == solution_instance.generateTheString(7)
