class Solution:

    def commonFactors(self, a: int, b: int) -> int:

        def gcd(a, b):
            if b == 0:
                return a
            return gcd(b, a % b)
        d = gcd(a, b)
        if d == 1:
            return 1
        divisors = 2
        root_d = int(sqrt(d))
        perfect_square = root_d * root_d == d
        for i in range(2, root_d):
            if d % i == 0:
                divisors += 2
        if d % root_d == 0 and root_d != 1:
            divisors += 1 if perfect_square else 2
        return divisors
def test_simple_case():
    solution_instance = Solution()
    assert common_factors(12) == solution_instance.commonFactors(12, 12)
def test_edge_case():
    solution_instance = Solution()
    assert common_factors(13) == solution_instance.commonFactors(13, 13)
def test_difficult_case():
    solution_instance = Solution()
    assert common_factors(36) == solution_instance.commonFactors(36, 36)

