from typing import *
from collections import *
from math import *

def numRollsToTarget(n: int, k: int, target: int) -> int:
    mod = 10 ** 9 + 7
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for t in range(j, target + 1):
                dp[i][t] = (dp[i][t] + dp[i - 1][t - j]) % mod
    return dp[-1][-1]
class Solution:

    def __init__(self):
        self.t = dict()
        return

    def numRollsToTarget(self, d: int, f: int, target: int) -> int:
        if d * f < target:
            return 0
        if d == 1:
            if 0 < target <= f:
                return 1
            else:
                return 0
        key = (d, target)
        if key not in self.t:
            count = 0
            for i in range(1, f + 1):
                count += self.numRollsToTarget(d - 1, f, target - i)
            self.t[key] = count
        return self.t[key] % (10 ** 9 + 7)
def test_simple_case():
    solution_instance = Solution()
    assert numRollsToTarget(1, 6, 3) == solution_instance.numRollsToTarget(1, 6, 3)
def test_edge_case():
    solution_instance = Solution()
    assert numRollsToTarget(2, 6, 7) == solution_instance.numRollsToTarget(2, 6, 7)
def test_difficult_case():
    solution_instance = Solution()
    assert numRollsToTarget(30, 30, 500) == solution_instance.numRollsToTarget(30, 30, 500)

