class Solution:

    def majorityElement(self, nums: List[int]) -> int:
        return self.majorityElementWithHashMap(nums)

    def majorityElementOptimal(self, nums):
        if not nums:
            return nums
        count = 1
        majority = nums[0]
        for i in range(1, len(nums)):
            num = nums[i]
            if count == 0:
                count = 1
                majority = num
            elif majority == num:
                count += 1
            else:
                count -= 1
        return majority

    def majorityElementWithHashMap(self, nums):
        if not nums:
            return nums
        hashMap = dict()
        n = len(nums)
        for i in nums:
            hashMap[i] = 1 + hashMap.get(i, 0)
            if hashMap[i] > n // 2:
                return i
def test_simple_case():
    solution_instance = Solution()
    assert majorityElement([3, 2, 3]) == solution_instance.majorityElementWithHashMap([3, 2, 3])
