def magical_string(n):
    if n == 0:
        return 0
    if n <= 3:
        return 1
    s = [0] * (n+1)
    s[0] = 1
    s[1] = 2
    s[2] = 2
    head = 2
    tail = 3
    num = 1
    count = 1
    while tail < n:
        for i in range(s[head]):
            s[tail] = num
            tail += 1
            if tail == n:
                return count
        num = 3 - num
        head += 1
        count += 1
    if tail == n:
        return count
    else:
        return count-1

