class Solution:

    def magicalString(self, n: int) -> int:
        ref = '122112'
        actual = ''
        start = 0
        one = True
        while len(ref) < n:
            for i in range(start, len(ref)):
                if one:
                    actual += int(ref[i]) * '1'
                    one = False
                else:
                    actual += int(ref[i]) * '2'
                    one = True
            if len(actual) > len(ref):
                start = len(ref)
                ref = actual
        return ref[:n].count('1')
def test_base_case():
    assert magical_string(0) == Solution().magicalString(0)
def test_simple_case():
    assert magical_string(5) == Solution().magicalString(5)
def test_complex_case():
    assert magical_string(10) == Solution().magicalString(10)

