from typing import *
from collections import *
from math import *

def perform_replacements(s, indices, sources, targets):
    for i in range(len(indices)):
        if sources[i] in s[indices[i]:]:
            s = s[:indices[i]] + s[indices[i]:].replace(sources[i], targets[i], 1)
    return s
class Solution:

    def findReplaceString(self, s: str, indices: List[int], sources: List[str], targets: List[str]) -> str:
        res = []
        i = 0
        replace_map = {i: (s, t) for i, s, t in zip(indices, sources, targets)}
        while i < len(s):
            if i in replace_map:
                done, p, sw_ind = (0, i, 0)
                source_word = replace_map[i][0]
                target = replace_map[i][1]
                while p < len(s) and sw_ind < len(source_word) and (s[p] == source_word[sw_ind]):
                    done += 1
                    p += 1
                    sw_ind += 1
                if done == len(source_word):
                    res.append(target)
                    i = i + len(source_word)
                else:
                    res.append(s[i])
                    i += 1
            else:
                res.append(s[i])
                i += 1
        return ''.join(res)
def test_simple_case():
    solution_instance = Solution()
    assert perform_replacements('abcd', [0, 2], ['a', 'cd'], ['eee', 'ffff']) == solution_instance.findReplaceString('abcd', [0, 2], ['a', 'cd'], ['eee', 'ffff'])
def test_edge_case():
    solution_instance = Solution()
    assert perform_replacements('abcd', [2], ['c'], ['ffff']) == solution_instance.findReplaceString('abcd', [2], ['c'], ['ffff'])
def test_difficult_case():
    solution_instance = Solution()
    assert perform_replacements('abcd', [0, 1], ['ab', 'b'], ['eee', 'fff']) == solution_instance.findReplaceString('abcd', [0, 1], ['ab', 'b'], ['eee', 'fff'])

