def maxSum(nums: List[int], k: int) -> int:
    n = len(nums)
    dp = [0] * n
    for i in range(n):
        for j in range(i-k, i):
            if j >= 0:
                dp[i] = max(dp[i], dp[j] + max(0, nums[i] + nums[j]))
            else:
                dp[i] = max(dp[i], max(0, nums[i]))
    return max(dp)

