class Solution:

    def constrainedSubsetSum(self, nums: List[int], k: int) -> int:
        max_dq = deque()
        max_sum = float('-inf')
        for i in range(len(nums)):
            local_max = nums[i]
            local_max += max_dq[0][1] if max_dq else 0
            max_sum = max(max_sum, local_max)
            while max_dq and max_dq[-1][1] < local_max:
                max_dq.pop()
            if local_max > 0:
                max_dq.append((i, local_max))
            if max_dq and max_dq[0][0] == i - k:
                max_dq.popleft()
        return max_sum
def test_simple_case():
    nums, k = ([10, 2, 1, 3], 1)
    solution_instance = Solution()
    assert maxSum(nums, k) == solution_instance.constrainedSubsetSum(nums, k)
def test_edge_case():
    nums, k = ([10, 2, 3, 5], 2)
    solution_instance = Solution()
    assert maxSum(nums, k) == solution_instance.constrainedSubsetSum(nums, k)
def test_difficult_case():
    nums, k = ([-1, -2, -3], 2)
    solution_instance = Solution()
    assert maxSum(nums, k) == solution_instance.constrainedSubsetSum(nums, k)

