def min_operations(nums, start, goal):
    queue = [(start, 0)]
    visited = set([start])
    while queue:
        curr, ops = queue.pop(0)
        if curr == goal:
            return ops
        for num in nums:
            add = curr + num
            sub = curr - num
            xor = curr ^ num
            if add <= 1000 and add not in visited:
                visited.add(add)
                queue.append((add, ops+1))
            if sub >= 0 and sub not in visited:
                visited.add(sub)
                queue.append((sub, ops+1))
            if xor not in visited:
                visited.add(xor)
                queue.append((xor, ops+1))
    return -1

