class Solution:

    def minimumOperations(self, nums: List[int], start: int, target: int) -> int:
        n = len(nums)
        vis = defaultdict(lambda: float('inf'), {start: 0})
        vis2 = defaultdict(lambda: float('inf'), {target: 0})
        q = deque([(0, start, 0), (0, target, 1)])
        nums = set(nums)
        while q:
            steps, cur, typ = q.popleft()
            if typ == 0:
                for x in nums:
                    for ops in '+-^':
                        if ops == '+':
                            new = cur + x
                        elif ops == '-':
                            new = cur - x
                        else:
                            new = cur ^ x
                        if new in vis2:
                            return steps + 1 + vis2[new]
                        if new > 1000 or new < 0:
                            continue
                        if vis[new] > steps + 1:
                            vis[new] = steps + 1
                            q.append((steps + 1, new, typ))
            else:
                for x in nums:
                    for ops in '+-^':
                        if ops == '+':
                            new = cur + x
                        elif ops == '-':
                            new = cur - x
                        else:
                            new = cur ^ x
                        if new in vis:
                            return steps + 1 + vis[new]
                        if new > 1000 or new < 0:
                            continue
                        if vis2[new] > steps + 1:
                            vis2[new] = steps + 1
                            q.append((steps + 1, new, typ))
        return -1
def test_simple_case():
    solution_instance = Solution()
    assert min_operations([2, 4, 6, 8, 10], 3, 5) == solution_instance.minimumOperations([2, 4, 6, 8, 10], 3, 5)
def test_edge_case():
    solution_instance = Solution()
    assert min_operations([3, 5, 7, 9], 8, 0) == solution_instance.minimumOperations([3, 5, 7, 9], 8, 0)
def test_difficult_case():
    solution_instance = Solution()
    assert min_operations([1, 2, 3], 10, 0) == solution_instance.minimumOperations([1, 2, 3], 10, 0)

