class Solution:

    def isHappy(self, n: int) -> bool:
        duplicate = {}

        def check(n: int) -> bool:
            if n == 1:
                return True
            res = []
            while n > 0:
                w = n % 10
                res.append(w)
                n = n // 10
            add = 0
            for num in res:
                add += num ** 2
            if add in duplicate:
                return False
            else:
                duplicate[add] = 0
                return check(add)
        return check(n)
