class Solution:

    def shipWithinDays(self, weights: List[int], days: int) -> int:
        n = len(weights)
        total = sum(weights)

        def helper(r):
            nonlocal weights
            days = 1
            counter = 0
            for weight in weights:
                counter += weight
                if counter <= r:
                    continue
                else:
                    days += 1
                    if weight > r:
                        return None
                    counter = weight
            return days
        l, h = (1, total)
        ans = None
        while l <= h:
            mid = (l + h) // 2
            num_days_needed = helper(mid)
            if num_days_needed == None:
                l = mid + 1
                continue
            elif num_days_needed <= days:
                ans = mid
                h = mid - 1
                continue
            else:
                l = mid + 1
                continue
        return ans
