def move_stones(a: int, b: int, c: int) -> List[int]:
    stones = [a, b, c]
    stones.sort()
    min_moves = 0
    max_moves = 0

    if stones[2] - stones[0] == 2:
        return [0, 0]

    if stones[1] - stones[0] <= 2 or stones[2] - stones[1] <= 2:
        min_moves = 1
    else:
        min_moves = 2

    max_moves = stones[2] - stones[0] - 2

    return [min_moves, max_moves]

