class Solution:

    def exclusiveTime(self, n: int, logs: List[str]) -> List[int]:
        fid = []
        ftime = [0] * n
        prev_ts = 0
        for log in logs:
            id, mode, ts = log.split(':')
            id, ts = (int(id), int(ts))
            if mode == 'start':
                if fid:
                    ftime[fid[-1]] += ts - prev_ts
                fid.append(id)
                prev_ts = ts
            else:
                if fid:
                    fid.pop()
                ftime[id] += ts + 1 - prev_ts
                prev_ts = ts + 1
        return ftime
