class Solution:

    def minimumLengthEncoding(self, words: List[str]) -> int:
        words.sort(key=len, reverse=True)
        wordSet = set(words)
        s = ''
        for word in words:
            if word not in wordSet:
                continue
            s += word + '#'
            for i in range(len(word)):
                if word[i:] not in wordSet:
                    continue
                wordSet.remove(word[i:])
        return len(s)
def test_simple_case():
    solution_instance = Solution()
    words = ['time', 'me', 'bell']
    indices = [3, 2, 5]
    assert shortestReferenceString(words, indices) == solution_instance.minimumLengthEncoding(words[:-1])
