class Solution:

    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        n = len(leftChild)
        parent = [-1] * n
        for idx, (left, right) in enumerate(zip(leftChild, rightChild)):
            if left != -1:
                if parent[left] != -1:
                    return False
                parent[left] = idx
            if right != -1:
                if parent[right] != -1:
                    return False
                parent[right] = idx
        if parent.count(-1) != 1:
            return False
        vis = set()

        def dfs_has_cycle(u):
            if u in vis:
                return True
            else:
                vis.add(u)
            for kid in [leftChild[u], rightChild[u]]:
                if kid != -1:
                    if dfs_has_cycle(kid):
                        return True
        if dfs_has_cycle(parent.index(-1)):
            return False
        if len(vis) != n:
            return False
        return True
def test_simple_case():
    assert is_valid_binary_tree(4, [1, -1, 3, -1], [2, -1, -1, -1]) == Solution().validateBinaryTreeNodes(4, [1, -1, 3, -1], [2, -1, -1, -1])
def test_edge_case():
    assert is_valid_binary_tree(4, [1, -1, 3, -1], [-1, -1, 1, -1]) == Solution().validateBinaryTreeNodes(4, [1, -1, 3, -1], [-1, -1, 1, -1])
def test_difficult_case():
    assert is_valid_binary_tree(2, [1, 0], [-1, 0]) == Solution().validateBinaryTreeNodes(2, [1, 0], [-1, 0])

