def basic_calculator(expr):
    return eval(expr)
class Solution:

    def calculate(self, s: str) -> int:

        def split_arr(s):
            s = s.replace(' ', '')
            i = 0
            curr = ''
            arr = []
            while i != len(s):
                if s[i] in ['+', '-']:
                    if curr != '':
                        arr.append(curr)
                    arr.append(s[i])
                    i += 1
                    curr = ''
                curr += s[i]
                i += 1
            arr.append(curr)
            return arr

        def eval_norm(s):
            arr = split_arr(s)
            curr = 0
            if arr[0].isnumeric():
                arr = ['+'] + arr
            for i in range(0, len(arr), 2):
                symbol = arr[i]
                num = int(arr[i + 1])
                if symbol == '+':
                    curr += num
                else:
                    curr -= num
            return curr
        s = '(' + s + ')'
        stack = []
        res = 0
        for ch in s:
            if ch == ')':
                to_eval = ''
                while stack[-1] != '(':
                    to_eval += str(stack.pop())
                stack.pop()
                to_eval = to_eval[::-1]
                to_eval = to_eval.replace('--', '+')
                stack += list(str(eval_norm(to_eval)))
                '\n                for ch in str(eval_norm(to_eval)):\n                    stack.append(ch)\n                '
            else:
                stack.append(ch)
        return int(''.join(stack))
def test_simple_case():
    solution_instance = Solution()
    assert basic_calculator('1 + 2 - 3') == solution_instance.calculate('1 + 2 - 3')
def test_edge_case():
    solution_instance = Solution()
    assert basic_calculator('100-200-300-400') == solution_instance.calculate('100-200-300-400')
def test_complex_case():
    solution_instance = Solution()
    assert basic_calculator('(1+(4+5+2)-3)+(6+8)') == solution_instance.calculate('(1+(4+5+2)-3)+(6+8)')

