def binary(x, n):
    return format(x, 'b').zfill(n)
def differOneBit(x, y):
    diff = x ^ y
    return diff & diff - 1 == 0
def permutation(n, start):
    binary_nums = [binary(i, n) for i in range(2 ** n)]
    index_start = binary_nums.index(binary(start, n))
    for i in range(n):
        for j in range(i + 1, n):
            index = index_start ^ 1 << i ^ 1 << j
            if differOneBit(int(binary_nums[index], 2), start):
                index_start = index
                break
    permutation = [start]
    for i in range(2 ** n - 1):
        for j in range(n):
            new_index = index_start ^ 1 << j
            if new_index != index_start and differOneBit(int(binary_nums[new_index], 2), int(binary_nums[index_start], 2)):
                permutation.append(int(binary_nums[new_index], 2))
                index_start = new_index
                break
    return permutation
class Solution:

    def circularPermutation(self, n: int, start: int) -> List[int]:
        gc, bit = ([0, 1], 1)
        while bit < n:
            bit += 1
            next_vals = []
            for val in reversed(gc):
                next_vals.append(val + 2 ** (bit - 1))
            gc.extend(next_vals)
        ind = gc.index(start)
        return gc[ind:] + gc[:ind]
def test_simple_case():
    sol_instance = Solution()
    assert permutation(2, 0) == sol_instance.circularPermutation(2, 0)
def test_edge_case():
    sol_instance = Solution()
    assert permutation(3, 3) == sol_instance.circularPermutation(3, 3)
def test_difficult_case():
    sol_instance = Solution()
    assert permutation(4, 1) == sol_instance.circularPermutation(4, 1)

