class Solution:

    def combinationSum4(self, nums: List[int], target: int) -> int:
        dp = {}
        return self.dfs(nums, target, dp)

    def dfs(self, nums, target, dp):
        if target == 0:
            return 1
        elif target < 0:
            return 0
        elif target in dp:
            return dp[target]
        out = 0
        for i in range(len(nums)):
            out += self.dfs(nums, target - nums[i], dp)
        dp[target] = out
        return out
