def maxNonOverlappingSubarrays(nums: List[int], target: int) -> int:
    dp = {}
    dp[0] = -1
    curr_sum = 0
    result = 0
    for i in range(len(nums)):
        curr_sum += nums[i]
        if curr_sum - target in dp:
            result += 1
            dp.clear()
            dp[0] = i
            curr_sum = 0
        dp[curr_sum] = i
    return result
