def find_smallest(n):
    digits = sorted(str(n))
    for i in range(n + 1, 2 * n):
        if sorted(str(i)) == digits:
            return i
    return -1
class Solution:

    def nextGreaterElement(self, n: int) -> int:
        num = list(str(n))
        i = len(num) - 1
        while i >= 1 and num[i] <= num[i - 1]:
            i -= 1
        if i == 0:
            return -1
        prefix = num[:i - 1]
        suffix = num[i - 1:]
        new_head_index = 0
        for i in range(1, len(suffix)):
            if int(suffix[i]) > int(suffix[0]):
                new_head_index += 1
            else:
                break
        suffix[0], suffix[new_head_index] = (suffix[new_head_index], suffix[0])
        suffix = str(suffix[0]) + ''.join(suffix[1:][::-1])
        ans = int(''.join(prefix) + suffix)
        upper_bound = 2 ** 31 - 1
        return ans if ans <= upper_bound else -1
def test_simple_case():
    solution_instance = Solution()
    assert find_smallest(12) == solution_instance.nextGreaterElement(12)
def test_edge_case():
    solution_instance = Solution()
    assert find_smallest(21) == solution_instance.nextGreaterElement(21)
def test_difficult_case():
    solution_instance = Solution()
    assert find_smallest(531) == solution_instance.nextGreaterElement(531)

