class Solution:

    def isRationalEqual(self, s: str, t: str) -> bool:

        def fn(s):
            """Return normalized string."""
            if '.' not in s:
                return s
            xxx, frac = s.split('.')
            if not frac:
                return xxx
            if '(' in frac:
                nonrep, rep = frac.split('(')
                rep = rep.rstrip(')')
                while nonrep and rep and (nonrep[-1] == rep[-1]):
                    nonrep = nonrep[:-1]
                    rep = rep[-1] + rep[:-1]
                if len(rep) > 1 and len(set(rep)) == 1:
                    rep = rep[0]
                if rep[:2] == rep[2:]:
                    rep = rep[:2]
                if rep == '0':
                    rep = ''
                if rep == '9':
                    rep = ''
                    if nonrep:
                        nonrep = nonrep[:-1] + str(int(nonrep[-1]) + 1)
                    else:
                        xxx = str(int(xxx) + 1)
                frac = ''
                if rep:
                    frac = f'({rep})'
                if nonrep:
                    frac = nonrep + frac
            if '(' not in frac:
                while frac and frac[-1] == '0':
                    frac = frac[:-1]
            return xxx + '.' + frac if frac else xxx
        return fn(s) == fn(t)
