def maxHappyGroups(batchSize, groups):
    freq = [0] * batchSize
    for group in groups:
        freq[group % batchSize] += 1
    happy = freq[0]
    freq[0] = 0
    for i in range(1, batchSize // 2 + 1):
        if i == batchSize - i:
            happy += freq[i] // 2
        else:
            happy += min(freq[i], freq[batchSize - i])
    return happy
class Solution:

    def maxHappyGroups(self, bs: int, gs: List[int]) -> int:
        c = {i: 0 for i in range(bs)}
        for g in gs:
            c[g % bs] += 1
        ret = c[0]
        c[0] = 0

        def get_keys(num):
            keys = []

            def rec(stack):
                if len(stack) == num:
                    if sum(stack) % bs == 0:
                        keys.append(Counter(stack))
                else:
                    for i in range(stack[-1] if stack else bs - 1, -1, -1):
                        stack.append(i)
                        rec(stack)
                        stack.pop()
            rec([])
            return keys

        def get_diff_keys(num):
            keys = []

            def rec(stack):
                if len(stack) == num:
                    if sum(stack) % bs == 0:
                        keys.append(Counter(stack))
                else:
                    for i in range(stack[-1] - 1 if stack else bs - 1, -1, -1):
                        stack.append(i)
                        rec(stack)
                        stack.pop()
            rec([])
            return keys
        for tc in range(2, bs):
            for keys in get_diff_keys(tc):
                add = min((c[key] // keys[key] for key in keys))
                if add == 0:
                    continue
                ret += add
                for key in keys:
                    c[key] -= add * keys[key]
        tc = 2
        while True:
            for keys in get_keys(tc):
                add = min((c[key] // keys[key] for key in keys))
                if add == 0:
                    continue
                ret += add
                for key in keys:
                    c[key] -= add * keys[key]
            if tc > sum(c.values()):
                break
            tc += 1
        return ret + bool(sum(c.values()))
def test_simple_case():
    solution_instance = Solution()
    assert maxHappyGroups(3, [1, 2, 3, 4, 1, 2, 3, 4]) == solution_instance.maxHappyGroups(3, [1, 2, 3, 4, 1, 2, 3, 4])
