def countConversions(startWords: List[str], targetWords: List[str]) -> int:
    def get_counts(s):
        counts = [0] * 26
        for c in s:
            counts[ord(c) - ord('a')] += 1
        return counts

    start_counts = [get_counts(s) for s in startWords]
    target_counts = [get_counts(s) for s in targetWords]

    def can_convert(c1, c2):
        num_extra = 0
        for i in range(26):
            if c1[i] < c2[i]:
                return False
            num_extra += c1[i] - c2[i]
        return num_extra <= len(c2) - 1

    num_conversions = 0
    for t in target_counts:
        for s in start_counts:
            if can_convert(s, t):
                num_conversions += 1
                break
    return num_conversions

