class Solution:

    def wordCount(self, startWords: List[str], targetWords: List[str]) -> int:

        def bin_word(word):
            num = 0
            for c in word:
                cn = ord(c) - ord('a')
                mask = 1 << cn
                num ^= mask
            return num

        def bin_take_out(word, letter):
            cn = ord(letter) - ord('a')
            mask = 1 << cn
            return word ^ mask
        starts = set([bin_word(w) for w in startWords])
        count = 0
        for t in targetWords:
            t_b = bin_word(t)
            for c in t:
                if bin_take_out(t_b, c) in starts:
                    count += 1
                    break
        return count
def test_simple_case():
    solution_instance = Solution()
    assert countConversions(['a', 'b', 'c'], ['ab', 'ac', 'bc', 'abc']) == solution_instance.wordCount(['a', 'b', 'c'], ['ab', 'ac', 'bc', 'abc'])
