def is_valid_parentheses(s, locked):
    stack = []
    for i in range(len(s)):
        if locked[i] == '1':
            if s[i] == '(':
                stack.append(s[i])
            else:
                if len(stack) == 0:
                    return False
                stack.pop()
    if len(stack) != 0:
        return False
    return True

