def find_rank(score):
    sorted_scores = sorted(score, reverse=True)
    ranks = ['Gold Medal', 'Silver Medal', 'Bronze Medal'] + list(map(str, range(4, len(score) + 1)))
    rank_dict = dict(zip(sorted_scores, ranks))
    return [rank_dict[x] for x in score]
class Solution:

    def findRelativeRanks(self, score: List[int]) -> List[str]:
        sorted_score = sorted(score, reverse=True)
        hashmap = {}
        if len(score) > 2:
            hashmap[sorted_score[0]] = 'Gold Medal'
            hashmap[sorted_score[1]] = 'Silver Medal'
            hashmap[sorted_score[2]] = 'Bronze Medal'
        elif len(score) == 1:
            return ['Gold Medal']
        elif score[0] > score[1]:
            return ['Gold Medal', 'Silver Medal']
        else:
            return ['Silver Medal', 'Gold Medal']
        rank = 4
        for index in range(3, len(sorted_score)):
            hashmap[sorted_score[index]] = str(rank)
            rank += 1
        return [hashmap[x] for x in score]
def test_simple_case():
    solution_instance = Solution()
    assert find_rank([5, 4, 3, 2, 1]) == solution_instance.findRelativeRanks([5, 4, 3, 2, 1])
