    solution_instance = Solution()
    assert find_rank([8, 7, 6, 5, 4, 3, 2, 1]) == solution_instance.findRelativeRanks([8, 7, 6, 5, 4, 3, 2, 1])

from typing import *
from collections import *
from math import *

def numSubarrayProductLessThanK(nums, k):
    if k <= 1:
        return 0
    l, r, prod, count = (0, 0, 1, 0)
    while r < len(nums):
        prod *= nums[r]
        while prod >= k:
            prod /= nums[l]
            l += 1
        count += r - l + 1
        r += 1
    return count
class Solution:

    def numSubarrayProductLessThanK(self, nums: List[int], k: int) -> int:
        n = len(nums)
        m = 0
        if k == 0:
            return 0
        if sum(nums) == n:
            return n * (n + 1) // 2 if k > 1 else 0
        for i, num_i in enumerate(nums):
            curr_prod = num_i
            if curr_prod < k:
                m += 1
            else:
                continue
            for num_j in nums[i + 1:]:
                curr_prod = curr_prod * num_j
                if curr_prod < k:
                    m += 1
                else:
                    break
        return m
def test_simple_case():
    solution_instance = Solution()
    assert numSubarrayProductLessThanK([10, 5, 1, 8], 10) == solution_instance.numSubarrayProductLessThanK([10, 5, 1, 8], 10)
def test_edge_case():
    solution_instance = Solution()
    assert numSubarrayProductLessThanK([1, 2, 3], 0) == solution_instance.numSubarrayProductLessThanK([1, 2, 3], 0)
def test_difficult_case():
    solution_instance = Solution()
    assert numSubarrayProductLessThanK([1, 1, 1], 2) == solution_instance.numSubarrayProductLessThanK([1, 1, 1], 2)

