class Solution:

    def canMakeArithmeticProgression(self, arr: List[int]) -> bool:
        arr.sort()
        first2 = arr[1] - arr[0]
        for x in range(2, len(arr)):
            if first2 == arr[x] - arr[x - 1]:
                continue
            else:
                return False
        return True
