def minOperations(boxes: str) -> List[int]:
    n = len(boxes)
    left = [0] * n
    right = [0] * n
    ans = [0] * n
    if boxes[0] == '1':
        left[0] = 1
    if boxes[n - 1] == '1':
        right[n - 1] = 1
    for i in range(1, n):
        if boxes[i] == '1':
            left[i] = left[i - 1] + 1
        else:
            left[i] = left[i - 1]
    for i in range(n - 2, -1, -1):
        if boxes[i] == '1':
            right[i] = right[i + 1] + 1
        else:
            right[i] = right[i + 1]
    for i in range(n):
        ans[i] = left[i] + right[i]
    return ans
class Solution:

    def minOperations(self, b: str) -> List[int]:
        boxes = [0 if c == '0' else 1 for c in b]
        onesBeforeLine, onesAfterLine = (0, sum(boxes[1:]))
        stepsBeforeLine, stepsAfterLine = (0, sum([i if b else 0 for i, b in enumerate(boxes)]))
        res = [stepsBeforeLine + stepsAfterLine]
        for line in range(1, len(boxes)):
            onesBeforeLine += boxes[line - 1]
            stepsBeforeLine += onesBeforeLine
            stepsAfterLine -= onesAfterLine
            onesAfterLine -= boxes[line]
            res.append(stepsBeforeLine + stepsAfterLine)
        return res
def test_simple_cases():
    s = Solution()
    assert minOperations('110') == s.minOperations('110')
def test_middle_balls():
    s = Solution()
    assert minOperations('001011') == s.minOperations('001011')
def test_extreme_cases():
    s = Solution()
    assert minOperations('111') == s.minOperations('111')

