def maxProductPath(grid: List[List[int]]) -> int:
    m, n = (len(grid), len(grid[0]))
    maxProd = [[-float('inf')] * n for _ in range(m)]
    minProd = [[float('inf')] * n for _ in range(m)]
    maxProd[0][0] = minProd[0][0] = grid[0][0]
    for i in range(1, m):
        maxProd[i][0] = minProd[i][0] = maxProd[i - 1][0] * grid[i][0]
    for j in range(1, n):
        maxProd[0][j] = minProd[0][j] = maxProd[0][j - 1] * grid[0][j]
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] > 0:
                maxProd[i][j] = max(maxProd[i - 1][j], maxProd[i][j - 1]) * grid[i][j]
                minProd[i][j] = min(minProd[i - 1][j], minProd[i][j - 1]) * grid[i][j]
            else:
                maxProd[i][j] = min(minProd[i - 1][j], minProd[i][j - 1]) * grid[i][j]
                minProd[i][j] = max(maxProd[i - 1][j], maxProd[i][j - 1]) * grid[i][j]
    res = maxProd[-1][-1] % (10 ** 9 + 7)
    return -1 if res < 0 else res
class Solution:

    def maxProductPath(self, grid: List[List[int]]) -> int:
        numRows, numCols = (len(grid), len(grid[0]))
        maxProduct, minProduct = ([[0] * numCols for _ in range(numRows)], [[0] * numCols for _ in range(numRows)])
        maxProduct[0][0], minProduct[0][0] = (grid[0][0], grid[0][0])
        for row in range(1, numRows):
            minProduct[row][0] = minProduct[row - 1][0] * grid[row][0]
            maxProduct[row][0] = maxProduct[row - 1][0] * grid[row][0]
        for col in range(1, numCols):
            minProduct[0][col] = minProduct[0][col - 1] * grid[0][col]
            maxProduct[0][col] = maxProduct[0][col - 1] * grid[0][col]
        for row in range(1, numRows):
            for col in range(1, numCols):
                if grid[row][col] < 0:
                    maxProduct[row][col] = min(minProduct[row - 1][col], minProduct[row][col - 1]) * grid[row][col]
                    minProduct[row][col] = max(maxProduct[row - 1][col], maxProduct[row][col - 1]) * grid[row][col]
                else:
                    maxProduct[row][col] = max(maxProduct[row - 1][col], maxProduct[row][col - 1]) * grid[row][col]
                    minProduct[row][col] = min(minProduct[row - 1][col], minProduct[row][col - 1]) * grid[row][col]
        res = maxProduct[numRows - 1][numCols - 1]
        return res % 1000000007 if res >= 0 else -1
def test_simple_case():
    s = Solution()
    grid = [[1, -2, 1], [1, -4, 1], [1, 3, -1]]
    assert maxProductPath(grid) == s.maxProductPath(grid)
def test_with_negative_values():
    s = Solution()
    grid = [[1, -1, 1], [2, 2, 2], [-1, -2, -3]]
    assert maxProductPath(grid) == s.maxProductPath(grid)
def test_all_positive_values():
    s = Solution()
    grid = [[1, 2], [3, 4]]
    assert maxProductPath(grid) == s.maxProductPath(grid)

