class First_class:

    def angleClock(self, hour: int, minutes: int) -> float:
        h = (hour % 12 + minutes / 60) * 30
        m = 6 * minutes
        angle = abs(h - m)
        return min(angle, 360 - angle)
class Solution:

    def angleClock(self, hour: int, minutes: int) -> float:
        min_clock = minutes / 5
        if minutes == 0 and hour * 30 == 360:
            return 0
        elif minutes == 0:
            only_hour = hour * 30
            if only_hour > 180:
                return 360 - only_hour
            return only_hour
        else:
            time = abs(hour - min_clock) * 30
            diff = 30 / (60 / minutes)
            if min_clock > hour:
                fin_time = time - diff
            else:
                fin_time = time + diff
            if fin_time > 180:
                diff = fin_time - 180
                return abs(180 - diff)
            else:
                return abs(fin_time)
def test_simple_case():
    instance1 = First_class()
    instance2 = Solution()
    assert instance1.angleClock(12, 30) == instance2.angleClock(12, 30)
