class Solution:

    def sumOfUnique(self, nums: List[int]) -> int:
        from collections import Counter
        frequency = Counter(nums)
        add = 0
        for i in frequency:
            if frequency[i] == 1:
                add += i
        return add
        n = len(nums)
        answer = 0
        for i in range(0, n):
            count = 0
            for j in range(0, n):
                if i != j:
                    if nums[i] != nums[j]:
                        count += 1
            if count == n - 1:
                answer += nums[i]
        return answer
def test_simple_case():
    solution_instance = Solution()
    assert sumOfUnique([1, 2, 3, 2]) == solution_instance.sumOfUnique([1, 2, 3, 2])
