class Solution:

    def isLongPressedName(self, name: str, typed: str) -> bool:
        n = len(name)
        m = len(typed)
        if m < n:
            return False
        if name[0] != typed[0]:
            return False
        i = 0
        j = 0
        while i < n:
            if name[i] == typed[j]:
                i += 1
                j += 1
            elif typed[j] == name[i - 1]:
                j += 1
            else:
                return False
            if j == m and i != n:
                return False
        if j != m:
            while j < m:
                if typed[j] != name[n - 1]:
                    return False
                j += 1
        return True
