def min_changes(nums, k):
    n = len(nums)
    res = float('inf')
    for left in range(n - k + 1):
        cnt = 0
        for right in range(left + k - 1, n):
            xor_sum = nums[left]
            for i in range(left + 1, right + 1):
                xor_sum ^= nums[i]
            if xor_sum == 0:
                cnt += 1
        res = min(res, cnt)
