from typing import *
from collections import *
from math import *

def min_changes(nums, k):
    n = len(nums)
    res = float('inf')
    for left in range(n - k + 1):
        cnt = 0
        for right in range(left + k - 1, n):
            xor_sum = nums[left]
            for i in range(left + 1, right + 1):
                xor_sum ^= nums[i]
            if xor_sum == 0:
                cnt += 1
        res = min(res, cnt)
    return res
class Solution:

    def minChanges(self, nums: List[int], k: int) -> int:
        freq = defaultdict(lambda: defaultdict(int))
        for i, x in enumerate(nums):
            freq[i % k][x] += 1
        n = 1 << 10
        dp = [0] + [-inf] * (n - 1)
        for i in range(k):
            mx = max(dp)
            tmp = [0] * n
            for x, c in enumerate(dp):
                for xx, cc in freq[i].items():
                    tmp[x ^ xx] = max(tmp[x ^ xx], c + cc, mx)
            dp = tmp
        return len(nums) - dp[0]
def test_simple_case():
    solution_instance = Solution()
    nums = [1, 2, 3, 4, 5]
    k = 3
    assert min_changes(nums, k) == solution_instance.minChanges(nums, k)
def test_edge_case():
    solution_instance = Solution()
    nums = [1, 1, 1, 1, 1]
    k = 1
    assert min_changes(nums, k) == solution_instance.minChanges(nums, k)
def test_difficult_case():
    solution_instance = Solution()
    nums = [3, 4, 5, 6, 7]
    k = 2
    assert min_changes(nums, k) == solution_instance.minChanges(nums, k)

