def is_Sublist(l, s):
    sub_set = False
    if s == []:
        sub_set = True
    elif s == l:
        sub_set = True
    elif len(s) > len(l):
        sub_set = False
    else:
        for i in range(len(l)):
            if l[i] == s[0]:
                n = 1
                while n < len(s) and l[i + n] == s[n]:
                    n += 1
                if n == len(s):
                    sub_set = True
    return sub_set
def test_simple_case():
    assert is_sublist([1, 2], [1, 2, 3, 4]) == is_Sublist([1, 2], [1, 2, 3, 4])
