class Solution:

    def rangeSum(self, nums: List[int], n: int, left: int, right: int) -> int:
        i, j, amount = (0, 0, 0)
        total_sum = []
        while i < len(nums):
            if j == len(nums) - 1:
                amount += nums[j]
                total_sum.append(amount)
                i += 1
                j = i
                amount = 0
            elif i == j:
                amount = nums[j]
                total_sum.append(amount)
                j += 1
            else:
                amount += nums[j]
                total_sum.append(amount)
                j += 1
        total_sum.sort()
        return sum(total_sum[left - 1:right]) % (10 ** 9 + 7)
def test_simple_case():
    solution_instance = Solution()
    assert sumSubarray([1, 2, 3]) == solution_instance.rangeSum([1, 2, 3], 3, 1, 6)
def test_edge_case():
    solution_instance = Solution()
    assert sumSubarray([1, 4, 2, 5, 3]) == solution_instance.rangeSum([1, 4, 2, 5, 3], 5, 1, 15)
def test_difficult_case():
    solution_instance = Solution()
    assert sumSubarray([1, 2, 3]) == solution_instance.rangeSum([1, 2, 3], 3, 1, 3)

