    s = s.replace(",", "")
    possibilities = []
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            x = s[:i+1]
            y = s[i+1:j+1]
            if (x.startswith("0") and len(x) > 1) or (y.startswith("0") and len(y) > 1):
                continue
            if "." in x:
                if x.count(".") > 1 or x.startswith(".") or x.endswith("."):
                    continue
            if "." in y:
                if y.count(".") > 1 or y.startswith(".") or y.endswith("."):
                    continue
            possibilities.append("({}, {})".format(x, y))
    return possibilities

