def find_possible_coordinates(s):
    s = s.replace(' ', '')
    s = s.replace(',', '')
    possibilities = []
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            x = s[:i + 1]
            y = s[i + 1:j + 1]
            if x.startswith('0') and len(x) > 1 or (y.startswith('0') and len(y) > 1):
                continue
            if '.' in x:
                if x.count('.') > 1 or x.startswith('.') or x.endswith('.'):
                    continue
            if '.' in y:
                if y.count('.') > 1 or y.startswith('.') or y.endswith('.'):
                    continue
            possibilities.append('({}, {})'.format(x, y))
    return possibilities
class Solution:

    def ambiguousCoordinates(self, s: str) -> List[str]:
        s = s[1:len(s) - 1]

        def helper(x):
            if len(x) == 1:
                return [x]
            if x[0] == '0' and x[len(x) - 1] == '0':
                return []
            if x[0] == '0':
                return ['0.' + x[1:]]
            if x[-1] == '0':
                return [x]
            else:
                local = [x]
                cur = ''
                for i in range(0, len(x) - 1):
                    cur += x[i]
                    second_portion = x[i + 1:]
                    overall = cur + '.' + second_portion
                    local.append(overall)
                return local
        ans = []
        n = len(s)
        for i in range(1, n):
            l = s[:i]
            r = s[i:]
            left_vals = helper(l)
            right_vals = helper(r)
            if not left_vals and (not right_vals):
                continue
            for l in left_vals:
                for r in right_vals:
                    new_pairing = '(' + l + ', ' + r + ')'
                    ans.append(new_pairing)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert find_possible_coordinates('(123)') == solution_instance.ambiguousCoordinates('(123)')
def test_edge_case():
    solution_instance = Solution()
    assert find_possible_coordinates('(00123)') == solution_instance.ambiguousCoordinates('(00123)')
def test_difficult_case():
    solution_instance = Solution()
    assert find_possible_coordinates('(00100123)') == solution_instance.ambiguousCoordinates('(00100123)')

