    n = len(nums1) 
    answer = [float('inf')] * n  
    answer[0] = 0
    for i in range(1,n):
        if nums1[i] > nums1[i-1] and nums2[i] > nums2[i-1]:
            answer[i] = answer[i-1]
        if nums2[i] > nums1[i-1] and nums1[i] > nums2[i-1]:
