class Solution:

    def minSwap(self, nums1: List[int], nums2: List[int]) -> int:
        dp = [[-1] * 2 for i in range(len(nums1))]

        def solve(prev1, prev2, i, swaped):
            if i >= len(nums1):
                return 0
            if dp[i][swaped] != -1:
                return dp[i][swaped]
            ans = 2 ** 31
            if nums1[i] > prev1 and nums2[i] > prev2:
                ans = solve(nums1[i], nums2[i], i + 1, 0)
            if nums1[i] > prev2 and nums2[i] > prev1:
                ans = min(ans, 1 + solve(nums2[i], nums1[i], i + 1, 1))
            dp[i][swaped] = ans
            return ans
        return solve(-1, -1, 0, 0)
def test_simple_case():
    sol_instance = Solution()
    assert minSwap([1, 3, 5, 4], [1, 2, 3, 7]) == sol_instance.minSwap([1, 3, 5, 4], [1, 2, 3, 7])
def test_edge_case():
    sol_instance = Solution()
    assert minSwap([0, 3, 5, 8], [2, 1, 4, 6]) == sol_instance.minSwap([0, 3, 5, 8], [2, 1, 4, 6])
def test_difficult_case():
    sol_instance = Solution()
    assert minSwap([1, 5, 3, 4], [2, 3, 4, 5]) == sol_instance.minSwap([1, 5, 3, 4], [2, 3, 4, 5])

