def min_rungs(rungs, dist):
    count = 0
    curr_pos = 0
    for i in range(len(rungs)):
        if rungs[i] - curr_pos <= dist:
            curr_pos = rungs[i]
        else:
            count += (rungs[i] - curr_pos - 1) // dist + 1
            curr_pos = rungs[i]
    return count

