class Solution:

    def addRungs(self, rungs: List[int], dist: int) -> int:
        rungs.insert(0, 0)
        fin = 0
        for number in range(len(rungs) - 1):
            if rungs[number + 1] - rungs[number] > dist:
                fin += (rungs[number + 1] - rungs[number] - 1) // dist
        return fin
def test_simple_case():
    solution_instance = Solution()
    assert min_rungs([1, 3, 5, 7], 2) == solution_instance.addRungs([1, 3, 5, 7], 2)
