def isAdditiveNumber(num):
    def helper(first, second, remaining):
        if not remaining:
            return True
        third = first + second
        if remaining.startswith(str(third)):
            return helper(second, third, remaining[len(str(third)):])
        return False

    for i in range(1, len(num)):
        for j in range(i+1, len(num)):
            first = num[:i]
            second = num[i:j]
            if (first.startswith('0') and len(first) > 1) or (second.startswith('0') and len(second) > 1):
                continue
            if helper(int(first), int(second), num[j:]):
                return True
    return False

