class Solution:

    def isAdditiveNumber(self, num: str) -> bool:
        n = len(num)

        def to_the_end(a, b, i):
            nonlocal n, num
            c, c_str = (a + b, str(a + b))
            c_l = len(c_str)
            while i + c_l <= n and num[i:i + c_l] == c_str:
                a, b = (b, c)
                c, c_str = (a + b, str(a + b))
                i, c_l = (i + c_l, len(c_str))
            return i == n
        for i in range(1, n):
            if i > 1 and num[0] == '0':
                break
            first = int(num[:i])
            for j in range(i + 1, n):
                if j > i + 1 and num[i] == '0':
                    break
                second = int(num[i:j])
                if to_the_end(first, second, j):
                    return True
        return False
def test_simple_case():
    solution_instance = Solution()
    assert isAdditiveNumber('112358') == solution_instance.isAdditiveNumber('112358')
def test_edge_case():
    solution_instance = Solution()
    assert isAdditiveNumber('1991001101') == solution_instance.isAdditiveNumber('1991001101')
def test_difficult_case():
    solution_instance = Solution()
    assert isAdditiveNumber('123') == solution_instance.isAdditiveNumber('123')

