class Solution:

    def nthMagicalNumber(self, n: int, a: int, b: int) -> int:

        def gcd(x, y):
            if x == 0:
                return y
            return gcd(y % x, x)
        lcm = a * b // gcd(a, b)
        s = set()
        x = a
        while x <= lcm:
            s.add(x)
            x += a
        x = b
        while x <= lcm:
            s.add(x)
            x += b
        le = 0
        l = []
        for i in s:
            l.append(i)
            le += 1
        l.sort()
        r = n % le
        q = n // (le + 1)
        if q == 0:
            return l[n - 1]
        else:
            q = n // le
            res = q * l[-1] % 1000000007
            if r > 0:
                res = (res + l[r - 1]) % 1000000007
            return res
def test_simple_case():
    first_instance = First_class()
