        neg = []
        res = []
        for i in nums:
            if i > 0:
                pos.append(i)
            else:
                neg.append(i)
        for j in range(len(nums)):
            if j < len(pos):
                res.append(pos[j])
            if j < len(neg):
                res.append(neg[j])
        return res
