class Solution:

    def maxScoreIndices(self, nums: List[int]) -> List[int]:
        t1 = [0]
        t2 = [0] * (len(nums) + 1)
        for i in nums:
            if not t1:
                t1.append(0)
            elif i == 0:
                t1.append(t1[-1] + 1)
            else:
                t1.append(t1[-1])
        for i in range(len(nums) - 1, -1, -1):
            t2[i] = nums[i] + t2[i + 1]
        ans = []
        for i in range(len(t1)):
            ans.append((t1[i] + t2[i], i))
        ans.sort(reverse=True)
        ans1 = ans[0][0]
        t = []
        for i in ans:
            if i[0] == ans1:
                t.append(i[1])
        return t
def test_simple_case():
    sol_instance = Solution()
    nums = [0, 0, 1, 0, 1, 0, 0, 1]
    assert division_score(nums) == sol_instance.maxScoreIndices(nums)
