class Solution:

    def maximumSwap(self, num: int) -> int:
        high_digit = high_pos = 0
        low_digit = low_pos = 0
        cur_high_digit, cur_high_pos = (-1, 0)
        pos = 1
        res = num
        while num:
            digit = num % 10
            if digit > cur_high_digit:
                cur_high_digit, cur_high_pos = (digit, pos)
            elif digit < cur_high_digit:
                high_digit, high_pos = (cur_high_digit, cur_high_pos)
                low_digit, low_pos = (digit, pos)
            pos *= 10
            num //= 10
        res += high_digit * (low_pos - high_pos) + low_digit * (high_pos - low_pos)
        return res
def test_simple_case():
    solution_instance = Solution()
    assert swap(2736) == solution_instance.maximumSwap(2736)
def test_edge_case():
    solution_instance = Solution()
    assert swap(9973) == solution_instance.maximumSwap(9973)
def test_difficult_case():
    solution_instance = Solution()
    assert swap(0) == solution_instance.maximumSwap(0)

