class Solution:

    def longestPalindrome(self, words: List[str]) -> int:
        dict_2 = {}
        d = {}
        count = 0
        for i in range(0, len(words)):
            if words[i] not in d:
                d.update({words[i]: 1})
            elif words[i] in d:
                d[words[i]] += 1
        for k, v in d.items():
            if k[0] == k[1]:
                dict_2.update({k: v})
        for key in dict_2.keys():
            del d[key]
        if len(dict_2) > 1:
            odd_counter = 0
            for k, v in dict_2.items():
                if dict_2[k] % 2 != 0:
                    odd_counter += 1
            if odd_counter > 1:
                max_odd_val = 0
                for k, v in dict_2.items():
                    if dict_2[k] % 2 == 0:
                        count += 2 * dict_2[k]
                    elif max_odd_val < dict_2[k]:
                        max_odd_val = dict_2[k]
                pass_count = 0
                for k, v in dict_2.items():
                    if dict_2[k] == max_odd_val and pass_count == 0:
                        count += 2 * max_odd_val
                        pass_count += 1
                    elif dict_2[k] % 2 != 0 or (dict_2[k] == max_odd_val and pass_count != 0):
                        count += 2 * dict_2[k] - 2
            elif odd_counter == 1:
                for k, v in dict_2.items():
                    count += 2 * dict_2[k]
            elif odd_counter == 0:
                for k, v in dict_2.items():
                    count += 2 * dict_2[k]
        else:
            for k, v in dict_2.items():
                count += 2 * dict_2[k]
        for k1, v1 in d.items():
            for k2, v2 in d.items():
                if k1[0] == k2[1] and k1[1] == k2[0]:
                    while d[k1] > 0 and d[k2] > 0:
                        d[k1] -= 1
                        d[k2] -= 1
                        count += 4
        return count
