class Solution:

    def checkAlmostEquivalent(self, word1: str, word2: str) -> bool:
        d1 = {}
        d2 = {}
        for i in word1:
            if i in d1:
                d1[i] += 1
            else:
                d1[i] = 1
        for i in word2:
            if i in d2:
                d2[i] += 1
            else:
                d2[i] = 1
        for i in d1.keys():
            if i in d2:
                if not abs(d2[i] - d1[i]) <= 3:
                    return False
            elif not d1[i] <= 3:
                return False
        for i in d2.keys():
            if i not in d1:
                if not d2[i] <= 3:
                    return False
        return True
def test_simple_case():
