solution_code:
def capture_surrounded_regions(board):
    def dfs(i, j):
        if 0 <= i < m and 0 <= j < n and board[i][j] == 'O':
            # Mark as visited
            board[i][j] = '#'
            dfs(i + 1, j)  # Down
            dfs(i - 1, j)  # Up
            dfs(i, j + 1)  # Right
            dfs(i, j - 1)  # Left

    if not board:  # Edge case
        return

    m, n = len(board), len(board[0])

    # First and last rows
    for i in range(n):
        if board[0][i] == 'O':
            dfs(0, i)
        if board[m - 1][i] == 'O':
            dfs(m - 1, i)

    # First and last columns
    for i in range(m):
        if board[i][0] == 'O':
            dfs(i, 0)
        if board[i][n - 1] == 'O':
            dfs(i, n - 1)

    # Flip regions
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == '#':
                board[i][j] = 'O'

