            dfs(i - 1, j)
            dfs(i, j + 1)
            dfs(i, j - 1)
    if not board:
        return
    m, n = (len(board), len(board[0]))
    for i in range(n):
        if board[0][i] == 'O':
            dfs(0, i)
        if board[m - 1][i] == 'O':
            dfs(m - 1, i)
    for i in range(m):
        if board[i][0] == 'O':
            dfs(i, 0)
        if board[i][n - 1] == 'O':
            dfs(i, n - 1)
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == '#':
                board[i][j] = 'O'
class UF:

    def __init__(self, n):
        self.parent = [i for i in range(n)]
        self.size = [1 for i in range(n)]
        self.count = n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, p, q):
        p_root = self.find(p)
        q_root = self.find(q)
        if q_root == p_root:
            return
        if self.size[p_root] > self.size[q_root]:
            self.parent[q_root] = p_root
            self.size[p_root] += self.size[q_root]
        else:
            self.parent[p_root] = q_root
            self.size[q_root] += p_root
        self.count -= 1

    def connected(self, p, q):
        return self.find(p) == self.find(q)

    def count():
        return self.count
class Solution:

    def solve(self, board: List[List[str]]) -> None:
        """
        Do not return anything, modify board in-place instead.
        """
        if len(board) == 0:
            return
        m = len(board)
        n = len(board[0])
        uf = UF(m * n + 1)
        dummy = m * n
        for i in range(0, m):
            if board[i][0] == 'O':
                uf.union(i * n, dummy)
                print(uf.connected(i * n, dummy))
            if board[i][n - 1] == 'O':
                uf.union(i * n + n - 1, dummy)
                print(uf.connected(i * n + n - 1, dummy))
        for j in range(0, n):
            if board[0][j] == 'O':
                uf.union(j, dummy)
                print(uf.connected(j, dummy))
            if board[m - 1][j] == 'O':
                uf.union(n * (m - 1) + j, dummy)
                print(uf.connected(n * (m - 1) + j, dummy))
        d = [[1, 0], [-1, 0], [0, 1], [0, -1]]
        for i in range(1, m - 1):
            for j in range(1, n - 1):
                if board[i][j] == 'O':
                    for k in range(4):
                        x = i + d[k][0]
                        y = j + d[k][1]
                        if board[x][y] == 'O':
                            uf.union(i * n + j, x * n + y)
        for i in range(1, m - 1):
            for j in range(1, n - 1):
                if not uf.connected(dummy, i * n + j):
                    board[i][j] = 'X'
def test_simple_case():
    board1 = [['X', 'X', 'X', 'X'], ['X', 'O', 'O', 'X'], ['X', 'X', 'O', 'X'], ['X', 'O', 'X', 'X']]
    board2 = [['X', 'X', 'X', 'X'], ['X', 'O', 'O', 'X'], ['X', 'X', 'O', 'X'], ['X', 'O', 'X', 'X']]
    Solution().solve(board2)
    capture_surrounded_regions(board1)
    assert board1 == board2
def test_edge_case():
    board1 = [['X', 'O', 'X', 'O', 'X', 'O'], ['O', 'X', 'O', 'X', 'O', 'X'], ['X', 'O', 'X', 'O', 'X', 'O'], ['O', 'X', 'O', 'X', 'O', 'X']]
    board2 = [['X', 'O', 'X', 'O', 'X', 'O'], ['O', 'X', 'O', 'X', 'O', 'X'], ['X', 'O', 'X', 'O', 'X', 'O'], ['O', 'X', 'O', 'X', 'O', 'X']]
    Solution().solve(board2)
    capture_surrounded_regions(board1)
    assert board1 == board2
def test_difficult_case():
    board1 = [['O', 'O', 'O'], ['O', 'O', 'O'], ['O', 'O', 'O']]
    board2 = [['O', 'O', 'O'], ['O', 'O', 'O'], ['O', 'O', 'O']]
