class Solution:

    def removeDuplicates(self, s: str, k: int) -> str:
        count, stack = ([], [])
        for ch in s:
            if stack == [] or stack[-1] != ch:
                stack.append(ch)
                count.append(1)
            else:
                n = count.pop()
                count.append(n + 1)
            if count[-1] == k:
                count.pop()
                stack.pop()
        res = ''
        while stack != []:
            ch = stack.pop()
            cnt = count.pop()
            while cnt != 0:
                res = ch + res
                cnt -= 1
        return res
