    assert findRightInterval(intervals) == solution_instance.findRightInterval(intervals)
def test_difficult_case():
    solution_instance = Solution()
    intervals = [[-1, 1]]
    assert findRightInterval(intervals) == solution_instance.findRightInterval(intervals)

