    solution_instance = Solution()
    assert beautiful_substring('aeeeiiioouu') == solution_instance.longestBeautifulSubstring('aeeeiiioouu')
def test_difficult_case():
    solution_instance = Solution()
    assert beautiful_substring('aaeeiioouuaa') == solution_instance.longestBeautifulSubstring('aaeeiioouuaa')

