def multi_key_quicksort(a):
    if len(a) <= 1:
        return a

    pivots = [], [], []
    pivot = a[0]
    for x in a:
        if x < pivot:
            pivots[0].append(x)
        elif x == pivot:
            pivots[1].append(x)
        else:
            pivots[2].append(x)

    return \
        multi_key_quicksort(pivots[0]) \
        + pivots[1] \
        + multi_key_quicksort(pivots[2])

# Example usage:
a = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]
a = multi_key_quicksort(a)
print(a)

