from math import *

def find_missing_rolls(rolls, mean, n):
    total_sum = mean * (n + len(rolls)) - sum(rolls)
    if total_sum % n != 0:
        return []
    else:
        missing_sum = total_sum // n
        missing_rolls = []
        for i in range(1, n + 1):
            if i not in rolls:
                missing_rolls.append(missing_sum - i + sum(rolls) // len(rolls))
        return missing_rolls
class Solution:

    def missingRolls(self, rolls: List[int], mean: int, n: int) -> List[int]:
        m = len(rolls)
        average = mean * (m + n) - sum(rolls)
        if average > 6 * n or average < n:
            return []
        ans = [average // n for i in range(n)]
        reminder = average % n
        for i in range(reminder):
            ans[i] += 1
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert find_missing_rolls([4, 5, 7], 5, 2) == solution_instance.missingRolls([4, 5, 7], 5, 2)
