def circularArray(nums):
    n = len(nums)
    visited = [False for _ in range(n)]
    for i in range(n):
        if not visited[i]:
            cycle = set()
            while i not in cycle:
                cycle.add(i)
                visited[i] = True
                i = (i + nums[i]) % n
            if len(cycle) > 1:
                return True
    return False

