from typing import *
from collections import *
from math import *

def circularArray(nums):
    n = len(nums)
    visited = [False for _ in range(n)]
    for i in range(n):
        if not visited[i]:
            cycle = set()
            while i not in cycle:
                cycle.add(i)
                visited[i] = True
                i = (i + nums[i]) % n
            if len(cycle) > 1:
                return True
    return False
class Solution:

    def circularArrayLoop(self, nums: List[int]) -> bool:
        """
            Bruteforce Solution with some improvement
        """
        size = len(nums)
        visited = [False] * size
        v = 0
        cycle_idx = 0
        i = 0
        while i < size:
            if visited[i]:
                i += 1
                continue
            v = i
            cycle_idx = 0
            for j in range(size):
                visited[v] = True
                v = (v + nums[v]) % size
                if visited[v]:
                    cycle_idx = v
            v = cycle_idx
            cycle_len = 0
            if nums[v] > 0:
                sign = 1
            else:
                sign = -1
            flag_nxt = False
            while True:
                cycle_len += 1
                if sign == 1 and nums[v] < 0:
                    flag_nxt = True
                    break
                if sign == -1 and nums[v] > 0:
                    flag_nxt = True
                    break
                v = (v + nums[v]) % size
                if v == cycle_idx:
                    break
            i += 1
            if flag_nxt:
                continue
            if cycle_len > 1:
                return True
        return False
def test_simple_case():
    nums = [2, -1, 1, 2, 2]
    sol_instance = Solution()
    assert circularArray(nums) == sol_instance.circularArrayLoop(nums)
def test_edge_case():
    nums = [-1, -2, -3, -4, -5]
    sol_instance = Solution()
    assert circularArray(nums) == sol_instance.circularArrayLoop(nums)
def test_difficult_case():
    nums = [3, 1, 2, -3, -2, 4, -1]
    sol_instance = Solution()
    assert circularArray(nums) == sol_instance.circularArrayLoop(nums)

