def min_operations(n):
    arr = [2 * i + 1 for i in range(n)]
    avg = sum(arr) // n
    operations = 0
    for i in range(n):
        operations += abs(arr[i] - avg)
    return operations // 2
class Solution:

    def __init__(self):
        self.even_cache = [1]
        self.odd_cache = [2]

    def minOperations(self, n: int) -> int:
        if n == 1:
            return 0
        '\n        1, 3: 1 (even)\n        1, 3, 5: 2                                            (odd)\n        1, 3, 5, 7: 1 + 3 = 4 (even)\n        1, 3, 5, 7, 9: 2 + 4 = 6                              (odd)\n        1, 3, 5, 7, 9, 11: 1 + 3 + 5 = 9 (even)\n        1, 3, 5, 7, 9, 11, 13: 2 + 4 + 6 = 12                 (odd)\n        1, 3, 5, 7, 9, 11, 13, 15: 1 + 3 + 5 + 7 = 16 (even)\n        ...\n        '

        def get_odd_cache(i):
            while len(self.odd_cache) <= i:
                self.odd_cache.append(self.odd_cache[-1] + (len(self.odd_cache) + 1) * 2)
            return self.odd_cache[i]

        def get_even_cache(i):
            while len(self.even_cache) <= i:
                self.even_cache.append(self.even_cache[-1] + (len(self.even_cache) * 2 + 1))
            return self.even_cache[i]
        d, r = divmod(n, 2)
        if r == 0:
            return get_even_cache(d - 1)
        else:
            return get_odd_cache(d - 1)
def test_even_case():
    solution_instance = Solution()
    assert min_operations(4) == solution_instance.minOperations(4)
def test_odd_case():
    solution_instance = Solution()
    assert min_operations(5) == solution_instance.minOperations(5)
def test_large_case():
    solution_instance = Solution()
    assert min_operations(10) == solution_instance.minOperations(10)

