from collections import *
from math import *

def minimumMoves(target: int, numMoves: int) -> int:
    if target == 0:
        return 0
    if abs(target) <= numMoves:
        return 1
    else:
        max_distance = numMoves * (numMoves + 1) // 2
        if target % 2 == max_distance % 2:
            return numMoves
        else:
            return numMoves + 1
class Solution:

    def reachNumber(self, target: int) -> int:

        def gaussSum(n):
            return n * (n + 1) // 2

        def binaryFind(lower, upper):
            t = abs(target)
            sums, n = (-1, -1)
            while lower <= upper:
                mid = (lower + upper) // 2
                if gaussSum(mid) >= t:
                    sums, n = (gaussSum(mid), mid)
                    upper = mid - 1
                else:
                    lower = mid + 1
            return (sums, n)
        lower, upper = (0, 10 ** 5)
        sums, n = binaryFind(lower, upper)
        while sums % 2 != abs(target) % 2:
            sums += n + 1
            n += 1
        return n
def test_simple_case():
    solution_instance = Solution()
    assert minimumMoves(2, 0) == solution_instance.reachNumber(2)
def test_edge_case():
    solution_instance = Solution()
    assert minimumMoves(-7, 0) == solution_instance.reachNumber(-7)
def test_difficult_case():
    solution_instance = Solution()
    assert minimumMoves(10, 0) == solution_instance.reachNumber(10)

