class Solution:

    def peakIndexInMountainArray(self, arr: List[int]) -> int:
        l, h = (0, len(arr) - 1)
        while l <= h:
            mid = (l + h) // 2
            if mid == 0:
                mid = 1
            middle = arr[mid]
            if middle > arr[mid - 1] and middle > arr[mid + 1]:
                return mid
            elif arr[mid - 1] < middle < arr[mid + 1]:
                l = mid + 1
                continue
            else:
                h = mid - 1
                continue
def test_simple_mountain_array():
