def is_X_matrix(grid):
    n = len(grid)
    # Check if diagonals have non-zero elements
    for i in range(n):
        if grid[i][i] == 0:
            return False
        if grid[i][n-i-1] == 0:
            return False
    # Check if non-diagonal elements are zero
    for i in range(n):
        for j in range(n):
            if i != j and i != n-j-1:
                if grid[i][j] != 0:
                    return False
    # If all conditions are met, return True
    return True

