    n = len(grid)
    for i in range(n):
        if grid[i][i] == 0:
            return False
        if grid[i][n - i - 1] == 0:
            return False
    for i in range(n):
        for j in range(n):
            if i != j and i != n - j - 1:
                if grid[i][j] != 0:
                    return False
    return True
class Solution:

    def checkXMatrix(self, grid: List[List[int]]) -> bool:
        firstDiagnol = 0
        secondDiagnol = 0
        remaining = 0
        m, n = (len(grid), len(grid[0]))
        for i in range(m):
            if grid[i][i] != 0:
                firstDiagnol += 1
        for i in range(m):
            if grid[i][n - i - 1] != 0:
                secondDiagnol += 1
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    remaining += 1
        if n % 2 == 0:
            return firstDiagnol == n and secondDiagnol == n and (remaining == n ** 2 - 2 * n)
        else:
            return firstDiagnol == n and secondDiagnol == n and (remaining == n ** 2 - (2 * n - 1))
def test_simple_case():
    solution_instance = Solution()
    grid = [[2, 0, 0, 1], [0, 3, 1, 0], [0, 5, 2, 0], [4, 0, 0, 2]]
    assert is_X_matrix(grid) == solution_instance.checkXMatrix(grid)
def test_edge_case():
    solution_instance = Solution()
    grid = [[5, 7, 0], [0, 3, 1], [0, 5, 0]]
    assert is_X_matrix(grid) == solution_instance.checkXMatrix(grid)
def test_difficult_case():
    solution_instance = Solution()
    grid = [[1]]
    assert is_X_matrix(grid) == solution_instance.checkXMatrix(grid)

