class Solution:

    def balancedStringSplit(self, s: str) -> int:
        """
        Time complexity : O(n)
        Space complexity : O(1)

        The idea is simple.
        1) Maintain three counters to count left, right, count value. 
        2) Start counting from the start of the string and count the no of left and right encountered.
        3) When the left and right count equals , that means it can now be splitted.
        4) So, instead of splitting and consuming extra memory , just increase the count
        5) Return count

        """
        rc = lc = cnt = 0
        for i in s:
            if i == 'R':
                rc += 1
            elif i == 'L':
                lc += 1
            if lc == rc:
                cnt += 1
        return cnt
def test_simple_case():
    solution_instance = Solution()
    assert balanced_substrings('RLRRLLRLRL') == solution_instance.balancedStringSplit('RLRRLLRLRL')
def test_edge_case():
    solution_instance = Solution()
    assert balanced_substrings('RLLLLRRRRR') == solution_instance.balancedStringSplit('RLLLLRRRRR')
def test_difficult_case():
    solution_instance = Solution()
    assert balanced_substrings('RLRRRRLLRLRRRLLRRL') == solution_instance.balancedStringSplit('RLRRRRLLRLRRRLLRRL')

