def imageSmoother(img):
    m, n = len(img), len(img[0])
    res = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            summ, cnt = 0, 0
            for r in range(max(0, i-1), min(m, i+2)):
                for c in range(max(0, j-1), min(n, j+2)):
                    summ += img[r][c]
                    cnt += 1
            res[i][j] = summ // cnt
    return res

