def selfDividingNumbers(left, right):
    res = []
    for num in range(left, right+1):
        if '0' in str(num):
            continue
        temp = num
        is_self_dividing = True
        while temp > 0:
            digit = temp % 10
            if num % digit != 0:
                is_self_dividing = False
                break
            temp //= 10
        if is_self_dividing:
            res.append(num)
    return res

