def count_special(nums):
    nums.sort(reverse=True)
    for i, x in enumerate(nums):
        if i + 1 >= x:
            return x
    return -1
class Solution:

    def specialArray(self, nums: List[int]) -> int:

        def binary_search(e, a):
            L, R = (0, len(a) - 1)
            while L <= R:
                mid = (L + R) // 2
                middle = a[mid]
                if middle > e:
                    R = mid - 1
                    continue
                elif middle < e:
                    L = mid + 1
                    continue
                else:
                    R = mid - 1
                    continue
            return L
        nums.sort()
        for i in range(1, len(nums) + 1):
            index = binary_search(i, nums)
            number_greater = len(nums) - index
            if number_greater == i:
                return i
        return -1
def test_regular_case():
    solution_instance = Solution()
    assert count_special([3, 5]) == solution_instance.specialArray([3, 5])
def test_no_special_case():
    solution_instance = Solution()
    assert count_special([3, 4]) == solution_instance.specialArray([3, 4])
def test_special_case():
    solution_instance = Solution()
    assert count_special([0, 0]) == solution_instance.specialArray([0, 0])

