def is_strictly_palindromic(n):
    for b in range(2, n):
        num_in_base_b = ''
        num = n
        while num > 0:
            num_in_base_b += str(num % b)
            num //= b
        if num_in_base_b != num_in_base_b[::-1]:
            return False
    return True

