class Solution:

    def solve(self, n, i):
        sign = '-' if n < 0 else ''
        n = abs(n)
        if n < i:
            return str(n)
        s = ''
        while n != 0:
            s = str(n % i) + s
            n = n // i
        return sign + s

    def isStrictlyPalindromic(self, n: int) -> bool:
        for i in range(2, n - 1):
            check = self.solve(n, i)
            print(check)
            if check == n:
                return False
            elif check[::-1] != check:
                return False
