def findLUSlength(strs: List[str]) -> int:

    def is_subsequence(s: str, t: str) -> bool:
        i = 0
        for c in t:
            if i < len(s) and s[i] == c:
                i += 1
        return i == len(s)
    strs.sort(key=len, reverse=True)
