class Solution:

    def findLUSlength(self, strs: List[str]) -> int:
        mem = dict()
        for s in strs:
            if len(s) not in mem:
                mem[len(s)] = list()
            mem[len(s)].append(s)
        mem = sorted(list(mem.items()), key=lambda x: x[0], reverse=True)

        def check(s1, s2):
            i, j = (0, 0)
            while i < len(s1) and j < len(s2):
                if s1[i] == s2[j]:
                    j += 1
                i += 1
            return j == len(s2)
        failed = list()
        for length, strings in mem:
            for s in strings:
                if strings.count(s) > 1:
                    failed.append(s)
                    continue
                is_ok = True
                for s1 in failed:
                    if check(s1, s):
                        is_ok = False
                        failed.append(s)
                        break
                if is_ok:
                    return length
        return -1
def test_simple_case():
    solution_instance = Solution()
    assert findLUSlength(['aba', 'cdc', 'eae']) == solution_instance.findLUSlength(['aba', 'cdc', 'eae'])
def test_edge_case():
    solution_instance = Solution()
    assert findLUSlength(['aaa', 'aaa', 'aa']) == solution_instance.findLUSlength(['aaa', 'aaa', 'aa'])
def test_difficult_case():
    solution_instance = Solution()
    assert findLUSlength(['aabbaba', 'aabbaba', 'aabbaba', 'aabbaba', 'aabbaba']) == solution_instance.findLUSlength(['aabbaba', 'aabbaba', 'aabbaba', 'aabbaba', 'aabbaba'])

