    while sum(piles) > 0:
        x = 1
        if is_alice_turn:
            while x <= 2*M:
                if sum(piles[:x]) % 2 == 1:
                    alice_stones += sum(piles[:x])
                    piles = piles[x:]
                    break
                x += 1
            if x > 2*M:
                alice_stones += piles[0]
                piles = piles[1:]
        else:
            while x <= 2*M:
                if sum(piles[:x]) % 2 == 1:
                    bob_stones += sum(piles[:x])
                    piles = piles[x:]
                    break
                x += 1
            if x > 2*M:
                bob_stones += piles[0]
                piles = piles[1:]
        M = max(M, x)
        is_alice_turn = not is_alice_turn
    return alice_stones

