def xor_queries(arr, queries):
    answer = []
    for query in queries:
        left = query[0]
        right = query[1]
        xor_sum = arr[left]
        for i in range(left+1, right+1):
            xor_sum ^= arr[i]
        answer.append(xor_sum)
    return answer

