def removeElements(nums):
    steps = 0
    i = 1
    while i < len(nums):
        if nums[i - 1] > nums[i]:
            nums.pop(i - 1)
            steps += 1
        else:
            i += 1
    return steps
class Solution:

    def totalSteps(self, nums: List[int]) -> int:
        n = len(nums)
        l = [i - 1 for i in range(n)]
        r = [i + 1 for i in range(n)]
        q = []
        dist = dict()
        ans = 0
        for i in range(1, n):
            if nums[i] < nums[i - 1]:
                q.append(i)
                dist[i] = 1
                ans = 1
        while len(q) != 0:
            u = q.pop(0)
            ans = max(ans, dist[u])
            if r[u] < n:
                l[r[u]] = l[u]
            if l[u] > -1:
                r[l[u]] = r[u]
            if r[u] not in dist and r[u] < n and (nums[r[u]] < nums[l[u]]):
                dist[r[u]] = dist[u] + 1
                q.append(r[u])
        return ans
def test_simple_case():
    solution_instance = Solution()
    nums = [5, 7, 1, 8]
    assert removeElements(nums[:]) == solution_instance.totalSteps(nums)
def test_edge_case():
    solution_instance = Solution()
    nums = [1, 2, 3]
    assert removeElements(nums[:]) == solution_instance.totalSteps(nums)
def test_difficult_case():
    solution_instance = Solution()
    nums = [8, 6, 5, 10, 2]
    assert removeElements(nums[:]) == solution_instance.totalSteps(nums)

