def minHours(initialEnergy: int, initialExperience: int, energy: List[int], experience: List[int]) -> int:
    n = len(energy)
    dp = [[float('inf')] * (initialExperience+1) for _ in range(initialEnergy+1)]
    dp[initialEnergy][initialExperience] = 0

    for i in range(n):
        for currEnergy in range(initialEnergy+1):
            for currExp in range(initialExperience+1):
                if currEnergy >= energy[i] and currExp >= experience[i]:
                    dp[currEnergy-energy[i]][currExp-experience[i]] = min(dp[currEnergy-energy[i]][currExp-experience[i]], dp[currEnergy][currExp]+1)
                dp[currEnergy][min(currExp+experience[i], initialExperience)] = min(dp[currEnergy][min(currExp+experience[i], initialExperience)], dp[currEnergy][currExp]+1)
                dp[min(currEnergy+energy[i], initialEnergy)][currExp] = min(dp[min(currEnergy+energy[i], initialEnergy)][currExp], dp[currEnergy][currExp]+1)

    res = float('inf')
    for i in range(initialEnergy+1):
        for j in range(initialExperience+1):
            res = min(res, dp[i][j])
    return res

