class Solution:

    def numberOfBeams(self, bank: List[str]) -> int:
        num_of_lasers = 0
        prev_one_count = 0
        for row in bank:
            one_count = 0
            for num in row:
                if num == '1':
                    one_count += 1
            if one_count == 0:
                continue
            if prev_one_count == 0:
                prev_one_count = one_count
                continue
            num_of_lasers += one_count * prev_one_count
            prev_one_count = one_count
        return num_of_lasers
def test_sample_input():
    solution_instance = Solution()
    bank = ['000', '111', '000', '000']
    assert count_laser_beams(bank) == solution_instance.numberOfBeams(bank)
