class Solution:

    def findOcurrences(self, text: str, first: str, second: str) -> List[str]:
        newstr = text.split(' ')
        prev = newstr[0]
        result = []
        correct = False
        for i in range(1, len(newstr)):
            if correct:
                result.append(newstr[i])
                correct = False
            if prev == first and newstr[i] == second:
                correct = True
            prev = newstr[i]
        return result
def test_simple_case():
