def is_digit_frequency_valid(num):
    n = len(num)
    for i in range(n):
        if num.count(str(i)) != int(num[i]):
            return False
    return True
class Solution:

    def digitCount(self, num: str) -> bool:
        d = dict()
        n = len(num)
        for char in num:
            if char in d:
                d[char] += 1
            else:
                d[char] = 1
        for i in range(n):
            val, freq = (str(i), int(num[i]))
            if val in d:
                if d[val] != freq:
                    return False
            elif freq > 0:
                return False
        return True
def test_simple_case():
    solution_instance = Solution()
    assert is_digit_frequency_valid('1210') == solution_instance.digitCount('1210')
