class Solution:

    def makeFancyString(self, s: str) -> str:
        stack = []
        curr_count = 1
        deletion = 0
        stack.append(s[0])
        for i in range(1, len(s)):
            if stack[len(stack) - 1] == s[i]:
                if curr_count == 2:
                    continue
                else:
                    stack.append(s[i])
                    curr_count += 1
            elif stack[len(stack) - 1] != s[i]:
                stack.append(s[i])
                curr_count = 1
        s = ''.join(stack)
        return s
