def get_unique_integers(digits, digit):
    result = set()
    str_digit = str(digit)
    for i in range(len(digits)):
        for j in range(len(digits)):
            for k in range(len(digits)):
                if i != j and i != k and j != k:
                    num_str = str(digits[i]) + str(digits[j]) + str(digits[k])
                    if num_str.startswith(str_digit) and int(num_str) % 2 == 0:
                        result.add(int(num_str))
    return sorted(result)

