    solution_instance = Solution()
    assert get_unique_integers([2, 2, 2, 2], 2) == solution_instance.findEvenNumbers([2, 2, 2, 2])
def test_difficult_case():
    solution_instance = Solution()
    assert get_unique_integers([1, 1, 2], 1) == solution_instance.findEvenNumbers([1, 1, 2])

