def numberOfSubarrays(nums, k):
    odd_count = 0
    count = 0
    freq = {0: 1}
    for num in nums:
        if num % 2 == 1:
            odd_count += 1
        if odd_count >= k:
            count += freq[odd_count - k]
        freq[odd_count] = freq.get(odd_count, 0) + 1
    return count

