class Solution:

    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        counter = {0: 1}
        res = 0
        odd_count = 0
        for i in range(len(nums)):
            if nums[i] % 2 != 0:
                odd_count += 1
            if odd_count - k in counter:
                res += counter[odd_count - k]
            counter[odd_count] = counter.get(odd_count, 0) + 1
        return res
def test_simple_case():
