from typing import *
from collections import *
from math import *

def minAbsoluteSumDiff(nums1, nums2):
    n = len(nums1)
    mod = 10 ** 9 + 7
    sum_diff = 0
    max_diff = 0
    max_index = 0
    for i in range(n):
        diff = abs(nums1[i] - nums2[i])
        sum_diff = (sum_diff + diff) % mod
        if diff > max_diff:
            max_diff = diff
            max_index = i
    for i in range(n):
        diff = abs(nums1[i] - nums2[max_index])
        new_sum_diff = (sum_diff - abs(nums1[max_index] - nums2[max_index]) + diff) % mod
        if new_sum_diff < sum_diff:
            nums1[i] = nums2[max_index]
            sum_diff = new_sum_diff
    return sum_diff
class Solution:

    def minAbsoluteSumDiff(self, nums1: List[int], nums2: List[int]) -> int:
        snums1 = sorted(nums1)

        def find_closest_abs_diff(arr, n, target):
            if target <= arr[0]:
                return arr[0]
            if target >= arr[n - 1]:
                return arr[n - 1]
            i = 0
            j = n
            mid = 0
            while i < j:
                mid = (i + j) // 2
                if arr[mid] == target:
                    return arr[mid]
                if target < arr[mid]:
                    if mid > 0 and target > arr[mid - 1]:
                        return getClosest(arr[mid - 1], arr[mid], target)
                    j = mid
                else:
                    if mid < n - 1 and target < arr[mid + 1]:
                        return getClosest(arr[mid], arr[mid + 1], target)
                    i = mid + 1
            return arr[mid]

        def getClosest(val1, val2, target):
            if target - val1 >= val2 - target:
                return val2
            else:
                return val1
        absdiffarr = [abs(nums1[idx] - nums2[idx]) for idx in range(len(nums1))]
        absdiff = sum(absdiffarr)
        output = float('inf')
        for idx in range(len(nums1)):
            change = find_closest_abs_diff(snums1, len(nums1), nums2[idx])
            output = min(output, absdiff - absdiffarr[idx] + abs(change - nums2[idx]))
        return output % (10 ** 9 + 7)
def test_simple_case():
    nums1 = [1, 2, 3, 4]
    nums2 = [2, 1, 3, 4]
    instance = Solution()
    assert minAbsoluteSumDiff(nums1, nums2) == instance.minAbsoluteSumDiff(nums1, nums2)
def test_edge_case():
    nums1 = [1, 2, 3, 4]
    nums2 = [4, 3, 2, 1]
    instance = Solution()
    assert minAbsoluteSumDiff(nums1, nums2) == instance.minAbsoluteSumDiff(nums1, nums2)
def test_difficult_case():
    nums1 = [3, 4, 5, 6, 7, 8]
    nums2 = [7, 5, 6, 4, 3, 2]
    instance = Solution()
    assert minAbsoluteSumDiff(nums1, nums2) == instance.minAbsoluteSumDiff(nums1, nums2)

