class Solution:

    def numDifferentIntegers(self, word: str) -> int:
        n = len(word)
        start, end = (0, 0)
        stringset = set()

        def remove_zeros(string):
            m = len(string)
            i = 0
            while i <= m - 1 and string[i] == '0':
                i += 1
            return string[i:]
        while start <= end and end <= n - 1:
            if word[start].isalpha():
                end += 1
            else:
                end = start
                while end <= n - 1 and (not word[end].isalpha()):
                    end += 1
                stringset.add(remove_zeros(word[start:end]))
            start = end
        return len(stringset)
def test_simple_case():
    solution_instance = Solution()
    assert replace_non_digits('a123bc34d8ef34') == solution_instance.numDifferentIntegers('a123bc34d8ef34')
