def solve(n):
    digits = list(str(n))
    length = len(digits)
    for i in range(length - 1, 0, -1):
        if digits[i] < digits[i - 1]:
            digits[i - 1] = str(int(digits[i - 1]) - 1)
            for j in range(i, length):
                digits[j] = '9'
    return int(''.join(digits))

