class Solution:

    def monotoneIncreasingDigits(self, N: int) -> int:
        N = str(N)
        cur = last = 0
        while cur < len(N) - 1 and int(N[cur]) <= int(N[cur + 1]):
            if int(N[cur]) != int(N[cur + 1]):
                last = cur + 1
            cur += 1
        if cur == len(N) - 1:
            return int(N)
        s1 = '' if last == 0 else str(int(N[:last]))
        s2 = str(int(N[last]) - 1)
        s3 = (len(N) - last - 1) * '9'
        return int(s1 + s2 + s3)
def test_simple_case():
    solution_instance = Solution()
    assert solve(1234567) == solution_instance.monotoneIncreasingDigits(1234567)
def test_edge_case():
    solution_instance = Solution()
    assert solve(10) == solution_instance.monotoneIncreasingDigits(10)
def test_difficult_case():
    solution_instance = Solution()
    assert solve(332) == solution_instance.monotoneIncreasingDigits(332)

