def reverseWords(s):
    return ' '.join(reversed(s.split()))
class Solution:

    def reverseWords(self, s: str) -> str:
        t, res = ('', [])
        s += ' '
        i = 0
        while i < len(s):
            ele = s[i]
            if ele != ' ':
                t += ele
                i += 1
            else:
                res.append(t)
                t = ''
                while i < len(s) - 1 and s[i + 1] == ' ':
                    i += 1
                i += 1
        if res[0] == '':
            res = res[1:]
        return ' '.join(res[::-1])
