def max_diff(num):

    def apply_op(n, x, y):
        n_lst = list(str(n))
        for i in range(len(n_lst)):
            if n_lst[i] == str(x):
                n_lst[i] = str(y)
        if n_lst[0] == '0':
            n_lst[0] = '1'
        return int(''.join(n_lst))
    a = [apply_op(num, x, y) for x in range(10) for y in range(10) if x != y]
