class Solution:

    def maxDiff(self, num: int) -> int:
        num_string = str(num)

        def apply_transform(src_char: str, dest_char: str, s: str):
            return int(s.replace(src_char, dest_char))
        max_num = num
        for char in num_string:
            if char < '9':
                max_num = apply_transform(char, '9', num_string)
                break
        min_num = num
        if num_string[0] > '1':
            min_num = apply_transform(num_string[0], '1', num_string)
        else:
            for char in num_string[1:]:
                if char > '1':
                    min_num = apply_transform(char, '0', num_string)
                    break
        return max_num - min_num
def test_simple_case():
    solution_instance = Solution()
    assert max_diff(11891) == solution_instance.maxDiff(11891)
def test_edge_case():
    solution_instance = Solution()
    assert max_diff(90) == solution_instance.maxDiff(90)
def test_difficult_case():
    solution_instance = Solution()
    assert max_diff(1000) == solution_instance.maxDiff(1000)

