def canDivideIntoPairs(nums: List[int], n: int) -> bool:
    # Check if the length of the array is divisible by n
    if len(nums) % n != 0:
        return False

    # Create a dictionary to store the frequency of each element
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Check if the frequency of each element is even
    for key in freq:
        if freq[key] % 2 != 0:
            return False

    return True

