class Solution:

    def sortByBits(self, arr: List[int]) -> List[int]:
        bin_dict = {}
        count_dict = {}
        for num in arr:
            bin_dict[num] = str(bin(num)[2:]).count('1')
            count_dict[num] = count_dict.get(num, 0) + 1
        bin_dict = dict(sorted(bin_dict.items(), key=lambda x: x[1]))
        final_arr = []
        lst = []
        last = None
        for key, val in bin_dict.items():
            if last == None:
                lst = lst + [key] * count_dict.get(key)
                last = val
            elif last == val:
                lst = lst + [key] * count_dict.get(key)
                last = val
            else:
                final_arr = final_arr + sorted(lst)
                lst = []
                lst = lst + [key] * count_dict.get(key)
                last = val
        return final_arr + sorted(lst)
