from typing import *
from collections import *
from math import *

def sort_items(n, m, group, beforeItems):
    graph = defaultdict(list)
    in_degree = [0] * n
    for i in range(n):
        for j in beforeItems[i]:
            graph[j].append(i)
            in_degree[i] += 1
    sorted_items = []
    for g in range(m):
        group_items = [i for i in range(n) if group[i] == g]
        group_graph = defaultdict(list)
        group_in_degree = [0] * len(group_items)
        for i in group_items:
            for j in beforeItems[i]:
                if group[j] == g:
                    group_graph[j].append(i)
                    group_in_degree[group_items.index(i)] += 1
        q = deque([i for i in group_items if group_in_degree[group_items.index(i)] == 0])
        while q:
            curr = q.popleft()
            sorted_items.append(curr)
            for neighbor in group_graph[curr]:
                idx = group_items.index(neighbor)
                group_in_degree[idx] -= 1
                if group_in_degree[idx] == 0:
                    q.append(neighbor)
    if len(sorted_items) != n:
        return []
    return sorted_items
class Solution:

    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:
        for i in range(n):
            if group[i] == -1:
                group[i] = i + m
        graph0 = {}
        indeg0 = [0] * (m + n)
        graph1 = {}
        indeg1 = [0] * n
        for i, x in enumerate(beforeItems):
            for xx in x:
                if group[xx] != group[i]:
                    graph0.setdefault(group[xx], []).append(group[i])
                    indeg0[group[i]] += 1
                graph1.setdefault(xx, []).append(i)
                indeg1[i] += 1

        def fn(graph, indeg):
            """Return topological sort of graph using Kahn's algo."""
            ans = []
            stack = [k for k in range(len(indeg)) if indeg[k] == 0]
            while stack:
                n = stack.pop()
                ans.append(n)
                for nn in graph.get(n, []):
                    indeg[nn] -= 1
                    if indeg[nn] == 0:
                        stack.append(nn)
            return ans
        tp0 = fn(graph0, indeg0)
        if len(tp0) != len(indeg0):
            return []
        tp1 = fn(graph1, indeg1)
        if len(tp1) != len(indeg1):
            return []
        mp0 = {x: i for i, x in enumerate(tp0)}
        mp1 = {x: i for i, x in enumerate(tp1)}
        return sorted(range(n), key=lambda x: (mp0[group[x]], mp1[x]))
