def max_distance(grid):
    max_dist = -1
    land_cells = []
    water_cells = []
    n = len(grid)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                land_cells.append((i, j))
            else:
                water_cells.append((i, j))
    if len(land_cells) == 0 or len(water_cells) == 0:
        return -1
    for water in water_cells:
        dist = n * n
        for land in land_cells:
            dist = min(dist, abs(water[0] - land[0]) + abs(water[1] - land[1]))
        max_dist = max(max_dist, dist)
    return max_dist
class Solution:

    def maxDistance(self, grid: List[List[int]]) -> int:
        rows, cols = (len(grid), len(grid[0]))
        directions = ((0, 1), (0, -1), (-1, 0), (1, 0))
        Position = namedtuple('Position', ['row', 'col'])

        def withinBounds(pos):
            return 0 <= pos.row < rows and 0 <= pos.col < cols
        queue = deque([Position(r, c) for r in range(rows) for c in range(cols) if grid[r][c]])
        if not queue or len(queue) == rows * cols:
            return -1
        distance = 0
        while queue:
            for i in range(len(queue)):
                pos = queue.popleft()
                for dr, dc in directions:
                    newPos = Position(pos.row + dr, pos.col + dc)
                    if withinBounds(newPos) and grid[newPos.row][newPos.col] == 0:
                        grid[newPos.row][newPos.col] = 1
                        queue.append(newPos)
            distance += 1
        return distance - 1
def test_simple_case():
    grid1 = [[0, 1], [1, 0]]
    solution_instance = Solution()
    assert max_distance(grid1) == solution_instance.maxDistance(grid1)
