    solution_instance = Solution()
    assert max_distance(grid2) == solution_instance.maxDistance(grid2)
def test_difficult_case():
    grid3 = [[1, 0, 0], [0, 0, 0], [0, 0, 0]]
    solution_instance = Solution()
    assert max_distance(grid3) == solution_instance.maxDistance(grid3)

