class Solution:

    def twoEditWords(self, queries: List[str], dictionary: List[str]) -> List[str]:
        output = []
        for query in queries:
            for word in dictionary:
                i = 0
                counter = 0
                while i < len(word):
                    if counter > 2:
                        break
                    if query[i] != word[i]:
                        counter += 1
                    i += 1
                if counter > 2:
                    continue
                elif counter <= 2:
                    break
            if counter <= 2:
                output.append(query)
        return output
def test_simple_case():
    solution_instance = Solution()
    assert findMatchedWords(['abc', 'def'], ['abc', 'def', 'ghi']) == solution_instance.twoEditWords(['abc', 'def'], ['abc', 'def', 'ghi'])
