def last_remaining_number(n):
    arr = list(range(1, n+1))
    left_to_right = True
    while len(arr) > 1:
        if left_to_right:
            arr = arr[1::2]
        else:
            arr = arr[-2::-2][::-1]
        left_to_right = not left_to_right
    return arr[0]

