from typing import *
from collections import *
from math import *

def last_remaining_number(n):
    arr = list(range(1, n + 1))
    left_to_right = True
    while len(arr) > 1:
        if left_to_right:
            arr = arr[1::2]
        else:
            arr = arr[-2::-2][::-1]
        left_to_right = not left_to_right
    return arr[0]
class Solution:

    def lastRemaining(self, n: int) -> int:
        return 1 if n == 1 else 2 * (1 + n // 2 - self.lastRemaining(n // 2))

    def lastRemaining1(self, n: int) -> int:
        """"
        removing from left to right [1 2 3 4 5 6 7 8 9]==[2 4 6 8]==2*[1 2 3 4]
        """

        def helper(n, is_left):
            if n == 1:
                return 1
            if is_left:
                return 2 * helper(n // 2, False)
            if n % 2 == 1:
                return 2 * helper(n // 2, True)
            return 2 * helper(n // 2, 2) - 1
        return helper(n, True)

    def lastRemaining2(self, n: int) -> int:
        if n == 0:
            return
        st1, st2, left = (list(range(1, n + 1)), [], True)
        while len(st1) > 1:
            if not left:
                st1 = st1[::-1]
            for i in range(1, len(st1), 2):
                st2.append(st1[i])
            st1 = list(st2) if left else list(st2[::-1])
            st2 = []
            left = not left
        return st1[0]
def test_simple_case():
    solution_instance = Solution()
    assert last_remaining_number(9) == solution_instance.lastRemaining(9)
def test_edge_case():
    solution_instance = Solution()
    assert last_remaining_number(1) == solution_instance.lastRemaining(1)
def test_difficult_case():
    solution_instance = Solution()
    assert last_remaining_number(10) == solution_instance.lastRemaining(10)

