class Solution:

    def isThree(self, n):
        answers = [4, 9, 25, 49, 121, 169, 289, 361, 529, 841, 961, 1369, 1681, 1849, 2209, 2809, 3481, 3721, 4489, 5041, 5329, 6241, 6889, 7921, 9409]
        while True:
            size = len(answers)
            if size == 1:
                return answers[0] == n
            elif size == 0:
                return False
            mp = size // 2
            if answers[mp] == n:
                return True
            elif answers[mp] > n:
                answers = answers[:mp]
            else:
                answers = answers[mp + 1:]
