from typing import *
from collections import *
from math import *

def shortestCompletingWord(licensePlate: str, words: List[str]) -> str:
    count = Counter(filter(str.isalpha, licensePlate.lower()))
    return min(filter(lambda x: count & Counter(x.lower()) == count, words), key=len)
class Solution:

    def shortestCompletingWord(self, licensePlate: str, words: List[str]) -> str:
        letter_occurences = [0 for a in range(26)]
        for char in licensePlate:
            if 'A' <= char <= 'Z':
                letter_occurences[ord(char.lower()) - 97] += 1
            elif 'a' <= char <= 'z':
                letter_occurences[ord(char) - 97] += 1
            else:
                pass
        letter_occurences = [[chr(a + 97), letter_occurences[a]] for a in range(26) if letter_occurences[a] > 0]
        min_length = 1001
        index = -1
        for index_, word in enumerate(words):
            if len(word) < min_length:
                word = sorted(word)
                index_word = 0
                take_word = True
                for letter, occurences in letter_occurences:
                    while index_word < len(word) and word[index_word] < letter:
                        index_word += 1
                    if index_word == len(word) or word[index_word] > letter:
                        take_word = False
                        break
                    else:
                        while index_word < len(word) and word[index_word] == letter:
                            occurences -= 1
                            index_word += 1
                        if occurences > 0:
                            take_word = False
                            break
                    if not take_word:
                        break
                if take_word:
                    min_length = len(word)
                    index = index_
        return words[index]
def test_simple_case():
    sol_instance = Solution()
    assert shortestCompletingWord('1s3 PSt', ['step', 'steps', 'stripe', 'stepple']) == sol_instance.shortestCompletingWord('1s3 PSt', ['step', 'steps', 'stripe', 'stepple'])
def test_multiple_words():
