class Solution:

    def matrixRankTransform(self, matrix: List[List[int]]) -> List[List[int]]:
        m = len(matrix)
        n = len(matrix[0])

        def find_root(x: int, y: int):
            if parent[x][y] == (x, y):
                return (x, y)
            else:
                r = find_root(parent[x][y][0], parent[x][y][1])
                parent[x][y] = r
                return r

        def union(x1, y1, x2, y2):
            root_a = find_root(x1, y1)
            root_b = find_root(x2, y2)
            parent[root_b[0]][root_b[1]] = root_a
        parent = [[(j, i) for i in range(n)] for j in range(m)]
        for i in range(m):
            value = []
            for j in range(n):
                v = tuple([matrix[i][j], i, j])
                value.append(v)
            value.sort()
            for k in range(n - 1):
                if value[k][0] == value[k + 1][0]:
                    union(value[k][1], value[k][2], value[k + 1][1], value[k + 1][2])
        for i in range(n):
            value = []
            for j in range(m):
                v = tuple([matrix[j][i], j, i])
                value.append(v)
            value.sort()
            for k in range(m - 1):
                if value[k][0] == value[k + 1][0]:
                    union(value[k][1], value[k][2], value[k + 1][1], value[k + 1][2])
        dic = {}
        in_degree = {}
        for i in range(m):
            for j in range(n):
                if parent[i][j] == (i, j):
                    dic[i, j] = []
                    in_degree[i, j] = 0
        for i in range(m):
            for j in range(n):
                while parent[i][j] not in dic:
                    parent[i][j] = parent[parent[i][j][0]][parent[i][j][1]]
        for i in range(m):
            row = []
            for j in range(n):
                r = tuple([matrix[i][j], parent[i][j][0], parent[i][j][1]])
                row.append(r)
            row.sort()
            for k in range(n - 1):
                if row[k][0] < row[k + 1][0]:
                    if (row[k][1], row[k][2]) in dic and (row[k + 1][1], row[k + 1][2]) in dic:
                        if (row[k + 1][1], row[k + 1][2]) not in dic[row[k][1], row[k][2]]:
                            dic[row[k][1], row[k][2]].append((row[k + 1][1], row[k + 1][2]))
                            in_degree[row[k + 1][1], row[k + 1][2]] += 1
        for i in range(n):
            col = []
            for j in range(m):
                c = tuple([matrix[j][i], parent[j][i][0], parent[j][i][1]])
                col.append(c)
            col.sort()
            for k in range(m - 1):
                if col[k][0] < col[k + 1][0]:
                    if (col[k][1], col[k][2]) in dic and (col[k + 1][1], col[k + 1][2]) in dic:
                        if (col[k + 1][1], col[k + 1][2]) not in dic[col[k][1], col[k][2]]:
                            dic[col[k][1], col[k][2]].append((col[k + 1][1], col[k + 1][2]))
                            in_degree[col[k + 1][1], col[k + 1][2]] += 1
        distance = {}
        for i in range(m):
            for j in range(n):
                if parent[i][j] == (i, j):
                    distance[i, j] = 0
        queue = []
        for i in in_degree:
            if in_degree[i] == 0:
                queue.append(i)
                distance[i] = 1
        head = 0
        tail = len(queue) - 1
        while head <= tail:
            h = queue[head]
            for p in dic[h]:
                in_degree[p] -= 1
                if in_degree[p] == 0:
                    queue.append(p)
                    distance[p] = distance[h] + 1
            head += 1
            tail = len(queue) - 1
        rank = [[0 for i in range(n)] for j in range(m)]
        for i in range(m):
            for j in range(n):
                rank[i][j] = distance[parent[i][j]]
        return rank
def test_small_matrix():
    matrix = [[10, 20], [20, 10]]
    solution = Solution()
    assert rank_matrix(matrix) == solution.matrixRankTransform(matrix)
def test_larger_matrix():
    matrix = [[1, 2], [3, 4], [5, 6]]
    solution = Solution()
    assert rank_matrix(matrix) == solution.matrixRankTransform(matrix)
def test_matrix_with_ties():
    matrix = [[1, 2, 2], [3, 1, 4], [0, 0, 5]]
    solution = Solution()
    assert rank_matrix(matrix) == solution.matrixRankTransform(matrix)

