def min_seed_value(nums: List[int], space: int) -> int:
    nums.sort()
    result = float('inf')
    n = len(nums)
    for i in range(n):
        cnt_targets = 0
        for j in range(i, n):
            if nums[j] - nums[i] <= space * (j - i):
                cnt_targets += 1
        if cnt_targets == n - i:
            result = min(result, nums[i])
