def numOfBurgers(tomatoSlices: int, cheeseSlices: int) -> List[int]:
    total_jumbo = (tomatoSlices - 2 * cheeseSlices) // 2
    total_small = cheeseSlices - total_jumbo
    if tomatoSlices % 2 != 0 or total_jumbo < 0 or total_small < 0:
        return []
