from typing import *
from collections import *
from math import *

def decrypt_code(code, k):
    decrypted = []
    for i in range(len(code)):
        sum = 0
        if k > 0:
            for j in range(k):
                sum += code[(i + j) % len(code)]
        elif k < 0:
            for j in range(abs(k)):
                sum += code[(i - j) % len(code)]
        decrypted.append(sum)
    return decrypted
class Solution:

    def decrypt(self, code: List[int], k: int) -> List[int]:
        if k == 0:
            return [0] * len(code)
        sum = 0
        res = []
        if k > 0:
            left = 0
            while left < k:
                left = left + 1
                sum += code[left]
            res.append(sum)
            for curr in range(1, len(code)):
                left = (left + 1) % len(code)
                sum -= code[curr]
                sum += code[left]
                res.append(sum)
        else:
            right = len(code)
            while len(code) - right < abs(k):
                right = right - 1
                sum += code[right]
            res.append(sum)
            for curr in range(0, len(code) - 1):
                sum += code[curr]
                sum -= code[right]
                right = (right + 1) % len(code)
                res.append(sum)
        return res
def test_simple_case():
    solution_instance = Solution()
    assert decrypt_code([5, 7, 1, 4], 3) == solution_instance.decrypt([5, 7, 1, 4], 3)
def test_edge_case():
    solution_instance = Solution()
    assert decrypt_code([1, 2, 3, 4], -1) == solution_instance.decrypt([1, 2, 3, 4], -1)
def test_difficult_case():
    solution_instance = Solution()
    assert decrypt_code([23, 3, 17, 6, 11], 0) == solution_instance.decrypt([23, 3, 17, 6, 11], 0)

