from typing import *
from collections import *
from math import *

def remove_subfolders(folder):
    folder.sort()
    result = []
    for f in folder:
        if not result or not f.startswith(result[-1] + '/'):
            result.append(f)
    return result
class Solution:

    def removeSubfolders(self, folder: List[str]) -> List[str]:
        self.result = []
        trie = Trie()
        folder.sort()
        for val in folder:
            val = val.split('/')
            if trie.insert(val):
                self.result.append('/'.join(val))
        return self.result
class TrieNode:

    def __init__(self, ch=None):
        self.ch = ch
        self.children = {}
        self.is_end = False
class Trie:

    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        cur = self.root
        for i in range(1, len(word)):
            c = word[i]
            if c not in cur.children:
                cur.children[c] = TrieNode(c)
            elif cur.children[c].is_end:
                return False
            cur = cur.children[c]
        cur.is_end = True
        return True
def test_simple_case():
    solution_instance = Solution()
    folder_list = ['/a', '/a/b', '/c']
    assert remove_subfolders(folder_list) == solution_instance.removeSubfolders(folder_list)
