def cocktail_shaker_sort(a):
    n = len(a)
    swapped = True
    start = 0
    end = n - 1
    while swapped == True:
        swapped = False
        for i in range(start, end):
            if a[i] > a[i + 1]:
                a[i], a[i + 1] = (a[i + 1], a[i])
                swapped = True
        if swapped == False:
            break
        swapped = False
        end = end - 1
        for i in range(end - 1, start - 1, -1):
            if a[i] > a[i + 1]:
                a[i], a[i + 1] = (a[i + 1], a[i])
                swapped = True
        start = start + 1
    return a
def cocktail_shaker_sort(alist):

    def swap(i, j):
        alist[i], alist[j] = (alist[j], alist[i])
    upper = len(alist) - 1
    lower = 0
    no_swap = False
    while not no_swap and upper - lower > 1:
        no_swap = True
        for j in range(lower, upper):
            if alist[j + 1] < alist[j]:
                swap(j + 1, j)
                no_swap = False
        upper = upper - 1
        for j in range(upper, lower, -1):
            if alist[j - 1] > alist[j]:
                swap(j - 1, j)
                no_swap = False
        lower = lower + 1
def test_simple_case():
    lst1 = [5, 3, 2, 4, 1]
    assert cocktail_shaker_sort(lst1.copy()) == cocktail_shaker_sort(lst1.copy())
def test_edge_case():
    lst2 = [1, 2, 3, 4, 5]
    assert cocktail_shaker_sort(lst2.copy()) == cocktail_shaker_sort(lst2.copy())
def test_difficult_case():
    lst3 = [5, 4, 3, 2, 1]
    assert cocktail_shaker_sort(lst3.copy()) == cocktail_shaker_sort(lst3.copy())

