from typing import *
from collections import *
from math import *

def max_profit(customers, boardingCost, runningCost):
    total_customers = 4
    total_profit = 0
    max_profit = -1
    rotations = 0
    for i in range(len(customers)):
        rotations += 1
        total_customers += customers[i]
        if total_customers > 16:
            return -1
        customers_to_board = min(total_customers, 16)
        total_customers -= customers_to_board
        profit = customers_to_board * boardingCost - rotations * runningCost
        total_profit += profit
        if total_profit > max_profit:
            max_profit = total_profit
    return max_profit if max_profit > 0 else -1
class Solution:

    def minOperationsMaxProfit(self, customers: List[int], boardingCost: int, runningCost: int) -> int:
        n = len(customers)
        dp = []
        reserved = 0
        on_board = 0
        rotation = 0
        for i in range(n):
            if reserved != 0:
                if reserved >= 4:
                    on_board += 4
                    reserved += customers[i] - 4
                else:
                    new_customers = 4 - reserved
                    if customers[i] >= new_customers:
                        on_board += 4
                        reserved = customers[i] - new_customers
                    else:
                        on_board += reserved + customers[i]
                        reserved = 0
            elif customers[i] >= 4:
                on_board += 4
                reserved += customers[i] - 4
            else:
                on_board += customers[i]
            rotation += 1
            dp.append(on_board * boardingCost - rotation * runningCost)
        for i in range(reserved // 4 + 1):
            if reserved >= 4:
                on_board += 4
                reserved -= 4
            else:
                on_board += reserved
                reserved = 0
            rotation += 1
            dp.append(on_board * boardingCost - rotation * runningCost)
        maxim = max(dp)
        return dp.index(maxim) + 1 if maxim >= 0 else -1
def test_simple_case():
    assert max_profit([8, 3], 5, 6) == Solution().minOperationsMaxProfit([8, 3], 5, 6)
def test_edge_case():
    assert max_profit([10, 9, 6], 6, 4) == Solution().minOperationsMaxProfit([10, 9, 6], 6, 4)
def test_difficult_case():
    assert max_profit([20, 0, 11, 5, 1], 4, 5) == Solution().minOperationsMaxProfit([20, 0, 11, 5, 1], 4, 5)

