def toHex(num):
    if num == 0:
        return '0'
    elif num < 0:
        num = 2 ** 32 + num
    hex_chars = '0123456789abcdef'
    hex_str = ''
    while num > 0:
        hex_str = hex_chars[num % 16] + hex_str
        num = num // 16
    return hex_str
class Solution:

    def toHex(self, num: int) -> str:
        if num == 0:
            return '0'
        d = {10: 'a', 11: 'b', 12: 'c', 13: 'd', 14: 'e', 15: 'f'}
        d1 = {'0000': 0, '0001': 1, '0010': 2, '0011': 3, '0100': 4, '0101': 5, '0110': 6, '0111': 7, '1000': 8, '1001': 9, '1010': 'a', '1011': 'b', '1100': 'c', '1101': 'd', '1110': 'e', '1111': 'f'}
        s, s1 = ('', '')
        if num > 0:
            while num != 0:
                r = num % 16
                if r in d:
                    s += str(d[r])
                else:
                    s += str(r)
                num //= 16
        else:
            num1 = -num
            carry = 1
            l1 = list(bin(num1)[2:].zfill(32))
            for i in range(len(l1)):
                if l1[i] == '1':
                    l1[i] = '0'
                else:
                    l1[i] = '1'
            for i in range(len(l1)):
                if l1[-i - 1] != '1':
                    l1[-i - 1] = str(int(l1[-i - 1]) + carry)
                    carry = 0
                elif carry == 1 and l1[-i - 1] == '1':
                    l1[-i - 1] = '0'
                    carry = 1
            if carry == 1:
                l1.insert(0, '1')
            s = ''.join(l1)
            for i in range(0, len(s), 4):
                s1 += str(d1[s[i:i + 4]])
        return s[::-1] if num >= 0 else s1
def test_simple_case():
    solution_instance = Solution()
    assert toHex(26) == solution_instance.toHex(26)
def test_edge_case():
    solution_instance = Solution()
    assert toHex(-1) == solution_instance.toHex(-1)
def test_difficult_case():
    solution_instance = Solution()
    assert toHex(0) == solution_instance.toHex(0)

