def is_well_spaced_string(s: str, distance: List[int]) -> bool:
    letter_count = [0] * 26
    for c in s:
        letter_count[ord(c) - ord('a')] += 1
    for i in range(26):
        if letter_count[i] != 2:
            continue
        pos1, pos2 = -1, -1
        for j in range(len(s)):
            if s[j] == chr(i + ord('a')):
                if pos1 == -1:
                    pos1 = j
                else:
                    pos2 = j
                    break
        if pos2 - pos1 - 1 != distance[i]:
            return False
    return True

