class Solution:

    def checkDistances(self, s: str, distance: List[int]) -> bool:
        for idx, char in enumerate(s):
            dist = distance[ord(char) - ord('a')]
            if dist >= 0:
                if idx + dist + 1 < len(s) and s[idx + dist + 1] == char:
                    distance[ord(char) - ord('a')] = -1
                else:
                    return False
        return True
