class Solution:

    def platesBetweenCandles(self, s: str, qs: List[List[int]]) -> List[int]:
        n = len(s)
        prefcandle = [-1] * n
        suffcandle = [0] * n
        pref = [0] * n
        ind = -1
        c = 0
        for i in range(n):
            if ind != -1 and s[i] == '*':
                c += 1
            elif s[i] == '|':
