class Solution:

    def minOperations(self, nums: List[int], numsDivide: List[int]) -> int:
        g, ans = (gcd(*numsDivide), 0)
        heapify(nums)
        while nums:
            if not g % heappop(nums):
                return ans
            else:
                ans += 1
        return -1
class Solution:

    def minOperations(self, nums: List[int], numsDivide: List[int]) -> int:
        g = gcd(*numsDivide)
        nums.sort()
        for i, num in enumerate(nums):
            if not g % num:
                return i
        return -1
