    for i in range(1, len(modified_string)):
        if modified_string[i] == modified_string[i - 1]:
            continue
        elif modified_string[i] != '?' and modified_string[i] != modified_string[i - 1]:
            continue
        elif modified_string[i] == '?':
            modified_string = modified_string[:i] + get_next_letter(modified_string[i - 1], modified_string[i + 1:]) + modified_string[i + 1:]
    return modified_string
def get_next_letter(previous_char, remaining_chars):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    for letter in alphabet:
        if letter != previous_char and letter not in remaining_chars:
