def find_kth_smallest(n, k):
    arr = [str(i) for i in range(1, n + 1)]
    arr.sort()
    return int(arr[k - 1])
class Solution:

    def findKthNumber(self, n: int, k: int) -> int:

        def fn(x):
            """Return node counts in denary trie."""
            ans, diff = (0, 1)
            while x <= n:
                ans += min(n - x + 1, diff)
                x *= 10
                diff *= 10
            return ans
        x = 1
        while k > 1:
            cnt = fn(x)
            if k > cnt:
                k -= cnt
                x += 1
            else:
                k -= 1
                x *= 10
        return x
def test_simple_case():
    solution_instance = Solution()
    assert find_kth_smallest(12, 3) == solution_instance.findKthNumber(12, 3)
def test_edge_case():
    solution_instance = Solution()
    assert find_kth_smallest(100, 10) == solution_instance.findKthNumber(100, 10)
def test_difficult_case():
    solution_instance = Solution()
    assert find_kth_smallest(5, 3) == solution_instance.findKthNumber(5, 3)

