class Solution(object):

    def beautySum(self, s):
        """
        :type s: str
        :rtype: int
        """
        res = 0
        h = [0 for _ in range(26)]
        for i in range(len(s)):
            h = [0 for _ in range(26)]
            for j in range(i, len(s)):
                h[ord(s[j]) - ord('a')] += 1
                minv, maxv = (501, -1)
                for x in h:
