def maximum_good_people(statements):
    n = len(statements)
    good_people = set(range(n))
    change = True
    while change:
        change = False
        for i in range(n):
            if i in good_people:
                for j in range(n):
                    if statements[i][j] == 0 and j in good_people:
                        good_people.remove(j)
                        change = True
                    elif statements[i][j] == 1 and j not in good_people:
