class Solution:

    def maximumGood(self, statements: List[List[int]]) -> int:
        n = len(statements)
        self.ans = 0
        good = set()

        def backtracking(idx, count):
            if idx == n:
                self.ans = max(self.ans, count)
                return
            good.add(idx)
            for i in range(idx):
                if statements[idx][i] == 1 and i not in good or (statements[idx][i] == 0 and i in good) or (i in good and statements[i][idx] == 0):
                    break
            else:
                backtracking(idx + 1, count + 1)
            good.remove(idx)
            for i in range(idx):
                if i in good and statements[i][idx] == 1:
                    return
            backtracking(idx + 1, count)
        backtracking(0, 0)
        return self.ans
def test_simple_case():
    statements = [[2, 1, 2], [1, 2, 2], [2, 0, 0]]
    solution_instance = Solution()
    assert maximum_good_people(statements) == solution_instance.maximumGood(statements)
def test_complex_case():
    statements = [[2, 0], [0, 2]]
    solution_instance = Solution()
    assert maximum_good_people(statements) == solution_instance.maximumGood(statements)
def test_edge_case():
    statements = [[2, 0], [1, 2]]
    solution_instance = Solution()
    assert maximum_good_people(statements) == solution_instance.maximumGood(statements)

