def palindrome(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    for i in range(n - 1):
        dp[i][i + 1] = s[i] == s[i + 1]
    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1
            dp[i][j] = dp[i + 1][j - 1] and s[i] == s[j]
