def max_product(s):
    dp = palindrome(s)
    n = len(s)
    res = 0
    for i in range(n):
        for j in range(i + 1, n):
            if dp[i][j]:
                for k in range(j + 2, n):
                    for l in range(k + 1, n):
                        if dp[k][l]:
                            res = max(res, (j - i + 1) * (l - k + 1))
    return res
class Solution:

    def maxProduct(self, s: str) -> int:
        n = len(s)
        hlen = [0] * n
        center = right = 0
        for i in range(n):
            if i < right:
                hlen[i] = min(right - i, hlen[2 * center - i])
            while 0 <= i - 1 - hlen[i] and i + 1 + hlen[i] < len(s) and (s[i - 1 - hlen[i]] == s[i + 1 + hlen[i]]):
                hlen[i] += 1
            if right < i + hlen[i]:
                center, right = (i, i + hlen[i])
        prefix = [0] * n
        suffix = [0] * n
        for i in range(n):
            prefix[i + hlen[i]] = max(prefix[i + hlen[i]], 2 * hlen[i] + 1)
            suffix[i - hlen[i]] = max(suffix[i - hlen[i]], 2 * hlen[i] + 1)
        for i in range(1, n):
            prefix[~i] = max(prefix[~i], prefix[~i + 1] - 2)
            suffix[i] = max(suffix[i], suffix[i - 1] - 2)
        for i in range(1, n):
            prefix[i] = max(prefix[i - 1], prefix[i])
            suffix[~i] = max(suffix[~i], suffix[~i + 1])
        return max((prefix[i - 1] * suffix[i] for i in range(1, n)))
def test_simple_case():
    s = 'abacaba'
    solution_instance = Solution()
    assert max_product(s) == solution_instance.maxProduct(s)
