class Solution:

    def findKDistantIndices(self, nums: List[int], key: int, k: int) -> List[int]:
        result = []
        n = len(nums)
        window_start = 0
        num_freq = {}
        for window_end in range(min(k, n)):
            right_num = nums[window_end]
            num_freq[right_num] = num_freq.get(right_num, 0) + 1
        for i in range(n):
            if window_end + 1 < n:
                window_end += 1
                right_num = nums[window_end]
                num_freq[right_num] = num_freq.get(right_num, 0) + 1
            if i - window_start > k:
                left_num = nums[window_start]
                num_freq[left_num] -= 1
                if num_freq[left_num] == 0:
                    num_freq.pop(left_num)
                window_start += 1
            if key in num_freq:
                result.append(i)
        return result
def test_simple_case():
    sol_instance = Solution()
    assert k_distant_indices([3, 4, 9, 1, 3, 9, 2], 3, 9) == sol_instance.findKDistantIndices([3, 4, 9, 1, 3, 9, 2], 9, 3)
