class Solution:

    def __init__(self):
        self.twos = {2 ** n: n for n in range(31)}

    def integerReplacement(self, n: int) -> int:
        memo = {}
        self.dp(n, 0, memo)
        return memo[1]

    def dp(self, number, steps, memo):
        if number in memo:
            if memo[number] > steps:
                memo[number] = steps
            else:
                return
        else:
            memo[number] = steps
        if number == 1:
            return
        if number in self.twos:
            self.dp(1, steps + self.twos[number], memo)
        new, res = divmod(number, 2)
        if res:
            self.dp(number + 1, steps + 1, memo)
            self.dp(number - 1, steps + 1, memo)
        else:
            self.dp(new, steps + 1, memo)
        return
def test_simple_case():
    solution_instance = Solution()
    assert minimum_operations(4) == solution_instance.integerReplacement(4)
def test_edge_case():
    solution_instance = Solution()
    assert minimum_operations(8) == solution_instance.integerReplacement(8)
def test_difficult_case():
    solution_instance = Solution()
    assert minimum_operations(7) == solution_instance.integerReplacement(7)

