class Solution:

    def atMostNGivenDigitSet(self, digits: List[str], n: int) -> int:
        num = list(str(n))
        N = len(num)
        tsum = 0
        if len(digits) > 1:
            tsum = len(digits) * (len(digits) ** (N - 1) - 1) // (len(digits) - 1)
        else:
            tsum = N - 1
        i = 0
        while i < N:
            count = 0
            equals = False
            for digit in digits:
                if digit > num[i]:
                    break
                if digit == num[i]:
                    equals = True
                    if i == N - 1:
                        count += 1
                    break
                count += 1
            tsum += count * len(digits) ** (N - 1 - i)
            if equals:
                i += 1
                continue
            break
        return tsum
def test_simple_case():
    solution_instance = Solution()
    assert count_numbers(['1', '2', '3'], 3) == solution_instance.atMostNGivenDigitSet(['1', '2', '3'], 3)
