    for word in words:
        if f(query) < f(word):
            count += 1
    return count
def smallest_lex_freq(words, queries):
    answer = []
    for query in queries:
        answer.append(count_words(words, query))
    return answer
class Solution:

    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:

        def helper(s):
            hashmap = {}
            for c in s:
                if c not in hashmap:
                    hashmap[c] = 1
                    continue
                else:
                    hashmap[c] += 1
            array = []
            for k, v in hashmap.items():
                array.append((k, v))
            array.sort(key=lambda x: x[0])
            return array[0][1]
        ans = []
        arr = []
        for word in words:
            arr.append(helper(word))
        arr.sort()
        for query in queries:
            requirement = helper(query)
            l, r = (0, len(arr) - 1)
            leftmost_index = None
            while l <= r:
                mid = (l + r) // 2
                middle = arr[mid]
                if middle > requirement:
                    leftmost_index = mid
                    r = mid - 1
                    continue
                else:
                    l = mid + 1
                    continue
            if leftmost_index == None:
                ans.append(0)
                continue
            ans.append(len(arr) - leftmost_index)
        return ans
def test_simple_case():
    words = ['a']
    queries = ['b']
    expected = [0]
    solution_instance = Solution()
    assert smallest_lex_freq(words, queries) == expected
    assert solution_instance.numSmallerByFrequency(queries, words) == expected
def test_multiple_cases():
    words = ['abbb', 'aa']
    queries = ['aa']
    expected = [1]
