def f(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    min_char, min_freq = None, float('inf')
    for char in sorted(freq):
        if freq[char] < min_freq:
            min_char = char
            min_freq = freq[char]
    return min_freq

def count_words(words, query):
    count = 0
    for word in words:
        if f(query) < f(word):
            count += 1
    return count

def smallest_lex_freq(words, queries):
    answer = []
    for query in queries:
        answer.append(count_words(words, query))
    return answer

