class Solution:

    def increasingTriplet(self, nums: List[int]) -> bool:
        n = len(nums)
        if n < 3:
            return False
        min = None
        nextMin = None
        '\n        Initialize min and second min \n        from first two elements \n\n        '
        if nums[0] < nums[1]:
            min = 0
            nextMin = 1
        else:
            min = 1
        for i in range(2, n):
            x = nums[i]
            '\n            This will handle the case if secont element is greater than the first element\n            in array and extMin remains None \n            '
            if nextMin is None:
                if x <= nums[min]:
                    min = i
                else:
                    nextMin = i
                continue
            '\n            If we have some nextMin , it means we must HAD some min for this nextMin , if we get some\n            element bigger than nextMin then we have the triplet\n            '
            if nums[i] > nums[nextMin]:
                return True
            '\n            This part is Tricky \n\n            For eg:- array is like [2 , 4 , 1 , 2 , 3]\n            and x = 1 \n            then only triplet is {1 ,2 ,3} \n            While traversing array we need to update the min .\n\n            After reaching 1 , min will become 2 {index of 1} and nextMin will remain at 1 {index of 4} only\n\n            So even if array would have been [2 , 4 , 1 , 5] , in next step x would be 5 and our nextMin\n            would be on 4 only {nextMin = 1} and above condition will return True .\n\n            But for the original array [2 , 4 , 1 ,2, 3 ] when x = 2 {index = 3} , nextMin will become 3 { index\n            of second 2} .\n            '
            if x < nums[min]:
                min = i
            elif x < nums[nextMin] and x > nums[min]:
                nextMin = i
        return False
def test_simple_case():
    solution_instance = Solution()
    nums = [1, 2, 3, 4, 5]
    assert increasing_triplet(nums) == solution_instance.increasingTriplet(nums)
def test_edge_case():
    solution_instance = Solution()
    nums = [5, 1, 2, 4, 3]
    assert increasing_triplet(nums) == solution_instance.increasingTriplet(nums)
def test_difficult_case():
    solution_instance = Solution()
    nums = [2, 1, 5, 0, 4, 6]
    assert increasing_triplet(nums) == solution_instance.increasingTriplet(nums)

