class Solution:

    def isValid(self, s: str) -> bool:
        if s[0] != 'a':
            return False
        stack = []
        for i in s:
            if i == 'c':
                if not stack:
                    return False
                prev = i
                pop_count = 0
                while stack and ord(prev) - ord(stack[-1]) == 1:
                    prev = stack[-1]
                    stack.pop()
                    pop_count += 1
                if pop_count != 2:
                    return False
            else:
                stack.append(i)
        return not stack
