class Solution:

    def maximumSubsequenceCount(self, text: str, pattern: str) -> int:
        filtered = []
        for let in text:
            if let in pattern:
                filtered.append(let)
        return max(self.maxFinder(False, filtered, pattern), self.maxFinder(True, filtered, pattern))

    def maxFinder(self, atTheBeginning, string, pattern):
        let_ONE = 0
        let_TWO = 0
        if not atTheBeginning:
            let_TWO = 1
        for index in range(len(string) - 1, -1, -1):
            if string[index] == pattern[0]:
                let_ONE += let_TWO
            if string[index] == pattern[1]:
                let_TWO += 1
        if atTheBeginning:
            let_ONE += let_TWO
        return let_ONE
def test_simple_case():
    solution_instance = Solution()
    assert max_occurrences('abdcdbc', 'ac') == solution_instance.maximumSubsequenceCount('abdcdbc', 'ac')
