def multiply(a, b):
    result = 0
    sign = 1 if a * b >= 0 else -1
    a, b = (abs(a), abs(b))
    while b:
        if b % 2 == 1:
            result += a
        a *= 2
        b //= 2
    return sign * result
def multiply(x, y):
    if y < 0:
        return -multiply(x, -y)
    elif y == 0:
        return 0
    elif y == 1:
        return x
    else:
        return x + multiply(x, y - 1)
def test_positive_multiplication():
    assert multiply(3, 4) == multiply(3, 4)
