from typing import *
from collections import *
from math import *

def distributeCandies(num_people: int, candies: int) -> List[int]:
    distribution = [0] * num_people
    curr_person = 0
    curr_candies = 1
    while candies > 0:
        distribution[curr_person] += curr_candies
        candies -= curr_candies
        curr_candies += 1
        curr_person = (curr_person + 1) % num_people
    distribution[curr_person - 1] += candies
    return distribution
class Solution:

    def distributeCandies(self, candies: int, num_people: int) -> List[int]:
        cycle_offset = num_people * (num_people + 1) // 2
        cycles = 0
        n_2 = num_people ** 2
        required_candies = cycle_offset
        ret = []
        while candies >= required_candies:
            cycles += 1
            candies -= required_candies
            required_candies = cycles * n_2 + cycle_offset
        if cycles > 0:
            fixed_candy_size = cycles * (cycles - 1) // 2 * num_people
            for person in range(1, num_people + 1):
                ret.append(fixed_candy_size + cycles * person)
            fixed_candy_size = cycles * num_people
            for person in range(num_people):
                person_candies = fixed_candy_size + person + 1
                if person_candies > candies:
                    ret[person] += candies
                    return ret
                else:
                    ret[person] += person_candies
                    candies -= person_candies
        else:
            skip = False
            for person in range(1, num_people + 1):
                if skip:
                    ret.append(0)
                elif candies < person:
                    ret.append(candies)
                    skip = True
                else:
                    ret.append(person)
                    candies -= person
            return ret
def test_simple_case():
    solution_instance = Solution()
    assert distributeCandies(3, 7) == solution_instance.distributeCandies(3, 7)
def test_edge_case():
    solution_instance = Solution()
    assert distributeCandies(1, 10) == solution_instance.distributeCandies(1, 10)
def test_difficult_case():
    solution_instance = Solution()
    assert distributeCandies(5, 17) == solution_instance.distributeCandies(5, 17)

