def min_elements(nums, limit, goal):
    total = sum(nums)
    diff = abs(goal - total)
    count = 0
    if diff == 0:
        return count

    nums.sort(key=abs, reverse=True)
    for num in nums:
        if abs(total + num - goal) < diff:
            total += num
            diff = abs(goal - total)
            count += 1
        if diff == 0:
            return count

    return count

