def longest_happy_string(a, b, c):
    chars = {'a':a, 'b':b, 'c':c}
    s = ''
    while True:
        temp = ''
        for k, v in sorted(chars.items(), key=lambda x: x[1], reverse=True):
            if v > 0 and (not s or s[-1] != k or (len(s) > 1 and s[-2] != k)):
                temp += k
                chars[k] -= 1
        if not temp:
            break
        s += temp
    return s

