from typing import *
from collections import *
from math import *

def longest_happy_string(a, b, c):
    chars = {'a': a, 'b': b, 'c': c}
    s = ''
    while True:
        temp = ''
        for k, v in sorted(chars.items(), key=lambda x: x[1], reverse=True):
            if v > 0 and (not s or s[-1] != k or (len(s) > 1 and s[-2] != k)):
                temp += k
                chars[k] -= 1
        if not temp:
            break
        s += temp
    return s
class Solution:

    def longestDiverseString(self, a: int, b: int, c: int) -> str:
        nums = [a, b, c]
        chars = ['a', 'b', 'c']
        indices = [0, 1, 2]

        def keyFunc(i):
            return nums[i]
        indices = sorted(indices, key=keyFunc)
        if nums[indices[2]] > (nums[indices[1]] + nums[indices[0]] + 1) * 2:
            nums[indices[2]] = (nums[indices[1]] + nums[indices[0]] + 1) * 2
        if nums[indices[2]] > nums[indices[1]] + nums[indices[0]] + 1:
            s = ''
            gaps = nums[indices[1]] + nums[indices[0]] + 1
            doubles = nums[indices[2]] % gaps
            if doubles == 0:
                doubles = gaps
            singles = nums[indices[2]] - doubles
            for k in [0, 1]:
                for i in range(nums[indices[k]]):
                    if doubles > 0:
                        s += chars[indices[2]]
                        doubles -= 1
                    s += chars[indices[2]]
                    s += chars[indices[k]]
            if doubles > 0:
                s += chars[indices[2]]
            s += chars[indices[2]]
            return s
        else:
            s = ''
            singles = nums[indices[2]]
            gaps = nums[indices[1]] + nums[indices[0]] + 1
            zeros = gaps - singles
            skip = True
            for k in [0, 1]:
                for i in range(nums[indices[k]]):
                    if zeros > 0 and skip:
                        zeros -= 1
                    else:
                        s += chars[indices[2]]
                    s += chars[indices[k]]
                    skip = not skip
            if not (zeros > 0 and skip):
                s += chars[indices[2]]
            return s
def test_simple_case():
    s_instance = Solution()
    assert longest_happy_string(1, 1, 1) == s_instance.longestDiverseString(1, 1, 1)
def test_edge_case():
    s_instance = Solution()
    assert longest_happy_string(2, 2, 1) == s_instance.longestDiverseString(2, 2, 1)
def test_difficult_case():
    s_instance = Solution()
    assert longest_happy_string(7, 1, 0) == s_instance.longestDiverseString(7, 1, 0)

