from collections import *
from math import *

def minimumPerimeter(neededApples: int) -> int:

    def countApples(x: int, y: int) -> int:
        return abs(x) * (abs(x) + 1) // 2 + abs(y) * (abs(y) + 1) // 2
    left, right = (1, 10 ** 6)
    while left < right:
        mid = (left + right) // 2
        totalApples = countApples(mid, mid) * 4 - countApples(mid, 0) * 4
        if totalApples >= neededApples:
            right = mid
        else:
            left = mid + 1
    return left * 8
class Solution:

    def minimumPerimeter(self, nap: int) -> int:
        n = 1
        val = 2 * n * (n + 1) * (2 * n + 1)
        while val < nap:
            n += 1
            val = val = 2 * n * (n + 1) * (2 * n + 1)
        return n * 8
def test_simple_case():
    solution_instance = Solution()
    assert minimumPerimeter(10) == solution_instance.minimumPerimeter(10)
def test_difficult_case():
    solution_instance = Solution()
    assert minimumPerimeter(100) == solution_instance.minimumPerimeter(100)
def test_edge_case():
    solution_instance = Solution()
    assert minimumPerimeter(200) == solution_instance.minimumPerimeter(200)

