def count_palindrome_subsequence(s):
    subseq_set = set()
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            subseq = s[i:j]
            if subseq == subseq[::-1]:
                subseq_set.add(subseq)
    count = 0
    for subseq in subseq_set:
        if len(subseq) == 3:
            count += 1
    return count

