class Solution:

    def countPalindromicSubsequence(self, s: str) -> int:
        indices = {}
        for i in range(len(s)):
            if s[i] in indices:
                indices[s[i]][1] = i
            else:
                indices[s[i]] = [i, i]
        count = 0
        for c in indices:
            if indices[c][0] == indices[c][1]:
                pass
            else:
                tempAdded = set()
                for i in range(indices[c][0] + 1, indices[c][1], 1):
                    tempAdded.add(s[i])
                count += len(tempAdded)
        return count
def test_simple_case():
    solution_instance = Solution()
    assert count_palindrome_subsequence('aaa') == solution_instance.countPalindromicSubsequence('aaa')
def test_edge_case():
    solution_instance = Solution()
    assert count_palindrome_subsequence('abcba') == solution_instance.countPalindromicSubsequence('abcba')
def test_difficult_case():
    solution_instance = Solution()
    assert count_palindrome_subsequence('abcdabcdabcda') == solution_instance.countPalindromicSubsequence('abcdabcdabcda')

