def countOdds(low: int, high: int) -> int:
    return (high - low + 1) // 2 if low % 2 == high % 2 == 1 else (high - low) // 2 + 1
class Solution:

    def countOdds(self, low: int, high: int) -> int:
        return (high + 1) // 2 - low // 2
        if low % 2 != 0:
            low = low
        else:
            low = low + 1
        if high % 2 != 0:
            high = high
        else:
            high = high - 1
        common_difference = 2
        n = (high - low) // common_difference + 1
        return n
        count = 0
        for i in range(low, high + 1):
            if i % 2 != 0:
                count += 1
        return count
def test_simple_case():
    solution_instance = Solution()
    assert countOdds(3, 7) == solution_instance.countOdds(3, 7)
