from typing import *
from collections import *
from math import *

def minMoves(target: int, maxDoubles: int) -> int:
    moves = 0
    x = 1
    while x < target:
        if maxDoubles == 0:
            moves += target - x
            break
        if target - x <= 2 ** maxDoubles - 1:
            moves += 1
            break
        x *= 2
        maxDoubles -= 1
        moves += 1
    return moves + target - x
class Solution:

    def minMoves(self, target: int, maxDoubles: int) -> int:
        steps = 0
        if maxDoubles == 0:
            return target - 1
        else:
            while target != 1:
                if target % 2 == 0 and maxDoubles > 0:
                    target = target / 2
                    steps = steps + 1
                    maxDoubles = maxDoubles - 1
                else:
                    target = target - 1
                    steps = steps + 1
            return steps
def test_simple_case():
    solution_instance = Solution()
    assert minMoves(5, 0) == solution_instance.minMoves(5, 0)
def test_typical_case():
    solution_instance = Solution()
    assert minMoves(10, 2) == solution_instance.minMoves(10, 2)
def test_complex_case():
    solution_instance = Solution()
    assert minMoves(100, 4) == solution_instance.minMoves(100, 4)

