from typing import *
from collections import *
from math import *

def fib(n):
    if n <= 1:
        return n
    else:
        return fib(n - 1) + fib(n - 2)
def fibonacci_nums(n):
    if n <= 0:
        return [0]
    sequence = [0, 1]
    while len(sequence) <= n:
        next_value = sequence[len(sequence) - 1] + sequence[len(sequence) - 2]
        sequence.append(next_value)
    return sequence
def test_simple_case():
    assert fib(5) == fibonacci_nums(5)[-1]
def test_edge_case():
    assert fib(0) == fibonacci_nums(0)[0]
def test_difficult_case():
    assert fib(10) == fibonacci_nums(10)[-1]

