from typing import *
from collections import *
from math import *

def robotGrid(n, startPos, s):
    row, col = startPos
    directions = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}
    answer = []
    for i in range(len(s)):
        move = directions[s[i]]
        newRow = row + move[0]
        newCol = col + move[1]
        if newRow < 0 or newRow >= n or newCol < 0 or (newCol >= n):
            break
        row, col = (newRow, newCol)
        answer.append(i + 1)
    return answer
class Solution:

    def executeInstructions(self, n: int, startPos: List[int], s: str) -> List[int]:
        ans = []
        r = startPos[0]
        c = startPos[1]
        count = 0
        while s != '':
            for j in range(len(s)):
                if s[j] == 'R':
                    if c < n - 1:
                        c += 1
                        count += 1
                    else:
                        ans.append(count)
                        count = 0
                        break
                elif s[j] == 'L':
                    if c > 0:
                        c -= 1
                        count += 1
                    else:
                        ans.append(count)
                        count = 0
                        break
                elif s[j] == 'D':
                    if r < n - 1:
                        r += 1
                        count += 1
                    else:
                        ans.append(count)
                        count = 0
                        break
                elif s[j] == 'U':
                    if r > 0:
                        r -= 1
                        count += 1
                    else:
                        ans.append(count)
                        count = 0
                        break
            if count == len(s):
                ans.append(count)
                count = 0
            r = startPos[0]
            c = startPos[1]
            s = s[1:]
        return ans
def test_simple_case():
    solution = Solution()
    assert robotGrid(3, [0, 0], 'RRRDDDD') == solution.executeInstructions(3, [0, 0], 'RRRDDDD')
def test_edge_case():
    solution = Solution()
    assert robotGrid(2, [1, 1], 'LURD') == solution.executeInstructions(2, [1, 1], 'LURD')
def test_difficult_case():
    solution = Solution()
    assert robotGrid(4, [1, 0], 'LLURLRDRRRDRLDD') == solution.executeInstructions(4, [1, 0], 'LLURLRDRRRDRLDD')

