def longest_vowel_substring(s):
    vowels = set('aeiou')
    counts = {vowel: 0 for vowel in vowels}
    start = 0
    result = ''
    for end, c in enumerate(s):
        if c in vowels:
            counts[c] += 1
        if all((count % 2 == 0 for count in counts.values())):
            if end - start + 1 > len(result):
                result = s[start:end + 1]
        while all((count % 2 == 0 for count in counts.values())) and start <= end:
            if end - start + 1 > len(result):
                result = s[start:end + 1]
            if s[start] in vowels:
                counts[s[start]] -= 1
            start += 1
    return result
class Solution:

    def findTheLongestSubstring(self, s: str) -> int:
        vowels = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        d = {0: -1}
        state, ans = (0, 0)
        for i, c in enumerate(s):
            if c in vowels:
                state ^= vowels[c]
            if not state in d:
                d[state] = i
            ans = max(ans, i - d[state])
        return ans
