class Solution(object):

    def checkRecord(self, s):
        """
        :type s: str
        :rtype: bool
        """
        count_abscence = 0
        previous_pos = -1
        count_late = 0
        for pos, i in enumerate(s):
            if i == 'A':
                count_abscence += 1
                if count_abscence == 2:
                    return False
            if i == 'L':
                if pos == 0:
                    previous_pos = pos
                else:
                    if pos - previous_pos == 1:
                        count_late += 1
                    else:
                        count_late = 0
                    previous_pos = pos
                if count_late >= 2:
                    return False
        return True
def test_eligible_attendance_simple():
    solution_instance = Solution()
    assert eligibleAttendance('PPALLP') == solution_instance.checkRecord('PPALLP')
