def maximumUnits(boxTypes, truckSize):
    boxTypes.sort(key=lambda x: x[1], reverse=True)
    total_units = 0
    for num_boxes, units_per_box in boxTypes:
        if truckSize == 0:
            break
        boxes_to_add = min(num_boxes, truckSize)
        total_units += boxes_to_add * units_per_box
        truckSize -= boxes_to_add
    return total_units

