def maximal_network_rank(n: int, roads: List[List[int]]) -> int:
    city_count = [0] * n
    connection_count = [[False] * n for _ in range(n)]
    for a, b in roads:
        city_count[a] += 1
        city_count[b] += 1
        connection_count[a][b] = True
        connection_count[b][a] = True
    max_rank = 0
    for i in range(n):
        for j in range(i + 1, n):
            rank = city_count[i] + city_count[j]
            if connection_count[i][j]:
                rank -= 1
            max_rank = max(max_rank, rank)
    return max_rank
class Solution:

    def maximalNetworkRank(self, n: int, roads: List[List[int]]) -> int:
        indegree = [0] * n
        for i, j in roads:
            indegree[i] += 1
            indegree[j] += 1
        fMax, sMax = (0, 0)
        fCt, sCt = (0, 0)
        for i in indegree:
            if i > fMax:
                sMax = fMax
                fMax = i
                sCt = fCt
                fCt = 1
            elif i < fMax and i > sMax:
                sMax = i
                sCt = 1
            elif i == fMax:
                fCt += 1
            elif i == sMax:
                sCt += 1
        if fCt > 1:
            edcount = 0
            for road in roads:
                if indegree[road[0]] == fMax and indegree[road[1]] == fMax:
                    edcount += 1
            if edcount == fCt * (fCt - 1) // 2:
                flag = 1
            else:
                flag = 0
            return 2 * fMax - flag
        else:
            edcount = 0
            for road in roads:
                if indegree[road[0]] == fMax and indegree[road[1]] == sMax:
                    edcount += 1
                if indegree[road[1]] == fMax and indegree[road[0]] == sMax:
                    edcount += 1
            if sCt == edcount:
                flag = 1
            else:
                flag = 0
            return fMax + sMax - flag
def test_simple_case():
    solution_instance = Solution()
    assert maximal_network_rank(4, [[0, 1], [0, 3], [1, 2], [1, 3]]) == solution_instance.maximalNetworkRank(4, [[0, 1], [0, 3], [1, 2], [1, 3]])
def test_medium_case():
    solution_instance = Solution()
    assert maximal_network_rank(5, [[0, 1], [1, 2], [2, 3], [3, 4]]) == solution_instance.maximalNetworkRank(5, [[0, 1], [1, 2], [2, 3], [3, 4]])
def test_complex_case():
    solution_instance = Solution()
    assert maximal_network_rank(6, [[0, 1], [1, 2], [2, 3], [0, 2], [3, 4], [4, 5]]) == solution_instance.maximalNetworkRank(6, [[0, 1], [1, 2], [2, 3], [0, 2], [3, 4], [4, 5]])

