from typing import *
from collections import *
from math import *

def carCollisions(n: int, directions: str) -> int:
    collisions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if directions[i] == 'L' and directions[j] == 'R':
                collisions += 2
            elif directions[i] == 'R' and directions[j] == 'L':
                collisions += 2
            elif directions[i] != 'S' and directions[j] == 'S':
                collisions += 1
            elif directions[i] == 'S' and directions[j] != 'S':
                collisions += 1
    return collisions
class Solution:

    def countCollisions(self, directions: str) -> int:
        count = 0
        stack = []
        for char in directions:
            if not stack and char == 'L':
                continue
            elif not stack and char != 'L':
                stack.append(char)
            else:
                cur = stack[-1]
                if char == cur or (cur == 'S' and char == 'R') or (cur == 'L' and char == 'S') or (cur == 'L' and char == 'R'):
                    stack.append(char)
                elif cur == 'S' and char == 'L':
                    count += 1
                elif cur == 'R' and char == 'S':
                    count += 1
                    stack.pop()
                    stack.append('S')
                elif cur == 'R' and char == 'L':
                    count += 2
                    stack.pop()
                    stack.append('S')
        n = len(stack)
        i = 0
        while i < n:
            rs = 1
            if stack[i] == 'S':
                i += 1
            elif stack[i] == 'R':
                if i == n - 1:
                    return count
                elif stack[i] != stack[i + 1]:
                    count += 1
                    i += 1
                else:
                    while i < n - 1 and stack[i] == 'R' and (stack[i] == stack[i + 1]):
                        rs += 1
                        i += 1
                    if i == n - 1:
                        return count
                    else:
                        count += rs
                        i += 1
        return count
def test_simple_case():
    solution_instance = Solution()
    assert carCollisions(5, 'RLRSR') == solution_instance.countCollisions('RLRSR')
def test_edge_case():
