            smaller_dict = d1
        else:
            smaller_dict = d2
        for key, val in smaller_dict.items():
            if key in d1 and key in d2:
                copies = min(d1[key], d2[key])
                while copies != 0:
                    intersection.append(key)
                    copies -= 1
        return intersection
