def minNumberOfClips(clips, time):
    clips.sort()
    curr_end, next_end, clip_count = 0, 0, 0

    for start, end in clips:
        if next_end >= time or start > next_end:
            break
        elif curr_end < start <= next_end:
            clip_count += 1
            curr_end = next_end
        next_end = max(next_end, end)

    return clip_count if next_end >= time else -1

