def minMagneticForce(position, m):
    position.sort() 
    low, high = 0, position[-1]-position[0]
    while low <= high:
        mid = (low+high)//2
        count, prev = 1, position[0]
        for i in range(1, len(position)):
            if position[i] - prev >= mid:
                count += 1
                prev = position[i]
        if count >= m:
            low = mid+1
        else:
            high = mid-1
    return high

