from typing import *
from collections import *
from math import *

def min_swaps(s):
    count = 0
    for i in range(0, len(s) - 1):
        if s[i] == s[i + 1]:
            if s[i] == '1':
                s = s[:i + 1] + '0' + s[i + 2:]
            else:
                s = s[:i + 1] + '1' + s[i + 2:]
            count += 1
    return count
class Solution:

    def minSwaps(self, s: str) -> int:
        ans = n = len(s)
        zero, one = (0, 0)
        for c in s:
            if c == '0':
                zero += 1
            else:
                one += 1
        if abs(zero - one) > 1:
            return -1
        if zero >= one:
            s1 = '01' * (n // 2)
            s1 += '0' if n % 2 else ''
            cnt = sum((c1 != c for c1, c in zip(s1, s)))
            ans = cnt // 2
        if zero <= one:
            s2 = '10' * (n // 2)
            s2 += '1' if n % 2 else ''
            cnt = sum((c2 != c for c2, c in zip(s2, s)))
            ans = min(ans, cnt // 2)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert min_swaps('1100') == solution_instance.minSwaps('1100')
def test_edge_case():
    solution_instance = Solution()
    assert min_swaps('010101') == solution_instance.minSwaps('010101')
def test_difficult_case():
    solution_instance = Solution()
    assert min_swaps('111000') == solution_instance.minSwaps('111000')

