class Solution:

    def countSubarrays(self, nums: List[int], minK: int, maxK: int) -> int:
        i = 0
        j = 0
        ans = 0
        minn = []
        maxx = []
        while j < len(nums):
            if nums[j] == minK:
                minn.append(j)
            if nums[j] == maxK:
                maxx.append(j)
            if nums[j] < minK or nums[j] > maxK:
                a, b = (0, 0)
                while a < len(minn) and b < len(maxx):
                    m = max(minn[a], maxx[b])
                    ans += j - m
                    if nums[i] == minK:
                        a += 1
                    if nums[i] == maxK:
                        b += 1
                    i += 1
                minn.clear()
                maxx.clear()
                i = j + 1
            j += 1
        a, b = (0, 0)
        while a < len(minn) and b < len(maxx):
            m = max(minn[a], maxx[b])
            ans += j - m
            if nums[i] == minK:
                a += 1
            if nums[i] == maxK:
                b += 1
            i += 1
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert fixed_bound_subarrays([1, 3, 5, 2, 7, 5, 2], 2, 5) == solution_instance.countSubarrays([1, 3, 5, 2, 7, 5, 2], 2, 5)
