def minSetSize(num, k):
    if num == 0:
        return -1
    if k == 0:
        return -1
    if k == 10:
        return -1
    sum = 0
    count = 0
    while sum < num:
        count += 1
        sum += int(str(k) + "0" * (count - 1))
    if sum == num:
        return count
    else:
        return -1

