def numSegments(s):
    return len(s.split())
class Solution:

    def countSegments(self, s: str) -> int:
        n = len(s)
        cnt = 0
        start = 0
        end = n - 1
        if n == 0:
            return 0
        while start <= n - 1 and s[start] == ' ':
            start += 1
        if start == n:
            return 0
        while end >= 0 and s[end] == ' ':
            end -= 1
        if end == -1:
            return 0
        if end + 1 <= start:
            return 0
        for i in range(start, end + 1):
            if i >= 1 and s[i] == ' ' and (s[i - 1] != ' '):
                cnt += 1
        return cnt + 1
def test_simple_case():
    solution_instance = Solution()
    assert numSegments('Hello, my name is John') == solution_instance.countSegments('Hello, my name is John')
