import re

def regex_match(p: str, s: str) -> bool:
    if not p and not s:
        return True
    if len(p) >= 2 and p[1] == "*":
        return (regex_match(p[2:], s) or (len(s) > 0 and (p[0] == "." or p[0] == s[0]) and regex_match(p, s[1:])))
    else:
        return len(s) > 0 and (p[0] == "." or p[0] == s[0]) and regex_match(p[1:], s[1:])

