class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        stack = []
        for val in preorder.split(','):
            stack.append(val)
            while len(stack) > 2 and stack[-2:] == ['#', '#'] and stack[-3] != '#':
                stack.pop()
                stack.pop()
                stack[-1] = '#'
        return len(stack) == 1 and stack.pop() == '#'

