    return True
class Solution:

    def compare(self, cache, word1, word2):
        i, j = (0, 0)
        while i < len(word1) and j < len(word2):
            if cache[word1[i]] < cache[word2[j]]:
                return True
            elif cache[word1[i]] > cache[word2[j]]:
                return False
            else:
                i += 1
                j += 1
        if i < len(word1):
            return False
        '\n            why false?\n            In some cases word1 can be aaa, word2 can be aa\n            here we must return false becoz they are not in lexicographic order\n            becoz word2 appears first than word1\n        '
        return True

    def isAlienSorted(self, words: List[str], order: str) -> bool:
        """
            Main Idea behind this is,
            How we see our Oxford or Some english Dictionary (So called lexicographic order)

            Eg:
            Case 1:
                Assume we have words like ad, af, ag, ba, bba, bbaaaag in our oxford Dictionary
                at diff page numbers Now compare the page numbers of these words once it is for sure
                pageNumber(ad) < pageNumber(af) < pageNumber(ag) < ... pageNumber(bbaaag)
            Case 2:
                if we go in depth
                if two 2 words are in same page, say x, xy
                it is for sure LineNumber(x) < lineNumber(xy) (Note < operator is Strictly lesser)
            Case 3:
                Words like a, aa, aaa, aaaa are in our dictionary
                definitly appearance(a) < appearance(aa) < appearance(aaa) < appearance(aaaa)
                appearance may be a line number or page number
        """
        '\n            In our Question there are asking for a different alphabetical order and asking us to check \n            whether appearance(word1) < appearance(word2) < appearance(word3) < ... < appearance(wordn) or not\n            Just compare \n                word1 with word2 \n                word2 with word3\n                word3 with word4\n                ....\n                wordn-1 with wordn\n            Reason: if word1 < word2 it is for sure lesser than word3 and so on\n        '
        cache = {}
        for i in range(len(order)):
            cache[order[i]] = i
        for i in range(1, len(words)):
            if not self.compare(cache, words[i - 1], words[i]):
                return False
        return True
def test_simple_case():
    solution_instance = Solution()
    assert isAlienSorted(['hello', 'leetcode'], 'hlabcdefgijkmnopqrstuvwxyz') == solution_instance.isAlienSorted(['hello', 'leetcode'], 'hlabcdefgijkmnopqrstuvwxyz')
def test_edge_case():
    solution_instance = Solution()
    assert isAlienSorted(['word', 'world', 'row'], 'worldabcefghijkmnpqstuvxyz') == solution_instance.isAlienSorted(['word', 'world', 'row'], 'worldabcefghijkmnpqstuvxyz')
def test_difficult_case():
    solution_instance = Solution()
    assert isAlienSorted(['apple', 'app'], 'abcdefghijklmnopqrstuvwxyz') == solution_instance.isAlienSorted(['apple', 'app'], 'abcdefghijklmnopqrstuvwxyz')

