def isMagicSquare(grid, i, j):
    # Check row sums
    row_sum = sum(grid[i][j:j+3])
    for k in range(1, 3):
        if sum(grid[i+k][j:j+3]) != row_sum:
            return False

    # Check column sums
    col_sum = sum(grid[i][j] + grid[i+1][j+1] + grid[i+2][j+2])
    if sum(grid[i][j] + grid[i+1][j+1] + grid[i+2][j+2]) != col_sum:
        return False
