def num_operations(num1, num2):
    count = 0
    while num1 > 0 and num2 > 0:
        if num1 >= num2:
            num1 -= num2
        else:
            num2 -= num1
        count += 1
    return count
class Solution:

    def countOperations(self, num1: int, num2: int) -> int:
        numberOfOperations = 0
        while True:
            if num1 == 0 or num2 == 0:
                break
            elif num1 == num2:
                numberOfOperations += 1
                break
            elif num1 > num2 and num1 % num2 == 0:
                numberOfOperations += num1 // num2
                break
            elif num2 > num1 and num2 % num1 == 0:
                numberOfOperations += num2 // num1
                break
            else:
                if num1 >= num2:
                    num1 -= num2
                else:
                    num2 -= num1
                numberOfOperations += 1
        return numberOfOperations
def test_simple_case():
    solution_instance = Solution()
    assert num_operations(10, 10) == solution_instance.countOperations(10, 10)
def test_edge_case():
    solution_instance = Solution()
    assert num_operations(15, 5) == solution_instance.countOperations(15, 5)
def test_difficult_case():
    solution_instance = Solution()
    assert num_operations(20, 3) == solution_instance.countOperations(20, 3)

