def maximumNumber(num: str, change: List[int]) -> str:
    nums = list(num)
    is_mutated = False

    for i in range(len(nums)):
        digit = int(nums[i])
        if change[digit] > digit:
            nums[i] = str(change[digit])
            is_mutated = True
        elif change[digit] == digit:
            continue
        else:
            if is_mutated:
                break

    return "".join(nums)

