class Solution:

    def maximumNumber(self, num: str, change: List[int]) -> str:
        num = list(num)
        mutated = False
        for idx, n in enumerate(num):
            n = int(n)
            if change[n] > n:
                num[idx] = str(change[n])
                mutated = True
            elif change[n] < n and mutated:
                break
        return ''.join(num)
def test_simple_case():
    sol_instance = Solution()
