def num_captures(board):
    white_rook_pos = None
    pawns_pos = []
    white_bishops_pos = []

    # finding positions
    for i in range(len(board)):
        for j in range(len(board[0])):

            if board[i][j] == 'R':
                white_rook_pos = (i, j)

            elif board[i][j] == 'p':
                pawns_pos.append((i, j))

            elif board[i][j] == 'B':
                white_bishops_pos.append((i, j))

    captures = 0

    # finding captures
    for pawn_pos in pawns_pos:

        # same row
        if pawn_pos[0] == white_rook_pos[0]:

            if pawn_pos[1] > white_rook_pos[1]:
                blocked = False
                for bishop_pos in white_bishops_pos:
                    if bishop_pos[1] > white_rook_pos[1] and bishop_pos[1] < pawn_pos[1] and bishop_pos[0] == pawn_pos[0]:
                        blocked = True
                        break
                if not blocked:
                    captures += 1

            else:
                blocked = False
                for bishop_pos in white_bishops_pos:
                    if bishop_pos[1] < white_rook_pos[1] and bishop_pos[1] > pawn_pos[1] and bishop_pos[0] == pawn_pos[0]:
                        blocked = True
                        break
                if not blocked:
                    captures += 1

        # same col
        elif pawn_pos[1] == white_rook_pos[1]:

            if pawn_pos[0] > white_rook_pos[0]:
                blocked = False
                for bishop_pos in white_bishops_pos:
                    if bishop_pos[0] > white_rook_pos[0] and bishop_pos[0] < pawn_pos[0] and bishop_pos[1] == pawn_pos[1]:
                        blocked = True
                        break
                if not blocked:
                    captures += 1

            else:
                blocked = False
                for bishop_pos in white_bishops_pos:
                    if bishop_pos[0] < white_rook_pos[0] and bishop_pos[0] > pawn_pos[0] and bishop_pos[1] == pawn_pos[1]:
                        blocked = True
                        break
                if not blocked:
                    captures += 1

    return captures

