class Solution:

    def numRookCaptures(self, board: List[List[str]]) -> int:
        res = [0]

        def find(i, j, dirn):
            if i < 0 or i > 7 or j < 0 or (j > 7) or (board[i][j] == 'B'):
                return
            if i >= 0 and i < 8 and (j >= 0) and (j < 8) and (board[i][j] == 'p'):
                res[0] += 1
                return
            if dirn == 'north':
                find(i + 1, j, 'north')
