def removeComments(source: List[str]) -> List[str]:
    ans = []
    in_block_comment = False
    for line in source:
        i = 0
        if not in_block_comment:
            new_line = []
        while i < len(line):
            if line[i:i + 2] == '/*' and (not in_block_comment):
                in_block_comment = True
                i += 1
            elif line[i:i + 2] == '*/' and in_block_comment:
                in_block_comment = False
                i += 1
            elif line[i:i + 2] == '//':
                break
            elif not in_block_comment:
                new_line.append(line[i])
            i += 1
        if new_line and (not in_block_comment):
            ans.append(''.join(new_line))
    return ans
class Solution(object):

    def removeComments(self, source):
        """
        :type source: List[str]
        :rtype: List[str]
        """
        result = []
        current_line = ''
        in_block = False
        in_line = False
        skip_next = False
        for line in source:
            skip_next = False
            in_line = False
            for index, character in enumerate(line):
                if skip_next:
                    skip_next = False
                    continue
                if in_line:
                    continue
                if in_block:
                    if line[index:index + 2] == '*/':
                        in_block = False
                        skip_next = True
                        continue
                    else:
                        continue
                if line[index:index + 2] == '/*':
                    in_block = True
                    skip_next = True
                    continue
                if line[index:index + 2] == '//':
                    in_line = True
                    skip_next = True
                    continue
                current_line += character
            if not in_block and current_line:
                result.append(current_line)
                current_line = ''
        return result
def test_simple_case():
    source_instance = Solution()
    assert removeComments(['/*Test program */', 'int main()', '{', '  // variable declaration ', 'int a, b, c;', '/* This is a test', '   multiline  ', '   comment for ', '   testing */', 'a = b + c;', '}']) == source_instance.removeComments(['/*Test program */', 'int main()', '{', '  // variable declaration ', 'int a, b, c;', '/* This is a test', '   multiline  ', '   comment for ', '   testing */', 'a = b + c;', '}'])
def test_edge_case():
    source_instance = Solution()
    assert removeComments(['int main()', '{', '  // variable declaration ', 'int a, b, c;', '}', '/* Code continues */', 'int main()', '{', '  // Reset variable values', 'a = b + c;', '}']) == source_instance.removeComments(['int main()', '{', '  // variable declaration ', 'int a, b, c;', '}', '/* Code continues */', 'int main()', '{', '  // Reset variable values', 'a = b + c;', '}'])
def test_difficult_case():
    source_instance = Solution()
    assert removeComments(['int main()', '{', '/* Just return 0 */', 'return 0;', '}']) == source_instance.removeComments(['int main()', '{', '/* Just return 0 */', 'return 0;', '}'])

