def minOperations(nums: List[int], x: int) -> int:
    target_sum = sum(nums) - x
    if target_sum == 0:
        return len(nums)
    if target_sum < 0:
        return -1
    left = 0
    curr_sum = 0
    max_len = float('-inf')
    for right in range(len(nums)):
        curr_sum += nums[right]
        while curr_sum > target_sum and left <= right:
            curr_sum -= nums[left]
            left += 1
        if curr_sum == target_sum:
            max_len = max(max_len, right - left + 1)
    return len(nums) - max_len if max_len != float('-inf') else -1
class Solution(object):

    def minOperations(self, li, x):
        numsSum = sum(li)
        k = numsSum - x
        n = len(li)
        i, j, s = (0, 0, 0)
        l = []
        maximum = float('-inf')
        if numsSum == x:
            return n
        if k > 0:
            while j < n:
                s += li[j]
                if s < k:
                    j += 1
                elif s == k:
                    maximum = max(maximum, j - i + 1)
                    j += 1
                elif s > k:
                    while s > k:
                        s -= li[i]
                        i += 1
                        if s == k:
                            maximum = max(maximum, j - i + 1)
                    j += 1
            return n - maximum if maximum != float('-inf') else -1
        else:
            return -1
def test_simple_case():
    sol_instance = Solution()
    assert minOperations([1, 1, 4, 2, 3], 5) == sol_instance.minOperations([1, 1, 4, 2, 3], 5)
def test_edge_case():
    sol_instance = Solution()
    assert minOperations([5, 6, 7, 8, 9], 4) == sol_instance.minOperations([5, 6, 7, 8, 9], 4)
def test_difficult_case():
    sol_instance = Solution()
    assert minOperations([3, 2, 20, 1, 1, 3], 10) == sol_instance.minOperations([3, 2, 20, 1, 1, 3], 10)

