def minMoves(nums):
    return sum(nums) - min(nums) * len(nums)
class Solution:

    def minMoves(self, nums: List[int]) -> int:
        _min = min(nums)
        ans = 0
        if all((ele == nums[0] for ele in nums)):
            return 0
        else:
            for ele in nums:
                ans = ans + (ele - _min)
            return ans
