class Solution:

    def new21Game(self, n: int, k: int, maxPts: int) -> float:
        if n >= k - 1 + maxPts:
            return 1
        dp = [0] * (n + 1)
        dp[0], curSum = (1, 0)
        for i in range(1, n + 1):
            if i - 1 < k:
                curSum += dp[i - 1]
            if i - 1 >= maxPts:
                curSum -= dp[i - 1 - maxPts]
            dp[i] = curSum / maxPts
        return sum(dp[k:])
def test_simple_case():
    solution_instance = Solution()
    assert game_probability(10, 1, 10) == solution_instance.new21Game(10, 1, 10)
def test_edge_case():
    solution_instance = Solution()
    assert game_probability(6, 1, 10) == solution_instance.new21Game(6, 1, 10)
def test_difficult_case():
    solution_instance = Solution()
    assert game_probability(21, 10, 20) == solution_instance.new21Game(21, 10, 20)

