from typing import *
from collections import *
from math import *

def can_reach_end(s: str, min_jump: int, max_jump: int) -> bool:
    if s[-1] != '0':
        return False
    dp = [False] * len(s)
    dp[0] = True
    for i in range(1, len(s)):
        if s[i] == '0':
            for j in range(max(min_jump, i - max_jump), i):
                if j >= 0 and dp[j]:
                    dp[i] = True
                    break
    return dp[-1]
class Solution:

    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
        if s[-1] == '1':
            return False
        if minJump <= len(s) - 1 <= maxJump:
            return True
        Len, start, end, pre_start, pre_end = (len(s), minJump, maxJump, -1, -1)
        while True:
            if pre_start == start and pre_end == end:
                return False
            pre_start, pre_end = (start, end)
            for i in range(pre_start, pre_end + 1):
                if s[i] == '0' and '0' in s[i + minJump:i + maxJump + 1]:
                    if start <= pre_end:
                        start = i + minJump
                    end = i + maxJump
                    if start <= Len - 1 <= end:
                        return True
def test_simple_case():
    sol_instance = Solution()
    assert can_reach_end('001010', 2, 3) == sol_instance.canReach('001010', 2, 3)
def test_edge_case():
    sol_instance = Solution()
    assert can_reach_end('00101010', 2, 2) == sol_instance.canReach('00101010', 2, 2)
def test_difficult_case():
    sol_instance = Solution()
    assert can_reach_end('0010101000', 3, 5) == sol_instance.canReach('0010101000', 3, 5)

