class Solution:

    def canBeTypedWords(self, text: str, brokenLetters: str) -> int:
        words = text.split(' ')
        output = len(words)
        for word in words:
            for letter in word:
                if brokenLetters.find(letter) != -1:
                    output -= 1
                    break
        return output
