class First_class:

    def detectCapitalUse(self, word: str) -> bool:
        if word.upper() == word or word.lower() == word or word.capitalize() == word:
            return True
        return False
class Solution:

    def detectCapitalUse(self, word: str) -> bool:

        def isSameCase(l, r, word, isUpper):
            while l <= r:
                if word[l].isupper() != isUpper or word[r].isupper() != isUpper:
                    return False
                l += 1
                r -= 1
            return True
        if len(word) == 1:
            return True
        if word[0].isupper() and word[1].isupper():
            return isSameCase(1, len(word) - 1, word, True)
        elif word[0].islower() and word[1].islower():
            return isSameCase(1, len(word) - 1, word, False)
        elif word[0].isupper() and word[1].islower():
            return isSameCase(1, len(word) - 1, word, False)
        else:
            return False
def test_simple_upper_case():
    first_instance = First_class()
    solution_instance = Solution()
    assert first_instance.detectCapitalUse('USA') == solution_instance.detectCapitalUse('USA')
