def large_groups(string):
    groups = []
    start = 0
    for i in range(len(string)):
        if i == len(string)-1 or string[i] != string[i+1]:
            if i - start + 1 >= 3:
                groups.append((start, i))
            start = i+1
    return sorted(groups, key=lambda x: x[0])

