class Solution:

    def largeGroupPositions(self, s: str) -> List[List[int]]:
        s = s + '!'
        LENGTH = len(s)
        soln = []
        prev = s[0]
        prevIndex = 0
        pointer = 1
        streak = 1
        while pointer < LENGTH:
            current = s[pointer]
            if current == prev:
                streak += 1
                pointer += 1
                continue
            elif current != prev and streak >= 3:
                soln.append([prevIndex, pointer - 1])
            streak = 1
            prev = current
            prevIndex = pointer
            pointer += 1
        return soln
def test_simple_case():
    solution = Solution()
    assert large_groups('aaa') == solution.largeGroupPositions('aaa')
def test_complex_case():
    solution = Solution()
    assert large_groups('abbxxxxzzy') == solution.largeGroupPositions('abbxxxxzzy')
