class Solution:

    def minNumberOperations(self, target: List[int]) -> int:
        threshold = 0
        n = len(target)
        target.append(0)
        target.insert(0, 0)
        ans = 0
        for i in range(1, n + 1):
            if target[i - 1] <= target[i] > target[i + 1]:
                ans += max(0, target[i] - threshold)
            elif target[i - 1] > target[i] <= target[i + 1]:
                threshold = target[i]
        return ans
