class Solution:

    def minimumAbsDifference(self, arr: List[int]) -> List[List[int]]:
        ref_arr = sorted(arr)
        min_diff = ref_arr[-1] - ref_arr[0]
        diff_pairs = []
        for i, number in enumerate(ref_arr[:-1], 1):
            if ref_arr[i] - number > min_diff:
                continue
            elif ref_arr[i] - number < min_diff:
                min_diff = ref_arr[i] - number
                diff_pairs.clear()
            diff_pairs.append([number, ref_arr[i]])
        return diff_pairs
