def closedIsland(grid):

    def dfs(i, j):
        if 0 <= i < m and 0 <= j < n and (grid[i][j] == 0):
            grid[i][j] = 1
            dfs(i + 1, j)
            dfs(i - 1, j)
            dfs(i, j + 1)
            dfs(i, j - 1)
            return True
        return False
    m, n = (len(grid), len(grid[0]))
    count = 0
    for i in range(m):
        for j in range(n):
            if i == 0 or j == 0 or i == m - 1 or (j == n - 1):
                dfs(i, j)
