    def remove_ab(s: str) -> Tuple[str, int]:
        points = 0
        while 'ab' in s:
            s = s.replace('ab', '', 1)
            points += x
        return (s, points)

    def remove_ba(s: str) -> Tuple[str, int]:
        points = 0
        while 'ba' in s:
            s = s.replace('ba', '', 1)
            points += y
        return (s, points)
    max_points = 0
