class Solution:

    def maximumGain(self, s: str, x: int, y: int) -> int:
        a, b = ('ab', 'ba')
        if y > x:
            b, a, y, x = (a, b, x, y)
        answer = 0
        for word in [a, b]:
            stack = []
            i = 0
            while i < len(s):
                stack.append(s[i])
                n = len(stack)
                prefix = stack[n - 2] + stack[n - 1]
                if prefix == word:
                    answer += x
                    stack.pop()
                    stack.pop()
                i += 1
            x = y
            s = ''.join(stack)
        return answer
def test_simple_case():
    solution_instance = Solution()
    assert max_points_gain('cabxbae', 2, 5, 2) == solution_instance.maximumGain('cabxbae', 2, 5)
