def maxCandies(candies: List[int], k: int) -> int:
    def check(x):
        total = 0
        for candy in candies:
            total += candy // x
            if total >= k:
                return True
        return False

    l, r = 1, sum(candies)
    while l < r:
        mid = (l+r+1) // 2
        if check(mid):
            l = mid
        else:
            r = mid - 1

    return l * k

