def deleteAndEarn(nums: List[int]) -> int:
    if not nums:
        return 0
    max_val = max(nums)
    freq = [0] * (max_val + 1)
    for num in nums:
        freq[num] += num
    prev, curr = (0, 0)
    for i in range(max_val + 1):
        temp = max(curr, prev + freq[i])
        prev = curr
        curr = temp
    return curr
class Solution:

    def deleteAndEarn(self, nums: List[int]) -> int:
        hashmap = {}
        for num in nums:
            if num not in hashmap:
                hashmap[num] = 1
            else:
                hashmap[num] += 1

        def helper(arr, d):
            if len(arr) == 1:
                return arr[0]
            s = set(arr)
            ans = 0
            for e in s:
                copy = d.copy()
                if copy[e] == 1:
                    copy.pop(e)
                else:
                    copy[e] -= 1
                if e + 1 in copy:
                    copy.pop(e + 1)
                if e - 1 in copy:
                    copy.pop(e - 1)
                overall_arr = []
                for k, v in copy.items():
                    overall_arr = overall_arr + [k for _ in range(v)]
                ans = max(ans, helper(overall_arr, copy) + e)
            return ans
        return helper(nums, hashmap)
def test_simple_case():
    solution_instance = Solution()
    assert deleteAndEarn([3, 4, 2]) == solution_instance.deleteAndEarn([3, 4, 2])
def test_edge_case():
    solution_instance = Solution()
    assert deleteAndEarn([2, 2, 3, 3, 3, 4]) == solution_instance.deleteAndEarn([2, 2, 3, 3, 3, 4])
def test_difficult_case():
    solution_instance = Solution()
