class Solution:

    def findLengthOfLCIS(self, nums: List[int]) -> int:
        LENGTH = len(nums)
        maxStreak = 1
        streak = 1
        pointer = 1
        prev = nums[0]
        while pointer < LENGTH:
            current = nums[pointer]
            if current > prev:
                streak += 1
            else:
                streak = 1
            maxStreak = max(streak, maxStreak)
            prev = current
            pointer += 1
        return maxStreak
def test_simple_case():
