    longest_streak = 0
    for num in num_set:
        if num - 1 not in num_set:
            current_num = num
            current_streak = 1
            while current_num + 1 in num_set:
                current_num += 1
                current_streak += 1
            longest_streak = max(longest_streak, current_streak)
    return longest_streak
class LinkedList:

    def __init__(self, v) -> None:
        self.val = v
        self.prev = None
        self.next = None
class Solution:

    def longestConsecutive(self, nums: List[int]) -> int:
        nodes = {}
        for n in nums:
            if n in nodes:
                continue
            node = LinkedList(n)
            nodes[n] = node
            if n - 1 in nodes:
                nodes[n - 1].next = node
                node.prev = nodes[n - 1]
            if n + 1 in nodes:
                nodes[n + 1].prev = node
                node.next = nodes[n + 1]
        starters = {n: node for n, node in nodes.items() if not node.prev}
        res = 0
        for n, node in starters.items():
            head = node
            count = 0
            while head:
                head = head.next
                count += 1
            res = max(res, count)
        return res
def test_simple_case():
    solution_instance = Solution()
    assert longestConsecutive([100, 4, 200, 1, 3, 2]) == solution_instance.longestConsecutive([100, 4, 200, 1, 3, 2])
def test_edge_case():
    solution_instance = Solution()
    assert longestConsecutive([0, 3, 7, 2, 5, 8, 4, 6, 0, 1]) == solution_instance.longestConsecutive([0, 3, 7, 2, 5, 8, 4, 6, 0, 1])
def test_difficult_case():
    solution_instance = Solution()
    assert longestConsecutive([9, 1, 4, 7, 3, -1, 0, 5, 8, -1, 6]) == solution_instance.longestConsecutive([9, 1, 4, 7, 3, -1, 0, 5, 8, -1, 6])

