def max_difference(nums):
    max_diff = -1
    min_num = float('inf')
    for num in nums:
        max_diff = max(max_diff, num - min_num)
        min_num = min(min_num, num)
    return max_diff if max_diff != 0 else -1
class Solution:

    def maximumDifference(self, nums: List[int]) -> int:
        curMin, curMinIdx = (float('inf'), 0)
        curMax, curMaxIdx = (-float('inf'), 0)
        result = -1
        for i in range(len(nums)):
            if nums[i] < curMin:
                curMin = nums[i]
                curMinIdx = i
                curMax = -float('inf')
            elif nums[i] > curMax:
                curMax = nums[i]
                curMaxIdx = i
            if curMaxIdx > curMinIdx and curMin < curMax:
                maxDiff = curMax - curMin
                if maxDiff > result:
                    result = maxDiff
        return result
def test_simple_case():
