def findKthPositive(arr, k):
    count = 0
    for i in range(1, arr[-1] + k + 1):
        if i not in arr:
            count += 1
            if count == k:
                return i
class Solution:

    def findKthPositive(self, arr: List[int], k: int) -> int:
        arr.sort()

        def helper(e, a):
            L, R = (0, len(a) - 1)
            while L <= R:
                mid = (L + R) // 2
                middle = a[mid]
                if middle == e:
                    return True
                elif middle < e:
                    L = mid + 1
                    continue
                else:
                    R = mid - 1
                    continue
            return False
        start = 1
        while True:
            if helper(start, arr):
                start += 1
                continue
            else:
                k -= 1
                if k == 0:
                    break
                start += 1
                continue
        return start
def test_simple_case():
    s_instance = Solution()
    assert findKthPositive([2, 3, 4, 7, 11], 5) == s_instance.findKthPositive([2, 3, 4, 7, 11], 5)
