def average(salary: List[int]) -> float:
    salary.sort()
    return sum(salary[1:-1]) / (len(salary) - 2)
class Solution:

    def merge(self, arr, L, R, m):
        i = j = k = 0
        while i < len(L) and j < len(R):
            if L[i] > R[j]:
                arr[k] = R[j]
                j += 1
            else:
                arr[k] = L[i]
                i += 1
            k += 1
        while i < len(L):
            arr[k] = L[i]
            i += 1
            k += 1
        while j < len(R):
            arr[k] = R[j]
            j += 1
            k += 1

    def mergeSort(self, arr):
        if len(arr) > 1:
            m = len(arr) // 2
            L = arr[:m]
            R = arr[m:]
            self.mergeSort(L)
            self.mergeSort(R)
            self.merge(arr, L, R, m)

    def average(self, salary: List[int]) -> float:
        self.mergeSort(salary)
        print(salary)
        neededArray = salary[1:-1]
        x = sum(neededArray)
        avg = x / len(neededArray)
        return avg
