def longestSubsequence(nums, k):
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] - nums[j] == k:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp) if max(dp) > 1 else 0

