class Solution:

    def triangleNumber(self, nums: List[int]) -> int:
        nums.sort()
        ans = 0
        for i in range(0, len(nums) - 2):
            for j in range(i + 1, len(nums) - 1):
                L, R = (j + 1, len(nums) - 1)
                while L <= R:
                    mid = (L + R) // 2
                    mid_e = nums[mid]
                    if mid_e < nums[i] + nums[j]:
                        L = mid + 1
                        continue
                    else:
                        R = mid - 1
                ans += L - j - 1
        return ans
def test_simple_case():
    nums = [2, 2, 3, 4]
    sol_instance = Solution()
    assert triangleNumber(nums) == sol_instance.triangleNumber(nums)
