    nums = [4, 2, 3, 4]
    sol_instance = Solution()
    assert triangleNumber(nums) == sol_instance.triangleNumber(nums)
def test_difficult_case():
    nums = [1, 1, 2, 3]
    sol_instance = Solution()
    assert triangleNumber(nums) == sol_instance.triangleNumber(nums)

