def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)
def countSubarrays(nums, k):
    n = len(nums)
    count = 0
    for i in range(n):
        subarray_gcd = nums[i]
        for j in range(i, n):
            subarray_gcd = gcd(subarray_gcd, nums[j])
            if subarray_gcd == k:
                count += 1
    return count
class Solution:

    def subarrayGCD(self, nums: List[int], k: int) -> int:

        def gcd(x, y):
            while y:
                x, y = (y, x % y)
            return x
        candidates = [_ % k for _ in nums]
        factor = [_ // k for _ in nums]
        segments = []
        start = 0
        inside = False
        while start < len(nums):
            if candidates[start] == 0:
                if not inside:
                    inside = True
                    segments.append(start)
            elif inside:
                segments.append(start - 1)
                inside = False
            start += 1
        if len(segments) % 2 == 1:
            segments.append(len(nums) - 1)
        res = 0
        for i in range(len(segments) // 2):
            start, end = (segments[i * 2], segments[i * 2 + 1])
            for t in range(start, end + 1):
                temp_gcd = factor[t]
                for k in range(t, end + 1):
                    temp_gcd = gcd(temp_gcd, factor[k])
                    if temp_gcd == 1:
                        res += end - k + 1
                        break
        return res
def test_simple_case():
    solution_instance = Solution()
    nums = [1, 2, 3, 4, 5]
    k = 1
    assert countSubarrays(nums, k) == solution_instance.subarrayGCD(nums, k)
def test_edge_case():
    solution_instance = Solution()
    nums = [2, 4, 6, 8, 10]
    k = 2
    assert countSubarrays(nums, k) == solution_instance.subarrayGCD(nums, k)
def test_difficult_case():
    solution_instance = Solution()
    nums = [1, 2, 3, 4, 5, 6, 7]
    k = 3
    assert countSubarrays(nums, k) == solution_instance.subarrayGCD(nums, k)

