def lengthOfLIS(nums):
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)
class Solution:

    def findNumberOfLIS(self, nums: List[int]) -> int:
        dp = [1] * len(nums)
        ct = [1] * len(nums)
        maxLen, maxCt = (0, 0)
        for i in range(len(nums)):
            for j in range(i):
                if nums[i] > nums[j]:
                    if dp[j] + 1 > dp[i]:
                        dp[i] = dp[j] + 1
                        ct[i] = ct[j]
                    elif dp[i] == dp[j] + 1:
                        ct[i] += ct[j]
            if dp[i] > maxLen:
                maxLen = dp[i]
        for i in range(len(nums)):
            if maxLen == dp[i]:
                maxCt += ct[i]
        return maxCt
def test_simple_case():
    solution_instance = Solution()
    nums = [1, 2, 4]
    assert lengthOfLIS(nums) == solution_instance.findNumberOfLIS(nums)
def test_edge_case():
    solution_instance = Solution()
    nums = [1, 3, 5, 4, 7]
    assert lengthOfLIS(nums) == solution_instance.findNumberOfLIS(nums)
def test_difficult_case():
    solution_instance = Solution()
    nums = [2, 2, 2, 2, 2]
    assert lengthOfLIS(nums) == solution_instance.findNumberOfLIS(nums)

