from typing import *
from collections import *
from math import *

def maxSumAfterPartitioning(arr, k):
    n = len(arr)
    dp = [0] * (n + 1)
    for i in range(n):
        curr_max = 0
        for j in range(1, k + 1):
            if i - j + 1 >= 0:
                curr_max = max(curr_max, arr[i - j + 1])
                dp[i] = max(dp[i], dp[i - j] + curr_max * j)
    return dp[n - 1]
class Solution:

    def maxSumAfterPartitioning(self, arr: List[int], k: int) -> int:
        n = len(arr)
        dp = [-1 for _ in range(n)]

        def solve(i):
            if i == n:
                return 0
            if dp[i] != -1:
                return dp[i]
            length = 0
            maxim = 0
            ansmax = 0
            for j in range(i, min(n, i + k)):
                length += 1
                maxim = max(maxim, arr[j])
                sumi = length * maxim + solve(j + 1)
                ansmax = max(ansmax, sumi)
            dp[i] = ansmax
            return dp[i]
        return solve(0)
def test_simple_case():
    sol_instance = Solution()
    assert maxSumAfterPartitioning([1, 15, 7, 9, 2, 5, 10], 3) == sol_instance.maxSumAfterPartitioning([1, 15, 7, 9, 2, 5, 10], 3)
def test_edge_case():
    sol_instance = Solution()
    assert maxSumAfterPartitioning([0, 1, 1, 2], 2) == sol_instance.maxSumAfterPartitioning([0, 1, 1, 2], 2)
def test_difficult_case():
    sol_instance = Solution()
    assert maxSumAfterPartitioning([1, 2, 3, 4, 5], 2) == sol_instance.maxSumAfterPartitioning([1, 2, 3, 4, 5], 2)

