    solution_instance = Solution()
    assert maxFrequency([1, 1, 1, 1, 1, 1], 0) == solution_instance.maxFrequency([1, 1, 1, 1, 1, 1], 0)
def test_difficult_case():
    solution_instance = Solution()
    assert maxFrequency([1, 2, 3, 4, 4], 3) == solution_instance.maxFrequency([1, 2, 3, 4, 4], 3)

