from typing import *
from collections import *
from math import *

def isIdealPermutation(nums):
    num_globals = 0
    num_locals = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] > nums[j]:
                num_globals += 1
                if j == i + 1:
                    num_locals += 1
    return num_globals == num_locals
class Solution:

    def isIdealPermutation(self, nums: List[int]) -> bool:
        cnt = sum((nums[i] > nums[i + 1] for i in range(len(nums) - 1)))
        aux = nums.copy()

        def fn(nums, aux, lo, hi):
            """Return count of global inversions of nums[lo:hi]."""
            if lo + 1 >= hi:
                return 0
            mid = lo + hi >> 1
            left = fn(aux, nums, lo, mid)
            right = fn(aux, nums, mid, hi)
            split = 0
            i, j = (lo, mid)
            for k in range(lo, hi):
                if j >= hi or (i < mid and aux[i] < aux[j]):
                    nums[k] = aux[i]
                    i += 1
                else:
                    nums[k] = aux[j]
                    j += 1
                    split += mid - i
            return left + split + right
        return cnt == fn(nums, aux, 0, len(nums))
def test_simple_case():
    solution_instance = Solution()
    assert isIdealPermutation([1, 0, 2]) == solution_instance.isIdealPermutation([1, 0, 2])
