def isIdealPermutation(nums):
    num_globals = 0
    num_locals = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] > nums[j]:
                num_globals += 1
                if j == i+1:
                    num_locals += 1
    return num_globals == num_locals

