class Solution:

    def reformatNumber(self, number: str) -> str:
        number = number.replace('-', '')
        number = number.replace(' ', '')
        returnString = ''
        while len(number) > 4:
            returnString += number[0:3] + '-'
            number = number[3:]
        if len(number) == 3:
            returnString += number[0:3]
        else:
            returnString += number[0:2]
            number = number[2:]
            if len(number) > 0:
                returnString += '-' + number
        return returnString
def test_simple_case():
    solution_instance = Solution()
    assert reformat_number('1-23-45 6') == solution_instance.reformatNumber('1-23-45 6')
