class Solution:

    def firstUniqChar(self, s: str) -> int:
        exdict = {}
        for i in s:
            if i not in exdict:
                exdict[i] = 1
            else:
                exdict[i] += 1
        temp = []
        for key, val in exdict.items():
            if val == 1:
                temp.append(key)
        if len(temp) == 0:
            return -1
        for count, i in enumerate(s):
            if i in temp:
                return count
def test_simple_case():
    sol_instance = Solution()
