def longestSubsequence(arr, difference):
    dp = {}
    for num in arr:
        dp[num] = dp.get(num - difference, 0) + 1
    return max(dp.values())
class Solution:

    def longestSubsequence(self, arr: List[int], difference: int) -> int:
        maps = {}
        for i, num in enumerate(arr):
            if num not in maps:
                maps[num] = [1, i]
            if num - difference in maps and maps[num - difference][1] < i:
                maps[num] = [maps[num - difference][0] + 1, i]
        return max([v[0] for v in maps.values()])
def test_simple_case():
    solution_instance = Solution()
    assert longestSubsequence([1, 2, 3], 1) == solution_instance.longestSubsequence([1, 2, 3], 1)
