class Solution:

    def corpFlightBookings(self, bookings: List[List[int]], n: int) -> List[int]:
        res, diffs = ([0] * n, [0] * n)
        for i in range(0, len(bookings)):
            first = bookings[i][0] - 1
            last = bookings[i][1] - 1
            k = bookings[i][2]
            diffs[first] += k
            if last + 1 < n:
                diffs[last + 1] -= k
        res[0] = diffs[0]
        for i in range(1, n):
            res[i] = res[i - 1] + diffs[i]
        return res
def test_simple_case():
    solution_instance = Solution()
    assert corpFlightBookings([[1, 2, 10], [2, 3, 20], [2, 5, 25]], 5) == solution_instance.corpFlightBookings([[1, 2, 10], [2, 3, 20], [2, 5, 25]], 5)
def test_edge_case():
    solution_instance = Solution()
    assert corpFlightBookings([[1, 1, 1], [2, 2, 2]], 2) == solution_instance.corpFlightBookings([[1, 1, 1], [2, 2, 2]], 2)
def test_difficult_case():
    solution_instance = Solution()
    assert corpFlightBookings([[1, 2, 10], [3, 4, 15], [1, 5, 20]], 5) == solution_instance.corpFlightBookings([[1, 2, 10], [3, 4, 15], [1, 5, 20]], 5)

