class Solution:

    def areNumbersAscending(self, s: str) -> bool:

        def getTokens(s):
            i = 0
            currentToken = []
            while i < len(s):
                if s[i] != ' ':
                    currentToken.append(s[i])
                else:
                    yield ''.join(currentToken)
                    currentToken = []
                i += 1
            if currentToken:
                yield ''.join(currentToken)
        prev = None
        for token in getTokens(s):
            try:
                num = int(token)
            except:
                continue
            if prev:
                if num <= prev:
                    return False
            prev = num
        return True
def test_simple_case():
    solution_instance = Solution()
    assert check_numbers('a 1 b 2') == solution_instance.areNumbersAscending('a 1 b 2')
def test_edge_case():
    solution_instance = Solution()
    assert check_numbers('1 2 3 4 5') == solution_instance.areNumbersAscending('1 2 3 4 5')
def test_difficult_case():
    solution_instance = Solution()
    assert check_numbers('a b c d 2 3 4 1') == solution_instance.areNumbersAscending('a b c d 2 3 4 1')

