class Solution:

    def findSpecialInteger(self, arr: List[int]) -> int:
        maxInt = arr[0]
        maxCount = 1
        currInt = arr[0]
        currCount = 1
        for i in range(1, len(arr)):
            if arr[i] == currInt:
                currCount += 1
            elif currCount > maxCount:
                maxCount = currCount
                maxInt = currInt
            else:
                currCount = 1
                currInt = arr[i]
        if currCount > maxCount:
            return currInt
        else:
            return maxInt
