        for num in range(1, k + 1):
            col = [matrix[j][left:right + 1] for j in range(k)].index([num] * (right - left + 1)) if [num] * (right - left + 1) in [matrix[j][left:right + 1] for j in range(k)] else -1
            if col != -1:
