        char = ''
        res = ''
        for i in s:
            ss = ''
            if i.isalpha():
                if i.islower():
                    if i.upper() in s:
                        indx = s.find(i.upper())
                        ss = i + s[indx]
                        char = i.upper()
                        s = s.replace(i, '%')
