def smallest_subarray(nums: List[int], p: int) -> int:
    curr_sum = 0
    min_len = float('inf')
    prefix_sums = [0]
    for num in nums:
        curr_sum += num
        prefix_sums.append(curr_sum)
    target = curr_sum % p
    if target == 0:
        return 0
    elif target == curr_sum:
        return -1
    remainder_indices = {}
    for i, prefix_sum in enumerate(prefix_sums):
        remainder = prefix_sum % p
        if remainder not in remainder_indices:
            remainder_indices[remainder] = i
        if (remainder - target) % p in remainder_indices:
            min_len = min(min_len, i - remainder_indices[(remainder - target) % p])
    return min_len if min_len < len(nums) else -1

