from typing import *
from collections import *
from math import *

def obtain_subsequence(nums):
    nums.sort(reverse=True)
    total_sum = sum(nums)
    subsequence_sum = 0
    subsequence = []
    for num in nums:
        if subsequence_sum > total_sum - subsequence_sum:
            return subsequence[::-1]
        subsequence_sum += num
        subsequence.append(num)
    return subsequence[::-1]
class Solution:

    def minSubsequence(self, nums: List[int]) -> List[int]:
        n = len(nums)
        if n == 1:
            return nums
        else:
            i, j, total = (0, 0, sum(nums))
            half = total / 2
            nums.sort(reverse=True)
            curr_sum = sum(nums[i:j + 1])
            while j < n:
                if curr_sum <= half:
                    j += 1
                    curr_sum += nums[j]
                elif curr_sum > half:
                    while curr_sum > half:
                        if curr_sum - nums[i] <= half:
                            break
                        curr_sum -= nums[i]
                        i += 1
                    break
            return nums[i:j + 1]
def test_simple_case():
    solution_instance = Solution()
    assert obtain_subsequence([4, 3, 10, 9, 8]) == solution_instance.minSubsequence([4, 3, 10, 9, 8])
