def create_folders(names):
    ans = []
    used_names = set()
    for name in names:
        i = 1
        new_name = name
        while new_name in used_names:
            new_name = name + '(' + str(i) + ')'
            i += 1
        used_names.add(new_name)
        ans.append(new_name)
    return ans
class Solution:

    def getFolderNames(self, names: List[str]) -> List[str]:
        n = len(names)
        dictNames = {}
        ans = [''] * n
        for idx, name in enumerate(names):
            if name in dictNames:
                k = dictNames[name]
                namestart = name
                while name in dictNames:
                    name = namestart + f'({k})'
                    k += 1
                dictNames[namestart] = k
                dictNames[name] = 1
            else:
                dictNames[name] = 1
            ans[idx] = name
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert create_folders(['gym', 'dancer', 'gym']) == solution_instance.getFolderNames(['gym', 'dancer', 'gym'])
def test_edge_case():
    solution_instance = Solution()
    assert create_folders(['doc', 'doc', 'image', 'doc(1)', 'doc']) == solution_instance.getFolderNames(['doc', 'doc', 'image', 'doc(1)', 'doc'])
