class Solution:

    def repeatedNTimes(self, nums: List[int]) -> int:
        dic = {}
        for n in nums:
            if n in dic:
                dic[n] += 1
            else:
                dic[n] = 1
        for k in dic:
            if dic[k] == len(nums) // 2:
                return k
