from typing import *
from collections import *
from math import *

def max_product(nums):
    nums.sort()
    return (nums[-1] - 1) * (nums[-2] - 1)
class Solution:

    def maxProduct(self, nums: List[int]) -> int:

        def mx_heapify(heap, sz, i):
            nonlocal nums, heap_sz
            l = 2 * i + 1
            r = 2 * i + 2
            if l <= heap_sz - 1 and nums[l] >= nums[i]:
                largest = l
            else:
                largest = i
            if r <= heap_sz - 1 and nums[r] > nums[largest]:
                largest = r
            if largest != i:
                nums[largest], nums[i] = (nums[i], nums[largest])
                mx_heapify(nums, heap_sz, largest)

        def build_max_heap(heap, heap_sz):
            nonlocal nums
            for i in range(heap_sz // 2 - 1, -1, -1):
                mx_heapify(nums, heap_sz, i)
        heap_sz = len(nums)
        build_max_heap(nums, heap_sz)

        def mx_return(heap, sz):
            nonlocal nums, heap_sz
            mx = nums[0]
            nums[0] = nums[heap_sz - 1]
            heap_sz -= 1
            mx_heapify(nums, heap_sz, 0)
            return mx
        x1 = mx_return(nums, heap_sz)
        x2 = mx_return(nums, heap_sz)
        return (x1 - 1) * (x2 - 1)
def test_simple_case():
    solution_instance = Solution()
    assert max_product([3, 4, 5, 2]) == solution_instance.maxProduct([3, 4, 5, 2])
def test_edge_case():
    solution_instance = Solution()
    assert max_product([1, 8]) == solution_instance.maxProduct([1, 8])
def test_difficult_case():
    solution_instance = Solution()
    assert max_product([0, 2]) == solution_instance.maxProduct([0, 2])

