from typing import *
from collections import *
from math import *

def leastPerfectSquaresSum(n):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        j = 1
        while j * j <= i:
            dp[i] = min(dp[i], dp[i - j * j] + 1)
            j += 1
    return dp[n]
class Solution:

    def numSquares(self, n: int) -> int:
        if int(n ** 0.5) ** 2 == n:
            return 1
        ps = set()
        i = 1
        while i ** 2 <= n:
            ps.add(i ** 2)
            i += 1
        begin = set()
        begin.add(0)
        end = set()
        end.add(n)
        step = 0
        while begin and end:
            step += 1
            temp = set()
            high = max(end)
            for i in begin:
                for j in ps:
                    if i + j in end:
                        return step
                    elif i + j < high:
                        temp.add(i + j)
            begin = temp
            step += 1
            temp = set()
            low = min(begin)
            for i in end:
                for j in ps:
                    if i - j in begin:
                        return step
                    elif i - j > low:
                        temp.add(i - j)
            end = temp
        return -1
def test_normal_case():
    solution_instance = Solution()
    assert leastPerfectSquaresSum(12) == solution_instance.numSquares(12)
def test_single_square_case():
    solution_instance = Solution()
    assert leastPerfectSquaresSum(13) == solution_instance.numSquares(13)
def test_multiple_squares_case():
    solution_instance = Solution()
    assert leastPerfectSquaresSum(16) == solution_instance.numSquares(16)

