def maximum_score(nums1, nums2):
    n = len(nums1)
    max_score = sum(nums1) + sum(nums2)
    for left in range(n):
        for right in range(left, n):
            score1 = sum(nums1[:left]) + sum(nums2[left:right+1]) + sum(nums1[right+1:])
            score2 = sum(nums2[:left]) + sum(nums1[left:right+1]) + sum(nums2[right+1:])
            max_score = max(max_score, score1, score2)
    return max_score

