from typing import *
from collections import *
from math import *

def pathInZigZagTree(label: int) -> List[int]:
    level = 1
    while 2 ** level - 1 < label:
        level += 1
    result = [0] * level
    for i in range(level - 1, -1, -1):
        result[i] = label
        label = 2 ** i - 1 - (label - 2 ** i) // 2
    return result
class Solution:

    def pathInZigZagTree(self, label: int) -> List[int]:
        if label == 1:
            return [1]
        start, end = (1, 1)
        data = [(start, end)]
        row = 1
        to_add = 2
        while True:
            start = end + 1
            end = start + to_add - 1
            to_add *= 2
            row += 1
            if row % 2 == 0:
                data.append((end, start))
            else:
                data.append((start, end))
            if end >= label:
                break
        ans = []
        if row % 2 == 0:
            ans.append(label)
            pos = start + 1 - label
            label = end - 1 + pos
            row -= 1
        else:
            ans.append(label)
            row -= 1
        while True:
            label = label // 2
            start, end = data[row - 1]
            if row % 2 == 0:
                pos = label - start + 1
                actual = end + 1 - pos
                ans.append(actual)
            else:
                ans.append(label)
            row -= 1
            if label == 1:
                break
        return ans[::-1]
def test_simple_case():
    solution_instance = Solution()
    assert pathInZigZagTree(14) == solution_instance.pathInZigZagTree(14)
def test_edge_case():
    solution_instance = Solution()
