from typing import *
from collections import *
from math import *

def numDistinct(s: str, t: str) -> int:
    m, n = (len(s), len(t))
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = 1
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i - 1][j]
            if s[i - 1] == t[j - 1]:
                dp[i][j] += dp[i - 1][j - 1]
    return dp[m][n]
class Solution:

    def numDistinctTopDown(self, s: str, t: str) -> int:

        @functools.cache
        def ways(si, ti):
            if ti == len(t):
                return 1
            elif si == len(s):
                return 0
            match = 0
            if s[si] == t[ti]:
                match = ways(si + 1, ti + 1)
            skip = ways(si + 1, ti)
            return match + skip
        return ways(0, 0)

    def numDistinct2D(self, s: str, t: str) -> int:
        N, M = (len(s), len(t))
        ways = [[0 for __ in range(M + 1)] for _ in range(N + 1)]
        for si in range(N + 1):
            ways[si][M] = 1
        for si in range(N - 1, -1, -1):
            for ti in range(M - 1, -1, -1):
                match = 0
                if s[si] == t[ti]:
                    match = ways[si + 1][ti + 1]
                skip = ways[si + 1][ti]
                ways[si][ti] = match + skip
        return ways[0][0]

    def numDistinct(self, s: str, t: str) -> int:
        N, M = (len(s), len(t))
        ways_today = [0 for _ in range(M + 1)]
        ways_today[M] = 1
        ways_tomm = ways_today[:]
        for si in range(N - 1, -1, -1):
            for ti in range(M - 1, -1, -1):
                match = 0
                if s[si] == t[ti]:
                    match = ways_tomm[ti + 1]
                skip = ways_tomm[ti]
                ways_today[ti] = match + skip
            ways_tomm = ways_today[:]
        return ways_today[0]
