    assert numDistinct('babgbag', 'bag') == solution_instance.numDistinct('babgbag', 'bag')
def test_difficult_case():
    solution_instance = Solution()
    assert numDistinct('AAAAAAAAA', 'AAAAA') == solution_instance.numDistinct('AAAAAAAAA', 'AAAAA')

