from collections import deque

def remove_invalid_parentheses(s):
    def is_valid(s):
        count = 0
        for c in s:
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
                if count < 0:
                    return False
        return count == 0

    visited = set()
    q = deque()
    q.append(s)
    visited.add(s)

    res = []
    found_valid = False

    while q:
        s = q.popleft()
        if is_valid(s):
            res.append(s)
            found_valid = True
        if found_valid:
            continue
        for i in range(len(s)):
            if s[i] not in '()':
                continue
            new_s = s[:i] + s[i+1:]
            if new_s not in visited:
                visited.add(new_s)
                q.append(new_s)

    return res

