def check_avg(nums):
    sum_nums = sum(nums)
    n = len(nums)
    if n <= 1:
        return False
    for i in range(1, n):
        if sum_nums * i % n == 0 and sum_nums * i // n in nums:
            return True
    return False
class Solution:

    def splitArraySameAverage(self, A: List[int]) -> bool:
        mem = {}

        def find(target, k, i):
            if k == 0:
                return target == 0
            if k + i > len(A):
                return False
            if (target, k, i) in mem:
                return mem[target, k, i]
            mem[target - A[i], k - 1, i + 1] = find(target - A[i], k - 1, i + 1) or find(target, k, i + 1)
            return mem[target - A[i], k - 1, i + 1]
        n, s = (len(A), sum(A))
        return any((find(s * j // n, j, 0) for j in range(1, n // 2 + 1) if s * j % n == 0))
def test_with_small_input():
    s = Solution()
    assert check_avg([1, 2, 3, 4, 5]) == s.splitArraySameAverage([1, 2, 3, 4, 5])
def test_with_even_distribution():
    s = Solution()
    assert check_avg([1, 2, 3, 4, 5, 6, 7, 8, 9]) == s.splitArraySameAverage([1, 2, 3, 4, 5, 6, 7, 8, 9])
def test_with_negative_numbers():
    s = Solution()
    assert check_avg([1, -1, 2, -2, 3]) == s.splitArraySameAverage([1, -1, 2, -2, 3])

