class Solution:

    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        subseq = self.LCS(str1, str2, len(str1), len(str2))
        bool1 = [False for i in range(len(str1))]
        bool2 = [False for j in range(len(str2))]
        j = 0
        for i in range(len(str1)):
            if j < len(subseq) and str1[i] == subseq[j]:
                bool1[i] = True
                j = j + 1
        j = 0
        for i in range(len(str2)):
            if j < len(subseq) and str2[i] == subseq[j]:
                bool2[i] = True
                j = j + 1
        i, j, x = (0, 0, 0)
        ans = []
        while i < len(str1) or j < len(str2):
            if i < len(str1) and (not bool1[i]):
                ans.append(str1[i])
                i = i + 1
            if j < len(str2) and (not bool2[j]):
                ans.append(str2[j])
                j = j + 1
            if j < len(str2) and i < len(str1) and bool1[i] and bool2[j]:
                ans.append(subseq[x])
                i = i + 1
                j = j + 1
                x = x + 1
        return ans

    def LCS(self, s1, s2, l1, l2):
        dp = [[0 for i in range(l2 + 1)] for j in range(l1 + 1)]
        for i in range(1, l1 + 1):
            for j in range(1, l2 + 1):
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        ans = []
        i, j = (l1, l2)
        while i > 0 and j > 0:
            if s1[i - 1] == s2[j - 1]:
                ans.append(s1[i - 1])
                i = i - 1
                j = j - 1
            elif dp[i - 1][j] < dp[i][j - 1]:
                j = j - 1
            else:
                i = i - 1
        return ans[::-1]
def test_simple_case():
    solution_instance = Solution()
    assert sorted(shortestSubsequence('abc', 'b')) == sorted(solution_instance.shortestCommonSupersequence('abc', 'b'))
def test_middle_case():
    solution_instance = Solution()
    assert sorted(shortestSubsequence('ab', 'bc')) == sorted(solution_instance.shortestCommonSupersequence('ab', 'bc'))
def test_difficult_case():
    solution_instance = Solution()
    assert sorted(shortestSubsequence('xyz', 'abc')) == sorted(solution_instance.shortestCommonSupersequence('xyz', 'abc'))

