from math import *

def get_sum_of_abs_diffs(nums):
    n = len(nums)
    result = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j:
                result[i] += abs(nums[i] - nums[j])
    return result
class Solution:

    def getSumAbsoluteDifferences(self, nums: List[int]) -> List[int]:
        ans = []
        n = len(nums)
        prefix_sum = []
        prefix_sum.append(nums[0])
        for a in range(1, len(nums)):
            prefix_sum.append(nums[a] + prefix_sum[a - 1])
        for i in range(0, len(nums)):
            subtraction = None
            if i == 0:
                subtraction = 0
            else:
                subtraction = prefix_sum[i - 1]
            first_sum = nums[i] * i - subtraction
            second_sum = prefix_sum[-1] - prefix_sum[i] - (n - i - 1) * nums[i]
            res = first_sum + second_sum
            ans.append(res)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert get_sum_of_abs_diffs([1, 3, 4]) == solution_instance.getSumAbsoluteDifferences([1, 3, 4])
def test_edge_case():
    solution_instance = Solution()
    assert get_sum_of_abs_diffs([2, 9, 8]) == solution_instance.getSumAbsoluteDifferences([2, 9, 8])
