def find_min_fibonacci_numbers(k):
    fib = [1, 1]
    while fib[-1] < k:
        fib.append(fib[-1] + fib[-2])
    min_fib = []
    i = len(fib) - 1
    while k > 0:
        if k >= fib[i]:
            k -= fib[i]
            min_fib.append(fib[i])
        i -= 1
    return len(min_fib)

