from typing import *
from collections import *
from math import *

def find_min_fibonacci_numbers(k):
    fib = [1, 1]
    while fib[-1] < k:
        fib.append(fib[-1] + fib[-2])
    min_fib = []
    i = len(fib) - 1
    while k > 0:
        if k >= fib[i]:
            k -= fib[i]
            min_fib.append(fib[i])
        i -= 1
    return len(min_fib)
class Solution(object):

    def findMinFibonacciNumbers(self, k):
        """
        :type k: int
        :rtype: int
        """
        fib = [0, 1]
        a, b = (1, 1)
        while a + b <= k:
            c = a + b
            fib.append(c)
            a = b
            b = c
        n = len(fib)

        def index(x):
            if x == 0:
                return 0
            if x >= fib[n - 1]:
                return n - 1
            left, right = (0, n - 1)
            while left < right:
                mid = (left + right) // 2
                if fib[mid] > x:
                    right = mid
                else:
                    left = mid + 1
            return left - 1
        res = 0
        while k > 0:
            idx = index(k)
            res += 1
            k -= fib[idx]
        return res
def test_simple_case():
    solution_instance = Solution()
    assert find_min_fibonacci_numbers(7) == solution_instance.findMinFibonacciNumbers(7)
def test_edge_case():
    solution_instance = Solution()
    assert find_min_fibonacci_numbers(10) == solution_instance.findMinFibonacciNumbers(10)
def test_difficult_case():
    solution_instance = Solution()
    assert find_min_fibonacci_numbers(2) == solution_instance.findMinFibonacciNumbers(2)

