def can_transform(start: str, target: str, n: int) -> bool:
    if start.replace('_', '') != target.replace('_', ''):
        return False
    start_cnt, target_cnt = (Counter(start), Counter(target))
    if start_cnt != target_cnt:
        return False
    for i in range(n):
        if target[i] != '_':
            if start[i] == '_' or start[i] == target[i]:
                continue
            else:
                return False
    for i in range(n):
        if start[i] != '_':
            if target[i] == '_' or target[i] == start[i]:
                continue
            else:
                return False
    return True
class Solution:

    def canChange(self, start: str, target: str) -> bool:
        i = self.findNextChar(0, start)
        j = self.findNextChar(0, target)
        if i < 0 and j < 0:
            return True
        if i < 0 or j < 0:
            return False
        while True:
            if start[i] != target[j]:
                return False
            if start[i] == 'R' and i > j:
                return False
            if start[i] == 'L' and i < j:
                return False
            i = self.findNextChar(i + 1, start)
            j = self.findNextChar(j + 1, target)
            if i < 0 and j < 0:
                return True
            if i < 0 or j < 0:
                return False

    def findNextChar(self, startingPosition, String):
        i = startingPosition
        while i < len(String) and String[i] == '_':
            i += 1
        if i == len(String):
            return -1
        return i
def test_simple_case():
    solution_instance = Solution()
    assert can_transform('L__R', 'L_R_', 4) == solution_instance.canChange('L__R', 'L_R_')
def test_edge_case():
