from typing import *
from collections import *
from math import *

def sum_odd_length_subarrays(arr):
    res = 0
    for i in range(len(arr)):
        for j in range(i, len(arr), 2):
            res += sum(arr[i:j + 1])
    return res
class Solution:

    def sumOddLengthSubarrays(self, arr: List[int]) -> int:
        prefix_sum = [None for i in range(len(arr))]
        prefix_sum[0] = arr[0]
        for i in range(1, len(prefix_sum), 1):
            prefix_sum[i] = prefix_sum[i - 1] + arr[i]
        ans = sum(arr)

        def helper(k):
            nonlocal arr, prefix_sum
            summation = 0
            for i in range(0, len(arr) - k + 1):
                prev, end = (i - 1, i + k - 1)
                subtract_away = prefix_sum[i - 1] if i - 1 >= 0 else 0
                up_to = prefix_sum[end]
                summation += up_to - subtract_away
            return summation
        cur_length = 3
        while True:
            res = helper(cur_length)
            if res == 0:
                break
            else:
                ans += res
                cur_length += 2
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert sum_odd_length_subarrays([1, 4, 2, 5, 3]) == solution_instance.sumOddLengthSubarrays([1, 4, 2, 5, 3])
def test_edge_case():
    solution_instance = Solution()
    assert sum_odd_length_subarrays([1, 2]) == solution_instance.sumOddLengthSubarrays([1, 2])
def test_difficult_case():
    solution_instance = Solution()
    assert sum_odd_length_subarrays([10, 11, 12]) == solution_instance.sumOddLengthSubarrays([10, 11, 12])

