def print_number_diamond(n):
    # Print the top half of the diamond
    for i in range(1, n+1):
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        # Print the numbers in increasing order
        for j in range(1, i+1):
            print(j, end='')
        # Print the numbers in decreasing order
        for j in range(i-1, 0, -1):
            print(j, end='')
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        print()

    # Print the bottom half of the diamond
    for i in range(n-1, 0, -1):
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        # Print the numbers in increasing order
        for j in range(1, i+1):
            print(j, end='')
        # Print the numbers in decreasing order
        for j in range(i-1, 0, -1):
            print(j, end='')
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        print()

# Example usage
print_number_diamond(5)

