from typing import *
from collections import *
from math import *

def minHeightShelves(books: List[List[int]], shelfWidth: int) -> int:
    n = len(books)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        cur_width, j, max_height = (0, i, 0)
        while j > 0:
            cur_width += books[j - 1][0]
            if cur_width > shelfWidth:
                break
            max_height = max(max_height, books[j - 1][1])
            dp[i] = min(dp[i], dp[j - 1] + max_height)
            j -= 1
    return dp[n]
class Solution:

    def minHeightShelves(self, books: List[List[int]], shelf_width: int) -> int:
        if not books:
            return 0
        best = dict()
        best[shelf_width, 0] = 0
        for width, height in books:
            new_best = dict()
            for (width_left, level_height), total_height in best.items():
                key = (shelf_width - width, height)
                val = total_height + height
                if key in new_best:
                    new_best[key] = min(new_best[key], val)
                else:
                    new_best[key] = val
                if width <= width_left:
                    key = (width_left - width, max(height, level_height))
                    val = total_height + max(height, level_height) - level_height
                    if key in new_best:
                        new_best[key] = min(new_best[key], val)
                    else:
                        new_best[key] = val
            best = new_best
        return min(best.values())
def test_simple_books():
    s = Solution()
    books = [[1, 3], [2, 4], [3, 2]]
    shelf_width = 6
    assert minHeightShelves(books, shelf_width) == s.minHeightShelves(books, shelf_width)
def test_more_books():
    s = Solution()
    books = [[1, 3], [2, 4], [3, 2], [2, 1]]
    shelf_width = 6
    assert minHeightShelves(books, shelf_width) == s.minHeightShelves(books, shelf_width)
def test_large_books():
    s = Solution()
    books = [[1, 3], [2, 3], [2, 3], [1, 4]]
    shelf_width = 8
    assert minHeightShelves(books, shelf_width) == s.minHeightShelves(books, shelf_width)

