import math

def introsort(arr):
    def _introsort(arr, start, end, maxdepth):
        if end - start <= 1:
            return
        if maxdepth == 0:
            heapsort(arr, start, end)
        else:
            p = partition(arr, start, end)
            _introsort(arr, start, p, maxdepth - 1)
            _introsort(arr, p + 1, end, maxdepth - 1)

    def partition(arr, start, end):
        pivot = arr[start]
        i, j = start + 1, end - 1
        while True:
            while i < end and arr[i] < pivot:
                i += 1
            while j > start and arr[j] > pivot:
                j -= 1
            if i >= j:
                break
            arr[i], arr[j] = arr[j], arr[i]
        arr[start], arr[j] = arr[j], arr[start]
        return j

    def heapsort(arr, start, end):
        heapify(arr, start, end)
        for i in range(end - 1, start, -1):
            arr[start], arr[i] = arr[i], arr[start]
            heapify(arr, start, i)

    def heapify(arr, start, end):
        def sift_down(arr, start, end, root):
            while True:
                left_child = root * 2 + 1
                if left_child >= end:
                    break
                right_child = left_child + 1
                if right_child < end and arr[right_child] > arr[left_child]:
                    max_child = right_child
                else:
                    max_child = left_child
                if arr[max_child] > arr[root]:
                    arr[max_child], arr[root] = arr[root], arr[max_child]
                    root = max_child
                else:
                    break
        n = end - start
        for i in range(n // 2 - 1, -1, -1):
            sift_down(arr, start, end, i)

    maxdepth = math.ceil(math.log(len(arr)))
    _introsort(arr, 0, len(arr), maxdepth)
    return arr

