    def partition(arr, start, end):
        pivot = arr[start]
        i, j = (start + 1, end - 1)
        while True:
            while i < end and arr[i] < pivot:
                i += 1
            while j > start and arr[j] > pivot:
                j -= 1
            if i >= j:
                break
            arr[i], arr[j] = (arr[j], arr[i])
        arr[start], arr[j] = (arr[j], arr[start])
        return j

    def heapsort(arr, start, end):
        heapify(arr, start, end)
        for i in range(end - 1, start, -1):
            arr[start], arr[i] = (arr[i], arr[start])
            heapify(arr, start, i)

    def heapify(arr, start, end):

        def sift_down(arr, start, end, root):
            while True:
                left_child = root * 2 + 1
                if left_child >= end:
                    break
                right_child = left_child + 1
                if right_child < end and arr[right_child] > arr[left_child]:
                    max_child = right_child
                else:
                    max_child = left_child
                if arr[max_child] > arr[root]:
                    arr[max_child], arr[root] = (arr[root], arr[max_child])
                    root = max_child
                else:
                    break
        n = end - start
        for i in range(n // 2 - 1, -1, -1):
            sift_down(arr, start, end, i)
    maxdepth = math.ceil(math.log(len(arr)))
    _introsort(arr, 0, len(arr), maxdepth)
    return arr
def introsort(alist):
    maxdepth = (len(alist).bit_length() - 1) * 2
    introsort_helper(alist, 0, len(alist), maxdepth)
def introsort_helper(alist, start, end, maxdepth):
    if end - start <= 1:
        return
    elif maxdepth == 0:
        heapsort(alist, start, end)
    else:
        p = partition(alist, start, end)
        introsort_helper(alist, start, p + 1, maxdepth - 1)
        introsort_helper(alist, p + 1, end, maxdepth - 1)
def partition(alist, start, end):
    pivot = alist[start]
    i = start - 1
    j = end
    while True:
        i = i + 1
        while alist[i] < pivot:
            i = i + 1
        j = j - 1
        while alist[j] > pivot:
            j = j - 1
        if i >= j:
            return j
        swap(alist, i, j)
def swap(alist, i, j):
    alist[i], alist[j] = (alist[j], alist[i])
def heapsort(alist, start, end):
    build_max_heap(alist, start, end)
    for i in range(end - 1, start, -1):
        swap(alist, start, i)
        max_heapify(alist, index=0, start=start, end=i)
def build_max_heap(alist, start, end):

    def parent(i):
        return (i - 1) // 2
    length = end - start
    index = parent(length - 1)
    while index >= 0:
        max_heapify(alist, index, start, end)
        index = index - 1
def max_heapify(alist, index, start, end):

    def left(i):
        return 2 * i + 1

    def right(i):
        return 2 * i + 2
    size = end - start
    l = left(index)
    r = right(index)
    if l < size and alist[start + l] > alist[start + index]:
        largest = l
    else:
        largest = index
    if r < size and alist[start + r] > alist[start + largest]:
        largest = r
    if largest != index:
        swap(alist, start + largest, start + index)
        max_heapify(alist, largest, start, end)
def test_simple_case():
    arr1 = [3, 6, 2, 7, 1]
    introsort_copy1 = arr1.copy()
    introsort(introsort_copy1)
    introsort_copy2 = arr1.copy()
    introsort_helper(introsort_copy2, 0, len(introsort_copy2), (len(introsort_copy2).bit_length() - 1) * 2)
    assert introsort_copy1 == introsort_copy2
def test_edge_case():
    arr1 = [2, 1]
    introsort_copy1 = arr1.copy()
    introsort(introsort_copy1)
    introsort_copy2 = arr1.copy()
    introsort_helper(introsort_copy2, 0, len(introsort_copy2), (len(introsort_copy2).bit_length() - 1) * 2)
    assert introsort_copy1 == introsort_copy2
def test_difficult_case():
    arr1 = [9, 8, 7, 6, 5, 4, 3, 2, 1]
    introsort_copy1 = arr1.copy()
    introsort(introsort_copy1)
    introsort_copy2 = arr1.copy()
    introsort_helper(introsort_copy2, 0, len(introsort_copy2), (len(introsort_copy2).bit_length() - 1) * 2)
    assert introsort_copy1 == introsort_copy2

