def is_valid_matrix(matrix):
    n = len(matrix)
    for i in range(n):
        row_values = set(matrix[i])
        column_values = set((matrix[j][i] for j in range(n)))
        if row_values != set(range(1, n + 1)) or column_values != set(range(1, n + 1)):
            return False
    return True
class Solution:

    def checkValid(self, matrix: List[List[int]]) -> bool:
        n = len(matrix)
        for i in range(n):
            for j in range(n):
                val = abs(matrix[i][j]) % n
                if matrix[i][val] < 0:
                    return False
                matrix[i][val] *= -1
                if abs(matrix[val][j]) > n:
                    return False
                if matrix[val][j] < 0:
                    matrix[val][j] -= n
                else:
                    matrix[val][j] += n
        return True
def test_simple_case():
    s = Solution()
    assert is_valid_matrix([[1, 2, 3], [3, 1, 2], [2, 3, 1]]) == s.checkValid([[1, 2, 3], [3, 1, 2], [2, 3, 1]])
def test_edge_case():
    s = Solution()
    assert is_valid_matrix([[1, 1, 1], [1, 2, 3], [1, 2, 3]]) == s.checkValid([[1, 1, 1], [1, 2, 3], [1, 2, 3]])
def test_difficult_case():
    s = Solution()
    assert is_valid_matrix([[1, 2, 3], [3, 2, 1], [2, 1, 3]]) == s.checkValid([[1, 2, 3], [3, 2, 1], [2, 1, 3]])

