class Solution:

    def getMinDistance(self, nums: List[int], target: int, start: int) -> int:
        i, j = (start, start + 1)
        while i >= 0 and j < len(nums):
            if nums[i] == target:
                return start - i
            if nums[j] == target:
                return j - start
            i -= 1
            j += 1
        while i >= 0:
            if nums[i] == target:
                return start - i
            i -= 1
        while j < len(nums):
            if nums[j] == target:
                return j - start
            j += 1
