from typing import *
from collections import *
from math import *

def steps_to_spell(ring: str, key: str) -> int:
    index = 0
    steps = 0
    while index < len(key):
        char = key[index]
        char_index = ring.index(char)
        steps += min(abs(char_index - 0), abs(char_index - len(ring)))
        ring = ring[char_index:] + ring[:char_index]
        steps += 1
        index += 1
    return steps
class Solution:

    def findRotateSteps(self, ring: str, key: str) -> int:
        char_pos = defaultdict(set)
        for i, c in enumerate(ring):
            char_pos[c].add(i)

        def minStep(fromm, to):
            if fromm == to:
                return 0
            minSteps = abs(fromm - to)
            minSteps = min(minSteps, abs(len(ring) - minSteps))
            return minSteps
        n = len(key)
        dp = [0] * len(ring)
        for p in char_pos[key[0]]:
            dp[p] = minStep(0, p)
        prev_char = key[0]
        for c in key[1:]:
            if prev_char == c:
                continue
            for next_pos in char_pos[c]:
                dp[next_pos] = min((dp[prev_pos] + minStep(prev_pos, next_pos) for prev_pos in char_pos[prev_char]))
            prev_char = c
        return min((dp[p] for p in char_pos[prev_char])) + len(key)
def test_simple_case():
    solution_instance = Solution()
    assert steps_to_spell('god', 'go') == solution_instance.findRotateSteps('god', 'go')
def test_edge_case():
    solution_instance = Solution()
    assert steps_to_spell('cbaaa', 'aaa') == solution_instance.findRotateSteps('cbaaa', 'aaa')
def test_difficult_case():
    solution_instance = Solution()
    assert steps_to_spell('godding', 'ding') == solution_instance.findRotateSteps('godding', 'ding')

