def second_largest_digit(s):
    digits = []
    for char in s:
        if char.isdigit():
            digits.append(int(char))
    if len(digits) < 2:
        return -1
    digits = list(set(digits))
    if len(digits) < 2:
        return -1
    digits.sort()
    return digits[-2]

