def second_largest_digit(s):
    digits = []
    for char in s:
        if char.isdigit():
            digits.append(int(char))
    if len(digits) < 2:
        return -1
    digits = list(set(digits))
    if len(digits) < 2:
        return -1
    digits.sort()
    return digits[-2]
class Solution:

    def secondHighest(self, s: str) -> int:
        return find_second_max(list(set(filter_integers(s))))
def find_second_max(x):
    max_1 = -1
    max_2 = -1
    for i in range(len(x)):
        if max_1 <= x[i]:
            max_2 = max_1
            max_1 = x[i]
        elif max_2 <= x[i] and x[i] <= max_1:
            max_2 = x[i]
    return max_2
def filter_integers(s: str):
    result = []
    for i in s:
        if i.isdigit():
            result.append(int(i))
    return result
def test_simple_case():
    solution_instance = Solution()
    assert second_largest_digit('a1b2c3') == solution_instance.secondHighest('a1b2c3')
def test_edge_case():
    solution_instance = Solution()
    assert second_largest_digit('a1b1') == solution_instance.secondHighest('a1b1')
def test_difficult_case():
    solution_instance = Solution()
    assert second_largest_digit('azsec9345') == solution_instance.secondHighest('azsec9345')

