from typing import *
from collections import *
from math import *

def minFallingPathSum(matrix: List[List[int]]) -> int:
    n = len(matrix)
    if n == 1:
        return matrix[0][0]
    for i in range(1, n):
        for j in range(n):
            if j == 0:
                matrix[i][j] += min(matrix[i - 1][j], matrix[i - 1][j + 1])
            elif j == n - 1:
                matrix[i][j] += min(matrix[i - 1][j], matrix[i - 1][j - 1])
            else:
                matrix[i][j] += min(matrix[i - 1][j], matrix[i - 1][j - 1], matrix[i - 1][j + 1])
    return min(matrix[n - 1])
class Solution:

    def minFallingPathSum1(self, A: List[List[int]]) -> int:
        rows, cols = (len(A), len(A[0]))

        def rcrs(r, c):
            if (r, c) in self.cache:
                return self.cache[r, c]
            if r == rows - 1:
                return A[r][c]
            tmp = float('inf')
            for dc in [-1, 0, 1]:
                if 0 <= c + dc < cols:
                    tmp = min(tmp, rcrs(r + 1, c + dc))
            min_sum = A[r][c] + tmp
            self.cache[r, c] = min_sum
            return min_sum
        self.cache = {}
        res = float('inf')
        for c in range(cols):
            res = min(res, rcrs(0, c))
        return res

    def minFallingPathSum2(self, A: List[List[int]]) -> int:
        rows, cols = (len(A), len(A[0]))
        dp = [[float('inf') for _ in range(rows)] for __ in range(cols)]
        dp[rows - 1] = A[rows - 1]
        for r in range(rows - 2, -1, -1):
            for c in range(cols - 1, -1, -1):
                tmp = float('inf')
                for dc in [-1, 0, 1]:
                    if 0 <= c + dc < cols:
                        tmp = min(tmp, dp[r + 1][c + dc])
                min_sum = A[r][c] + tmp
                dp[r][c] = min_sum
        return min(dp[0])

    def minFallingPathSum(self, A: List[List[int]]) -> int:
        rows, cols = (len(A), len(A[0]))
        for r in range(rows - 2, -1, -1):
            for c in range(cols - 1, -1, -1):
                tmp = float('inf')
                for dc in [-1, 0, 1]:
                    if 0 <= c + dc < cols:
                        tmp = min(tmp, A[r + 1][c + dc])
                A[r][c] += tmp
        return min(A[0])
def test_simple_case():
    solution_instance = Solution()
    matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert minFallingPathSum(matrix) == solution_instance.minFallingPathSum(matrix)
def test_edge_case():
    solution_instance = Solution()
    matrix = [[10]]
    assert minFallingPathSum(matrix) == solution_instance.minFallingPathSum(matrix)
def test_difficult_case():
    solution_instance = Solution()
    matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert minFallingPathSum(matrix) == solution_instance.minFallingPathSum(matrix)

