from typing import *
from collections import *
from math import *

def goodIndices(nums: List[int], k: int) -> List[int]:
    res = []
    for i in range(k, len(nums) - k):
        decreasing = all((nums[j] >= nums[j + 1] for j in range(i - k, i)))
        increasing = all((nums[j] <= nums[j + 1] for j in range(i, i + k)))
        if decreasing and increasing:
            res.append(i)
    return res
class Solution:

    def goodIndices(self, nums: List[int], k: int) -> List[int]:
        forward = [False] * len(nums)
        stack = []
        for i in range(len(nums)):
            if len(stack) >= k:
                forward[i] = True
            if not stack:
                stack.append(nums[i])
            elif nums[i] <= stack[-1]:
                stack.append(nums[i])
            else:
                stack = [nums[i]]
        res = []
        stack = []
        for i in reversed(range(len(nums))):
            if len(stack) >= k and forward[i]:
                res.append(i)
            if not stack:
                stack.append(nums[i])
            elif nums[i] <= stack[-1]:
                stack.append(nums[i])
            else:
                stack = [nums[i]]
        return res[::-1]
def test_simple_case():
    nums, k = ([2, 1, 1, 3, 4, 3], 2)
    s = Solution()
    assert goodIndices(nums, k) == s.goodIndices(nums, k)
def test_edge_case():
    nums, k = ([1, 1, 1], 1)
    s = Solution()
    assert goodIndices(nums, k) == s.goodIndices(nums, k)
def test_difficult_case():
    nums, k = ([2, 1, 5, 0, 4, 6], 3)
    s = Solution()
    assert goodIndices(nums, k) == s.goodIndices(nums, k)

