def count_valid_buildings(s):
    count = 0
    for i in range(len(s) - 2):
        if s[i] != s[i + 1] and s[i + 1] != s[i + 2] and (s[i] != s[i + 2]):
            count += 1
    return count
class Solution:

    def numberOfWays(self, s: str) -> int:
        prefix = []
        one = zero = 0
        for c in s:
            prefix.append([zero, one])
            if c == '1':
                one += 1
            else:
                zero += 1
        suffix = []
        one = zero = 0
        for c in s[::-1]:
            suffix.append([zero, one])
            if c == '1':
                one += 1
            else:
                zero += 1
        suffix = suffix[::-1]
        ans = 0
        for i, c in enumerate(s):
            if c == '1':
                ans += prefix[i][0] * suffix[i][0]
            else:
                ans += prefix[i][1] * suffix[i][1]
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert count_valid_buildings('001') == solution_instance.numberOfWays('001')
def test_edge_case():
    solution_instance = Solution()
    assert count_valid_buildings('001101') == solution_instance.numberOfWays('001101')
def test_difficult_case():
    solution_instance = Solution()
    assert count_valid_buildings('10101') == solution_instance.numberOfWays('10101')

