def calculate_dimensions(area):
    target_area = area
    min_difference = float('inf')
    min_dimensions = [0, 0]
    for width in range(1, int(area ** 0.5) + 1):
        if area % width == 0:
            length = area // width
            if length >= width and length - width < min_difference:
                min_difference = length - width
                min_dimensions = [length, width]
    return min_dimensions
class Solution:

    def constructRectangle(self, area: int) -> list[int]:
        sqrt = area ** 0.5
        if sqrt % 1 == 0:
            return [int(sqrt)] * 2
        factors = [[area // i, i] for i in range(2, int(sqrt) + 1) if area % i == 0]
        return [area, 1] if not factors else factors[-1]
def test_simple_case():
    solution_instance = Solution()
    assert calculate_dimensions(4) == solution_instance.constructRectangle(4)
def test_edge_case():
    solution_instance = Solution()
    assert calculate_dimensions(37) == solution_instance.constructRectangle(37)
def test_difficult_case():
    solution_instance = Solution()
    assert calculate_dimensions(122122) == solution_instance.constructRectangle(122122)

