class Solution:

    def rearrangeCharacters(self, s: str, target: str) -> int:
        answer = len(s)
        dicS = {}
        dicT = {}
        for i in s:
            if i not in dicS:
                dicS[i] = 1
            else:
                dicS[i] = dicS[i] + 1
        for i in target:
            if i not in dicT:
                dicT[i] = 1
            else:
                dicT[i] = dicT[i] + 1
        for i in dicT.keys():
            if i not in dicS:
                return 0
            x = dicS[i] // dicT[i]
            answer = min(answer, x)
        return answer
class Solution:

    def rearrangeCharacters(self, s: str, target: str) -> int:
        answer = len(s)
        dicS = Counter(s)
        dicT = Counter(target)
        for i in dicT.keys():
            if i not in dicS:
                return 0
            x = dicS[i] // dicT[i]
            answer = min(answer, x)
        return answer
def test_simple_case():
    solution_instance = Solution()
    assert max_num_of_substrings('ilowz') == solution_instance.rearrangeCharacters('ilowz', 'lw')
