def count_substrings(s):
    count = {'1': 0, '0': 0}
    result = 0
    for i in range(len(s)):
        count[s[i]] += 1
        if count['1'] == count['0']:
            result += 1
    return result * 2  # multiply by 2 to count both '0's 1's and '1's 0's substrings

