def reorder_and_square(n):
    digits = []
    while n > 0:
        digits.append(n % 10)
        n //= 10
    digits.sort()
    num_with_zero = ''
    for d in digits:
        num_with_zero += str(d)
    num_without_zero = int(num_with_zero.lstrip('0'))
    result = num_without_zero ** 2
    return result
class Solution:

    def reorderedPowerOf2(self, n: int) -> bool:
        two_mul_digit_counts = [{1: 1}, {2: 1}, {4: 1}, {8: 1}, {6: 1, 1: 1}, {2: 1, 3: 1}, {4: 1, 6: 1}, {8: 1, 2: 1, 1: 1}, {6: 1, 5: 1, 2: 1}, {2: 1, 1: 1, 5: 1}, {4: 1, 2: 1, 0: 1, 1: 1}, {8: 1, 4: 1, 0: 1, 2: 1}, {6: 1, 9: 1, 0: 1, 4: 1}, {2: 1, 9: 1, 1: 1, 8: 1}, {4: 1, 8: 1, 3: 1, 6: 1, 1: 1}, {8: 1, 6: 1, 7: 1, 2: 1, 3: 1}, {6: 2, 3: 1, 5: 2}, {2: 1, 7: 1, 0: 1, 1: 2, 3: 1}, {4: 2, 1: 1, 2: 2, 6: 1}, {8: 2, 2: 2, 4: 1, 5: 1}, {6: 1, 7: 1, 5: 1, 8: 1, 4: 1, 0: 1, 1: 1}, {2: 2, 5: 1, 1: 1, 7: 1, 9: 1, 0: 1}, {4: 3, 0: 1, 3: 1, 9: 1, 1: 1}, {8: 4, 0: 1, 6: 1, 3: 1}, {6: 2, 1: 2, 2: 1, 7: 3}, {2: 1, 3: 3, 4: 2, 5: 2}, {4: 1, 6: 2, 8: 2, 0: 1, 1: 1, 7: 1}, {8: 1, 2: 2, 7: 2, 1: 2, 4: 1, 3: 1}, {6: 2, 5: 2, 4: 2, 3: 1, 8: 1, 2: 1}, {2: 1, 1: 1, 9: 1, 0: 1, 7: 1, 8: 1, 6: 1, 3: 1, 5: 1}]
        digit_count = {}
        while n > 0:
            if n % 10 not in digit_count:
                digit_count[n % 10] = 0
            digit_count[n % 10] += 1
            n = n // 10
        for i in two_mul_digit_counts:
            if digit_count == i:
                return True
        return False
