def isPerfectSquare(num):
    return num == int(num ** 0.5) ** 2
class Solution:

    def isPerfectSquare(self, num: int) -> bool:
        L, H = (1, num)
        while L <= H:
            mid = (L + H) // 2
            if mid * mid == num:
                return True
            elif mid * mid > num:
                H = mid - 1
                continue
            else:
                L = mid + 1
                continue
        return False
def test_simple_case():
    solution_instance = Solution()
    assert isPerfectSquare(16) == solution_instance.isPerfectSquare(16)
def test_edge_case():
    solution_instance = Solution()
    assert isPerfectSquare(1) == solution_instance.isPerfectSquare(1)
def test_difficult_case():
    solution_instance = Solution()
    assert isPerfectSquare(14) == solution_instance.isPerfectSquare(14)

