def chunk(lst, size):
    return [lst[i:i + size] for i in range(0, len(lst), size)]
def chunk_list(lst, size):
    return list(map(lambda x: lst[x * size:x * size + size], list(range(ceil(len(lst) / size)))))
def test_simple_case():
    assert chunk([1, 2, 3, 4, 5], 2) == chunk_list([1, 2, 3, 4, 5], 2)
def test_edge_case():
    assert chunk([1, 2, 3, 4, 5, 6, 7], 3) == chunk_list([1, 2, 3, 4, 5, 6, 7], 3)
def test_difficult_case():
    assert chunk([1, 2, 3, 4, 5, 6, 7, 8], 5) == chunk_list([1, 2, 3, 4, 5, 6, 7, 8], 5)

