class Solution:

    def modpow(self, a: int, b: int, m: int) -> int:
        """ Compute a^b mod m with fast exponentiation"""
        if b == 0:
            return 1
        r = self.modpow(a, b // 2, m)
        if b % 2 == 0:
            return r * r % m
        else:
            return a * r * r % m

    def superPow(self, a: int, b: List[int]) -> int:
        m = 1337
        r = 1
        base = a
        for e in b[::-1]:
            r = r * self.modpow(base, e, m) % m
            base = self.modpow(base, 10, m)
            if base == 1:
                return r
        return r
def test_simple_case():
    fc_instance = First_class()
    sol_instance = Solution()
    assert fc_instance.superPow(2, [1, 0]) == sol_instance.superPow(2, [1, 0])
