class Solution:

    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        pre = 0
        ans = None
        longest_job_duration = -1
        for ID, end_time in logs:
            job_time = end_time - pre
            if job_time > longest_job_duration:
                longest_job_duration = job_time
                ans = ID
            if job_time == longest_job_duration:
                ans = min(ans, ID)
            pre = end_time
        return ans
def test_simple_case():
    solution_instance = Solution()
    logs = [[0, 3], [2, 5], [0, 9]]
    assert longest_working_employee(logs) == solution_instance.hardestWorker(3, logs)
def test_edge_case():
    solution_instance = Solution()
    logs = [[0, 5], [5, 10], [10, 15]]
    assert longest_working_employee(logs) == solution_instance.hardestWorker(3, logs)
def test_difficult_case():
    solution_instance = Solution()
    logs = [[0, 3], [1, 9], [2, 15]]
    assert longest_working_employee(logs) == solution_instance.hardestWorker(3, logs)

