    return -1
class Solution:

    def repeatedStringMatch(self, a: str, b: str) -> int:
        if a == b:
            return 1
        char_a = set()
        for s in a:
            if s not in char_a:
                char_a.add(s)
        for t in b:
            if t not in char_a:
                return -1
        org_a = a
        repeat = 1
        n = len(b)
        pi = [0 for _ in range(n)]
        j = 0
        for i in range(1, n):
            while j and b[i] != b[j]:
                j = pi[j - 1]
            j += b[i] == b[j]
            pi[i] = j
        while len(a) < len(b):
            a += org_a
            repeat += 1

        def strStr(s, t, pi):
            i = 0
            j = 0
            while i < len(s):
                if s[i] == t[j]:
                    i += 1
                    j += 1
                    if j == len(t):
                        return True
                elif j > 0:
                    j = pi[j - 1]
                else:
                    i += 1
            return False
        found = strStr(a, b, pi)
        while not found:
            if repeat == 1 or len(a) <= 2 * len(b):
                a += org_a
                repeat += 1
                found = strStr(a, b, pi)
                continue
            else:
                break
        return repeat if found else -1
def test_simple_case():
    solution_instance = Solution()
    assert min_repeats('abcd') == solution_instance.repeatedStringMatch('abcd', 'abcd')
def test_complex_case():
    solution_instance = Solution()
    assert min_repeats('abab') == solution_instance.repeatedStringMatch('abab', 'ababab')
def test_impossible_case():
    solution_instance = Solution()
    assert min_repeats('abc') == solution_instance.repeatedStringMatch('abc', 'abcd')

