def isSolvable(words, result):
    unique_chars = set(''.join(words) + result)
    if len(unique_chars) > 10:
        return False

    char_map = {}
    used_digits = set()

    def backtrack(i, carry):
        if i == len(words):
            return carry == 0

        word = words[i]
        for j in range(len(word)):
            char = word[j]
            if j == 0 and len(word) > 1:
                if char in char_map or carry == 0:
                    continue
                char_map[char] = carry % 10
                used_digits.add(carry % 10)
                if backtrack(i+1, carry // 10):
                    return True
                del char_map[char]
                used_digits.remove(carry % 10)
            else:
                for digit in range(10):
                    if digit in used_digits or (digit == 0 and j == len(word) - 1):
                        continue
                    char_map[char] = digit
                    used_digits.add(digit)
                    if backtrack(i+1, carry):
                        return True
                    del char_map[char]
                    used_digits.remove(digit)
        return False

    return backtrack(0, 0)

