        return False
    return backtrack(0, 0)
class Solution:

    def isSolvable(self, words: List[str], result: str) -> bool:
        words = [i[::-1] for i in words]
        result = result[::-1]
        allWords = words + [result]
        nonZero = set()
        for word in allWords:
            if len(word) > 1:
                nonZero.add(word[-1])
        selected = set()
        charToInt = dict()
        mxLen = max([len(i) for i in allWords])

        def res(i=0, c=0, sm=0):
            if c == mxLen:
                return 1 if sm == 0 else 0
            elif i == len(words):
                num = sm % 10
                carry = sm // 10
                if c >= len(result):
                    if num == 0:
                        return res(0, c + 1, carry)
                    else:
                        return 0
                if result[c] in charToInt:
                    if charToInt[result[c]] != num:
                        return 0
                    else:
                        return res(0, c + 1, carry)
                elif num in selected:
                    return 0
                elif num == 0 and result[c] not in nonZero or num > 0:
                    selected.add(num)
                    charToInt[result[c]] = num
                    ret = res(0, c + 1, carry)
                    del charToInt[result[c]]
                    selected.remove(num)
                    return ret
                else:
                    return 0
            else:
                word = words[i]
                if c >= len(word):
                    return res(i + 1, c, sm)
                elif word[c] in charToInt:
                    return res(i + 1, c, sm + charToInt[word[c]])
                else:
                    ret = 0
                    for j in range(10):
                        if j == 0 and word[c] not in nonZero or j > 0:
                            if j not in selected:
                                selected.add(j)
                                charToInt[word[c]] = j
                                ret += res(i + 1, c, sm + j)
                                del charToInt[word[c]]
                                selected.remove(j)
                    return ret
        return res() > 0
def test_simple_case():
    solution_instance = Solution()
    assert isSolvable(['SEND', 'MORE'], 'MONEY') == solution_instance.isSolvable(['SEND', 'MORE'], 'MONEY')
def test_edge_case():
    solution_instance = Solution()
    assert isSolvable(['SILENT', 'LISTEN'], 'SOUND') == solution_instance.isSolvable(['SILENT', 'LISTEN'], 'SOUND')
def test_difficult_case():
    solution_instance = Solution()
    assert isSolvable(['ELEVEN', 'SEVEN', 'SIX'], 'TWENTYSIX') == solution_instance.isSolvable(['ELEVEN', 'SEVEN', 'SIX'], 'TWENTYSIX')

