def is_possible_split(nums):
    start = None
    seq_len = 0
    for i in range(len(nums)):
        if start is None:
            start = i
            seq_len = 1
        elif nums[i] == nums[i-1]+1:
            seq_len += 1
        else:
            if seq_len >= 3:
                start = i - 1
                seq_len = 2
            else:
                start = i
                seq_len = 1
    return seq_len >= 3

