class Solution:

    def isPossible(self, nums: List[int]) -> bool:
        freqMap = Counter(nums)
        nextMap = Counter()
        for i in nums:
            if not freqMap[i]:
                continue
            if nextMap[i]:
                nextMap[i] -= 1
                nextMap[i + 1] += 1
            elif freqMap[i + 1] and freqMap[i + 2]:
                freqMap[i + 1] -= 1
                freqMap[i + 2] -= 1
                nextMap[i + 3] += 1
            else:
                return False
            freqMap[i] -= 1
        return True
def test_simple_case():
    solution_instance = Solution()
    assert is_possible_split([1, 2, 3, 3, 4, 5]) == solution_instance.isPossible([1, 2, 3, 3, 4, 5])
def test_edge_case():
    solution_instance = Solution()
    assert is_possible_split([1, 2, 3, 4, 5]) == solution_instance.isPossible([1, 2, 3, 4, 5])
def test_difficult_case():
    solution_instance = Solution()
    assert is_possible_split([1, 2, 2, 3, 4, 4, 5]) == solution_instance.isPossible([1, 2, 2, 3, 4, 4, 5])

