class Solution:

    def slowestKey(self, releaseTimes: List[int], keysPressed: str) -> str:
        prev_key, prev_ts = ('', 0)
        slowest_key, max_duration = ('', 0)
        for key, release_ts in zip(keysPressed, releaseTimes):
            cur_duration = release_ts - prev_ts
            if prev_ts == 0:
                prev_ts = release_ts
                max_duration = release_ts
            if cur_duration > max_duration:
                slowest_key, max_duration = (key, cur_duration)
            elif cur_duration == max_duration:
                if key > slowest_key:
                    slowest_key = key
            prev_key, prev_ts = (key, release_ts)
        return slowest_key
