def makeGood(s):
    if len(s) < 2:
        return s
    for i in range(len(s) - 1):
        if s[i].islower() and s[i + 1].isupper() and (s[i] == s[i + 1].lower()) or (s[i].isupper() and s[i + 1].islower() and (s[i] == s[i + 1].upper())):
