class Solution:

    def makeGood(self, s: str) -> str:
        stack = []
        for let in s:
            if stack:
                if stack[-1].lower() == let.lower():
                    if stack[-1].isupper() and let.islower() or (stack[-1].islower() and let.isupper()):
                        stack.pop()
                        continue
                    else:
                        stack.append(let)
                        continue
            stack.append(let)
        if not stack:
            return ''
        good_string = ''
        for val in stack:
            good_string += val
        return good_string
