class Solution:

    def minimumDeletions(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 1
        maxIdx = nums.index(max(nums))
        minIdx = nums.index(min(nums))
        if maxIdx > minIdx:
            a = maxIdx + 1
        else:
            a = minIdx + 1
        revMaxIdx = n - 1 - maxIdx
        revMinIdx = n - 1 - minIdx
        if revMaxIdx > revMinIdx:
            b = revMaxIdx + 1
        else:
            b = revMinIdx + 1
        maxIdxFront = maxIdx
        minIdxBack = revMinIdx
        maxIdxBack = revMaxIdx
        minIdxFront = minIdx
        c = maxIdxFront + minIdxBack + 2
        d = maxIdxBack + minIdxFront + 2
        e = min(c, d)
        return min(a, min(b, e))
def test_simple_case():
    solution_instance = Solution()
    assert min_max_deletions([3, 2, 5, 3, 1, 4]) == solution_instance.minimumDeletions([3, 2, 5, 3, 1, 4])
def test_edge_case():
    solution_instance = Solution()
    assert min_max_deletions([2]) == solution_instance.minimumDeletions([2])
def test_difficult_case():
    solution_instance = Solution()
    assert min_max_deletions([4, 2, 4, 3]) == solution_instance.minimumDeletions([4, 2, 4, 3])

