def evaluate_expression(expression):
    return eval(expression)
class Solution:

    def __init__(self):
        self.operators = set(['*', '/', '+', '-'])

    def calculate(self, s: str) -> int:
        if not s:
            return 0
        '\n        Step 1: Split the string into a list of numbers and operators, in the same order as they arrived in the string\n        '
        parsed = []
        s_ptr = 0
        while s_ptr < len(s):
            if s[s_ptr] in self.operators:
                parsed.append(s[s_ptr])
                s_ptr += 1
                continue
            if s[s_ptr].isnumeric():
                number_string = ''
                while s_ptr < len(s) and s[s_ptr].isnumeric():
                    number_string += s[s_ptr]
                    s_ptr += 1
                parsed.append(int(number_string))
                continue
            if s[s_ptr].isspace():
                s_ptr += 1
                continue
            print('seen invalid char in input: ' + s[s_ptr])
            break
        '\n        Step 2: apply operations to numbers, using operator precedence.\n        \n        Examples\n        3+2*4 = 3+(2*4) = 11\n        2*4+3*3 = (2*4)+(3*3) = 17\n        2*4+3*3+2 = (2*4)+(3*3)+2 = 19\n        '
        sum_list = []
        cur_num = parsed.pop(0)
        cur_op = None
        for it in parsed:
            if it in self.operators:
                if it == '+' or it == '-':
                    sum_list.append(cur_num)
                cur_op = it
            if type(it) is int:
                if cur_op == '+' or cur_op == '-':
                    cur_num = it if cur_op == '+' else -it
                    cur_op = None
                elif cur_op == '*':
                    cur_num = it * cur_num
                else:
                    sign = -1 if cur_num < 0 else 1
                    cur_num = cur_num * sign
                    cur_num = cur_num // it
                    cur_num = cur_num * sign
        sum_list.append(cur_num)
        return sum(sum_list)
def test_simple_case():
    sol_instance = Solution()
    assert evaluate_expression('3+2*2') == sol_instance.calculate('3+2*2')
def test_division_case():
    sol_instance = Solution()
    assert evaluate_expression('14/3') == sol_instance.calculate('14/3')
def test_complex_case():
    sol_instance = Solution()
    assert evaluate_expression('1-1+1') == sol_instance.calculate('1-1+1')

