class Solution:

    def powerfulIntegers(self, x: int, y: int, bound: int) -> List[int]:
        x_bound, y_bound = (0, 0)
        resLis = []
        if x == 1:
            x_bound = 1
        else:
            x_bound = int(log(bound, x))
        if y == 1:
            y_bound = 1
        else:
