class Solution(object):

    def isValid(self, temp):
        thedict = {}
        for i in range(len(temp)):
            if temp[i] not in thedict:
                thedict[temp[i]] = 0
            else:
                return False
        return True

    def countGoodSubstrings(self, s):
        """
        :type s: str
        :rtype: int
        """
        if len(s) <= 2:
            return 0
        res = []
        temp = ''
        for i in range(3):
            temp += s[i]
        if self.isValid(temp):
            res.append(temp)
        for i in range(3, len(s)):
            temp = temp[1:] + s[i]
            if len(temp) == 3:
                if self.isValid(temp):
                    res.append(temp)
        return len(res)
