class Stack:

    def __init__(self):
        self.items = []

    def is_empty(self):
        return self.items == []

    def push(self, data):
        self.items.append(data)

    def pop(self):
        return self.items.pop()
def test_simple_case():
    expr1 = '({}[]())'
    stack = Stack()
    result = check_parenthesis(expr1)
    assert result == stack.is_empty()
