    stack = Stack()
    result = check_parenthesis(expr2)
    assert result == stack.is_empty()
def test_difficult_case():
    expr3 = '([{}])'
    stack = Stack()
    result = check_parenthesis(expr3)
    assert result == stack.is_empty()

