def apply_operations(nums, operations):
    for op in operations:
        nums[op[0]] = op[1]
    return nums
class Solution:

    def arrayChange(self, nums: List[int], operations: List[List[int]]) -> List[int]:
        n = len(operations)
        dic = defaultdict()
        for i in range(n - 1, -1, -1):
            key, value = operations[i]
            if value in dic:
                tmp = dic[value]
                del dic[value]
                dic[key] = tmp
            else:
                dic[key] = value
        for i, num in enumerate(nums):
            if num in dic:
                nums[i] = dic[num]
        return nums
def test_simple_case():
    solution_instance = Solution()
    nums = [1, 2]
    operations = [[0, 3], [1, 4]]
    assert apply_operations(nums, operations) == solution_instance.arrayChange(nums, operations)
