def surfaceArea(grid):
    ans = 0
    n = len(grid)
    for i in range(n):
        for j in range(n):
            if grid[i][j]:
                ans += 2 + 4 * grid[i][j]
            if i:
                ans -= min(grid[i][j], grid[i - 1][j]) * 2
            if j:
                ans -= min(grid[i][j], grid[i][j - 1]) * 2
    return ans
class Solution:

    def surfaceArea(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return 0 if grid[0][0] == 0 else 2 * (2 * grid[0][0] + 1)
        count = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] != 0:
                    count += 2 * (2 * grid[i][j] + 1)
        for i in range(n):
            for j in range(n):
                x = 0
                if i == 0:
                    if grid[i + 1][j] != 0:
                        x += min(grid[i + 1][j], grid[i][j])
                    if j == 0:
                        if grid[i][j + 1] != 0:
                            x += min(grid[i][j], grid[i][j + 1])
                    elif j == n - 1:
                        if grid[i][j - 1] != 0:
                            x += min(grid[i][j], grid[i][j - 1])
                    else:
                        if grid[i][j + 1] != 0:
                            x += min(grid[i][j], grid[i][j + 1])
                        if grid[i][j - 1] != 0:
                            x += min(grid[i][j], grid[i][j - 1])
                elif i == n - 1:
                    if grid[i - 1][j] != 0:
                        x += min(grid[i - 1][j], grid[i][j])
                    if j == 0:
                        if grid[i][j + 1] != 0:
                            x += min(grid[i][j], grid[i][j + 1])
                    elif j == n - 1:
                        if grid[i][j - 1] != 0:
                            x += min(grid[i][j], grid[i][j - 1])
                    else:
                        if grid[i][j + 1] != 0:
                            x += min(grid[i][j], grid[i][j + 1])
                        if grid[i][j - 1] != 0:
                            x += min(grid[i][j], grid[i][j - 1])
                else:
                    if grid[i - 1][j] != 0:
                        x += min(grid[i - 1][j], grid[i][j])
                    if grid[i + 1][j] != 0:
                        x += min(grid[i + 1][j], grid[i][j])
                    if j == 0:
                        if grid[i][j + 1] != 0:
                            x += min(grid[i][j], grid[i][j + 1])
                    elif j == n - 1:
                        if grid[i][j - 1] != 0:
                            x += min(grid[i][j], grid[i][j - 1])
                    else:
                        if grid[i][j + 1] != 0:
                            x += min(grid[i][j], grid[i][j + 1])
                        if grid[i][j - 1] != 0:
                            x += min(grid[i][j], grid[i][j - 1])
                count -= x
        return count
def test_simple_case():
    s = Solution()
    assert surfaceArea([[1, 1, 1], [1, 0, 1], [1, 1, 1]]) == s.surfaceArea([[1, 1, 1], [1, 0, 1], [1, 1, 1]])
def test_edge_case():
    s = Solution()
    assert surfaceArea([[2, 1, 2], [1, 1, 1], [2, 1, 2]]) == s.surfaceArea([[2, 1, 2], [1, 1, 1], [2, 1, 2]])
def test_difficult_case():
    s = Solution()
    assert surfaceArea([[1, 3, 4], [2, 2, 1], [4, 1, 3]]) == s.surfaceArea([[1, 3, 4], [2, 2, 1], [4, 1, 3]])

