from typing import *
from collections import *
from math import *

def get_factor_sum(num):
    sum = 0
    for i in range(1, num // 2 + 1):
        if num % i == 0:
            sum += i
    return sum
def are_amicable(num1, num2):
    sum1 = get_factor_sum(num1)
    sum2 = get_factor_sum(num2)
    if sum1 == num2 and sum2 == num1:
        return True
    else:
        return False
def sum_amicable_numbers(n):
    amicable_list = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if are_amicable(i, j):
                amicable_list.append(i)
                amicable_list.append(j)
    return sum(set(amicable_list))
def amicable_numbers_sum(limit):
    if not isinstance(limit, int):
        return 'Input is not an integer!'
    if limit < 1:
        return 'Input must be bigger than 0!'
    amicables = set()
    for num in range(2, limit + 1):
        if num in amicables:
            continue
        sum_fact = sum([fact for fact in range(1, num) if num % fact == 0])
        sum_fact2 = sum([fact for fact in range(1, sum_fact) if sum_fact % fact == 0])
        if num == sum_fact2 and num != sum_fact:
            amicables.add(num)
            amicables.add(sum_fact2)
    return sum(amicables)
def test_simple_case():
    assert sum_amicable_numbers(100) == amicable_numbers_sum(100)
def test_edge_case():
    assert sum_amicable_numbers(500) == amicable_numbers_sum(500)
def test_difficult_case():
    assert sum_amicable_numbers(1000) == amicable_numbers_sum(1000)

