from typing import *
from collections import *
from math import *

def xor_pairs(nums1, nums2):
    nums3 = []
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] ^ nums2[j] not in nums3:
                nums3.append(nums1[i] ^ nums2[j])
    return nums3
class Solution:

    def xorAllNums(self, nums1: List[int], nums2: List[int]) -> int:
        len1, len2 = (len(nums1) % 2, len(nums2) % 2)
        data = [0] * 32
        for element in nums1:
            bin_rep = bin(element)[2:]
            start_index = 32 - len(bin_rep)
            for t in range(start_index, 32):
                data[t] += int(bin_rep[t - start_index]) * len2
        for element in nums2:
            bin_rep = bin(element)[2:]
            start_index = 32 - len(bin_rep)
            for t in range(start_index, 32):
                data[t] += int(bin_rep[t - start_index]) * len1
        return int(''.join(['1' if x % 2 == 1 else '0' for x in data]), 2)
def test_simple_case():
    solution_instance = Solution()
    assert xor_pairs([1, 2], [3, 4]) == solution_instance.xorAllNums([1, 2], [3, 4])
def test_edge_case():
    solution_instance = Solution()
    assert xor_pairs([5], [7, 1]) == solution_instance.xorAllNums([5], [7, 1])
def test_difficult_case():
    solution_instance = Solution()
    assert xor_pairs([1, 2, 3], [4, 5, 6]) == solution_instance.xorAllNums([1, 2, 3], [4, 5, 6])

