class Solution:

    def numTeams(self, rating: List[int]) -> int:
        if len(rating) < 3:
            return 0
        else:
            count = 0
            for i in range(len(rating) - 2):
                arr = []
                arr.append(rating[i])
                for j in range(i + 1, len(rating) - 1):
                    curelmt = rating[i]
                    if rating[j] > curelmt:
                        curelmt = rating[j]
                        arr.append(rating[j])
                        for k in range(j + 1, len(rating)):
                            if rating[k] > curelmt:
                                arr.append(rating[k])
                            if len(arr) == 3:
                                count += 1
                                arr.pop(-1)
                    elif rating[j] < curelmt:
                        curelmt = rating[j]
                        arr.append(rating[j])
                        for k in range(j + 1, len(rating)):
                            if rating[k] < curelmt:
                                arr.append(rating[k])
                            if len(arr) == 3:
                                count += 1
                                arr.pop(-1)
                    arr.pop(-1)
        return count
