test_code:
from typing import *
from collections import *
from math import *

def colorGrid(n):
    MOD = 10 ** 9 + 7
    same, diff = (6, 6)
    for i in range(2, n + 1):
        same, diff = ((3 * same + 2 * diff) % MOD, (2 * same + 2 * diff) % MOD)
    return (same + diff) % MOD
class Solution:

    def colorTheGrid(self, m: int, n: int) -> int:
        M = 10 ** 9 + 7
        ans = 3
        if m == 1:
            for i in range(n - 1):
                ans *= 2
                ans %= M
            return ans % M

        def IsValid(a):
            return all((a[i] != a[i + 1] for i in range(len(a) - 1)))
        if m >= 2:
            AllStates = [[0], [1], [2]]
            colors = [0, 1, 2]
            for j in range(m - 1):
                L = len(AllStates)
                for i in range(L):
                    x = AllStates.pop(0)
                    for c in colors:
                        AllStates.append(tuple([*x, c]))
            v = set()
            for a in AllStates:
                if IsValid(a):
                    v.add(a)
            d = {i: a for i, a in enumerate(v)}
            numStates = len(v)

            def IsValidNeigbor(a, b):
                if a not in v or b not in v:
                    return False
                else:
                    for i in range(len(a)):
                        if a[i] == b[i]:
                            return False
                    return True
            adj = {i: [] for i in range(numStates)}
            for i in range(numStates):
                for j in range(i + 1, numStates):
                    if IsValidNeigbor(d[i], d[j]):
                        adj[i].append(j)
                        adj[j].append(i)
            dp = [[0 for _ in range(n + 1)] for _ in range(numStates)]
            for i in range(numStates):
                dp[i][1] = 1
            for j in range(2, n + 1):
                for i in range(numStates):
                    for k in adj[i]:
                        dp[i][j] += dp[k][j - 1]
                        dp[i][j] %= M
            return sum((dp[i][n] for i in range(numStates))) % M
def test_simple_case():
    assert colorGrid(1) == Solution().colorTheGrid(1, 1)
def test_medium_case():
    assert colorGrid(2) == Solution().colorTheGrid(2, 2)
def test_complex_case():
    assert colorGrid(3) == Solution().colorTheGrid(3, 3)

