def maxSubarrayProduct(nums):
    max_len = 0
    start = end = 0

    for i in range(len(nums)):
        if nums[i] > 0:
            end += 1
        elif nums[i] == 0:
            max_len = max(max_len, end - start)
            start = end = i + 1

    # If the array ends with positive integers, max_len needs to be updated again
    max_len = max(max_len, end - start)

    return max_len

