def find_frequent_elements(arr):
    n = len(arr)
    freq = n // 3
    counter = Counter(arr)
    res = []
    for num, count in counter.items():
        if count > freq:
            res.append(num)
    return res
class Solution:

    def majorityElement(self, nums: List[int]) -> List[int]:
        d = {}
        for num in nums:
            if num not in d:
                d[num] = 0
            d[num] += 1
        res = []
        k = len(nums) // 3
        for key in d:
            if d[key] > k:
                res.append(key)
        return res
class Solution:

    def majorityElement(self, nums: List[int]) -> List[int]:
        count1 = count2 = 0
        candidate1, candidate2 = (0, 1)
        for num in nums:
            if num == candidate1:
                count1 += 1
            elif num == candidate2:
                count2 += 1
            elif count1 == 0:
                candidate1, count1 = (num, 1)
            elif count2 == 0:
                candidate2, count2 = (num, 2)
            else:
                count1 -= 1
                count2 -= 1
        res = []
        for candidate in [candidate1, candidate2]:
            cnt = 0
            for num in nums:
                if num == candidate:
                    cnt += 1
            if cnt > len(nums) // 3:
                res.append(candidate)
        return res
def test_simple_case():
    sol = Solution()
    assert find_frequent_elements([3, 2, 3]) == sol.majorityElement([3, 2, 3])
def test_edge_case():
    sol = Solution()
    assert find_frequent_elements([1, 2]) == sol.majorityElement([1, 2])
def test_difficult_case():
    sol = Solution()
    assert find_frequent_elements([1, 1, 1, 3, 3, 2, 2, 2]) == sol.majorityElement([1, 1, 1, 3, 3, 2, 2, 2])

