def getHint(secret: str, guess: str) -> str:
    bulls = 0
    cows = 0
    secret_count = {}
    for i in range(len(secret)):
        if secret[i] == guess[i]:
            bulls += 1
        elif secret[i] not in secret_count:
            secret_count[secret[i]] = 1
        else:
            secret_count[secret[i]] += 1
    for i in range(len(secret)):
        if secret[i] != guess[i] and guess[i] in secret_count and (secret_count[guess[i]] > 0):
            cows += 1
            secret_count[guess[i]] -= 1
    return str(bulls) + 'A' + str(cows) + 'B'
class Solution:

    def getHint(self, secret: str, guess: str) -> str:
        bulls = cows = 0
        secretCopy = list(secret)
        guessCopy = list(guess)
        for i in range(len(secret)):
            if secret[i] == guess[i]:
                bulls += 1
                secretCopy.pop(secretCopy.index(secret[i]))
                guessCopy.pop(guessCopy.index(guess[i]))
        secretCounter = Counter(secretCopy)
        guessCounter = Counter(guessCopy)
        dif = secretCounter - (secretCounter - guessCounter)
        cows = dif.total()
        return f'{bulls}A{cows}B'
def test_simple_case():
    solution_instance = Solution()
    assert getHint('1807', '7810') == solution_instance.getHint('1807', '7810')
def test_edge_case():
    solution_instance = Solution()
    assert getHint('1123', '0111') == solution_instance.getHint('1123', '0111')
def test_difficult_case():
    solution_instance = Solution()
    assert getHint('1011', '1110') == solution_instance.getHint('1011', '1110')

