class Solution:

    def wonderfulSubstrings(self, word: str) -> int:
        dp = [0] * 1024
        curr = 0
        dp[0] = 1
        res = 0
        for c in word:
            curr ^= 1 << ord(c) - ord('a')
            res += dp[curr]
            for i in range(10):
                res += dp[curr ^ 1 << i]
            dp[curr] += 1
        return res
