def find_min_subarray(nums):
    ans = [0] * len(nums)
    max_bit = [-1] * 32
    for i in range(len(nums)-1, -1, -1):
        val = nums[i]
        for j in range(32):
            if val & (1 << j):
                if max_bit[j] == -1:
                    max_bit[j] = i
                else:
                    max_bit[j] = min(max_bit[j], i)
        min_idx = len(nums)
        for j in range(32):
            if max_bit[j] != -1:
                min_idx = min(min_idx, max_bit[j])
        ans[i] = min_idx - i + 1
    return ans

