class Solution:

    def smallestSubarrays(self, nums: List[int]) -> List[int]:
        """
        TLE with BinSearch
        """

        def bins(k):
            ret = []
            while k > 0:
                ret.append(k % 2)
                k = k // 2
            return ret
        n = len(nums)
        h = [{}]
        for i in range(n):
            bi = bins(nums[i])
            hi = {i: 1 for i in range(len(bi)) if bi[i] == 1}
            ti = {k: v for k, v in h[i].items()}
            for k in hi:
                ti[k] = ti.get(k, 0) + 1
            h.append(ti)
        ans = []
        for i in range(n):
            x = 0
            for k in h[n]:
                if h[n].get(k, 0) - h[i].get(k, 0) > 0:
                    x += 1
            l, r = (i, n - 1)
            while l < r:
                mid = (l + r) // 2
                xmid = 0
                for k in h[mid + 1]:
                    if h[mid + 1].get(k, 0) - h[i].get(k, 0) > 0:
                        xmid += 1
                if xmid != x:
                    l = mid + 1
                else:
                    r = mid
            size = r - i + 1
            ans.append(size)
        return ans
def test_simple_case():
    nums = [1, 2, 3]
    assert find_min_subarray(nums) == Solution().smallestSubarrays(nums)
def test_edge_case():
    nums = [0, 0, 1, 0, 0]
    assert find_min_subarray(nums) == Solution().smallestSubarrays(nums)
def test_difficult_case():
    nums = [3, 1, 5, 11]
    assert find_min_subarray(nums) == Solution().smallestSubarrays(nums)

