class Solution:

    def reorderLogFiles(self, logs: List[str]) -> List[str]:
        llogs = dict()
        dlogs = []
        for log in logs:
            names = log.split()
            if names[1].isdigit():
                dlogs.append(log)
            elif names[0] in llogs:
                llogs[names[0] + ' '] = names[1:]
            else:
                llogs[names[0]] = names[1:]
        res = sorted(llogs)
        res.sort(key=llogs.get)
        for i in range(len(res)):
            name = res[i]
            logs = llogs[res[i]]
            res[i] = f'{name.split()[0]} {' '.join(logs)}'
        return res + dlogs
def test_simple_case():
    solution_instance = Solution()
    logs = ['dig1 8 1 2', 'let1 art zero', 'let2 own tree', 'dig2 3 2 1']
    assert reorder_logs(logs) == solution_instance.reorderLogFiles(logs)
def test_edge_case():
    solution_instance = Solution()
    logs = ['a1 9 2 3 1', 'g1 act car', 'z1 4 2 3', 'r1 7 5 3 2', 'g2 bye car two three']
    assert reorder_logs(logs) == solution_instance.reorderLogFiles(logs)
def test_difficult_case():
    solution_instance = Solution()
    logs = ['g1 act car', 'a8 act zoo', 'ab1 off key dog', 'a1 9 2 3 1', 'zo4 4 7']
