from typing import *
from collections import *
from math import *

def min_swaps(n, grid):
    count = 0
    for i in range(n):
        if grid[i][i] == 1:
            for j in range(i + 1, n):
                if grid[j][i] == 0 and grid[i][j] == 0:
                    grid[i], grid[j] = (grid[j], grid[i])
                    count += 1
                    break
            else:
                return -1
    return count
class Solution:

    def minSwaps(self, grid: List[List[int]]) -> int:
        m, n = (len(grid), len(grid[0]))
        row = [0] * m
        for i in range(m):
            row[i] = next((j for j in reversed(range(n)) if grid[i][j]), 0)
        ans = 0
        for k in range(m):
            for i, v in enumerate(row):
                if v <= k:
                    ans += i
                    row.pop(i)
                    break
            else:
                return -1
        return ans
def test_simple_case():
    sol_instance = Solution()
    grid = [[0, 1, 0], [0, 0, 0], [1, 0, 0]]
    n = len(grid)
    assert min_swaps(n, grid) == sol_instance.minSwaps(grid)
def test_edge_case():
    sol_instance = Solution()
    grid = [[1, 0, 0], [0, 1, 0], [0, 0, 0]]
    n = len(grid)
    assert min_swaps(n, grid) == sol_instance.minSwaps(grid)
