def maxSumTwoNoOverlap(nums: List[int], firstLen: int, secondLen: int) -> int:
    n = len(nums)
    presum = [0] * (n + 1)
    for i in range(n):
        presum[i + 1] = presum[i] + nums[i]
    res = float('-inf')
    for i in range(firstLen - 1, n - secondLen):
        max_left = max((presum[j] - presum[j - firstLen] for j in range(i, firstLen - 2, -1)))
        max_right = max((presum[j + secondLen] - presum[j] for j in range(i, n - secondLen)))
        res = max(res, max_left + max_right)
    for i in range(secondLen - 1, n - firstLen):
        max_left = max((presum[j] - presum[j - secondLen] for j in range(i, secondLen - 2, -1)))
        max_right = max((presum[j + firstLen] - presum[j] for j in range(i, n - firstLen)))
        res = max(res, max_left + max_right)
    return res
class Solution:

    def maxSumTwoNoOverlap(self, A: List[int], L: int, M: int) -> int:
        n = len(A)
        left_max_l = [-float('inf') for _ in range(n)]
        right_max_l = [-float('inf') for _ in range(n)]
        cur = ma = sum(A[:L])
        for i in range(L - 1, len(A)):
            if i > L - 1:
                cur += A[i] - A[i - L]
            ma = max(ma, cur)
            left_max_l[i] = ma
        cur = ma = sum(A[n - L:])
        for i in range(n - L, -1, -1):
            if i < n - L:
                cur += A[i] - A[i + L]
            ma = max(cur, ma)
            right_max_l[i] = ma
        left_max = -float('inf')
        right_max = -float('inf')
        res = -float('inf')
        cur = sum(A[:M])
        for i in range(M - 1, n):
            if i > M - 1:
                cur += A[i] - A[i - M]
            if M + L - 1 <= i <= n - L - 1:
                left_max = left_max_l[i - M]
                right_max = right_max_l[i + 1]
                res = max(res, cur + max(left_max, right_max))
            elif M + L - 1 <= i:
                res = max(res, cur + left_max_l[i - M])
            elif i <= n - L - 1:
                res = max(res, cur + right_max_l[i + 1])
        return res
def test_simple_case():
    solution_instance = Solution()
    assert maxSumTwoNoOverlap([0, 6, 5, 2, 2, 5, 1, 9, 4], 1, 2) == solution_instance.maxSumTwoNoOverlap([0, 6, 5, 2, 2, 5, 1, 9, 4], 1, 2)
def test_case1():
    solution_instance = Solution()
    assert maxSumTwoNoOverlap([3, 8, 1, 3, 2, 1, 8, 9, 0], 3, 2) == solution_instance.maxSumTwoNoOverlap([3, 8, 1, 3, 2, 1, 8, 9, 0], 3, 2)
def test_case2():
    solution_instance = Solution()
    assert maxSumTwoNoOverlap([2, 9, 5, 6, 1, 7], 2, 3) == solution_instance.maxSumTwoNoOverlap([2, 9, 5, 6, 1, 7], 2, 3)

