def maxProduct(nums: List[int]) -> int:
    if len(nums) == 0:
        return 0
    max_product = nums[0]
    curr_min = nums[0]
    curr_max = nums[0]
    for i in range(1, len(nums)):
        if nums[i] < 0:
            curr_min, curr_max = (curr_max, curr_min)
        curr_min = min(nums[i], curr_min * nums[i])
        curr_max = max(nums[i], curr_max * nums[i])
        max_product = max(max_product, curr_max)
    return max_product
class Solution:

    def getProduct(self, nums, start, end):
        if start >= end:
            return float('-inf')
        product = 1
        for i in range(start, end):
            product *= nums[i]
        return product

    def maxProduct(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        fst_neg_idx = -1
        last_neg_idx = -1
        last_zero_idx = -1
        n_neg = 0
        max_prod = float('-inf')
        for i in range(n):
            if nums[i] < 0:
                if fst_neg_idx == -1:
                    fst_neg_idx = i
                last_neg_idx = i
                n_neg += 1
            elif nums[i] == 0:
                if n_neg % 2 == 0:
                    max_prod = max(max_prod, self.getProduct(nums, last_zero_idx + 1, i))
                else:
                    max_prod = max(max_prod, self.getProduct(nums, fst_neg_idx + 1, i), self.getProduct(nums, last_zero_idx + 1, last_neg_idx))
                max_prod = max(max_prod, 0)
                fst_neg_idx = -1
                last_neg_idx = -1
                n_neg = 0
                last_zero_idx = i
        if n_neg % 2 == 0:
            max_prod = max(max_prod, self.getProduct(nums, last_zero_idx + 1, n))
        else:
            max_prod = max(max_prod, self.getProduct(nums, fst_neg_idx + 1, n), self.getProduct(nums, last_zero_idx + 1, last_neg_idx))
        return max_prod
def test_simple_case():
    solution_instance = Solution()
    assert maxProduct([2, 3, -2, 4]) == solution_instance.maxProduct([2, 3, -2, 4])
def test_edge_case():
    solution_instance = Solution()
    assert maxProduct([-2]) == solution_instance.maxProduct([-2])
def test_difficult_case():
    solution_instance = Solution()
    assert maxProduct([-4, -3]) == solution_instance.maxProduct([-4, -3])

