def maxPoints(points):
    dp = [[0] * len(points[0]) for _ in range(len(points))]
    for j in range(len(points[0])):
        dp[0][j] = points[0][j]
    for i in range(1, len(points)):
        max_score = max(dp[i-1])
        max_index = dp[i-1].index(max_score)
        for j in range(len(points[0])):
            dp[i][j] = points[i][j] + max_score - abs(j - max_index)
    return max(dp[-1])

