from math import *

def max_employees_invited(favorite: List[int]) -> int:
    n = len(favorite)
    max_invited = 0
    for i in range(n):
        visited = set()
        curr_employee = i
        invited = 0
        while curr_employee not in visited:
            visited.add(curr_employee)
            invited += 1
            curr_employee = favorite[curr_employee]
        max_invited = max(max_invited, invited)
    return max_invited
class Solution:

    def maximumInvitations(self, favorite: List[int]) -> int:
        n = len(favorite)
        graph = [[] for _ in range(n)]
        for i, x in enumerate(favorite):
            graph[x].append(i)

        def bfs(x, seen):
            """Return longest arm of x."""
            ans = 0
            queue = deque([x])
            while queue:
                for _ in range(len(queue)):
                    u = queue.popleft()
                    for v in graph[u]:
                        if v not in seen:
                            seen.add(v)
                            queue.append(v)
                ans += 1
            return ans
        ans = 0
        seen = [False] * n
        for i, x in enumerate(favorite):
            if favorite[x] == i and (not seen[i]):
                seen[i] = seen[x] = True
                ans += bfs(i, {i, x}) + bfs(x, {i, x})
        dp = [0] * n
        for i, x in enumerate(favorite):
            if dp[i] == 0:
                ii, val = (i, 0)
                memo = {}
                while ii not in memo:
                    if dp[ii]:
                        cycle = dp[ii]
                        break
                    memo[ii] = val
                    val += 1
                    ii = favorite[ii]
                else:
                    cycle = val - memo[ii]
                for k in memo:
                    dp[k] = cycle
        return max(ans, max(dp))
def test_simple_case():
    solution_instance = Solution()
    favorite = [2, 2, 1, 2]
    assert max_employees_invited(favorite) == solution_instance.maximumInvitations(favorite)
def test_edge_case():
    solution_instance = Solution()
    favorite = [1, 2, 0]
    assert max_employees_invited(favorite) == solution_instance.maximumInvitations(favorite)
def test_difficult_case():
    solution_instance = Solution()
    favorite = [3, 0, 1, 4, 1]
    assert max_employees_invited(favorite) == solution_instance.maximumInvitations(favorite)

