class Solution:

    def divideString(self, s: str, k: int, fill: str) -> List[str]:
        if len(s) < k:
            return [s + (k - len(s)) * fill]
        else:
            counter = 0
            output, substr = ([], '')
            for i in range(len(s)):
                substr += s[i]
                counter += 1
                if counter == k:
                    counter = 0
                    output.append(substr)
                    substr = ''
            if output[-1] != s[-k:]:
                output.append(substr + fill * (k - len(substr)))
                return output
            else:
                return output
def test_simple_case():
    solution_instance = Solution()
    assert partition_groups('abcdefghij', 3, 'x') == solution_instance.divideString('abcdefghij', 3, 'x')
