def divide_pairs_sum(arr, k):
    counts = [0] * k
    for num in arr:
        counts[num % k] += 1
    if counts[0] % 2 != 0:
        return False
    for i in range(1, k//2+1):
        if counts[i] != counts[k-i]:
            return False
    return True

