class Solution:

    def predictPartyVictory(self, senate: str) -> str:
        n = len(senate)
        count = Counter(senate)
        skip_r = 0
        skip_d = 0
        removed_r = set()
        removed_d = set()
        while count['D'] > 0 and count['R'] > 0:
            for i in range(n):
                s = senate[i]
                if s == 'R':
                    if skip_r <= 0 and i not in removed_r:
                        count['D'] -= 1
                        skip_d += 1
                    elif i not in removed_r:
                        skip_r -= 1
                        removed_r.add(i)
                elif skip_d <= 0 and i not in removed_d:
                    count['R'] -= 1
                    skip_r += 1
                elif i not in removed_d:
                    skip_d -= 1
                    removed_d.add(i)
        if count['D'] > 0:
            return 'Dire'
        else:
            return 'Radiant'
def test_initial_balance():
    senate = 'RD'
    solution_instance = Solution()
    assert predictPartyVictory(senate) == solution_instance.predictPartyVictory(senate)
def test_immediate_victory():
