class Solution:

    def arrangeCoins(self, n: int) -> int:
        l, h = (1, n)
        ans = None
        while l <= h:
            mid_row = (l + h) // 2
            req_coins = mid_row * (mid_row + 1) / 2
            if req_coins <= n:
                ans = mid_row
                l = mid_row + 1
                continue
            else:
                h = mid_row - 1
                continue
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert num_complete_rows(5) == solution_instance.arrangeCoins(5)
def test_edge_case():
    solution_instance = Solution()
    assert num_complete_rows(8) == solution_instance.arrangeCoins(8)
