def find_ball_path(box: List[List[int]], n: int) -> List[int]:
    answer = [-1] * n
    for i in range(n):
        col = i
        for row in range(len(box)):
            if box[row][col] == 1:
                if col == 0:
                    answer[i] = row
                    break
                if box[row][col-1] == -1:
                    col -= 1
                elif col < n-1 and box[row][col+1] == 1:
                    col += 1
    return answer

