def generate_strings(n: int) -> List[str]:
    vowels = ['a', 'e', 'i', 'o', 'u']
    result = []

    def backtrack(i: int, curr: str) -> None:
        if len(curr) == n:
            result.append(curr)
            return

        for v in vowels:
            if not curr or v > curr[-1]:
                backtrack(i+1, curr + v)

    backtrack(0, "")
    return result

