def merge(arr1, arr2):
    if not arr1:
        return arr2
    if not arr2:
        return arr1
    if arr1[0] <= arr2[0]:
        return [arr1[0]] + merge(arr1[1:], arr2)
    return [arr2[0]] + merge(arr1, arr2[1:])

def insertion_sort(arr):
    for i in range(1, len(arr)):
        j = i - 1
        key = arr[i]
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key

def merge_insertion_sort(arr):
    if len(arr) <= 4:
        insertion_sort(arr)
        return arr
    mid = len(arr) // 2
    left = merge_insertion_sort(arr[:mid])
    right = merge_insertion_sort(arr[mid:])
    return merge(left, right)

