class Solution:

    def gcdOfStrings2(self, str1: str, str2: str) -> str:
        if str1 == str2:
            return str1
        if str1 + str2 != str2 + str1:
            return ''
        if len(str1) > len(str2):
            shorter = str2
            longer = str1
        else:
            shorter = str1
            longer = str2
        shorter_length = len(shorter)
        longer_length = len(longer)
        prefix = ''
        for index in range(len(shorter), 0, -1):
            if shorter_length % index == 0 and longer_length % index == 0:
                pref = shorter[0:index]
                if shorter == pref * (shorter_length // index) and longer == pref * (longer_length // index):
                    prefix = pref
                    break
        return prefix
def test_simple_case():
    solution_instance = Solution()
    assert find_largest_divisor('ABCABC', 'ABC') == solution_instance.gcdOfStrings2('ABCABC', 'ABC')
def test_edge_case():
    solution_instance = Solution()
    assert find_largest_divisor('ABABAB', 'ABAB') == solution_instance.gcdOfStrings2('ABABAB', 'ABAB')
def test_difficult_case():
    solution_instance = Solution()
    assert find_largest_divisor('LEET', 'LEETCODE') == solution_instance.gcdOfStrings2('LEET', 'LEETCODE')

