def max_jump(arr, d):
    max_visits = 0
    for i in range(len(arr)):
        j = i + 1
        while j < len(arr) and j - i <= d and arr[i] > arr[j]:
            k = j + 1
            while k < len(arr) and k <= j + d:
                if arr[i] > arr[k] and arr[j] > arr[k]:
                    max_visits = max(max_visits, k - i)
                k += 1
            j += 1
    return max_visits

