from typing import *
from collections import *
from math import *

def max_jump(arr, d):
    max_visits = 0
    for i in range(len(arr)):
        j = i + 1
        while j < len(arr) and j - i <= d and (arr[i] > arr[j]):
            k = j + 1
            while k < len(arr) and k <= j + d:
                if arr[i] > arr[k] and arr[j] > arr[k]:
                    max_visits = max(max_visits, k - i)
                k += 1
            j += 1
    return max_visits
class Solution:

    def maxJumps(self, nums: List[int], d: int) -> int:
        N = len(nums)
        seen = set()
        dp = [1] * N

        def recursion(indx):
            if indx in seen:
                return dp[indx]
            if indx < 0 or indx >= N:
                return 0
            tempR, tempL = (0, 0)
            curr = nums[indx]
            for i in range(indx + 1, min(indx + d + 1, N)):
                if nums[i] < curr:
                    tempR = max(tempR, recursion(i))
                else:
                    break
            for i in range(indx - 1, max(-1, indx - d - 1), -1):
                if nums[i] < curr:
                    tempL = max(tempL, recursion(i))
                else:
                    break
            dp[indx] = max(tempR, tempL) + 1
            seen.add(indx)
            return dp[indx]
        for i in range(N):
            if i not in seen:
                recursion(i)
        return max(dp)
def test_simple_case():
    assert max_jump([6, 4, 14, 6], 2) == Solution().maxJumps([6, 4, 14, 6], 2)
def test_edge_case():
    assert max_jump([4, 8, 9], 1) == Solution().maxJumps([4, 8, 9], 1)
def test_difficult_case():
    assert max_jump([11, 7, 2, 15], 2) == Solution().maxJumps([11, 7, 2, 15], 2)

