def countCharacters(words, chars):
    res = 0
    for word in words:
        if all((word.count(c) <= chars.count(c) for c in set(word))):
            res += len(word)
    return res
class Solution:

    def countCharacters(self, words: List[str], chars: str) -> int:
        wordlen = 0
        runningsum = 0
        charedits = chars
        for word in words:
            wordlen = 0
            charedits = chars
            for letter in word:
                if letter in charedits:
                    wordlen += 1
                    charedits = charedits.replace(letter, ' ', 1)
            if len(word) == wordlen:
                runningsum += len(word)
        return runningsum
def test_simple_case():
    solution_instance = Solution()
