solution_code:
def choose_team(scores, ages):
    team = []
    for i in range(len(scores)):
        team.append((scores[i], ages[i]))
    team.sort(reverse=True)
    chosen = []
    for player in team:
        conflict = False
        for chosen_player in chosen:
            if chosen_player[1] < player[1] and chosen_player[0] > player[0]:
                conflict = True
                break
        if not conflict:
            chosen.append(player)
    return sum([player[0] for player in chosen])

