from collections import OrderedDict

def non_repeating_character(word):
    # create an ordered dictionary with the frequency of each character
    freq = OrderedDict((c, word.count(c)) for c in set(word))

    # return the first character with a frequency of 1
    return next((char for char, count in freq.items() if count == 1), None)

