def kthRepeating(input, k):
    dict = OrderedDict.fromkeys(input, 0)
    for ch in input:
        dict[ch] += 1
    nonRepeatDict = [key for key, value in dict.items() if value == 1]
    if len(nonRepeatDict) < k:
        return 'Less than k non-repeating characters in input.'
    else:
        return nonRepeatDict[k - 1]
def test_simple_case():
    assert non_repeating_character('abcabcdefg') == kthRepeating('abcabcdefg', 1)
def test_edge_case():
    assert non_repeating_character('abccba') == kthRepeating('abccba', 2)
def test_difficult_case():
    assert non_repeating_character('aabbcc') == kthRepeating('aabbcc', 3)

