from typing import *
from collections import *
from math import *

def max_sum_divisible_by_three(nums):
    dp = [0, 0, 0]
    for num in nums:
        dp[(num + dp[0]) % 3], dp[(num + dp[1]) % 3], dp[(num + dp[2]) % 3] = (dp[(num + dp[0]) % 3] + num, dp[(num + dp[1]) % 3] + num, dp[(num + dp[2]) % 3] + num)
    return dp[0]
class Solution:

    def maxSumDivThree(self, nums: List[int]) -> int:
        dp = []
        for i in range(3):
            z = []
            for j in range(len(nums)):
                z.append(0)
            dp.append(z)
        dp[nums[0] % 3][0] = nums[0]
        for i in range(1, len(nums)):
            for j in range(3):
                x = dp[j][i - 1] + nums[i]
                dp[x % 3][i] = max([dp[x % 3][i], x, dp[x % 3][i - 1]])
                dp[j][i] = max(dp[j][i - 1], dp[j][i])
        return dp[0][-1]
def test_simple_case():
    solution_instance = Solution()
    assert max_sum_divisible_by_three([3, 6, 5, 1, 8]) == solution_instance.maxSumDivThree([3, 6, 5, 1, 8])
def test_edge_case():
    solution_instance = Solution()
    assert max_sum_divisible_by_three([4]) == solution_instance.maxSumDivThree([4])
def test_difficult_case():
    solution_instance = Solution()
    assert max_sum_divisible_by_three([1, 2, 3, 4, 4]) == solution_instance.maxSumDivThree([1, 2, 3, 4, 4])

