def maximum_possible_value(arr):
    n = len(arr)
    max_val = max(arr)
    freq = [0] * (max_val+1)
    for i in range(n):
        freq[arr[i]] += 1
    ans = arr[0]
    for i in range(1, max_val+1):
        if freq[i] == 0:
            break
        if freq[i-1] > 0:
            ans = i
            freq[i-1] -= 1
        else:
            ans = i-1
            freq[i] -= 1
    return ans

