    arr = [1, 2, 3, 4]
    solution_instance = Solution()
    assert maximum_possible_value(arr) == solution_instance.maximumElementAfterDecrementingAndRearranging(arr)
def test_difficult_case():
    arr = [7, 8, 9, 10]
    solution_instance = Solution()
    assert maximum_possible_value(arr) == solution_instance.maximumElementAfterDecrementingAndRearranging(arr)

