def sender_largest_word_count(messages, senders):
    word_counts = {}
    for i in range(len(messages)):
        sender = senders[i]
        message = messages[i]
        words = message.strip().split()
        count = len(words)
        if sender in word_counts:
            word_counts[sender] += count
        else:
            word_counts[sender] = count
    max_count = -1
    largest_sender = ""
    for sender, count in word_counts.items():
        if count > max_count:
            max_count = count
            largest_sender = sender
        elif count == max_count:
            largest_sender = max(largest_sender, sender)
    return largest_sender

