class Solution:

    def largestWordCount(self, messages: List[str], senders: List[str]) -> str:
        word_count_map = {}
        n = len(messages)
        for i in range(n):
            if senders[i] in word_count_map:
                word_count_map[senders[i]] += len(messages[i].split())
            else:
                word_count_map[senders[i]] = len(messages[i].split())
        person_with_max_word = next(iter(word_count_map))
        max_word_count = word_count_map[person_with_max_word]
        for person in word_count_map:
            if word_count_map[person] > max_word_count:
                max_word_count = word_count_map[person]
                person_with_max_word = person
            elif word_count_map[person] == max_word_count and person > person_with_max_word:
                max_word_count = word_count_map[person]
                person_with_max_word = person
        return person_with_max_word
def test_simple_case():
    solution_instance = Solution()
    assert sender_largest_word_count(['hi', 'hello'], ['a', 'b']) == solution_instance.largestWordCount(['hi', 'hello'], ['a', 'b'])
def test_edge_case():
    solution_instance = Solution()
    assert sender_largest_word_count(['a', '', 'my message'], ['alice', 'bob', 'alice']) == solution_instance.largestWordCount(['a', '', 'my message'], ['alice', 'bob', 'alice'])
def test_difficult_case():
    solution_instance = Solution()
    assert sender_largest_word_count(['hello world', 'message bob'], ['alice', 'bob', 'alice']) == solution_instance.largestWordCount(['hello world', 'message bob'], ['alice', 'bob', 'alice'])

