from typing import *
from collections import *
from math import *

def find_middle_index(nums):
    for i in range(len(nums)):
        left_sum = sum(nums[:i])
        right_sum = sum(nums[i + 1:])
        if left_sum == right_sum:
            return i
    return -1
class Solution:

    def findMiddleIndex(self, nums: List[int]) -> int:
        prefix_sum = []
        prefix_sum.append(nums[0])
        for i in range(1, len(nums)):
            prefix_sum.append(prefix_sum[i - 1] + nums[i])
        for j in range(0, len(nums), 1):
            L, R = (None, None)
            if j == 0:
                L = 0
            else:
                L = prefix_sum[j - 1]
            if j == len(nums) - 1:
                R = 0
            else:
                R = prefix_sum[-1] - prefix_sum[j]
            if L == R:
                return j
            else:
                continue
        return -1
def test_simple_case():
    solution_instance = Solution()
    assert find_middle_index([2, 3, -1, 8, 4]) == solution_instance.findMiddleIndex([2, 3, -1, 8, 4])
def test_edge_case():
    solution_instance = Solution()
    assert find_middle_index([1, -1, 4]) == solution_instance.findMiddleIndex([1, -1, 4])
def test_difficult_case():
    solution_instance = Solution()
    assert find_middle_index([-1, -1, -1, -1, -1, -1]) == solution_instance.findMiddleIndex([-1, -1, -1, -1, -1, -1])

