from collections import *
from math import *

def max_score(a, b, c):
    piles = [a, b, c]
    score = 0
    while sum((x > 0 for x in piles)) > 1:
        choices = []
        for i in range(3):
            for j in range(i + 1, 3):
                if piles[i] > 0 and piles[j] > 0:
                    choices.append((i, j))
        best_choice = max(choices, key=lambda x: piles[x[0]] + piles[x[1]])
        piles[best_choice[0]] -= 1
        piles[best_choice[1]] -= 1
        score += 1
    return score
class Solution:

    def maximumScore(self, a, b, c):
        if a >= b and a >= c:
            largest = a
        elif b >= a and b >= c:
            largest = b
        else:
            largest = c
        s = a + b + c
        if s - largest <= largest:
            return s - largest
        return s // 2
class Solution:

    def maximumScore(self, num1, num2, num3):

        def largest(num1, num2, num3):
            if num1 > num2 and num1 > num3:
                largest_num = num1
            elif num2 > num1 and num2 > num3:
                largest_num = num2
            else:
                largest_num = num3
            return largest_num
        l = largest(num1, num2, num3)
        s = num1 + num2 + num3
        if s - l <= l:
            return s - l
        return s // 2
def test_simple_case():
    solution_instance = Solution()
    assert max_score(2, 4, 6) == solution_instance.maximumScore(2, 4, 6)
def test_edge_case():
    solution_instance = Solution()
    assert max_score(3, 3, 3) == solution_instance.maximumScore(3, 3, 3)
def test_difficult_case():
    solution_instance = Solution()
    assert max_score(1, 8, 8) == solution_instance.maximumScore(1, 8, 8)

