class Solution:

    def squareIsWhite(self, coordinates: str) -> bool:
        diction = {}
        letters = 'abcdefgh'
        i = 0
        for letter in letters:
            diction[letter] = i
            i += 1
        coor = coordinates.split()
        if diction[coordinates[0]] % 2 == 0:
            if int(coordinates[1]) % 2 == 0:
                return True
        elif diction[coordinates[0]] % 2 == 1:
            if int(coordinates[1]) % 2 == 1:
                return True
        else:
            return False
