def aliceWins(stones):
    n = len(stones)
    dp = [[None]*3 for _ in range(n+1)]

    def dfs(idx, mod):
        if dp[idx][mod] is not None:
            return dp[idx][mod]
        if idx == n:
            return False
        res = False
        for i in range(n):
            if stones[i]:
                stones[i] -= 1
                if dfs(idx+1, (mod+stones[i])%3):
                    stones[i] += 1
                    return True
                stones[i] += 1
        dp[idx][mod] = res
        return res

    return dfs(0, 0)

