    dp = [[None] * 3 for _ in range(n + 1)]

    def dfs(idx, mod):
        if dp[idx][mod] is not None:
            return dp[idx][mod]
        if idx == n:
            return False
        res = False
        for i in range(n):
            if stones[i]:
                stones[i] -= 1
                if dfs(idx + 1, (mod + stones[i]) % 3):
                    stones[i] += 1
                    return True
                stones[i] += 1
        dp[idx][mod] = res
        return res
    return dfs(0, 0)
class Solution:

    def stoneGameIX(self, stones: List[int]) -> bool:
        stones = [v % 3 for v in stones]
        d = defaultdict(int)
        for v in stones:
            d[v] += 1
        while d[1] >= 2 and d[2] >= 2:
            d[2] -= 1
            d[1] -= 1
        if d[0] % 2 == 0:
            if d[1] == 1 and d[2] >= 1 or (d[2] == 1 and d[1] >= 1):
                return True
        else:
            if d[1] == 0 and d[2] >= 3 or (d[2] == 0 and d[1] >= 3):
                return True
            if d[1] == 1 and d[2] >= 4 or (d[2] == 1 and d[1] >= 4):
                return True
        return False
def test_simple_case():
    solution_instance = Solution()
    stones = [1, 2, 3, 4, 2]
    assert aliceWins(stones) == solution_instance.stoneGameIX(stones)
def test_edge_case():
    solution_instance = Solution()
    stones = [5, 1, 3, 2]
    assert aliceWins(stones) == solution_instance.stoneGameIX(stones)
def test_difficult_case():
    solution_instance = Solution()
    stones = [2, 3, 5, 4]
    assert aliceWins(stones) == solution_instance.stoneGameIX(stones)

