def max_length(arr):
    unique_chars = set(''.join(arr))
    max_len = 0
    for i in range(2 ** len(arr)):
        subseq = [arr[j] for j in range(len(arr)) if i & 1 << j]
        if len(set(''.join(subseq))) == len(unique_chars):
            max_len = max(max_len, len(''.join(subseq)))
    return max_len
class Solution:

    def maxLength(self, arr: List[str]) -> int:
        max_length = float('-inf')
        prefix_size = [0] * len(arr)
        prefix_size[-1] = len(set(list(arr[-1])))
        for i in range(len(arr) - 2, -1, -1):
            prefix_size[i] = len(set(list(arr[i]))) + prefix_size[i + 1]

        def backtrack(arr, string, index=0):
            nonlocal max_length
            if index < len(prefix_size) and len(string) + prefix_size[index] < max_length:
                return
            if len(string) > max_length and len(string) > 0:
                max_length = len(string)
            if index == len(arr):
                return
            for i in range(index, len(arr)):
                set1 = set(string)
                set2 = set(list(arr[i]))
                union = set1.union(set2)
                if len(union) == len(string) + len(arr[i]):
                    for c in set2:
                        string.append(c)
                    backtrack(arr, string, i + 1)
                    for c in range(len(arr[i])):
                        string.pop()
            return
        backtrack(arr, [], 0)
        return max_length if max_length != float('-inf') else 0
def test_simple_case():
    solution_instance = Solution()
    assert max_length(['un', 'iq', 'ue']) == solution_instance.maxLength(['un', 'iq', 'ue'])
def test_case_with_duplicates():
