class Solution:

    def fillCups(self, amount: List[int]) -> int:
        count = 0
        amount = list(filter(lambda e: e > 0, sorted(amount, reverse=True)))
        while len(amount) == 3:
            count += 1
            amount[0] -= 1
            amount[1] -= 1
            amount = list(filter(lambda e: e > 0, sorted(amount, reverse=True)))
        if len(amount) == 1:
            count += amount[0]
        elif len(amount) == 2:
            count += max(amount)
        return count
