from typing import *
from collections import *
from math import *

def frequent_word(paragraph: str, banned: List[str]) -> str:
    import re
    from collections import Counter
    words = re.findall('\\w+', paragraph.lower())
    freq = Counter([word for word in words if word not in banned])
    return freq.most_common(1)[0][0]
class Solution:

    def mostCommonWord(self, paragraph: str, banned: List[str]) -> str:
        cleaned = []
        for char in paragraph:
            if char >= 'a' and char <= 'z':
                cleaned.append(char)
            elif char >= 'A' and char <= 'Z':
                cleaned.append(char.lower())
            else:
                cleaned.append(' ')
        wordsPara = ''.join(cleaned)
        wordsPara = wordsPara.split()
        counter = Counter(wordsPara)
        banHammer = set()
        for ban in banned:
            banHammer.add(ban.lower())
        for key in banHammer:
            if key in counter:
                del counter[key]
        maxOccurence = -1
        maxWord = None
        for word in counter:
            occurence = counter[word]
            if occurence > maxOccurence:
                maxOccurence = occurence
                maxWord = word
        return maxWord
def test_simple_case():
    solution_instance = Solution()
    assert frequent_word('Bob hit a ball, the hit BALL flew far after it was hit.', ['hit']) == solution_instance.mostCommonWord('Bob hit a ball, the hit BALL flew far after it was hit.', ['hit'])
def test_edge_case():
    solution_instance = Solution()
    assert frequent_word('a.', []) == solution_instance.mostCommonWord('a.', [])
def test_difficult_case():
    solution_instance = Solution()
    assert frequent_word("Let's take the blue pill and ride the bullet train down the rabbit hole.", ['the', 'and', 'the']) == solution_instance.mostCommonWord("Let's take the blue pill and ride the bullet train down the rabbit hole.", ['the', 'and', 'the'])

