class Solution:

    def removeStars(self, s: str) -> str:
        ans = ''
        for i in range(len(s)):
            cur_char = s[i]
            if cur_char == '*':
                ans = ans[:len(ans) - 1]
                continue
            else:
                ans += cur_char
        return ans
def test_simple_case():
