from typing import *
from collections import *
from math import *

def longest_nice_substring(s):
    max_len = 0
    res = ''
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub = s[i:j]
            if all((c.lower() in sub and c.upper() in sub for c in set(sub))):
                if len(sub) > max_len:
                    max_len = len(sub)
                    res = sub
    return res
class Solution:

    def longestNiceSubstring(self, s: str) -> str:

        def helper(i: int, j: int):
            if j - i + 1 < 2:
                return (0, -1)
            hashset = set()
            for k in range(i, j + 1):
                hashset.add(s[k])
            parts = [i - 1]
            for k in range(i, j + 1):
                up = s[k].upper()
                lower = s[k].lower()
                if up not in hashset or lower not in hashset:
                    parts.append(k)
            parts.append(j + 1)
            max_len_pair = (0, -1)
            if len(parts) == 2:
                return (i, j)
            for i in range(len(parts) - 1):
                ni, nj = helper(parts[i] + 1, parts[i + 1] - 1)
                if nj - ni + 1 > max_len_pair[1] - max_len_pair[0] + 1:
                    max_len_pair = (ni, nj)
            return max_len_pair
        lt, rt = helper(0, len(s) - 1)
        return s[lt:rt + 1]
def test_simple_case():
    sol_instance = Solution()
    assert longest_nice_substring('abA') == sol_instance.longestNiceSubstring('abA')
def test_edge_case():
    sol_instance = Solution()
    assert longest_nice_substring('YazaAay') == sol_instance.longestNiceSubstring('YazaAay')
def test_difficult_case():
    sol_instance = Solution()
    assert longest_nice_substring('dDdbAaAB') == sol_instance.longestNiceSubstring('dDdbAaAB')

