def min_squares(n,m):
    if n == m:
        return 1
    else:
        max_side = min(n,m)
        min_side = max_side
        while True:
            num_squares = (n//min_side) * (m//min_side)
            if num_squares > 0:
                return num_squares
            else:
                min_side -= 1

