class Solution:

    def decompressRLElist(self, nums: List[int]) -> List[int]:
        """
        Straightforward basic solution
        Try to optimize via moving to generators
        """
        '\n        Generator based solution.\n        All for the sake of avoiding append.\n        But I`m not sure, how reasonable it is, since append is O(1).\n        '

        def _get_val_sequence(freq, val):
            while freq:
                freq -= 1
                yield val
        '\n        I will try one more approach, to get rid of counter variable.\n        '
        '\n        Not that big of a difference in pperforamnce.\n        '

        def _generate_sequences(nums):
            for i in range(0, len(nums), 2):
                for val in _get_val_sequence(nums[i], nums[i + 1]):
                    yield val
        return list(_generate_sequences(nums))
