from typing import *
from collections import *
from math import *

def checkStraightLine(coordinates):
    if len(coordinates) <= 2:
        return True
    x0, y0 = coordinates[0]
    x1, y1 = coordinates[1]
    for i in range(2, len(coordinates)):
        xi, yi = coordinates[i]
        if (y1 - y0) * (xi - x0) != (yi - y0) * (x1 - x0):
            return False
    return True
class Solution:

    def checkStraightLine(self, coordinates):
        numerator = coordinates[1][1] - coordinates[0][1]
        denominator = coordinates[1][0] - coordinates[0][0]
        if denominator != 0:
            slope = numerator / denominator
            for r in range(2, len(coordinates)):
                nextNumerator = coordinates[r][1] - coordinates[0][1]
                nextDenominator = coordinates[r][0] - coordinates[0][0]
                if nextDenominator == 0:
                    return False
                nextSlope = nextNumerator / nextDenominator
                if nextSlope != slope:
                    return False
            return True
        else:
            for r in range(2, len(coordinates)):
                nextDenominator = coordinates[r][0] - coordinates[0][0]
                if nextDenominator != 0:
                    return False
            return True
