def averageWaitingTime(customers: List[List[int]]) -> float:
    wait_time = 0
    start_time = 0
    for i in range(len(customers)):
        if start_time <= customers[i][0]:
            start_time = customers[i][0] + customers[i][1]
            wait_time += customers[i][1]
