class Solution:

    def maxHeight(self, cuboids: List[List[int]]) -> int:
        cuboids = sorted([sorted(cub) for cub in cuboids], reverse=True)
        ok = lambda x, y: x[0] >= y[0] and x[1] >= y[1] and (x[2] >= y[2])
        n = len(cuboids)
        dp = [cu[2] for cu in cuboids]
        ans = max(dp)
        for i in range(1, n):
            for j in range(i):
                if ok(cuboids[j], cuboids[i]):
                    dp[i] = max(dp[i], dp[j] + cuboids[i][2])
            ans = max(ans, dp[i])
        return ans
def test_simple_case():
    solution_instance = Solution()
