def getCompetitiveSubsequence(nums: List[int], k: int) -> List[int]:
    stack = []
    for i, num in enumerate(nums):
        while stack and len(nums) - i + len(stack) > k and stack[-1] > num:
            stack.pop()
        if len(stack) < k:
            stack.append(num)
    return stack

