    return stack
class Solution:

    def __init__(self):
        self.stack = []
        self.toRemove = 0

    def mostCompetitive(self, nums: List[int], k: int) -> List[int]:
        self.stack.append(nums[0])
        self.toRemove = len(nums) - k
        for i in range(1, len(nums)):
            while self.stack and self.toRemove > 0 and (self.stack[-1] > nums[i]):
                self.toRemove -= 1
                self.stack.pop()
            self.stack.append(nums[i])
        while self.toRemove > 0 or len(self.stack) > k:
            self.toRemove -= 1
            self.stack.pop()
        return self.stack
def test_simple_case():
    solution_instance = Solution()
    assert getCompetitiveSubsequence([1, 5, 2, 1, 2, 3], 3) == solution_instance.mostCompetitive([1, 5, 2, 1, 2, 3], 3)
def test_edge_case():
    solution_instance = Solution()
    assert getCompetitiveSubsequence([2, 4, 3, 3, 5, 4, 9, 6], 4) == solution_instance.mostCompetitive([2, 4, 3, 3, 5, 4, 9, 6], 4)
def test_difficult_case():
    solution_instance = Solution()
    assert getCompetitiveSubsequence([3, 5, 2, 6], 2) == solution_instance.mostCompetitive([3, 5, 2, 6], 2)

