def min_subarray(nums, target):
    if not nums:
        return 0
    start = end = 0
    cur_sum = 0
    min_len = float('inf')
    while end < len(nums):
        while cur_sum < target and end < len(nums):
            cur_sum += nums[end]
            end += 1
        while cur_sum >= target and start <= end:
            min_len = min(min_len, end - start)
            cur_sum -= nums[start]
            start += 1
    return min_len if min_len != float('inf') else 0

