def nearestValidPoint(x: int, y: int, points: List[List[int]]) -> int:
    min_dist = float('inf')
    index = -1
    for i in range(len(points)):
        point = points[i]
        if point[0] == x or point[1] == y:
            dist = abs(point[0] - x) + abs(point[1] - y)
            if dist < min_dist:
                min_dist = dist
                index = i
    return index
class Solution:

    def nearestValidPoint(self, x: int, y: int, points: List[List[int]]) -> int:
        valid_pair = []
        distance_holder = (9999, 9999)

        def __calculate_manhattan(x, y, x_point, y_point):
            return abs(x - x_point) + abs(y - y_point)
        for idx, pair in enumerate(points):
            x_point, y_point = pair
            if x == x_point or y == y_point:
                distance = __calculate_manhattan(x, y, x_point, y_point)
                if distance <= distance_holder[1]:
                    if distance == distance_holder[1]:
                        distance_holder = (min(distance_holder[0], idx), distance)
                    else:
                        distance_holder = (idx, distance)
                valid_pair.append(distance_holder)
        if not valid_pair:
            return -1
        else:
            return distance_holder[0]
def test_simple_case():
    solution_instance = Solution()
    assert nearestValidPoint(3, 4, [[1, 2], [3, 1], [2, 4], [2, 3], [4, 4]]) == solution_instance.nearestValidPoint(3, 4, [[1, 2], [3, 1], [2, 4], [2, 3], [4, 4]])
