class Solution:

    def minWastedSpace(self, packages: List[int], boxes: List[List[int]]) -> int:
        acc = [0] + [*accumulate(packages)]
        packages.sort()
        ans = float('inf')
        for box in boxes:
            tmp = 0
            box.sort()
            start = 0
            for b in box:
                loc = bisect.bisect(packages, b)
                if loc == 0:
                    continue
                tmp += b * (loc - start) - (acc[loc] - acc[start])
                if loc == len(packages):
                    ans = min(ans, tmp)
                    break
                start = loc
        return ans % (10 ** 9 + 7) if ans != float('inf') else -1
def test_simple_case():
    packages = [2, 3, 5]
    boxes = [[4, 8]]
    assert min_wasted_space(packages, boxes) == Solution().minWastedSpace(packages, boxes)
def test_edge_case():
    packages = [1, 2, 3, 4, 5]
    boxes = [[3, 5, 6], [1, 6], [5, 6, 7]]
    assert min_wasted_space(packages, boxes) == Solution().minWastedSpace(packages, boxes)
def test_difficult_case():
    packages = [2, 3, 5, 7, 11]
    boxes = [[1, 2], [4, 8], [6, 10]]
    assert min_wasted_space(packages, boxes) == Solution().minWastedSpace(packages, boxes)

