class Solution:

    def validMountainArray(self, arr: List[int]) -> bool:
        up = [None, None]
        down = [None, None]
        for idx in range(len(arr) - 1):
            if arr[idx] == arr[idx + 1]:
                return False
            elif arr[idx] < arr[idx + 1] and (not up[0]):
                up[0] = 1
                down[0] = 0
            elif arr[idx] < arr[idx + 1] and down[1]:
                return False
            elif arr[idx] > arr[idx + 1] and up[0]:
                down[1] = 1
                up[1] = 0
            elif arr[idx] > arr[idx + 1] and (not down[1]):
                return False
        if up[0] == 1 and up[1] == None or (up[0] == None and up[1] == None):
            return False
        else:
            return True
def test_simple_case():
    solution_instance = Solution()
