class Solution:

    def checkIfPangram(self, sentence: str) -> bool:
        occurred = 0
        for i in sentence:
            temp = ord(i) - ord('a')
            occurred |= 1 << temp
        if occurred == (1 << 26) - 1:
            return True
        return False
def test_simple_pangram_case():
