def check_double(arr):
    for i in range(len(arr)):
        for j in range(len(arr)):
            if i != j and arr[i] == 2 * arr[j]:
                return True
    return False
class Solution:

    def checkIfExist(self, arr: List[int]) -> bool:
        arr.sort()
        n = len(arr)
        for i in range(n):
            k = arr[i]
            if k < 0:
                lo = 0
                hi = i
                while lo < hi:
                    mid = (lo + hi) // 2
                    if arr[mid] == 2 * k:
                        return True
                    elif arr[mid] < 2 * k:
                        lo = mid + 1
                    else:
                        hi = mid
            else:
                lo = i + 1
                hi = n
                while lo < hi:
                    mid = (lo + hi) // 2
                    if arr[mid] == k * 2:
                        return True
                    elif arr[mid] < k * 2:
                        lo = mid + 1
                    else:
                        hi = mid
        return False
def test_simple_case():
    solution_instance = Solution()
    arr = [10, 2, 5, 3]
    assert check_double(arr) == solution_instance.checkIfExist(arr)
def test_edge_case():
    solution_instance = Solution()
    arr = [-2, 1, 2, 4]
    assert check_double(arr) == solution_instance.checkIfExist(arr)
def test_difficult_case():
    solution_instance = Solution()
    arr = [3, 6, 1, 2, 4]
    assert check_double(arr) == solution_instance.checkIfExist(arr)

