class Solution:

    def reverseString(self, s: List[str]) -> None:
        """
        Do not return anything, modify s in-place instead.
        """
        return self.reverseStringOptimal(s)

    def reverseStringOptimal(self, string):
        if not string:
            return string
        left, right = (0, len(string) - 1)
        while left < right:
            string[left], string[right] = (string[right], string[left])
            left += 1
            right -= 1
        return string

    def reverseStringWithNewList(self, string):
        if not string:
            return string
        newList = [0] * len(string)
        j = 0
        for i in reversed(range(len(string))):
            newList[i] = string[j]
            j += 1
        return newList

    def reverseStringWithListCompression(self, string):
        if not string:
            return string
        return [string[i] for i in reversed(range(len(string)))]

    def reversedStringWithReverse(self, string):
        string.reverse()
        return string or string[::-1]
def test_simple_case():
    solution_instance = Solution()
    s = ['h', 'e', 'l', 'l', 'o']
    reverseString(s)
    assert s == solution_instance.reverseStringOptimal(['h', 'e', 'l', 'l', 'o'])
