from typing import *
from collections import *
from math import *

def smallestString(k: int, s: str) -> str:
    if k >= len(s):
        return s
    return min((s[i:k] + s[k:] for i in range(len(s) - k + 1)))
class Solution:

    def orderlyQueue(self, s: str, k: int) -> str:
        if len(set(s)) == 1:
            return s
        if k != 1:
            return ''.join(sorted(s))
        Len = len(s)
        Min = '{'
        Min_idxs = dict()
        for i in range(Len):
            if Min > s[i]:
                Min = s[i]
                Min_idxs = {i: s[i]}
            elif Min == s[i]:
                Min_idxs[i] = s[i]
        step = 1
        while len(Min_idxs) != 1 and step < Len:
            Min = '{'
            for idx in Min_idxs:
                comp_idx = (idx + step) % Len
                if Min > s[comp_idx]:
                    Min = s[comp_idx]
                Min_idxs[idx] = s[comp_idx]
            del_list = [k for k, v in Min_idxs.items() if v != Min]
            for idx in del_list:
                Min_idxs.pop(idx)
            step += 1
        split_idx = list(Min_idxs.keys())[0]
        return s[split_idx:] + s[:split_idx]
def test_simple_case():
    solution_instance = Solution()
    assert smallestString(2, 'cba') == solution_instance.orderlyQueue('cba', 2)
def test_single_move_case():
    solution_instance = Solution()
    assert smallestString(1, 'cba') == solution_instance.orderlyQueue('cba', 1)
def test_no_changes_case():
    solution_instance = Solution()
    assert smallestString(3, 'a') == solution_instance.orderlyQueue('a', 3)

