def square_triple(n):
    results = []
    for a in range(1, n + 1):
        for b in range(a, n + 1):
            c_squared = a ** 2 + b ** 2
            c = int(c_squared ** 0.5)
            if c ** 2 == c_squared and c <= n:
                results.append((a, b, c))
    return len(results)
class Solution:
    cache = {1: 0, 2: 0, 3: 0, 4: 0}

    def countTriples(self, n: int) -> int:
        if n in self.cache.keys():
            return self.cache[n]
        else:
            self.cache[n] = self.findTriples(n) + self.countTriples(n - 1)
            return self.cache[n]

    def findTriples(self, n: int) -> int:
        count = 0
        for a in range(0, n):
            for b in range(a, n):
                if self.isSquareTriple(a, b, n):
                    count += 1
        return count * 2

    def isSquareTriple(self, a: int, b: int, c: int) -> bool:
        if a * a + b * b == c * c:
            return True
        else:
            return False
def test_simple_case():
    solution_instance = Solution()
    assert square_triple(5) == solution_instance.countTriples(5)
def test_edge_case():
    solution_instance = Solution()
    assert square_triple(10) == solution_instance.countTriples(10)
def test_difficult_case():
    solution_instance = Solution()
    assert square_triple(20) == solution_instance.countTriples(20)

