def lexicalOrder(n):
    cur = 1
    for i in range(n):
        print(cur)
        if cur * 10 <= n:
            cur *= 10
        elif cur % 10 != 9 and cur + 1 <= n:
            cur += 1
        else:
            while cur // 10 % 10 == 9:
                cur //= 10
            cur = cur // 10 + 1
class Solution:

    def lexicalOrder(self, n: int) -> List[int]:
        r = []
        a = 1
        while a <= n and a < 10:
            r.append(a)
            b = a * 10
            while b <= n and b < (a + 1) * 10:
                r.append(b)
                c = b * 10
                while c <= n and c < (b + 1) * 10:
                    r.append(c)
                    d = c * 10
                    while d <= n and d < (c + 1) * 10:
                        r.append(d)
                        e = d * 10
                        while e <= n and e < (d + 1) * 10:
                            r.append(e)
                            e += 1
                        d += 1
                    c += 1
                b += 1
            a += 1
        return r
def test_simple_case():
    solution_instance = Solution()
    assert lexicalOrder(13) == solution_instance.lexicalOrder(13)
