def maxPizza(slices):

    def helper(slices):
        n = len(slices)
        dp = [[0 for i in range((n + 1) // 2 + 1)] for j in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, (n + 1) // 2 + 1):
                if i == 1:
                    dp[i][j] = slices[i - 1]
                elif j == 1:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 2][j - 1] + slices[i - 1])
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 2][j - 1] + slices[i - 1])
        return dp[n][(n + 1) // 2]
    return (helper(slices[:-1]), helper(slices[1:]))
class Solution:

    def maxSizeSlices(self, slices: List[int]) -> int:

        def solve(index, end, slices, n, dic):
            key = (index, n)
            if key in dic:
                return dic[key]
            else:
                if n == 0 or index > end:
                    return 0
                include = slices[index] + solve(index + 2, end, slices, n - 1, dic)
                exclude = solve(index + 1, end, slices, n, dic)
                dic[key] = max(include, exclude)
                return dic[key]
        l = len(slices)
        dic1 = {}
        dic2 = {}
        c1 = solve(0, l - 2, slices, l // 3, dic1)
        c2 = solve(1, l - 1, slices, l // 3, dic2)
        return max(c1, c2)
def test_simple_case():
    solution_instance = Solution()
    result1 = maxPizza([1, 2, 3, 4, 5, 6])
    result2 = solution_instance.maxSizeSlices([1, 2, 3, 4, 5, 6])
    assert max(result1) == result2
def test_edge_case():
    solution_instance = Solution()
    result1 = maxPizza([8, 9, 8, 6, 1, 1, 8, 8, 1, 9])
    result2 = solution_instance.maxSizeSlices([8, 9, 8, 6, 1, 1, 8, 8, 1, 9])
    assert max(result1) == result2
def test_difficult_case():
    solution_instance = Solution()
    result1 = maxPizza([4, 1, 2, 5, 8, 3, 1, 9, 7])
    result2 = solution_instance.maxSizeSlices([4, 1, 2, 5, 8, 3, 1, 9, 7])
    assert max(result1) == result2

