from typing import *
from collections import *
from math import *

def numberOfArithmeticSlices(nums):
    count = 0
    for i in range(len(nums) - 2):
        diff = nums[i + 1] - nums[i]
        for j in range(i + 2, len(nums)):
            if nums[j] - nums[j - 1] == diff:
                count += 1
            else:
                break
    return count
class Solution:

    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        if len(nums) < 3:
            return 0
        n = len(nums)
        getdiff = lambda i, j: nums[i] - nums[j]
        getPossibilities = lambda l: l * (l + 1) // 2
        checkMinSubArrayLength = lambda i, j: abs(i - j) >= 2
        i, j = (0, 1)
        diff = getdiff(j, i)
        cnt = 0
        while i < n and j < n:
            if checkMinSubArrayLength(i, j):
                if diff != getdiff(j, j - 1):
                    diff = getdiff(j, j - 1)
                    i = j - 1
                    continue
                length = 3
                j += 1
                while j < n:
                    if diff == getdiff(j, j - 1):
                        length += 1
                        j += 1
                    else:
                        diff = getdiff(j, j - 1)
                        i = j - 1
                        break
                cnt += getPossibilities(length - 2)
            else:
                j += 1
        return cnt
def test_simple_case():
    solution_instance = Solution()
    assert numberOfArithmeticSlices([1, 3, 5, 7, 9]) == solution_instance.numberOfArithmeticSlices([1, 3, 5, 7, 9])
def test_edge_case():
    solution_instance = Solution()
    assert numberOfArithmeticSlices([5, 5, 5, 5]) == solution_instance.numberOfArithmeticSlices([5, 5, 5, 5])
def test_difficult_case():
