from typing import *
from collections import *
from math import *

def numWaterBottles(numBottles: int, numExchange: int) -> int:
    full_bottles = numBottles
    empty_bottles = 0
    total_drinks = 0
    while full_bottles > 0:
        total_drinks += full_bottles
        new_full_bottles = (full_bottles + empty_bottles) // numExchange
        empty_bottles = (full_bottles + empty_bottles) % numExchange
        full_bottles = new_full_bottles
    return total_drinks
class Solution:

    def numWaterBottles(self, numBottles: int, numExchange: int) -> int:

        def helper(full, empty, drank):
            if full + empty < numExchange:
                return drank + full
            if full:
                empty += full
            new = empty // numExchange
            remaining_empt = empty - new * numExchange
            return helper(new, remaining_empt, drank + full)
        return helper(numBottles, 0, 0)
def test_simple_case():
    solution_instance = Solution()
    assert numWaterBottles(9, 3) == solution_instance.numWaterBottles(9, 3)
def test_edge_case():
    solution_instance = Solution()
    assert numWaterBottles(15, 4) == solution_instance.numWaterBottles(15, 4)
def test_difficult_case():
    solution_instance = Solution()
    assert numWaterBottles(5, 5) == solution_instance.numWaterBottles(5, 5)

