def fib(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 2:
        return 1
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]
def fibonacci(n):
    """Return the nth Fibonacci number."""
    r = [-1] * (n + 1)
    return fibonacci_helper(n, r)
def fibonacci_helper(n, r):
    """Return the nth Fibonacci number and store the ith Fibonacci number in
    r[i] for 0 <= i <= n."""
    if r[n] >= 0:
        return r[n]
    if n == 0 or n == 1:
        q = n
    else:
        q = fibonacci_helper(n - 1, r) + fibonacci_helper(n - 2, r)
    r[n] = q
    return q
def test_simple_case():
    assert fib(1) == fibonacci(1)
def test_mid_range_case():
    assert fib(10) == fibonacci(10)
def test_large_case():
    assert fib(30) == fibonacci(30)

