def maxIceCream(costs, coins):
    count = [0] * 100001
    for cost in costs:
        count[cost] += 1

    max_ice_creams = 0
    for i in range(1, 100001):
        if coins < i:
            break

        max_ice_creams += min(count[i], coins//i)
        coins -= i * min(count[i], coins//i)

    return max_ice_creams

