class Solution:

    def mergeSimilarItems(self, items1: List[List[int]], items2: List[List[int]]) -> List[List[int]]:
        hashmap = {}
        for items in items1:
            if hashmap.get(items[0]) is not None:
                hashmap[items[0]] += items[1]
            else:
                hashmap[items[0]] = items[1]
        for items in items2:
            if hashmap.get(items[0]) is not None:
                hashmap[items[0]] += items[1]
            else:
                hashmap[items[0]] = items[1]
        result = [k for k in hashmap.keys()]
        self.mergeSort(result)
        return [[k, hashmap[k]] for k in result]

    def mergeSort(self, arr):
        if len(arr) > 1:
            mid = len(arr) // 2
            left = arr[:mid]
            right = arr[mid:]
            self.mergeSort(left)
            self.mergeSort(right)
            i, j, k = (0, 0, 0)
            while i < len(left) and j < len(right):
                if left[i] < right[j]:
                    arr[k] = left[i]
                    i += 1
                    k += 1
                else:
                    arr[k] = right[j]
                    j += 1
                    k += 1
            while i < len(left):
                arr[k] = left[i]
                i += 1
                k += 1
            while j < len(right):
                arr[k] = right[j]
                j += 1
                k += 1
def test_simple_case():
    solution_instance = Solution()
    assert combine_items([[1, 3], [2, 2]], [[3, 5], [2, 4]]) == solution_instance.mergeSimilarItems([[1, 3], [2, 2]], [[3, 5], [2, 4]])
def test_edge_case():
    solution_instance = Solution()
    assert combine_items([[1, 1], [2, 2], [3, 3]], [[3, 3], [2, 2], [1, 1]]) == solution_instance.mergeSimilarItems([[1, 1], [2, 2], [3, 3]], [[3, 3], [2, 2], [1, 1]])
def test_difficult_case():
    solution_instance = Solution()
    assert combine_items([[10, 5], [20, 10], [30, 15]], [[20, 4], [10, 8], [30, 6]]) == solution_instance.mergeSimilarItems([[10, 5], [20, 10], [30, 15]], [[20, 4], [10, 8], [30, 6]])

