from typing import *
from collections import *
from math import *

def max_subsequence(p: str, s: str, removable: List[int]) -> int:
    left = 0
    right = len(removable)
    while left <= right:
        mid = (left + right) // 2
        indices_to_remove = set(removable[:mid])
        i, j = (0, 0)
        while i < len(p) and j < len(s):
            if p[i] == s[j] and i not in indices_to_remove:
                j += 1
            i += 1
        if j == len(s):
            left = mid + 1
        else:
            right = mid - 1
    return right
class Solution:

    def maximumRemovals(self, s: str, p: str, removable: List[int]) -> int:
        left, right = (0, len(removable))
        lenS, lenP = (len(s), len(p))

        def checkGood(target):
            seen = set(removable[:target])
            if target == 0:
                return True
            sIndx, pIndx = (0, 0)
            while sIndx < lenS and pIndx < lenP:
                if sIndx in seen:
                    pass
                elif s[sIndx] == p[pIndx]:
                    pIndx += 1
                sIndx += 1
            return pIndx == lenP
        while left <= right:
            mid = left + (right - left) // 2
            if checkGood(mid):
                left = mid + 1
            else:
                right = mid - 1
        return right
def test_simple_case():
    s = 'abcdebc'
    p = 'abc'
    removable = [3, 1, 0]
    instance = Solution()
    assert max_subsequence(p, s, removable) == instance.maximumRemovals(s, p, removable)
def test_edge_case():
    s = 'abcebdde'
    p = 'abe'
    removable = [5, 3, 2, 1, 0]
    instance = Solution()
    assert max_subsequence(p, s, removable) == instance.maximumRemovals(s, p, removable)
def test_difficult_case():
    s = 'debeacbbcd'
    p = 'debc'
    removable = [1, 4, 8, 10, 2, 3, 5, 9]
    instance = Solution()
    assert max_subsequence(p, s, removable) == instance.maximumRemovals(s, p, removable)

