from typing import *
from collections import *
from math import *

def rounds_completed(string, k):
    rounds = 0
    while len(string) > k:
        groups = [string[i:i + k] for i in range(0, len(string), k)]
        last_group_len = len(groups[-1])
        if last_group_len < k:
            groups[-2] += groups[-1]
            groups.pop()
        string = ''.join((str(sum((int(digit) for digit in group))) for group in groups))
        rounds += 1
    return rounds
class Solution:

    def digitSum(self, s: str, k: int) -> str:
        if len(s) > k:
            op = []
            i = 0
            while i < len(s) - k:
                op.append(s[i:i + k])
                i += k
            op.append(s[i:])
            fl_op = ''
            for i in op:
                sm = 0
                for j in i:
                    sm += int(j)
                fl_op += str(sm)
            if len(fl_op) > k:
                return self.digitSum(fl_op, k)
            else:
                return fl_op
        return s
def test_simple_case():
    solution_instance = Solution()
    assert rounds_completed('111112222233334444', 4) == len(solution_instance.digitSum('111112222233334444', 4))
def test_edge_case():
    solution_instance = Solution()
    assert rounds_completed('00000000', 3) == len(solution_instance.digitSum('00000000', 3))
def test_difficult_case():
    solution_instance = Solution()
    assert rounds_completed('999998987654', 2) == len(solution_instance.digitSum('999998987654', 2))

