def subarray(nums, k, threshold):
    curr_sum = sum(nums[:k])
    count = 0
    for i in range(k, len(nums)):
        if curr_sum < threshold:
            curr_sum += nums[i] - nums[i-k]
        if curr_sum >= threshold*k:
            count += 1
    return count if count > 0 else -1

