def unlock_safe(n, k, password):
    combinations = set()
    def helper(curr):
        if len(curr) == n:
            combinations.add(curr)
            return
        for i in range(k):
            helper(curr + str(i))
    helper("0" * (n - 1))
    curr = "0" * (n - 1)
    count = n - 1
    for digit in password:
        curr += digit
        if curr not in combinations:
            curr = curr[1:]
        else:
            count += 1
    return count

