class Solution:

    def crackSafe(self, n: int, k: int) -> str:

        def dfs(path, visitedCombinations, targetNumVisited, combos):
            if len(visitedCombinations) == targetNumVisited:
                combos.append(''.join([str(x) for x in path]))
                return True
            if n > 1:
                lastDigits = ''.join([str(x) for x in path[-(n - 1):]])
            else:
                lastDigits = ''
            for i in range(k):
                path.append(i)
                newPwd = f'{lastDigits}{i}'
                if len(newPwd) != n:
                    if dfs(path, visitedCombinations, targetNumVisited, combos):
                        return True
                if len(newPwd) == n and newPwd not in visitedCombinations:
                    visitedCombinations[newPwd] = 1
                    if dfs(path, visitedCombinations, targetNumVisited, combos):
                        return True
                    del visitedCombinations[newPwd]
                path.pop()
            return False
        visitedCombinations = {}
        combos = []
        dfs([], visitedCombinations, k ** n, combos)
        return combos[0]
def test_simple_case():
    solution_instance = Solution()
    assert unlock_safe(1, 2, '01100') == len(solution_instance.crackSafe(1, 2))
def test_edge_case():
    solution_instance = Solution()
    assert unlock_safe(2, 2, '0011001122') == len(solution_instance.crackSafe(2, 2))
def test_difficult_case():
    solution_instance = Solution()
    assert unlock_safe(2, 3, '02022211200') == len(solution_instance.crackSafe(2, 3))

