def equal_typed_strings(t: str, s: str) -> bool:
    def build_string(string):
        typed = []
        for char in string:
            if char != '#':
                typed.append(char)
            elif typed:
                typed.pop()
        return ''.join(typed)
    return build_string(t) == build_string(s)

