def equal_typed_strings(t: str, s: str) -> bool:

    def build_string(string):
        typed = []
        for char in string:
            if char != '#':
                typed.append(char)
            elif typed:
                typed.pop()
        return ''.join(typed)
    return build_string(t) == build_string(s)
class Solution:

    def backspaceCompare(self, string: str, target: str) -> bool:
        return self.solOne(string, target)
        return self.solTwo(string, target)

    def solOne(self, string, target):
        stringLength = len(string) - 1
        targetLength = len(target) - 1
        while stringLength >= 0 or targetLength >= 0:
            skipString = 0
            skipTarget = 0
            while stringLength >= 0:
                if string[stringLength] == '#':
                    skipString += 1
                    stringLength -= 1
                elif skipString > 0:
                    stringLength -= 1
                    skipString -= 1
                else:
                    break
            while targetLength >= 0:
                if target[targetLength] == '#':
                    skipTarget += 1
                    targetLength -= 1
                elif skipTarget > 0:
                    targetLength -= 1
                    skipTarget -= 1
                else:
                    break
            if (stringLength >= 0) != (targetLength >= 0):
                return False
            if stringLength >= 0 and targetLength >= 0 and (string[stringLength] != target[targetLength]):
                return False
            stringLength -= 1
            targetLength -= 1
        return True

    def solTwo(self, string, target):
        stackOne, stackTwo = ([], [])
        for i in string:
            if i == '#':
                if stackOne:
                    stackOne.pop()
            else:
                stackOne.append(i)
        for i in target:
            if i == '#':
                if stackTwo:
                    stackTwo.pop()
            else:
                stackTwo.append(i)
        return stackOne == stackTwo
def test_simple_case():
    solution_instance = Solution()
    assert equal_typed_strings('ab#c', 'ad#c') == solution_instance.backspaceCompare('ab#c', 'ad#c')
def test_edge_case():
    solution_instance = Solution()
    assert equal_typed_strings('ab##', 'c#d#') == solution_instance.backspaceCompare('ab##', 'c#d#')
def test_difficult_case():
    solution_instance = Solution()
    assert equal_typed_strings('a#c', 'b') == solution_instance.backspaceCompare('a#c', 'b')

