def findEqualPairs(grid):
    pairs = []
    n = len(grid)
    for i in range(n):
        for j in range(n):
            for m in range(i, n):
                start = j if i == m else 0
                for k in range(start, n):
                    if i != m or j < k:
                        if grid[i][j] == grid[m][k]:
                            pairs.append((i,j))
                            pairs.append((m,k))
    return pairs

