def visitedSectors(n, rounds):
    visited = []
    start = rounds[0]
    end = rounds[-1]
    if end > start:
        visited = [i for i in range(start, end + 1)]
    else:
        visited = [i for i in range(start, n + 1)] + [i for i in range(1, end + 1)]
    return visited
class Solution:

    def mostVisited(self, n: int, rounds: List[int]) -> List[int]:
        hash_map = {}
        for i in range(0, len(rounds) - 1):
            if i == 0:
                start = rounds[i]
            elif rounds[i] == n:
                start = 1
            else:
                start = rounds[i] + 1
            end = rounds[i + 1]
            if start <= end:
                for i in range(start, end + 1):
                    if i in hash_map:
                        hash_map[i] += 1
                    else:
                        hash_map[i] = 1
            else:
                for i in range(start, n + 1):
                    if i in hash_map:
                        hash_map[i] += 1
                    else:
                        hash_map[i] = 1
                for i in range(1, end + 1):
                    if i in hash_map:
                        hash_map[i] += 1
                    else:
                        hash_map[i] = 1
        k = list(hash_map.keys())
        v = list(hash_map.values())
        ans = []
        m = -1
        i = 0
        j = 0
        while i < len(k) and j < len(v):
            if len(ans) == 0:
                ans.append(k[i])
                m = v[j]
            elif m < v[j]:
                ans = []
                ans.append(k[i])
                m = v[j]
            elif m == v[j]:
                ans.append(k[i])
            i += 1
            j += 1
        ans = sorted(ans)
        return ans
def test_simple_case():
    solution_instance = Solution()
    result1 = visitedSectors(4, [1, 3, 1, 2])
    result2 = solution_instance.mostVisited(4, [1, 3, 1, 2])
    assert sorted(result1) == sorted(result2)
def test_edge_case():
    solution_instance = Solution()
    result1 = visitedSectors(2, [2, 1, 2])
    result2 = solution_instance.mostVisited(2, [2, 1, 2])
    assert sorted(result1) == sorted(result2)
def test_difficult_case():
    solution_instance = Solution()
    result1 = visitedSectors(7, [1, 3, 5, 7])
    result2 = solution_instance.mostVisited(7, [1, 3, 5, 7])
    assert sorted(result1) == sorted(result2)

