            graph.add_vertex(u)
        if v not in graph:
            graph.add_vertex(v)
        graph.add_undirected_edge(u, v)
    visited = set()
    for vertex in graph:
        if vertex not in visited:
            if is_cycle_present(vertex, visited):
                assert True
    nodes = {i: False for i in range(3)}
