        j = binary_search(arr, key, 0, i - 1)
        arr = arr[:j] + [key] + arr[j:i] + arr[i + 1:]
    return arr
def binary_search(arr, key, start, end):
    if start == end:
        if arr[start] > key:
            return start
        else:
            return start + 1
    elif start > end:
        return start
    else:
        mid = (start + end) // 2
        if arr[mid] > key:
            return binary_search(arr, key, start, mid - 1)
        else:
