    assert binary_insertion_sort([1, 2, 3, 4]) == binary_insertion_sort([1, 2, 3, 4])
def test_reverse_sorted_case():
    assert binary_insertion_sort([4, 3, 2, 1]) == binary_insertion_sort([4, 3, 2, 1])

