def count_stars(s):
    pairs = s.split('|')[1:-1]
    count = 0
    for i in range(len(pairs) // 2):
        pair = pairs[i * 2:i * 2 + 2]
        count += pair[1].count('*') - (pair[0].count('*') + pair[1].count('*') - len(pair[1]))
    return count
class Solution:

    def countAsterisks(self, s: str) -> int:
        count = 0
        if '|' not in s:
            count += s.count('*')
        while '|' in s:
            split_list = s.split('|', 2)
            count += split_list[0].count('*')
            s = split_list[2]
            if '|' not in split_list[2]:
                count += split_list[2].count('*')
        return count
def test_simple_case():
    solution_instance = Solution()
    assert count_stars('a|b*****|c') == solution_instance.countAsterisks('a|b*****|c')
