    solution_instance = Solution()
    assert count_stars('*****|*****|*****|s|') == solution_instance.countAsterisks('*****|*****|*****|s|')
def test_difficult_case():
    solution_instance = Solution()
    assert count_stars('||*|*|*') == solution_instance.countAsterisks('||*|*|*')

