def is_valid_path(matrix):
    def is_valid_string(s):
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif len(stack) > 0 and stack[-1] == '(':
                stack.pop()
            else:
                return False
        return len(stack) == 0

    m, n = len(matrix), len(matrix[0])
    dp = [[False] * n for _ in range(m)]
    dp[0][0] = matrix[0][0] == '('

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] and matrix[i][0] == '('

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] and matrix[0][j] == ')'

    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == '(':
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i][j-1]

            if dp[i][j]:
                s = ""
                for k in range(i+1):
                    s += matrix[k][j]
                for k in range(j+1):
                    s += matrix[i][k]

                dp[i][j] = is_valid_string(s)

    return dp[-1][-1]

