from typing import *
from collections import *
from math import *

def alice_wins(piles):
    size = len(piles)
    if size % 2 == 0:
        return True
    else:
        return False
class Solution:

    def stoneGame(self, piles: List[int]) -> bool:
        n = len(piles)
        memo = [[0] * n for i in range(n)]

        def dp(i, j):
            if i > j:
                return 0
            if memo[i][j] != 0:
                return memo[i][j]
            player_turn = (n - (j - i)) % 2
            if player_turn == 1:
                memo[i][j] = max(piles[i] + dp(i + 1, j), piles[j] + dp(i, j - 1))
            else:
                memo[i][j] = min(-piles[i] + dp(i + 1, j), -piles[j] + dp(i, j - 1))
            return memo[i][j]
        return dp(0, n - 1) > 0
def test_even_piles():
    solution_instance = Solution()
    assert alice_wins([1, 2, 3, 4]) == solution_instance.stoneGame([1, 2, 3, 4])
def test_odd_piles():
    solution_instance = Solution()
    assert alice_wins([1, 2, 3]) == solution_instance.stoneGame([1, 2, 3])
def test_single_pile():
    solution_instance = Solution()
    assert alice_wins([5]) == solution_instance.stoneGame([5])

