from typing import *
from collections import *
from math import *

def palindrome(s):
    s = ''.join(filter(str.isalnum, s)).lower()
    return s == s[::-1]
class Solution:

    def isPalindrome(self, string: str) -> bool:
        return self.isPalindromeOptimal(string)

    def isPalindromeOptimal(self, string):
        if not string:
            return True
        left, right = (0, len(string) - 1)
        while left < right:
            while left < right and (not self.isAlphaNum(string[left])):
                left += 1
            while right > left and (not self.isAlphaNum(string[right])):
                right -= 1
            if string[left].lower() != string[right].lower():
                return False
            left, right = (left + 1, right - 1)
        return True

    def isAlphaNum(self, char):
        return ord('A') <= ord(char) <= ord('Z') or ord('a') <= ord(char) <= ord('z') or ord('0') <= ord(char) <= ord('9')

    def isPalindromeByList(self, string):
        if not string:
            return True
        newStringList = list()
        for char in string:
            if char.isalnum():
                newStringList.append(char.lower())
        left, right = (0, len(newStringList) - 1)
        while left < right:
            if newStringList[left] != newStringList[right]:
                return False
            left += 1
            right -= 1
        return True
def test_simple_case():
    solution_instance = Solution()
    assert palindrome('A man, a plan, a canal: Panama') == solution_instance.isPalindromeOptimal('A man, a plan, a canal: Panama')
def test_edge_case():
    solution_instance = Solution()
    assert palindrome('') == solution_instance.isPalindromeOptimal('')
def test_difficult_case():
    solution_instance = Solution()
    assert palindrome('race a car') == solution_instance.isPalindromeOptimal('race a car')

