    return num_str == num_str[::-1]
def base_conversion(n, a, b):
    """
    Convert number n from base a to base b.
    """
    res = ''
    while n > 0:
        res = str(n % b) + res
        n //= b
    return res
def sum_of_smallest_k_mirror_numbers(n, k):
    mirror_nums = []
    num = 1
    while len(mirror_nums) < n:
        if is_k_mirror(num, k):
            mirror_nums.append(num)
        num += 1
