def heapify(arr, n, i):
    largest = i
    l = 2 * i + 1
    r = 2 * i + 2
    if l < n and arr[i] < arr[l]:
        largest = l
    if r < n and arr[largest] < arr[r]:
        largest = r
    if largest != i:
        arr[i], arr[largest] = (arr[largest], arr[i])
        heapify(arr, n, largest)
def heapSort(arr):
    n = len(arr)
    for i in range(n, -1, -1):
        heapify(arr, n, i)
    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = (arr[0], arr[i])
        heapify(arr, i, 0)
def left(i):
    return 2 * i + 1
def right(i):
    return 2 * i + 2
def heapSize(A):
    return len(A) - 1
def MaxHeapify(A, i):
    l = left(i)
    r = right(i)
    if l <= heapSize(A) and A[l] > A[i]:
        largest = l
    else:
        largest = i
    if r <= heapSize(A) and A[r] > A[largest]:
        largest = r
    if largest != i:
        A[i], A[largest] = (A[largest], A[i])
        MaxHeapify(A, largest)
def BuildMaxHeap(A):
    for i in range(int(heapSize(A) / 2) - 1, -1, -1):
        MaxHeapify(A, i)
def HeapSort(A):
    BuildMaxHeap(A)
    B = list()
    heapSize1 = heapSize(A)
    for i in range(heapSize(A), 0, -1):
        A[0], A[i] = (A[i], A[0])
        B.append(A[heapSize1])
        A = A[:-1]
        heapSize1 = heapSize1 - 1
        MaxHeapify(A, 0)
def test_normal_case():
    arr1 = [3, 2, 1, 7, 6, 5, 4]
    arr2 = arr1.copy()
    heapSort(arr1)
    HeapSort(arr2)
    assert arr1 == arr2
def test_reversed_case():
    arr1 = [7, 6, 5, 4, 3, 2, 1]
    arr2 = arr1.copy()
    heapSort(arr1)
    HeapSort(arr2)
    assert arr1 == arr2
def test_already_sorted_case():
    arr1 = [1, 2, 3, 4, 5, 6, 7]
    arr2 = arr1.copy()
    heapSort(arr1)
    HeapSort(arr2)
    assert arr1 == arr2

