            return [-1, -1]
        i += 1
        j += 1
    return [i - 1, j]
class Solution:

    def threeEqualParts(self, arr: List[int]) -> List[int]:
        indices = deque([])
        N = len(arr)
        ans = [-1, -1]
        for idx, val in enumerate(arr):
            if val:
                indices.append(idx)
        if not indices:
            return [0, N - 1]
        if len(indices) % 3 != 0:
            return [-1, -1]
        start = 0
        end = len(indices) - 1
        s = indices[start]
        endsInZero = arr[-1] == 0
        while start < end:
            if endsInZero:
                edge_len = N - 1 - indices[end]
                medge_index = min(indices[end], indices[start + 1] + edge_len + 1)
                medge_index = max(medge_index, indices[end - 1])
                if medge_index - indices[start + 1] == edge_len + 1:
                    if arr[s:s + edge_len + 1] == arr[indices[end]:] == arr[indices[start + 1]:medge_index]:
                        return (s + edge_len, medge_index)
            elif indices[start] - s == N - indices[end] - 1 == indices[end - 1] - indices[start + 1]:
                if arr[s:indices[start] + 1] == arr[indices[end]:] == arr[indices[start + 1]:indices[end - 1] + 1]:
                    return (indices[start], indices[end - 1] + 1)
            start += 1
            end -= 1
        return ans
def test_simple_case():
    sol_instance = Solution()
    assert threeEqualParts([1, 0, 1, 0, 1]) == sol_instance.threeEqualParts([1, 0, 1, 0, 1])
def test_edge_case():
    sol_instance = Solution()
    assert threeEqualParts([0, 0, 0, 0, 0]) == sol_instance.threeEqualParts([0, 0, 0, 0, 0])
def test_difficult_case():
    sol_instance = Solution()
    assert threeEqualParts([1, 1, 0, 1, 1]) == sol_instance.threeEqualParts([1, 1, 0, 1, 1])

