def is_anagram(t: str, s: str) -> bool:
    if len(s) != len(t):
        return False
    for char in t:
        if char not in s:
            return False
        if t.count(char) != s.count(char):
            return False
    return True
class Solution:

    def isAnagram(self, s: str, t: str) -> bool:
        d = {}
        for element in s:
            if element in d:
                d[element] += 1
            else:
                d[element] = 1
        for element in t:
            if element in d:
                d[element] -= 1
            else:
                return False
        for key, value in d.items():
            if value != 0:
                return False
        return True
def test_simple_case():
    solution_instance = Solution()
    assert is_anagram('listen', 'silent') == solution_instance.isAnagram('listen', 'silent')
def test_edge_case():
    solution_instance = Solution()
    assert is_anagram('hello', 'olelh') == solution_instance.isAnagram('hello', 'olelh')
def test_difficult_case():
    solution_instance = Solution()
    assert is_anagram('bored', 'bordered') == solution_instance.isAnagram('bored', 'bordered')

