def crossword_validate(board, word):

    for i in range(len(board)):
        for j in range(len(board[0])):

            if board[i][j] == ' ' or board[i][j] == word[0]:
                # Check horizontal placement
                if j + len(word) <= len(board[0]) and ((j == 0 or board[i][j-1] == '#') and (j+len(word) == len(board[0]) or board[i][j+len(word)] == '#' or board[i][j+len(word)] == ' ')):
                    valid = True
                    for k in range(len(word)):
                        if board[i][j+k] != ' ' and board[i][j+k] != word[k]:
                            valid = False
                            break
                    if valid:
                        return True

                # Check vertical placement
                if i + len(word) <= len(board) and ((i == 0 or board[i-1][j] == '#') and (i+len(word) == len(board) or board[i+len(word)][j] == '#' or board[i+len(word)][j] == ' ')):
                    valid = True
                    for k in range(len(word)):
                        if board[i+k][j] != ' ' and board[i+k][j] != word[k]:
                            valid = False
                            break
                    if valid:
                        return True

    return False

