class Solution:

    def replaceDigits(self, s: str) -> str:
        if not len(s):
            return s
        alpha_list = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']
        output_str = ''
        for i in range(1, len(s), 2):
            output_str += s[i - 1]
            curr_ch = int(s[i])
            prev_ch_ind = alpha_list.index(s[i - 1])
            output_str += alpha_list[prev_ch_ind + curr_ch]
        return output_str if not len(s) % 2 else output_str + s[-1]
def test_simple_case():
    solution_instance = Solution()
    assert replace_digits('a1c1e1') == solution_instance.replaceDigits('a1c1e1')
def test_edge_case():
    solution_instance = Solution()
    assert replace_digits('') == solution_instance.replaceDigits('')
def test_difficult_case():
    solution_instance = Solution()
    assert replace_digits('d2p0h7') == solution_instance.replaceDigits('d2p0h7')

