from collections import *
from math import *

def minimumInteger(num: str, k: int) -> str:
    num = list(num)
    n = len(num)
    for i in range(n):
        if k == 0:
            break
        if i == n - 1:
            if k % 2 == 1:
                num[n - 1], num[n - 2] = (num[n - 2], num[n - 1])
            break
        min_idx = i
        for j in range(i + 1, min(n, i + k + 1)):
            if num[j] < num[min_idx]:
                min_idx = j
        k -= min_idx - i
        while min_idx > i:
            num[min_idx], num[min_idx - 1] = (num[min_idx - 1], num[min_idx])
            min_idx -= 1
    return ''.join(num)
class Solution:

    def minInteger(self, num: str, k: int) -> str:
        n = len(num)
        if k >= n * (n - 1) // 2:
            return ''.join(sorted(num))
        num = list(num)
        for i in range(n):
            if not k:
                break
            ii = i
            for j in range(i + 1, min(n, i + k + 1)):
                if num[ii] > num[j]:
                    ii = j
            if ii != i:
                k -= ii - i
                for j in range(ii, i, -1):
                    num[j - 1], num[j] = (num[j], num[j - 1])
        return ''.join(num)
def test_simple_case():
    solution_instance = Solution()
    assert minimumInteger('4321', 4) == solution_instance.minInteger('4321', 4)
def test_medium_case():
    solution_instance = Solution()
    assert minimumInteger('1020', 1) == solution_instance.minInteger('1020', 1)
def test_difficult_case():
    solution_instance = Solution()
    assert minimumInteger('987654', 3) == solution_instance.minInteger('987654', 3)

