class Solution:

    def partitionArray(self, nums: List[int], k: int) -> int:
        nums.sort()
        if len(nums) == 0:
            return 0
        ans = 1
        currmax = None
        currmin = None
        for n in nums:
            if currmax is None and currmin is None:
                currmax = currmin = n
            if n > currmax:
                currmax = n
            if n < currmin:
                currmin = n
            if currmax - currmin > k:
                ans += 1
                currmax = currmin = n
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert minSubsequence([2, 1, 4, 3], 2) == solution_instance.partitionArray([2, 1, 4, 3], 2)
def test_edge_case():
    solution_instance = Solution()
    assert minSubsequence([1, 2, 3], 1) == solution_instance.partitionArray([1, 2, 3], 1)
def test_difficult_case():
    solution_instance = Solution()
    assert minSubsequence([100, 100, 100], 1) == solution_instance.partitionArray([100, 100, 100], 1)

