def incident(a, b):
    count = 0
    for edge in edges:
        if a in edge and b in edge:
            count += 1
    return count
class Solution:

    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        degree = [0] * n
        freq = defaultdict(int)
        for u, v in edges:
            degree[u - 1] += 1
            degree[v - 1] += 1
            freq[min(u - 1, v - 1), max(u - 1, v - 1)] += 1
        vals = sorted(degree)
        ans = []
        for query in queries:
            cnt = 0
            lo, hi = (0, n - 1)
            while lo < hi:
                if query < vals[lo] + vals[hi]:
                    cnt += hi - lo
                    hi -= 1
                else:
                    lo += 1
            for u, v in freq:
                if degree[u] + degree[v] - freq[u, v] <= query < degree[u] + degree[v]:
                    cnt -= 1
            ans.append(cnt)
        return ans
def test_simple_case():
    n = 4
    edges = [[1, 2], [2, 3], [3, 4]]
    queries = [1, 2, 3]
