def minimumHammingDistance(source, target, allowedSwaps):
    parent = [i for i in range(len(source))]
    def find(x):
        if parent[x]!=x:
            parent[x] = find(parent[x])
        return parent[x]
    for u, v in allowedSwaps:
        a = find(u)
        b = find(v)
        parent[a] = b
    d = {}
    for i, num in enumerate(source):
        parentIndex = find(i)
        if parentIndex not in d:
            d[parentIndex] = []
        d[parentIndex].append(num)
    for k in d.keys():
        d[k].sort()
    res = 0
    for i, num in enumerate(target):
        parentIndex = find(i)
        if len(d[parentIndex]) > 0 and num != d[parentIndex][0]:
            d[parentIndex].pop(0)
            res += 1
    return res

