    for i, num in enumerate(target):
        parentIndex = find(i)
        if len(d[parentIndex]) > 0 and num != d[parentIndex][0]:
            d[parentIndex].pop(0)
            res += 1
    return res
class Solution:

    def minimumHammingDistance(self, source: List[int], target: List[int], allowedSwaps: List[List[int]]) -> int:
        idx_to_group = {}
        group_to_idx = {}
        global_group_id = 0
        for swap in allowedSwaps:
            foundGroups = set()
            for idx in swap:
                if idx in idx_to_group:
                    foundGroups.add(idx_to_group[idx])
            if foundGroups:
                pivot = min(foundGroups)
                for group_id in foundGroups:
                    if pivot != group_id:
                        group_to_idx[pivot].update(group_to_idx[group_id])
                        group_to_idx.pop(group_id)
                group_to_idx[pivot].update(swap)
                for idx in group_to_idx[pivot]:
                    idx_to_group[idx] = pivot
            else:
                for idx in swap:
                    idx_to_group[idx] = global_group_id
                group_to_idx[global_group_id] = set(swap)
                global_group_id += 1
        ans = 0
        if group_to_idx == {}:
            for i in range(len(source)):
                if source[i] != target[i]:
                    ans += 1
        else:
            for group_id in group_to_idx:
                src = {}
                tgt = {}
                for idx in group_to_idx[group_id]:
                    if source[idx] not in src:
                        src[source[idx]] = 0
                    src[source[idx]] += 1
                    if target[idx] not in tgt:
                        tgt[target[idx]] = 0
                    tgt[target[idx]] += 1
                for key in src:
                    if key in tgt:
                        if src[key] > tgt[key]:
                            ans += src[key] - tgt[key]
                    else:
                        ans += src[key]
            for i in range(len(source)):
                if i not in idx_to_group and source[i] != target[i]:
                    ans += 1
        return ans
def test_simple_case():
    source = [1, 2, 3, 4, 5]
    target = [1, 2, 3, 4, 6]
    allowedSwaps = [[0, 2], [1, 4]]
    sol_instance = Solution()
    assert minimumHammingDistance(source, target, allowedSwaps) == sol_instance.minimumHammingDistance(source, target, allowedSwaps)
def test_edge_case():
    source = [1, 2, 3, 4, 5]
    target = [1, 3, 2, 5, 4]
    allowedSwaps = [[0, 4], [4, 2], [1, 3], [3, 0]]
    sol_instance = Solution()
    assert minimumHammingDistance(source, target, allowedSwaps) == sol_instance.minimumHammingDistance(source, target, allowedSwaps)
def test_difficult_case():
