class Solution:
    def readBinaryWatch(self, turnedOn: int) -> List[str]:
        res = []
        for hour in range(0, 12):
            for minute in range(0, 60):
                if (bin(hour) + bin(minute)).count('1') == turnedOn:
                    res.append(f"{hour:0>2}:{minute:0>2}")
        return res

