                if (bin(hour) + bin(minute)).count('1') == turnedOn:
                    res.append(f'{hour:0>2}:{minute:0>2}')
        return res
class Solution:

    def readBinaryWatch(self, turnedOn: int) -> List[str]:
        ans = set()
        m_so_far = 0
        h_so_far = 0
        hashmap = {}
        hashmap['hr'] = [1, 2, 4, 8]
        hashmap['min'] = [1, 2, 4, 8, 16, 32]

        def helper(LEDS, hr_set, min_set):
            nonlocal m_so_far, h_so_far, ans, turnedOn, hashmap
            if m_so_far > 59 or h_so_far > 11:
                return
            if LEDS == turnedOn:
                m_string = ''
                if 0 <= m_so_far <= 9:
                    m_string = m_string + '0' + str(m_so_far)
                else:
                    m_string = str(m_so_far)
                res = str(h_so_far) + ':' + m_string
                ans.add(res)
                return
            for hour in hashmap['hr']:
                if hour in hr_set:
                    continue
                hr_set.add(hour)
                h_so_far += hour
                helper(LEDS + 1, hr_set, min_set)
                h_so_far -= hour
                hr_set.remove(hour)
            for minute in hashmap['min']:
                if minute in min_set:
                    continue
                min_set.add(minute)
                m_so_far += minute
                helper(LEDS + 1, hr_set, min_set)
                m_so_far -= minute
                min_set.remove(minute)
        helper(0, set(), set())
        return list(ans)
def test_simple_case():
    first_class_instance = First_class()
    solution_instance = Solution()
    assert sorted(first_class_instance.readBinaryWatch(1)) == sorted(solution_instance.readBinaryWatch(1))
