def min_flips(fronts: List[int], backs: List[int]) -> int:
    seen = set(fronts + backs)
    flips = float('inf')
    for card in seen:
        f_flip = sum((front != card for front, back in zip(fronts, backs) if back != card))
        b_flip = sum((back != card for front, back in zip(fronts, backs) if front != card))
        flips = min(flips, min(f_flip, b_flip))
    return flips if flips != float('inf') else 0
class Solution:

    def flipgame(self, fronts: List[int], backs: List[int]) -> int:
        """
        O(n) time complexity: n is length of fronts
        O(n) space complexity
        """
        same = {x for i, x in enumerate(fronts) if x == backs[i]}
        res = 9999
        for i in range(len(fronts)):
            if fronts[i] not in same:
                res = min(res, fronts[i])
            if backs[i] not in same:
                res = min(res, backs[i])
        return res % 9999
def test_simple_case():
    sol_instance = Solution()
    assert min_flips([2, 6, 5, 3], [1, 3, 2, 4]) == sol_instance.flipgame([2, 6, 5, 3], [1, 3, 2, 4])
def test_edge_case():
    sol_instance = Solution()
    assert min_flips([4], [4]) == sol_instance.flipgame([4], [4])
def test_difficult_case():
    sol_instance = Solution()
    assert min_flips([17, 18, 5, 4, 2, 1], [12, 7, 4, 11, 2, 2]) == sol_instance.flipgame([17, 18, 5, 4, 2, 1], [12, 7, 4, 11, 2, 2])

