def sort_matrix_diagonal(matrix):
    numRows = len(matrix)
    numCols = len(matrix[0])
    diagonals = [[] for i in range(numRows + numCols - 1)]
    for i in range(numRows):
        for j in range(numCols):
            diagonals[i-j+numCols-1].append(matrix[i][j])
    for diagonal in diagonals:
        diagonal.sort()
    sortedMatrix = [[0 for j in range(numCols)] for i in range(numRows)]
    for i in range(numRows):
        for j in range(numCols):
            sortedMatrix[i][j] = diagonals[i-j+numCols-1].pop(0)
    return sortedMatrix

