class Solution:

    def diagonalSort(self, mat: list[list[int]]) -> list[list[int]]:
        height = len(mat)
        width = len(mat[0])
        if width == 1:
            return mat
        matrix = [[[] for _ in range(width)] for _ in range(height)]
        first = [[] for _ in range(width)]
        second = [[] for _ in range(height - 1)]
        for i in range(width):
            first[i].append(mat[0][i])
            for j in range(1, height):
                if i + j >= width:
                    break
                first[i].append(mat[j][j + i])
        for k in range(1, height):
            second[k - 1].append(mat[k][0])
            for m in range(1, width):
                if k + m >= height:
                    break
                second[k - 1].append(mat[m + k][m])
        sorted_first = [sorted(q) for q in first]
        sorted_second = [sorted(q) for q in second]
        for e, a in enumerate(sorted_first):
            for e2, b in enumerate(a):
                matrix[e2][e + e2] = b
        for e3, f in enumerate(sorted_second, start=1):
            for e4, g in enumerate(f):
                matrix[e3 + e4][e4] = g
        return matrix
def test_simple_case():
    matrix = [[2, 3, 5], [1, 4, 6], [0, 7, 8]]
    solution_instance = Solution()
    assert sort_matrix_diagonal(matrix) == solution_instance.diagonalSort(matrix)
def test_edge_case():
    matrix = [[6, 2, 3], [4, 5, 1], [7, 0, 8]]
    solution_instance = Solution()
    assert sort_matrix_diagonal(matrix) == solution_instance.diagonalSort(matrix)
def test_difficult_case():
    matrix = [[3, 4, 5], [2, 5, 1], [1, 4, 2], [1, 1, 0]]
    solution_instance = Solution()
    assert sort_matrix_diagonal(matrix) == solution_instance.diagonalSort(matrix)

