class Solution:

    def canTransform(self, start: str, end: str) -> bool:
        if len(start) != len(end) or sorted(start) != sorted(end):
            return False
        invalid = ['XR', 'LX', 'RL', 'LR']
        for i in range(len(start)):
            e = end[i]
            s = start[i]
            print([(s, e)])
            if e == s:
                continue
            if s + e in invalid:
                return False
            if s == 'R' and e == 'X':
                idx = start.find('X', i)
                if idx == -1:
                    return False
                if start.find('L', i, idx) != -1:
                    return False
                start = start[:i] + 'X' + start[i + 1:idx] + 'R' + start[idx + 1:]
            elif s == 'X' and e == 'L':
                idx = start.find('L', i)
                if idx == -1:
                    return False
                if start.find('R', i, idx) != -1:
                    return False
                start = start[:i] + 'L' + start[i + 1:idx] + 'X' + start[idx + 1:]
        return True
