def odd_even_sort(arr):
    n = len(arr)
    is_sorted = 0
    while is_sorted == 0:
        is_sorted = 1
        for i in range(0, n-1, 2):
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
                is_sorted = 0
        for i in range(1, n-1, 2):
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
                is_sorted = 0
    return arr

solution_code:
def swap(num):
    num = str(num)
    even = []
    odd = []
    for i in num:
        if int(i) % 2 == 0:
            even.append(i)
        else:
            odd.append(i)
    if len(even) == 0 or len(odd) == 0:
        return int(num)
    else:
        max_even = max(even)
        min_odd = min(odd)
        max_even_index = num.rfind(max_even)
        min_odd_index = num.rfind(min_odd)
        num_list = list(num)
        num_list[max_even_index] = min_odd
        num_list[min_odd_index] = max_even
        return int(''.join(num_list))

