def comb_sort(alist):

    def swap(i, j):
        alist[i], alist[j] = (alist[j], alist[i])
    gap = len(alist)
    shrink = 1.3
    no_swap = False
    while not no_swap:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
            no_swap = True
        else:
            no_swap = False
        i = 0
        while i + gap < len(alist):
            if alist[i] > alist[i + gap]:
                swap(i, i + gap)
                no_swap = False
            i = i + 1
def test_simple_case():
    assert combSort([7, 1, 8, 2, 0]) == comb_sort([7, 1, 8, 2, 0])
def test_edge_case():
    assert combSort([1, 2, 3, 4, 5]) == comb_sort([1, 2, 3, 4, 5])
def test_difficult_case():
    assert combSort([0, -1, 4, 3, -2, 6, 5]) == comb_sort([0, -1, 4, 3, -2, 6, 5])

