from typing import List

def lastStoneWeight(stones: List[int]) -> int:
    while len(stones) > 1:
        stones.sort()
        x = stones.pop()
        y = stones.pop()
        if x != y:
            stones.append(y - x)
    if stones:
        return stones[0]
    else:
        return 0

