from typing import *
from collections import *
from math import *

def lastStoneWeight(stones: List[int]) -> int:
    while len(stones) > 1:
        stones.sort()
        x = stones.pop()
        y = stones.pop()
        if x != y:
            stones.append(y - x)
    if stones:
        return stones[0]
    else:
        return 0
class Solution:

    def lastStoneWeight(self, stones: List[int]) -> int:
        stones = sorted(stones)
        while stones:
            if stones[0] == 0:
                stones.remove(0)
            else:
                break
        if len(stones) == 0:
            return 0
        elif len(stones) == 1:
            return stones[0]
        else:
            maxstone, secstone = (stones[-1], stones[-2])
            stones[-1] = maxstone - secstone
            stones[-2] = 0
        return self.lastStoneWeight(stones)
def test_simple_case():
    solution_instance = Solution()
    assert lastStoneWeight([2, 7, 4, 1]) == solution_instance.lastStoneWeight([2, 7, 4, 1])
def test_edge_case():
    solution_instance = Solution()
    assert lastStoneWeight([10]) == solution_instance.lastStoneWeight([10])
def test_difficult_case():
    solution_instance = Solution()
    assert lastStoneWeight([2, 1]) == solution_instance.lastStoneWeight([2, 1])

