def thirdMax(nums):
    nums = list(set(nums))
    if len(nums) < 3:
        return max(nums)
    nums.sort(reverse=True)
    return nums[2]
class Solution:

    def thirdMax(self, nums: List[int]) -> int:
        max1 = nums[0]
        secmax = float('-inf')
        thirmax = float('-inf')
        if len(nums) < 3:
            return max(nums)
        for i in range(len(nums)):
            num = nums[i]
            if num > max1:
                thirmax = secmax
                secmax = max1
                max1 = nums[i]
            elif num > secmax and num < max1:
                thirmax = secmax
                secmax = num
            elif num > thirmax and num < secmax:
                thirmax = num
        return thirmax if thirmax != float('-inf') else max1
def test_simple_case():
    solution_instance = Solution()
    assert thirdMax([3, 2, 1]) == solution_instance.thirdMax([3, 2, 1])
def test_no_third_max():
    solution_instance = Solution()
    assert thirdMax([1, 2]) == solution_instance.thirdMax([1, 2])
def test_with_negative():
    solution_instance = Solution()
    assert thirdMax([2, 2, 3, 0, -1]) == solution_instance.thirdMax([2, 2, 3, 0, -1])

