solution_code:
def is_palindrome(num):
    return str(num) == str(num)[::-1]

def is_super_palindrome(num):
    if is_palindrome(num):
        sqrt_num = int(num ** 0.5)
        return is_palindrome(sqrt_num) and sqrt_num ** 2 == num
    return False

def superpalindromesInRange(left, right):
    left_num = int(left)
    right_num = int(right)
    res = 0
    for i in range(1, 100000):
        if i ** 2 > right_num:
            break
        if is_super_palindrome(i ** 2) and left_num <= i ** 2 <= right_num:
            res += 1
    for i in range(1, 100000):
        if i > right_num:
            break
        for j in [0, 1, 2, 3, 4]:
            num = int(str(i) + str(j) + str(i)[::-1])
            if num ** 2 > right_num:
                break
            if is_super_palindrome(num ** 2) and left_num <= num ** 2 <= right_num:
                res += 1
    return res

test_code:
from typing import *
from collections import *
from math import *

def is_palindrome(num):
    return str(num) == str(num)[::-1]
def is_super_palindrome(num):
    if is_palindrome(num):
        sqrt_num = int(num ** 0.5)
        return is_palindrome(sqrt_num) and sqrt_num ** 2 == num
    return False
def superpalindromesInRange(left, right):
    left_num = int(left)
    right_num = int(right)
    res = 0
    for i in range(1, 100000):
        if i ** 2 > right_num:
            break
        if is_super_palindrome(i ** 2) and left_num <= i ** 2 <= right_num:
            res += 1
    for i in range(1, 100000):
        if i > right_num:
            break
        for j in [0, 1, 2, 3, 4]:
            num = int(str(i) + str(j) + str(i)[::-1])
            if num ** 2 > right_num:
                break
            if is_super_palindrome(num ** 2) and left_num <= num ** 2 <= right_num:
                res += 1
    return res
class Solution:

    def superpalindromesInRange(self, left: str, right: str) -> int:
        """
        1. For each number in the range [floor(square root of integer value of left), floor(square root of integer value of right)], 
                - need to check if the number is palindrome and (number^2) is palindrome
        2. One possible way to do this quicker is 
                - to generate all the palindromes within the range [floor(square root of integer value of left), floor(square root of integer value of right)]
                - and check whether the square of this palindrome is also a palindrome
        3. If [floor(square root of integer value of left)] is of x digits and [floor(square root of integer value of right)] is of y digits, then
                - if x>1: start generating palindrome from the lowest number of x digits that is divisible by 10, else: start generating palindrome from 1
                - generate palindrome upto the highest number of y digits that is 999...9 (y 9's) 
        4. To generate palindromes of x and y digits, we need to check only the first ceil(x/2) digits and ceil(y/2) digits 
                of [floor(square root of integer value of left)] and [floor(square root of integer value of right)] respectively
        """
        cnt = 0
        lft = str(int(int(left) ** 0.5))
        rght = str(int(int(right) ** 0.5))
        lft_1 = lft
        rght_1 = rght
        if len(lft) % 2:
            lft = '1' + '0' * (len(lft) // 2)
        else:
            lft = '1' + '0' * (len(lft) // 2 - 1)
        if len(rght) % 2:
            rght = '9' * (len(rght) // 2 + 1)
        else:
            rght = '9' * (len(rght) // 2)
        for num in range(int(lft), int(rght) + 1):
            num = str(num)
            len_string = len(num)
            if len_string * 2 - 1 >= len(lft_1):
                str_N_1 = num[0:len_string - 1] + num[len_string - 1] + num[0:len_string - 1][::-1]
                sq_1 = str(int(str_N_1) ** 2)
                if int(left) <= int(sq_1) <= int(right) and sq_1 == sq_1[::-1]:
                    cnt += 1
            if len_string * 2 <= len(rght_1):
                str_N_2 = num + num[::-1]
                sq_2 = str(int(str_N_2) ** 2)
                if int(left) <= int(sq_2) <= int(right) and sq_2 == sq_2[::-1]:
                    cnt += 1
        return cnt
def test_simple_case():
    solution_instance = Solution()
    assert superpalindromesInRange('4', '1000') == solution_instance.superpalindromesInRange('4', '1000')
def test_edge_case():
    solution_instance = Solution()
    assert superpalindromesInRange('1', '100') == solution_instance.superpalindromesInRange('1', '100')
def test_difficult_case():
    solution_instance = Solution()
    assert superpalindromesInRange('100', '100000') == solution_instance.superpalindromesInRange('100', '100000')

