def min_garbage_pickup_time(garbage, travel):
    mp, pg, mg = [], [], []
    for i in range(len(garbage)):
        if garbage[i] == 'M':
            mp.append(travel[i])
        elif garbage[i] == 'P':
            pg.append(travel[i])
        elif garbage[i] == 'G':
            mg.append(travel[i])
    mp.sort()
    pg.sort()
    mg.sort()
    if len(mp) == 0 or len(pg) == 0 or len(mg) == 0:
        return -1
    return mp[0] + pg[0] + mg[0] + max(sum(mp), sum(pg), sum(mg)) - 3 * max(mp[-1], pg[-1], mg[-1])

