def min_garbage_pickup_time(garbage, travel):
    mp, pg, mg = ([], [], [])
    for i in range(len(garbage)):
        if garbage[i] == 'M':
            mp.append(travel[i])
        elif garbage[i] == 'P':
            pg.append(travel[i])
        elif garbage[i] == 'G':
            mg.append(travel[i])
    mp.sort()
    pg.sort()
    mg.sort()
    if len(mp) == 0 or len(pg) == 0 or len(mg) == 0:
