class Solution:

    def garbageCollection(self, garbage: List[str], travel: List[int]) -> int:
        metal = {}
        paper = {}
        glass = {}
        travel_cost = []
        travel_cost.append(0)
        cur_cost = 0
        for e in travel:
            cur_cost += e
            travel_cost.append(cur_cost)
        for i in range(len(garbage)):
            for c in garbage[i]:
                if c == 'M':
                    if i not in metal:
                        metal[i] = 1
                    else:
                        metal[i] += 1
                elif c == 'P':
                    if i not in paper:
                        paper[i] = 1
                    else:
                        paper[i] += 1
                elif i not in glass:
                    glass[i] = 1
                else:
                    glass[i] += 1
        metal_cost = 0
        pre = 0
        metal_keys = sorted(metal.keys())
        for mk in metal_keys:
            metal_cost += metal[mk]
            metal_cost += travel_cost[mk] - travel_cost[pre]
            pre = mk
        paper_cost = 0
        pre2 = 0
        paper_keys = sorted(paper.keys())
        for pk in paper_keys:
            paper_cost += paper[pk]
            paper_cost += travel_cost[pk] - travel_cost[pre2]
            pre2 = pk
        glass_cost = 0
        pre3 = 0
        glass_keys = sorted(glass.keys())
        for gk in glass_keys:
            glass_cost += glass[gk]
            glass_cost += travel_cost[gk] - travel_cost[pre3]
            pre3 = gk
        return metal_cost + paper_cost + glass_cost
