class Solution:

    def numRescueBoats(self, people: List[int], limit: int) -> int:
        boats = 0
        people.sort()
        lighter, heavier = (0, len(people) - 1)
        while lighter <= heavier:
            if people[lighter] + people[heavier] > limit:
                heavier -= 1
            else:
                lighter += 1
                heavier -= 1
            boats += 1
        return boats
