from math import *

def largest_sum_of_averages(nums: List[int], k: int) -> float:
    dp = [[0] * len(nums) for _ in range(k)]
    for i in range(len(nums)):
        dp[0][i] = sum(nums[:i + 1]) / (i + 1)
    for i in range(1, k):
        for j in range(i, len(nums)):
            for m in range(i - 1, j):
                dp[i][j] = max(dp[i][j], dp[i - 1][m] + sum(nums[m + 1:j + 1]) / (j - m))
    return dp[-1][-1]
class Solution:

    def largestSumOfAverages(self, nums: List[int], k: int) -> float:

        def helper(ind, k, currSum, count):
            if ind >= n:
                return 0
            if k == 0:
                return -int(1000000000.0)
            if dp[ind][count][k] != -1:
                return dp[ind][count][k]
            currSum += nums[ind]
            notTake = currSum / count + helper(ind + 1, k - 1, 0, 1)
            take = helper(ind + 1, k, currSum, count + 1)
            dp[ind][count][k] = max(take, notTake)
            return dp[ind][count][k]
        n = len(nums)
        dp = [[[-1] * (k + 1) for i in range(n + 1)] for i in range(n + 1)]
        return helper(0, k, 0, 1)
def test_simple_case():
    solution_instance = Solution()
    assert largest_sum_of_averages([1, 12, 5, 3], 2) == solution_instance.largestSumOfAverages([1, 12, 5, 3], 2)
