def min_taps(n: int, ranges: List[int]) -> int:
    """
    Returns minimum number of taps needed to water the whole garden.
    """
    dp = [0] + [n + 2] * n
    for i, x in enumerate(ranges):
        left, right = max(0, i - x), min(n, i + x)
        for j in range(left, right + 1):
            dp[j] = min(dp[j], dp[max(0, i - x)] + 1)
    return dp[n] if dp[n] < n + 2 else -1

