def min_taps(n: int, ranges: List[int]) -> int:
    """
    Returns minimum number of taps needed to water the whole garden.
    """
    dp = [0] + [n + 2] * n
    for i, x in enumerate(ranges):
        left, right = (max(0, i - x), min(n, i + x))
        for j in range(left, right + 1):
            dp[j] = min(dp[j], dp[max(0, i - x)] + 1)
    return dp[n] if dp[n] < n + 2 else -1
class Solution:

    def minTaps(self, n: int, ranges: List[int]) -> int:
        arr = []
        for i in range(len(ranges)):
            arr.append([i - ranges[i], i + ranges[i]])
        arr.sort(key=lambda item: (item[0], -item[1]))
        i = 0
        maxy = -inf
        maxind = 0
        while i <= n and arr[i][0] <= 0:
            if arr[i][1] >= maxy:
                maxy = arr[i][1]
                maxind = i
            i += 1
        i = maxind
        cnt = 1
        if maxy != -inf and maxy >= n:
            return cnt
        while i <= n:
            a, b = arr[i]
            j = i + 1
            maxy = -inf
            maxind = i
            while j <= n:
                p, q = arr[j]
                if q >= a and p <= b:
                    if q >= maxy:
                        maxy = q
                        maxind = j
                    j += 1
                else:
                    break
            cnt += 1
            if maxy >= n:
                return cnt
            if maxy == -inf or maxy <= b:
                return -1
            else:
                i = maxind
        return -1
def test_simple_case():
    solution_instance = Solution()
    assert min_taps(5, [3, 4, 1, 1, 0, 0]) == solution_instance.minTaps(5, [3, 4, 1, 1, 0, 0])
def test_difficult_case():
    solution_instance = Solution()
    assert min_taps(8, [4, 0, 6, 2, 3, 1, 6, 7]) == solution_instance.minTaps(8, [4, 0, 6, 2, 3, 1, 6, 7])
def test_edge_case():
    solution_instance = Solution()
    assert min_taps(10, [3, 5, 1, 4, 2, 1, 1, 3, 0, 2]) == solution_instance.minTaps(10, [3, 5, 1, 4, 2, 1, 1, 3, 0, 2])

