def fib_square(n):
    if n <= 1:
        return n
    else:
        return fib_square(n - 1) + fib_square(n - 2)
def fibonacci_nums(x=0, y=1):
    yield x
    while True:
        yield y
        x, y = (y, x + y)
def test_simple_case():
    fib_square_result = list(map(lambda x: x ** 2, [fib_square(n) for n in range(5)]))
