def count_hidden_sequences(differences, lower, upper):
    n = len(differences)
    dp = [[0] * (upper + 1) for _ in range(n + 1)]
    dp[0][1:] = [1] * upper
    for i in range(1, n + 1):
        for j in range(1, upper + 1):
            for k in range(max(1, j - differences[i - 1]), j):
                dp[i][j] += dp[i - 1][k]
        for j in range(1, upper + 1):
            dp[i][j] -= dp[i - 1][j - 1]
        for j in range(1, upper + 1):
            dp[i][j] += dp[i][j - 1]
    return dp[-1][upper] - dp[-1][lower - 1] if lower > 1 else dp[-1][upper]
class Solution:

    def numberOfArrays(self, differences: List[int], lower: int, upper: int) -> int:
        l = lower
        r = upper
        right = float('-inf')
        while l <= r:
            mid = l + r >> 1
            isHidden, condition = self.isHiddenSequence(differences, mid, lower, upper)
            if isHidden:
                right = mid
                l = mid + 1
            elif condition == 'HIGH':
                r = mid - 1
            else:
                l = mid + 1
        l = lower
        r = upper
        left = float('inf')
        while l <= r:
            mid = l + r >> 1
            isHidden, condition = self.isHiddenSequence(differences, mid, lower, upper)
            if isHidden:
                left = mid
                r = mid - 1
            elif condition == 'HIGH':
                r = mid - 1
            else:
                l = mid + 1
        if right == float('-inf') or left == float('inf'):
            return 0
        return right - left + 1

    def isHiddenSequence(self, differences, start, lower, upper):
        cur_sum = start
        for difference in differences:
            cur_sum += difference
            if cur_sum < lower:
                return (False, 'LOW')
            if cur_sum > upper:
                return (False, 'HIGH')
        return (True, 'PERFECT')
def test_simple_case():
    sol_instance = Solution()
    assert count_hidden_sequences([1, -3, 4], 1, 6) == sol_instance.numberOfArrays([1, -3, 4], 1, 6)
def test_edge_case():
    sol_instance = Solution()
    assert count_hidden_sequences([-2, 0, 2], 1, 4) == sol_instance.numberOfArrays([-2, 0, 2], 1, 4)
def test_difficult_case():
    sol_instance = Solution()
    assert count_hidden_sequences([100, 0, -3], 5, 7) == sol_instance.numberOfArrays([100, 0, -3], 5, 7)

