from typing import *
from collections import *
from math import *

def entity_parser(text):
    specials = {'&quot;': '"', '&apos;': "'", '&amp;': '&', '&gt;': '>', '&lt;': '<', '&frasl;': '/'}
    for special in specials:
        text = text.replace(special, specials[special])
    return text
class Solution:

    def entityParser(self, text: str) -> str:
        dat = {'&amp;quot;': '"', '&amp;apos;': "'", '&amp;amp;': '&amp;', '&amp;gt;': '>', '&amp;lt;': '<', '&amp;frasl;': '/'}
        txt = ''
        amp_idx, sem_idx = (None, None)
        for i, e in enumerate(text):
            if e == '&amp;':
                amp_idx = i
            if e == ';':
                sem_idx = i
            if amp_idx == None:
                txt += e
            if amp_idx != None and sem_idx != None:
                key = text[amp_idx:sem_idx + 1]
                if key in dat.keys():
                    txt += dat[key]
                else:
                    txt += key
                amp_idx, sem_idx = (None, None)
        return txt
def test_simple_case():
    solution_instance = Solution()
    assert entity_parser('&amp;quot;Welcome to &amp;quot;Geeks&amp;quot;, I hope you &amp;lt;u&amp;gt;like&amp;lt;/u&amp;gt; the place&amp;frasl;') == solution_instance.entityParser('&amp;quot;Welcome to &amp;quot;Geeks&amp;quot;, I hope you &amp;lt;u&amp;gt;like&amp;lt;/u&amp;gt; the place&amp;frasl;')
def test_edge_case():
    solution_instance = Solution()
    assert entity_parser('&amp;amp;') == solution_instance.entityParser('&amp;amp;')
def test_difficult_case():
    solution_instance = Solution()
    assert entity_parser('real <b>text entity</b>') == solution_instance.entityParser('real <b>text entity</b>')

