from typing import *
from collections import *
from math import *

def maxConsecutiveAnswers(answerKey: str, k: int) -> int:
    count = {'T': 0, 'F': 0}
    max_count = 0
    start = 0
    for end in range(len(answerKey)):
        count[answerKey[end]] += 1
        while min(count.values()) > k:
            count[answerKey[start]] -= 1
            start += 1
        max_count = max(max_count, end - start + 1)
    return max_count
class Solution:

    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:
        L = 0
        hashmap = {'T': 0, 'F': 0}
        answer = 0
        for R in range(len(answerKey)):
            right_char = answerKey[R]
            hashmap[right_char] += 1
            while min(hashmap['T'], hashmap['F']) > k:
                answer = max(answer, R - L)
                if answerKey[L] == 'T':
                    hashmap['T'] -= 1
                else:
                    hashmap['F'] -= 1
                L += 1
        answer = max(answer, hashmap['T'] + hashmap['F'])
        return answer
def test_simple_case():
    solution_instance = Solution()
    assert maxConsecutiveAnswers('TTFF', 2) == solution_instance.maxConsecutiveAnswers('TTFF', 2)
def test_edge_case():
    solution_instance = Solution()
    assert maxConsecutiveAnswers('TFFT', 1) == solution_instance.maxConsecutiveAnswers('TFFT', 1)
def test_difficult_case():
    solution_instance = Solution()
    assert maxConsecutiveAnswers('TTFTFFFT', 3) == solution_instance.maxConsecutiveAnswers('TTFTFFFT', 3)

