def findConsecutive(num):
    res = []
    for i in range(1,num//2+2):
        for j in range(i+1,num//2+2):
            sum = (i+j)*(j-i+1)/2
            if sum == num:
                for k in range(i,j+1):
                    res.append(k)
                return res
            elif sum > num:
                break
    return res

