def maxVowels(s: str, k: int) -> int:
    vowels = set(['a', 'e', 'i', 'o', 'u'])
    max_vowels = 0
    curr_vowels = 0
    for i in range(len(s)):
        if i >= k and s[i-k] in vowels:
            curr_vowels -= 1
        if s[i] in vowels:
            curr_vowels += 1
        max_vowels = max(max_vowels, curr_vowels)
    return max_vowels

