def maxVowels(s: str, k: int) -> int:
    vowels = set(['a', 'e', 'i', 'o', 'u'])
    max_vowels = 0
    curr_vowels = 0
    for i in range(len(s)):
        if i >= k and s[i - k] in vowels:
            curr_vowels -= 1
        if s[i] in vowels:
            curr_vowels += 1
        max_vowels = max(max_vowels, curr_vowels)
    return max_vowels
class Solution:

    def maxVowels(self, s: str, k: int) -> int:
        n = len(s)
        vowels = {'a', 'e', 'i', 'o', 'u'}
        count = 0
        for i in range(0, k):
            if s[i] in vowels:
                count += 1
        max_vowel_count = count
        for tail_index in range(k, n):
            head_index = tail_index - k
            head_char, tail_char = (s[head_index], s[tail_index])
            if head_char in vowels:
                count -= 1
            if tail_char in vowels:
                count += 1
            max_vowel_count = max(max_vowel_count, count)
        return max_vowel_count
def test_simple_case():
    solution_instance = Solution()
    assert maxVowels('abciiidef', 3) == solution_instance.maxVowels('abciiidef', 3)
def test_edge_case():
    solution_instance = Solution()
    assert maxVowels('aeiou', 2) == solution_instance.maxVowels('aeiou', 2)
def test_difficult_case():
    solution_instance = Solution()
    assert maxVowels('leetcode', 3) == solution_instance.maxVowels('leetcode', 3)

