def find_mirror_characters(s):
    mirror_dict = {'b': 'd', 'd': 'b', 'o': 'o', 'p': 'q', 'q': 'p', 'v': 'v', 'w': 'w', 'x': 'x'}
    result_dict = {}
    for i, char in enumerate(s):
