            if i == len(s) - 1 - i:
                result_dict[i] = char
            elif s[len(s) - 1 - i] == mirror_dict[char]:
                result_dict[i] = char
                result_dict[len(s) - 1 - i] = s[len(s) - 1 - i]
    return result_dict

