from typing import *
from collections import *
from math import *

def canMeasureWater(jug1Capacity: int, jug2Capacity: int, targetCapacity: int) -> bool:
    if targetCapacity > jug1Capacity + jug2Capacity:
        return False

    def gcd(a, b):
        while b:
            a, b = (b, a % b)
        return a
    return targetCapacity % gcd(jug1Capacity, jug2Capacity) == 0
class Solution:

    def canMeasureWater(self, jug1Capacity: int, jug2Capacity: int, targetCapacity: int) -> bool:
        edges = [jug1Capacity, jug2Capacity, abs(jug2Capacity - jug1Capacity)]
        lst = [0]
        mx = max(jug1Capacity, jug2Capacity, targetCapacity)
        visited = [0] * 1000001
        if targetCapacity > jug1Capacity + jug2Capacity:
            return False
        visited[0] = 1
        while lst:
            x = lst.pop(0)
            if x == targetCapacity:
                return True
            for i in edges:
                if x + i <= mx and visited[x + i] == 0:
                    lst.append(x + i)
                    visited[x + i] = 1
                if x - i >= 0 and visited[x - i] == 0:
                    lst.append(x - i)
                    visited[x - i] = 1
        return False
def test_simple_case():
    solution_instance = Solution()
    assert canMeasureWater(3, 5, 4) == solution_instance.canMeasureWater(3, 5, 4)
def test_edge_case():
    solution_instance = Solution()
    assert canMeasureWater(2, 6, 5) == solution_instance.canMeasureWater(2, 6, 5)
def test_difficult_case():
    solution_instance = Solution()
    assert canMeasureWater(10, 6, 4) == solution_instance.canMeasureWater(10, 6, 4)

