def average(nums):
    even_nums_divisible_by_3 = [num for num in nums if num % 2 == 0 and num % 3 == 0]
    if not even_nums_divisible_by_3:
        return 0
    return round(sum(even_nums_divisible_by_3) / len(even_nums_divisible_by_3))
class Solution:

    def averageValue(self, nums: List[int]) -> int:
        """        
        Algorithm:
        1.declare total variable to hold the sum of all even numbers divisible by 3
        2. declare a count variable to hold the number of the even numbers divisible by 3
        3. loop over the array
        4. check if the number is even and divisible by 3
        5. if yes update sum and number variables
        6. when the loop ends, return total/count which is average

        Time Complexity O(N)
        Space Complexity O(1)
        """
        total = 0
        count = 0
        for i in nums:
            if i % 2 == 0 and i % 3 == 0:
                total += i
                count += 1
        try:
            return int(total / count)
        except:
            return 0
def test_simple_case():
    solution_instance = Solution()
    assert average([6, 8, 12]) == solution_instance.averageValue([6, 8, 12])
def test_empty_case():
    solution_instance = Solution()
    assert average([]) == solution_instance.averageValue([])
def test_mixed_case():
    solution_instance = Solution()
    assert average([1, 4, 6, 7, 9, 12]) == solution_instance.averageValue([1, 4, 6, 7, 9, 12])

