def max_turbulent_subarray(arr):
    if len(arr) < 2:
        return len(arr)
    max_len = 1
    cur_len = 1
    i = 0
    while i < len(arr) - 1:
        if arr[i] == arr[i + 1]:
            cur_len = 1
        elif i == len(arr) - 2 or (arr[i] > arr[i + 1] and arr[i + 1] < arr[i + 2]) or (arr[i] < arr[i + 1] and arr[i + 1] > arr[i + 2]):
            cur_len += 1
            max_len = max(max_len, cur_len)
        else:
            cur_len = 2
        i += 1
