class Solution:

    def maxTurbulenceSize(self, arr: List[int]) -> int:
        if len(arr) <= 1:
            return len(arr)
        if len(arr) == 2 and arr[0] != arr[1]:
            return 2
        if len(arr) == 2:
            return 1
        max_len = 2
        ans = max_len
        is_last_increasing = arr[0] < arr[1]
        if arr[0] == arr[1]:
            return self.maxTurbulenceSize(arr[1:])
        for i in range(2, len(arr)):
            if is_last_increasing:
                if arr[i - 1] > arr[i]:
                    is_last_increasing = False
                    max_len += 1
                else:
                    ans = max(ans, max_len)
                    if arr[i - 1] == arr[i]:
                        max_len = 1
                    else:
                        max_len = 2
            elif arr[i - 1] < arr[i]:
                is_last_increasing = True
                max_len += 1
            else:
                ans = max(ans, max_len)
                if arr[i - 1] == arr[i]:
                    max_len = 1
                else:
                    max_len = 2
        return max(ans, max_len)
def test_simple_case():
