from typing import *
from collections import *
from math import *

def hamming_weight(n: int) -> int:
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count
class Solution:

    def hammingWeight(self, n: int) -> int:
        return self.optimalSol(n)
        return self.bruteForce(n)
        return self.builtInMethod(n)

    def optimalSol(self, n):
        if not n:
            return 0
        count = 0
        while n > 0:
            count += 1 if n % 2 == 1 else 0
            n >>= 1
        return count

    def bruteForce(self, n):
        count = 0
        while n > 0:
            count += 1 if n % 2 == 1 else 0
            n //= 2
        return count

    def builtInMethod(self, n):
        return bin(n)[2:].count('1')
def test_simple_case():
    s = Solution()
    assert hamming_weight(3) == s.optimalSol(3)
def test_edge_case():
    s = Solution()
    assert hamming_weight(0) == s.optimalSol(0)
def test_difficult_case():
    s = Solution()
    assert hamming_weight(-3) == s.optimalSol(-3)

