def goat_latin(sentence):
    vowels = set(["a", "e", "i", "o", "u"])
    words = sentence.split()
    for i in range(len(words)):
        if words[i][0].lower() in vowels:
            words[i] += "ma"
        else:
            words[i] = words[i][1:] + words[i][0] + "ma"
        words[i] += "a" * (i + 1)
    return " ".join(words)

