        is_swapped = False
        for j in range(i, 0, -1):
            if nums[j] < nums[j - 1]:
                nums[j], nums[j - 1] = (nums[j - 1], nums[j])
                is_swapped = True
        for j in range(i):
            if nums[j] > nums[j + 1]:
                nums[j], nums[j + 1] = (nums[j + 1], nums[j])
                is_swapped = True
        if not is_swapped:
            return nums
