class Solution:

    def sortArrayByParityII(self, nums: List[int]) -> List[int]:
        odd = 1
        even = 0
        while max(odd, even) < len(nums):
            if nums[odd] % 2:
                odd += 2
            else:
                for i in range(odd + 1, len(nums), 2):
                    if nums[i] % 2:
                        nums[odd], nums[i] = (nums[i], nums[odd])
                        odd += 2
                        break
            if nums[even] % 2 == 0:
                even += 2
            else:
                for i in range(even + 1, len(nums), 2):
                    if nums[i] % 2 == 0:
                        nums[even], nums[i] = (nums[i], nums[even])
                        even += 2
                        break
        return nums
def test_simple_case():
    solution_instance = Solution()
    assert sortArray([2, 3]) == solution_instance.sortArrayByParityII([2, 3])
def test_edge_case():
    solution_instance = Solution()
    assert sortArray([4, 5, 0, 1]) == solution_instance.sortArrayByParityII([4, 5, 0, 1])
def test_difficult_case():
    solution_instance = Solution()
    assert sortArray([3, 1, 2, 4]) == solution_instance.sortArrayByParityII([3, 1, 2, 4])

