        if num % 2 == 0:
            evens.append(num)
        else:
            odds.append(num)
    odds.sort()
    evens.sort()
    sorted_nums = []
    for i in range(len(nums)):
        if nums[i] % 2 == 0:
            sorted_nums.append(evens.pop(0))
        else:
            sorted_nums.append(odds.pop(0))
    return sorted_nums

