    else:
        return True
class Solution:

    def containsDuplicate(self, nums: List[int]) -> bool:
        for i in range(len(nums)):
            for j in range(len(nums)):
                if i == j:
                    continue
                elif nums[i] == nums[j]:
                    return True
        return False
        nums.sort()
        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1]:
                return True
        return False
        res = {}
        for el in nums:
            if el in res:
                return True
            else:
                res[el] = 1
        return False
def test_no_duplicates():
