def minDominoRotations(tops, bottoms):
    for val in [tops[0], bottoms[0]]:
        if all((val in d for d in zip(tops, bottoms))):
            return len(tops) - max(tops.count(val), bottoms.count(val))
    return -1
class Solution:

    def minDominoRotations(self, A: List[int], B: List[int]) -> int:
        if not (A and B):
            return 0
        ab0 = (A[0], B[0])
        a0 = [1, 0]
        b0 = [0, 1]
        length = len(A)
        for i in range(1, length):
            if ab0[0] != A[i] and ab0[0] != B[i]:
                a0 = [0]
            if ab0[1] != A[i] and ab0[1] != B[i]:
                b0 = [0]
            if a0 == [0] and b0 == [0]:
                return -1
            if a0 != [0] and A[i] == ab0[0]:
                a0[0] += 1
            if a0 != [0] and B[i] == ab0[0]:
                a0[1] += 1
            if b0 != [0] and A[i] == ab0[1]:
                b0[0] += 1
            if b0 != [0] and B[i] == ab0[1]:
                b0[1] += 1
        return length - max(max(a0), max(b0))
def test_normal_case():
    solution_instance = Solution()
    tops = [2, 1, 2]
    bottoms = [2, 2, 2]
    assert minDominoRotations(tops, bottoms) == solution_instance.minDominoRotations(tops, bottoms)
def test_edge_case():
    solution_instance = Solution()
    tops = [3, 5, 1, 2, 3]
    bottoms = [3, 6, 3, 3, 4]
    assert minDominoRotations(tops, bottoms) == solution_instance.minDominoRotations(tops, bottoms)
def test_difficult_case():
    solution_instance = Solution()
    tops = [1, 2, 1, 2]
