            i, j = queue.pop(0)
            for ni, nj in ((i - 1, j), (i, j + 1), (i + 1, j), (i, j - 1)):
                if 0 <= ni < len(isWater) and 0 <= nj < len(isWater[0]):
                    if isWater[ni][nj] == 0 and height[ni][nj] == 0:
                        height[ni][nj] = height[i][j] + 1
                        queue.append((ni, nj))
    for i in range(len(isWater)):
        for j in range(len(isWater[0])):
            if isWater[i][j] == 1:
                bfs([(i, j)])
    max_height = max([max(row) for row in height])
    return [[max_height - h for h in row] for row in height]
class Solution:

    def highestPeak(self, isWater):
        m, n = (len(isWater), len(isWater[0]))
        visited = set()
        q = []
        for i in range(m):
            for j in range(n):
                if isWater[i][j] == 1:
                    visited.add((i, j))
                    q.append((i, j))
                    isWater[i][j] = 0
        while q:
            num = len(q)
            for i in range(num):
                x, y = q.pop(0)
                val = isWater[x][y]
                if x > 0 and (x - 1, y) not in visited:
                    isWater[x - 1][y] = val + 1
                    visited.add((x - 1, y))
                    q.append((x - 1, y))
                if y > 0 and (x, y - 1) not in visited:
                    isWater[x][y - 1] = val + 1
                    visited.add((x, y - 1))
                    q.append((x, y - 1))
                if x < m - 1 and (x + 1, y) not in visited:
                    isWater[x + 1][y] = val + 1
                    visited.add((x + 1, y))
                    q.append((x + 1, y))
                if y < n - 1 and (x, y + 1) not in visited:
                    isWater[x][y + 1] = val + 1
                    visited.add((x, y + 1))
                    q.append((x, y + 1))
        return isWater
def test_simple_case():
    solution_instance = Solution()
    isWater_example = [[0, 0, 1], [1, 0, 0], [0, 0, 0]]
    assert assign_heights(isWater_example) == solution_instance.highestPeak(isWater_example)
def test_edge_case():
    solution_instance = Solution()
    isWater_example = [[0, 1], [0, 0]]
    assert assign_heights(isWater_example) == solution_instance.highestPeak(isWater_example)
def test_difficult_case():
    solution_instance = Solution()
    isWater_example = [[0, 0, 0], [0, 0, 1]]
    assert assign_heights(isWater_example) == solution_instance.highestPeak(isWater_example)

