        if grid[i][0] == 0:
            for j in range(len(grid[i])):
                if grid[i][j] == 0:
                    grid[i][j] = 1
                else:
                    grid[i][j] = 0
    for j in range(1, len(grid[0])):
        count = 0
        for i in range(len(grid)):
            if grid[i][j] == 1:
                count += 1
        if count < len(grid) - count:
            for i in range(len(grid)):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                else:
                    grid[i][j] = 1
    result = 0
    for row in grid:
        binary = ""
        for num in row:
            binary += str(num)
        result += int(binary, 2)
    return result

