        for num in row:
            binary += str(num)
        result += int(binary, 2)
    return result
class Solution:

    def matrixScore(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        for i in range(m):
            if grid[i][0] == 0:
                for j in range(n):
                    if grid[i][j] == 0:
                        grid[i][j] = 1
                    else:
                        grid[i][j] = 0
        for j in range(n):
            zero_col_count = 0
            for i in range(m):
                if not grid[i][j]:
                    zero_col_count += 1
            if zero_col_count > m // 2:
                for k in range(len(grid)):
                    grid[k][j] = 0 if grid[k][j] else 1
        ans = 0
        for i in range(len(grid)):
            grid[i] = map(str, grid[i])
            str1 = '0b' + ''.join(grid[i])
            int1 = int(str1, 2)
            ans = ans + int1
        return ans
