class Solution:

    def haveConflict(self, event1: List[str], event2: List[str]) -> bool:
        hour1a, minute1a = map(int, event1[0].split(':'))
        hour1b, minute1b = map(int, event1[1].split(':'))
        hour2a, minute2a = map(int, event2[0].split(':'))
        hour2b, minute2b = map(int, event2[1].split(':'))
        if hour2a == hour1a or hour2b == hour1b:
            return True
        if hour2a == hour1b:
            if minute2a <= minute1b:
                return True
            else:
                return False
        if hour2b == hour1a:
            if minute2b >= minute1a:
                return True
            else:
                return False
        for hh in range(hour2a, hour2b + 1):
            if hour1a <= hh <= hour1b:
                return True
        return False
def test_simple_overlapping_events():
    solution_instance = Solution()
    event1 = ['10:00', '11:00']
    event2 = ['10:30', '11:30']
    assert check_conflict(event1, event2) == solution_instance.haveConflict(event1, event2)
