def min_operations(nums):
    smallest_nonzero = float('inf')
    for num in nums:
        if num != 0:
            smallest_nonzero = min(smallest_nonzero, num)
    operations = 0
    for num in nums:
        if num > 0:
            operations += (num - smallest_nonzero) // smallest_nonzero
            if (num - smallest_nonzero) % smallest_nonzero != 0:
                operations += 1
    return operations

