from typing import *
from collections import *
from math import *

def min_operations(nums):
    smallest_nonzero = float('inf')
    for num in nums:
        if num != 0:
            smallest_nonzero = min(smallest_nonzero, num)
    operations = 0
    for num in nums:
        if num > 0:
            operations += (num - smallest_nonzero) // smallest_nonzero
            if (num - smallest_nonzero) % smallest_nonzero != 0:
                operations += 1
    return operations
class Solution:

    def minimumOperations(self, nums: List[int]) -> int:
        minOperations = 0
        tempList = nums[:]
        while not isAllElementsZero(tempList):
            minElement = getMinNonZeroElement(tempList)
            minOperations += 1
            for j in range(len(tempList)):
                if tempList[j] != 0:
                    tempList[j] -= minElement
                else:
                    continue
        return minOperations
def isAllElementsZero(nums):
    for element in nums:
        if element != 0:
            return False
    return True
def getMinNonZeroElement(nums):
    minElem = float('inf')
    for element in nums:
        if element != 0 and element < minElem:
            minElem = element
        else:
            continue
    return minElem
def test_simple_case():
    s = Solution()
    assert min_operations([2, 5, 3]) == s.minimumOperations([2, 5, 3])
def test_edge_case():
