def num_valid_times(time):
    count = 0
    for h in range(24):
        for m in range(60):
            if (str(h).zfill(2) + ':' + str(m).zfill(2))[:5] == time.replace('?', '0') or (str(h).zfill(2) + ':' + str(m).zfill(2))[:5] == time.replace('?', '9'):
                count += 1
            else:
                num = time.count('?')
                temp = str(h).zfill(2) + ':' + str(m).zfill(2)
                if temp.count(':') == 1 and len(temp) == 5 and num == 2:
                    if all(c.isdigit() or c == '?' for c in temp):
                        count += 1
                elif num == 1 and '?' in temp:
                    count += 1
    return count

