class Solution:

    def countTime(self, time: str) -> int:
        answer = 1
        n = 5
        i = 0
        while i != n:
            if time[i] != '?' and i == 0 and (time[i + 1] != '?'):
                i = 3
            elif time[i] == '?' and i == 0 and (time[i + 1] == '?'):
                answer *= 24
