            elif time[i] == '?' and i == 0 and (time[i + 1] != '?') and (int(time[i + 1]) > 3):
                answer *= 2
                i = 3
            elif time[i] == '?' and i == 0 and (time[i + 1] != '?') and (int(time[i + 1]) <= 3):
                answer *= 3
                i = 3
            elif time[i] == '2' and i == 0 and (time[i + 1] == '?'):
                answer *= 4
                i = 3
            elif time[i] != '?' and (time[i] == '0' or time[i] == '1') and (i == 0) and (time[i + 1] == '?'):
