def min_operations(grid, x):
    elements = set()
    for row in grid:
        elements.update(row)  # Get unique elements in the grid

    min_ops = float('inf')  # Initialize minimum operations to infinity

    for elem in elements:
        ops = 0
        for row in grid:
            for col in row:
                if abs(col - elem) % x != 0:  # Check if difference is divisible by x
                    if (col - elem) % x == 0:
                        ops += abs(col - elem) // x  # Add number of x-subtraction operations required
                    else:
                        ops = float('inf')  # If not divisible, update ops to infinity and break
                        break
            if ops == float('inf'):  # Break out of outer loop if ops is infinity
                break
        min_ops = min(min_ops, ops)  # Update minimum operations if lower value is found

    return min_ops if min_ops < float('inf') else -1  # Return min operations or -1 if not possible

