class Solution:

    def minOperations(self, grid: List[List[int]], x: int) -> int:
        li = []
        for val in grid:
            li += val
        li.sort()
        median = li[len(li) // 2]
        ops = 0
        for val in li:
            if abs(val - median) % x != 0:
                return -1
            ops += abs(val - median) // x
        return ops
