def isPathCrossing(path: str) -> bool:
    visited = {(0,0)}
    x,y = 0,0
    for move in path:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        else:
            x -= 1
        if (x,y) in visited:
            return True
        visited.add((x,y))
    return False

