class Solution:

    def isPathCrossing(self, path: str) -> bool:
        directions = {'N': [0, 1], 'E': [1, 0], 'W': [-1, 0], 'S': [0, -1]}
        visited = set()
        visited.add((0, 0))
        curr_x, curr_y = (0, 0)
        for i in path:
            curr_x += directions[i][0]
            curr_y += directions[i][1]
            if (curr_x, curr_y) not in visited:
                visited.add((curr_x, curr_y))
            else:
                return True
        return False
