class Solution:

    def scoreOfParentheses(self, s: str) -> int:
        a_plus_b = []
        count = 0
        start = 0
        for i in range(len(s)):
            if s[i] == '(':
                count += 1
            elif s[i] == ')':
                count -= 1
            if count == 0:
                a_plus_b.append(s[start:i + 1])
                start = i + 1
        solution = 0
        for sub_string in a_plus_b:
            sub_solution = 0
            count = 0
            check_point = 1
            for p in sub_string:
                if p == '(':
                    count += 1
                    if check_point == 0:
                        check_point = 1
                elif p == ')':
                    count -= 1
                    if check_point == 1:
                        solution += 2 ** count
                        check_point = 0
            solution += sub_solution
            sub_solution = 0
        return solution
def test_simple_case():
    s = '()'
    sol_instance = Solution()
    assert score_of_parentheses(s) == sol_instance.scoreOfParentheses(s)
def test_edge_case():
    s = '(())'
    sol_instance = Solution()
    assert score_of_parentheses(s) == sol_instance.scoreOfParentheses(s)
def test_difficult_case():
    s = '(()(()))'
    sol_instance = Solution()
    assert score_of_parentheses(s) == sol_instance.scoreOfParentheses(s)

