class Solution:

    def minimumRecolors(self, blocks: str, k: int) -> int:
        n = len(blocks)
        minimum = n
        L, R = (0, 0)
        length = 0
        white = 0
        while R < len(blocks):
            length += 1
            cur = blocks[R]
            if cur == 'W':
                white += 1
            while length == k:
                minimum = min(minimum, white)
                length -= 1
                if blocks[L] == 'W':
                    white -= 1
                L += 1
            R += 1
        return minimum
