class Solution:

    def numTilePossibilities(self, tiles: str) -> int:
        ans = set()
        n = len(tiles)

        def helper(fa, cur):
            nonlocal n, ans, tiles
            ans.add(cur[:])
            if len(cur) == n:
                return
            for i in range(0, n, 1):
                if fa[i] == 0:
                    fa[i] = 1
                    cur += tiles[i]
                    helper(fa, cur)
                    fa[i] = 0
                    cur = cur[:len(cur) - 1]
                else:
                    continue
        boolean_arr = [0 for _ in range(n)]
        helper(boolean_arr, '')
        return len(ans) - 1
def test_simple_case():
    solution_instance = Solution()
