def distanceValue(arr1, arr2, d):
    distance = 0
    for i in arr1:
        for j in arr2:
            if abs(i - j) <= d:
                break
        else:
            distance += 1
    return distance
class Solution:

    def findTheDistanceValue(self, arr1: List[int], arr2: List[int], d: int) -> int:
        ans = 0
        arr2.sort()

        def helper(e, a):
            L, R = (0, len(a) - 1)
            while L <= R:
                mid = (L + R) // 2
                if a[mid] == e:
                    return True
                elif a[mid] > e:
                    R = mid - 1
                    continue
                else:
                    L = mid + 1
                    continue
            return False
        for num in arr1:
            flag = True
            for i in range(num - d, num + d + 1):
                if helper(i, arr2):
                    flag = False
                    break
            if flag:
                ans += 1
        return ans
def test_simple_case():
    s = Solution()
    assert distanceValue([1, 2, 3], [1, 4], 1) == s.findTheDistanceValue([1, 2, 3], [1, 4], 1)
