def min_days(n):
    days = 0
    while n > 1:
        if n % 2 == 0:
            n /= 2
        elif n % 3 == 0:
            n = 2 * (n / 3)
        else:
            n -= 1
        days += 1
    return days + 1 if n == 1 else 0

