from typing import *
from collections import *
from math import *

def is_crossing(distance):
    x = 0
    y = 0
    direction = 0
    for i in range(len(distance)):
        if direction == 0:
            y += distance[i]
        elif direction == 1:
            x -= distance[i]
        elif direction == 2:
            y -= distance[i]
        elif direction == 3:
            x += distance[i]
        direction = (direction + 1) % 4
        if direction == 0 and (x != 0 or y != 0):
            return True
    return False
class Solution:

    def isSelfCrossing(self, x: List[int]) -> bool:

        def intersect(p1, p2, p3, p4):
            v1 = p2 - p1
            if v1.real == 0:
                return p1.imag <= p3.imag <= p2.imag and p3.real <= p1.real <= p4.real
            return p3.imag <= p1.imag <= p4.imag and p1.real <= p3.real <= p2.real

        def overlap(p1, p2, p3, p4):
            v1 = p2 - p1
            if v1.real == 0:
                return min(p2.imag, p4.imag) >= max(p1.imag, p3.imag) and p1.real == p3.real
            return min(p2.real, p4.real) >= max(p1.real, p3.real) and p1.imag == p3.imag
        uv = complex(0, 1)
        p = complex(0, 0)
        segments = deque()
        for s in x:
            segments.append(sorted([p, (np := (p + uv * s))], key=lambda x: (x.real, x.imag)))
            if len(segments) > 5 and intersect(*segments[-1], *segments[-6]):
                return True
            if len(segments) > 4 and overlap(*segments[-1], *segments[-5]):
                return True
            if len(segments) > 3 and intersect(*segments[-1], *segments[-4]):
                return True
            if len(segments) == 6:
                segments.popleft()
            p = np
            uv *= complex(0, 1)
        return False
def test_simple_case():
    sol_instance = Solution()
    distance = [10, 5, 2, 5]
    assert is_crossing(distance) == sol_instance.isSelfCrossing(distance)
