from collections import Counter

def minStickers(stickers, target):
    # step 1: convert all stickers and target to character count dictionaries
    # step 2: dfs with memoization to find minimum number of stickers
    def dfs(sticker_counts, target_counts):
        if target in memo:
            return memo[target]
        if not target_counts:
            return 0
        res = float('inf')
        for sticker_count in sticker_counts:
            # check if the sticker can be used to make progress towards target
            if not any(target_counts & sticker_count):
                continue
            # create a new target_counts by subtracting the sticker count
            new_target_counts = target_counts - sticker_count
            # recursively find the minimum number of stickers needed
            sub_res = dfs(sticker_counts, new_target_counts)
            if sub_res != -1:
                res = min(res, sub_res + 1)
        memo[target] = -1 if res == float('inf') else res
        return memo[target]

    sticker_counts = []
    for sticker in stickers:
        sticker_counts.append(Counter(sticker))
    target_counts = Counter(target)
    memo = {}
    return dfs(sticker_counts, target_counts)

