class Solution:

    @staticmethod
    def substract(c1, c2):
        remove_keys = []
        result = ''
        for k in c1.keys():
            if k in c2:
                c1[k] -= c2[k]
                if c1[k] <= 0:
                    remove_keys.append(k)
            if c1[k] > 0:
                result += k + str(c1[k])
        for key in remove_keys:
            c1.pop(key, None)
        return (c1, result)

    def minStickers(self, stickers: List[str], target: str) -> int:
        target_count = Counter(target)
        stickers_counter = []
        s1 = set(target_count.keys())
        s2 = set()
        for i in range(len(stickers)):
            sticker = stickers[i]
            sticker_counter = defaultdict(int)
            for letter in sticker:
                if letter in target_count:
                    sticker_counter[letter] += 1
            stickers_counter.append(sticker_counter)
            s2.update(sticker_counter.keys())
        if s2 != s1:
            return -1
        total_letters = sum(target_count.values())
        counter = 0
        q = deque([target_count])
        visited = set()
        while q:
            q_size = len(q)
            for _ in range(q_size):
                target_count = q.popleft()
                for sticker in stickers_counter:
                    tmp, encoded = self.substract(target_count.copy(), sticker)
                    if sum(tmp.values()) == 0:
                        return counter + 1
                    if encoded not in visited:
                        q.append(tmp)
                        visited.add(encoded)
            counter += 1
        return -1
def test_simple_case():
    stickers = ['red', 'red', 'blue', 'green']
    target = 'red'
    sol = Solution()
    assert minStickers(stickers, target) == sol.minStickers(stickers, target)
def test_edge_case():
    stickers = ['yellow', 'red']
    target = 'redyellowred'
    sol = Solution()
    assert minStickers(stickers, target) == sol.minStickers(stickers, target)
def test_difficult_case():
    stickers = ['orange', 'purple', 'red']
    target = 'redpurredorange'
    sol = Solution()
    assert minStickers(stickers, target) == sol.minStickers(stickers, target)

