from typing import *
from collections import *
from math import *

def time_sort(arr):
    n = len(arr)
    bucket_size = round(n / 30)
    min_val = min(arr)
    max_val = max(arr)
    value_range = max_val - min_val + 1
    buckets = [[] for _ in range(bucket_size)]
    for i in range(n):
        index = int((arr[i] - min_val) / value_range * (bucket_size - 1))
        buckets[index].append(arr[i])
    for i in range(bucket_size):
        buckets[i].sort()
    result = []
    for i in range(bucket_size):
        result += buckets[i]
    return result
def binary_search(lst, item, start, end):
    if start == end:
        if lst[start] > item:
            return start
        else:
            return start + 1
    if start > end:
        return start
    mid = (start + end) // 2
    if lst[mid] < item:
        return binary_search(lst, item, mid + 1, end)
    elif lst[mid] > item:
        return binary_search(lst, item, start, mid - 1)
    else:
        return mid
def insertion_sort(lst):
    length = len(lst)
    for index in range(1, length):
        value = lst[index]
        pos = binary_search(lst, value, 0, index - 1)
        lst = lst[:pos] + [value] + lst[pos:index] + lst[index + 1:]
    return lst
def merge(left, right):
    if not left:
        return right
    if not right:
        return left
    if left[0] < right[0]:
        return [left[0]] + merge(left[1:], right)
    return [right[0]] + merge(left, right[1:])
def time_sort(lst):
    runs, sorted_runs = ([], [])
    length = len(lst)
    new_run = [lst[0]]
    sorted_array = []
    for i in range(1, length):
        if i == length - 1:
            new_run.append(lst[i])
            runs.append(new_run)
            break
        if lst[i] < lst[i - 1]:
            if not new_run:
                runs.append([lst[i - 1]])
                new_run.append(lst[i])
            else:
                runs.append(new_run)
                new_run = []
        else:
            new_run.append(lst[i])
    for run in runs:
        sorted_runs.append(insertion_sort(run))
    for run in sorted_runs:
        sorted_array = merge(sorted_array, run)
    return sorted_array
def test_simple_case():
    assert time_sort([3, 1, 4, 1, 5, 9, 2, 6, 5, 3]) == time_sort([3, 1, 4, 1, 5, 9, 2, 6, 5, 3])
def test_edge_case():
    assert time_sort([9, 8, 7, 6, 5, 4, 3, 2, 1, 0]) == time_sort([9, 8, 7, 6, 5, 4, 3, 2, 1, 0])
def test_difficult_case():
    assert time_sort([5, 1, 2, 7, 3, 8, 4, 9, 6, 0]) == time_sort([5, 1, 2, 7, 3, 8, 4, 9, 6, 0])

