from typing import *
from collections import *
from math import *

def remove_occurrences(part: str, s: str) -> str:
    while part.find(s) >= 0:
        part = part[:part.find(s)] + part[part.find(s) + len(s):]
    return part
class Solution:

    def removeOccurrences(self, s: str, part: str) -> str:

        def prefix_function(string):
            result = [0] * len(string)
            for i in range(1, len(string)):
                k = result[i - 1]
                while k > 0 and string[i] != string[k]:
                    k = result[k - 1]
                if string[i] == string[k]:
                    k += 1
                result[i] = k
            return result
        pi = prefix_function(part)
        stack = []
        iter_index, index = (0, 0)
        while iter_index < len(s):
            ch = s[iter_index]
            if part[index] == ch:
                index += 1
                stack.append((ch, index))
                if index == len(part):
                    for _ in range(len(part)):
                        stack.pop()
                    if len(stack) > 0:
                        _, index = stack[-1]
                    else:
                        index = 0
            elif index > 0:
                index = pi[index - 1]
                iter_index -= 1
            else:
                stack.append((ch, index))
            iter_index += 1
        return ''.join((ch for ch, _ in stack))
def test_simple_case():
    solution_instance = Solution()
    assert remove_occurrences('hello', 'll') == solution_instance.removeOccurrences('hello', 'll')
def test_edge_case():
    solution_instance = Solution()
