def maxScore(power: int, tokens: List[int]) -> int:
    score = 0
    left, right = 0, len(tokens) - 1
    while left <= right:
        if power >= tokens[left]:
            power -= tokens[left]
            score += 1
            left += 1
        elif score > 0:
            power += tokens[right]
            score -= 1
            right -= 1
        else:
            break
    return score

