class Solution:

    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:
        score = 0
        d = deque(sorted(tokens))
        while d:
            if power < d[0]:
                if score > 0 and len(d) > 1:
                    power += d.pop()
                    score -= 1
                else:
                    return score
            else:
                power -= d.popleft()
                score += 1
        return score
def test_simple_case():
    s = Solution()
    assert maxScore(100, [100, 200, 300, 600, 900, 1200]) == s.bagOfTokensScore([100, 200, 300, 600, 900, 1200], 100)
