def num_pyramid_plots(grid):
    n = len(grid)
    m = len(grid[0])
    total = 0

    # pyramidal plots
    for r in range(n):
        for c in range(m):
            for h in range(1, min(n-r, c+1)+1):
                count = 0
                for i in range(r, r+h):
                    for j in range(c-(i-r), c+(i-r)+1):
                        if i>=0 and i<n and j>=0 and j<m and grid[i][j]==1:
                            count += 1
                if count > 1:
                    total += 1

    # inverse pyramidal plots
    for r in range(n-1, -1, -1):
        for c in range(m):
            for h in range(1, min(r+1, m-c)+1):
                count = 0
                for i in range(r-h+1, r+1):
                    for j in range(c-(r-i), c+(r-i)+1):
                        if i>=0 and i<n and j>=0 and j<m and grid[i][j]==1:
                            count += 1
                if count > 1:
                    total += 1

    return total

