def num_pyramid_plots(grid):
    n = len(grid)
    m = len(grid[0])
    total = 0
    for r in range(n):
        for c in range(m):
            for h in range(1, min(n - r, c + 1) + 1):
                count = 0
                for i in range(r, r + h):
                    for j in range(c - (i - r), c + (i - r) + 1):
                        if i >= 0 and i < n and (j >= 0) and (j < m) and (grid[i][j] == 1):
                            count += 1
                if count > 1:
                    total += 1
    for r in range(n - 1, -1, -1):
        for c in range(m):
            for h in range(1, min(r + 1, m - c) + 1):
                count = 0
                for i in range(r - h + 1, r + 1):
                    for j in range(c - (r - i), c + (r - i) + 1):
                        if i >= 0 and i < n and (j >= 0) and (j < m) and (grid[i][j] == 1):
                            count += 1
                if count > 1:
                    total += 1
    return total
class Solution:

    def countPyramids(self, grid: List[List[int]]) -> int:

        def check(x, y):
            count = 0
            to_check = {(1, 0), (1, -1), (1, 1)}
            for dx, dy in to_check:
                if 0 <= x + dx < len(grid) and 0 <= y + dy < len(grid[0]) and (grid[x + dx][y + dy] == 1):
                    count += 1
            if count == 3:
                return True
            else:
                return False
        memo = {}

        def dp(x, y):
            if (x, y) in memo:
                return memo[x, y]
            levels = 0
            if check(x, y) == True:
                levels += 1
            else:
                return levels
            to_check = {(1, 0), (1, -1), (1, 1)}
            t = float('inf')
            for dx, dy in to_check:
                if 0 <= x + dx < len(grid) and 0 <= y + dy < len(grid[0]) and (grid[x + dx][y + dy] == 1):
                    t = min(t, dp(x + dx, y + dy))
            memo[x, y] = levels + t
            return levels + t
        ans = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    ans += dp(i, j)
        memo = {}
        grid = grid[::-1]
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    ans += dp(i, j)
        return ans
def test_simple_case():
    grid = [[0, 1, 1, 0], [1, 1, 1, 1]]
    solution_instance = Solution()
    assert num_pyramid_plots(grid) == solution_instance.countPyramids(grid)
