from typing import *
from collections import *
from math import *

def prisonAfterNDays(cells: List[int], n: int) -> List[int]:

    def getNextDay(cells):
        new_cells = [0] * len(cells)
        for i in range(1, len(cells) - 1):
            if cells[i - 1] == cells[i + 1]:
                new_cells[i] = 1
        return new_cells
    seen = {}
    for i in range(n):
        cell_tuple = tuple(cells)
        if cell_tuple in seen:
            loop_len = i - seen[cell_tuple]
            return prisonAfterNDays(cells, (n - i) % loop_len)
        else:
            seen[cell_tuple] = i
            cells = getNextDay(cells)
    return cells
class Solution:

    def prisonAfterNDays(self, cells: List[int], n: int) -> List[int]:
        if not n:
            return cells
        cells = convert_cells(cells)
        day1 = str(cells)
        n -= 1
        counter = 0
        while n:
            new_cells = convert_cells(cells)
            n -= 1
            counter += 1
            if str(new_cells) == day1:
                n = n % counter
            cells = new_cells
        return map(int, cells)
def convert_cells(cells):
    cells2 = cells.copy()
