def time_to_type(word):
    pointer = 'a'
    time = 0
    for char in word:
        clockwise = abs(ord(pointer) - ord(char))
        anticlockwise = 26 - clockwise
        time += min(clockwise, anticlockwise)
        pointer = char
    return time
class Solution:

    def minTimeToType(self, word: str) -> int:
        if len(word) == 1:
            return len(word) + min(ord(word[0]) - ord('a'), 26 - (ord(word[0]) - ord('a')))
        move = 0
        for i in range(len(word)):
            if i == 0:
                move += min(ord(word[0]) - ord('a'), 26 - (ord(word[0]) - ord('a')))
            elif ord(word[i]) > ord(word[i - 1]):
                move += min(abs(ord(word[i]) - ord(word[i - 1])), abs(26 - (ord(word[i]) - ord(word[i - 1]))))
            elif ord(word[i - 1]) > ord(word[i]):
                move += min(abs(ord(word[i - 1]) - ord(word[i])), abs(26 - (ord(word[i - 1]) - ord(word[i]))))
        return move + len(word)
def test_simple_case():
