def isSubsequence(t: str, s: str) -> bool:
    t_length = len(t)
    s_length = len(s)
    t_index = 0
    s_index = 0
    while t_index < t_length and s_index < s_length:
        if t[t_index] == s[s_index]:
            t_index += 1
        s_index += 1
    return t_index == t_length

