class Solution:

    def findLonely(self, nums: List[int]) -> List[int]:
        answer = []
        nums.sort()
        n = len(nums)
        if len(nums) == 1:
            return nums
        for i in range(n):
            if i == 0:
                if nums[i] != nums[i + 1] and nums[i] != nums[i + 1] - 1:
                    answer.append(nums[i])
            elif i == n - 1:
                if nums[i] != nums[i - 1] and nums[i] != nums[i - 1] + 1:
                    answer.append(nums[i])
            elif 0 < i < n - 1 and nums[i] == nums[i - 1]:
                continue
            elif nums[i] != nums[i + 1] - 1 and nums[i] != nums[i - 1] + 1 and (nums[i] != nums[i - 1]) and (nums[i] != nums[i + 1]):
                answer.append(nums[i])
        return answer
