from typing import *
from collections import *
from math import *

def max_length_subarray(nums1, nums2):
    n1, n2 = (len(nums1), len(nums2))
    dp = [[0] * (n2 + 1) for _ in range(n1 + 1)]
    max_len = 0
    start_idx = None
    for i in range(1, n1 + 1):
        for j in range(1, n2 + 1):
            if nums1[i - 1] == nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    start_idx = i - max_len
            else:
                dp[i][j] = 0
    return nums1[start_idx:start_idx + max_len]
class Solution:

    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        l, r = (0, min(len(nums1), len(nums2)) + 1)
        while l < r:
            k = l + (r - l) // 2
            if self.exist_length_k(nums1, nums2, k):
                l = k + 1
            else:
                r = k
        return l - 1

    def exist_length_k(self, nums1: List[int], nums2: List[int], k: int, p=101, m=10 ** 9 + 7) -> bool:
        if k == 0:
            return True
        s1 = self.rolling_hash(nums1, k)
        s2 = self.rolling_hash(nums2, k)
        if len(s1) > len(s2):
            s1, s2 = (s2, s1)
        for h in s1:
            if h in s2:
                return True
        return False

    def rolling_hash(self, nums: List[int], k: int, p=101, m=10 ** 9 + 7) -> Set[int]:
        if k == 0:
            return set()
        s = set()
        t = p ** k % m
        h = 0
        for i in range(k):
            h = (h * p + nums[i]) % m
        s.add(h)
        for i in range(k, len(nums)):
            h = (h * p - nums[i - k] * t + nums[i]) % m
            s.add(h)
        return s
