def can_cross(stones):
    last_stone = stones[-1]
    positions = set(stones)
    jumps = {}
    return backtrack(positions, 0, 1, last_stone, jumps)

def backtrack(positions, curr_pos, jump_size, last_stone, jumps):
    if curr_pos == last_stone:
        return True

    if (curr_pos, jump_size) in jumps:
        return jumps[(curr_pos, jump_size)]

    for i in range(-1, 2):
        next_jump = jump_size + i
        next_pos = curr_pos + next_jump

        if next_pos in positions and next_jump != 0:
            if backtrack(positions, next_pos, next_jump, last_stone, jumps):
                jumps[(curr_pos, jump_size)] = True
                return True

    jumps[(curr_pos, jump_size)] = False
    return False

stones = [0,1,3,5,6,8,12,17]
print(can_cross(stones)) # True

