def backtrack(positions, curr_pos, jump_size, last_stone, jumps):
    if curr_pos == last_stone:
        return True
    if (curr_pos, jump_size) in jumps:
        return jumps[curr_pos, jump_size]
    for i in range(-1, 2):
        next_jump = jump_size + i
        next_pos = curr_pos + next_jump
        if next_pos in positions and next_jump != 0:
            if backtrack(positions, next_pos, next_jump, last_stone, jumps):
                jumps[curr_pos, jump_size] = True
                return True
    jumps[curr_pos, jump_size] = False
    return False
class Solution:

    def canCross(self, stones: List[int]) -> bool:
        jump_mods = [-1, 0, 1]
        stone_ref = {}
        prev = 0
        for i, stone in enumerate(stones):
            stone_ref[stone] = i
            if stone - prev > i:
                return False
            prev = stone
        stack = [(0, 0)]
        seen = set()
        while stack:
            jump, stone = stack.pop()
            seen.add((jump, stone))
            if stone == stones[-1]:
                return True
            for mod in jump_mods:
                if stone + jump + mod in stone_ref and stone_ref[stone + jump + mod] > stone_ref[stone]:
                    if (jump + mod, stone + jump + mod) not in seen:
                        stack.append((jump + mod, stone + jump + mod))
        return False
def test_simple_case():
    stones = [0, 1, 3, 5, 6, 8, 12, 17]
    solution_instance = Solution()
    assert can_cross(stones) == solution_instance.canCross(stones)
def test_edge_case():
    stones = [0, 2]
    solution_instance = Solution()
    assert can_cross(stones) == solution_instance.canCross(stones)
