from typing import *
from collections import *
from math import *

def sum_without_operators(b, c):
    while c != 0:
        a = b & c
        b = b ^ c
        c = a << 1
    return b
class Solution:

    def getSum(self, a: int, b: int) -> int:

        def bin2int(bin_list):
            result = 0
            for i, v in enumerate(bin_list):
                result += pow(2, i) * v
            return result
        if a == 0 or b == 0:
            return a if b == 0 else b
        elif a > 0 and b > 0 or (a < 0 and b < 0):
            a_bin = list(map(lambda e: int(e), '{:032b}'.format(abs(a))[::-1]))
            b_bin = list(map(lambda e: int(e), '{:032b}'.format(abs(b))[::-1]))
            cb = 0
            r_bin = []
            for av, bv in zip(a_bin, b_bin):
                if av == 0 and bv == 0:
                    r_bin.append(cb)
                    cb = 0
                elif av == 0 and bv == 1 or (av == 1 and bv == 0):
                    if cb:
                        r_bin.append(0)
                    else:
                        r_bin.append(1)
                elif cb:
                    r_bin.append(1)
                else:
                    r_bin.append(0)
                    cb = 1
            result = bin2int(r_bin)
            return result if a > 0 else -1 * result
        else:
            is_negative = False
            if a > 0:
                if a < abs(b):
                    is_negative = True
                    a, b = (abs(b), a)
                else:
                    a, b = (a, abs(b))
            elif b < abs(a):
                is_negative = True
                a, b = (abs(a), b)
            else:
                a, b = (b, abs(a))
            a_bin = list(map(lambda e: int(e), '{:032b}'.format(a)[::-1]))
            b_bin = list(map(lambda e: int(e), '{:032b}'.format(b)[::-1]))
            r_bin = []
            for av, bv in zip(a_bin, b_bin):
                if av == bv:
                    r_bin.append(0)
                elif av == 1 and bv == 0:
                    r_bin.append(1)
                else:
                    r_bin.append(-1)
            for i in range(len(r_bin)):
                if r_bin[i] < 0:
                    for j in range(i + 1, len(r_bin)):
                        if r_bin[j] == 0:
                            r_bin[j] == 1
                        else:
                            r_bin[j] == 0
                            break
                    r_bin[i] == 1
