class Solution:

    def countBadPairs(self, nums: List[int]) -> int:
        for i in range(len(nums)):
            nums[i] -= i
        hashmap = {}
        for num in nums:
            if num not in hashmap:
                hashmap[num] = 1
            else:
                hashmap[num] += 1
        total_pairs_array = [i for i in range(len(nums))]
        total_pairs = sum(total_pairs_array)
        good_pairs = 0
        for k, v in hashmap.items():
            if v > 1:
                good_pairs_array = [i for i in range(v)]
                good_pairs += sum(good_pairs_array)
        bad_pairs = total_pairs - good_pairs
        return bad_pairs
def test_simple_case():
    sol_instance = Solution()
    nums = [2, 4, 6, 8]
    assert countBadPairs(nums) == sol_instance.countBadPairs(nums)
