class Solution:

    def intersection(self, nums1: List[int], nums2: List[int]) -> List[int]:
        hmap = {}
        ans = []
        m = len(nums2)
        n = len(nums1)
        if n > m:
            for i in range(m):
                hmap[nums2[i]] = 1
            for x in nums1:
                if x in hmap and hmap[x] != 0:
                    hmap[x] = 0
                    ans.append(x)
        else:
            for j in range(n):
                hmap[nums1[j]] = 1
            for y in nums2:
                if y in hmap and hmap[y] != 0:
                    hmap[y] = 0
                    ans.append(y)
        return ans
