from typing import *
from collections import *
from math import *

class First_class:

    def findCircleNum(self, isConnected: List[List[int]]) -> int:

        def dfs(i):
            for j in range(n):
                if isConnected[i][j] == 1 and visited[j] == 0:
                    visited[j] = 1
                    dfs(j)
        n = len(isConnected)
