class Solution:

    def minSteps(self, s: str, t: str) -> int:
        count_s = Counter(s)
        count_t = Counter(t)
        count = 0
        for i in count_t:
            if i not in count_s:
                count += count_t[i]
                count_s[i] = count_t[i]
            elif count_t[i] > count_s[i]:
                count += count_t[i] - count_s[i]
                count_s[i] += count_t[i] - count_s[i]
                count_s[i] = count_t[i]
            elif count_t[i] < count_s[i]:
                count += count_s[i] - count_t[i]
                count_t[i] += count_s[i] - count_t[i]
                count_t[i] = count_s[i]
        for i in count_s:
            if i not in count_t:
                count += count_s[i]
                count_t[i] = count_s[i]
            else:
                count += abs(count_t[i] - count_s[i])
                count_t[i] = count_t[i] + abs(count_t[i] - count_s[i])
        return count
