class Solution:

    def numSteps(self, s: str) -> int:
        if s == '1':
            return 0
        s = [a for a in str(s)]
        count = 0
        while 1 < len(s):
            if s[-1] == '1':
                s[-1] = '0'
                carry = True
                for i in range(len(s) - 2, -1, -1):
                    if carry == True:
                        if s[i] == '1':
                            s[i] = '0'
                            carry = True
                        else:
                            s[i] = '1'
                            carry = False
                            break
                if carry:
                    s.insert(0, '1')
            else:
                s = s[:-1]
            count += 1
        if s == ['0']:
            return null
        return count
