    solution_instance = Solution()
    assert find_x_with_f_of_k(6) == solution_instance.preimageSizeFZF(6)
def test_hard_case():
    solution_instance = Solution()
    assert find_x_with_f_of_k(5) == solution_instance.preimageSizeFZF(5)

