            elif abs(asteroid) == stack[-1]:
                stack.pop()
            break
        else:
            stack.append(asteroid)
    return stack
class Solution:

    def asteroidCollision(self, asteroids: List[int]) -> List[int]:
        low, high = (0, 0)
        result = []
        isPositive = False
        stack = []
        for i in range(len(asteroids)):
            if asteroids[i] < 0 and isPositive:
                if stack[-1] > abs(asteroids[i]):
                    continue
                elif stack[-1] == abs(asteroids[i]):
                    stack.pop()
                    if not stack:
                        isPositive = False
                    continue
                else:
                    while stack and stack[-1] < abs(asteroids[i]):
                        stack.pop()
                    if stack and stack[-1] == abs(asteroids[i]):
                        stack.pop()
                        if not stack:
                            isPositive = False
                        continue
                    elif stack and stack[-1] > abs(asteroids[i]):
                        continue
                    elif not stack:
                        isPositive = False
            if asteroids[i] > 0 and (not isPositive):
                isPositive = True
            if isPositive:
                stack.append(asteroids[i])
            if asteroids[i] < 0 and (not stack):
                result.append(asteroids[i])
        result += stack
        return result
def test_simple_case():
    solution_instance = Solution()
    assert asteroidCollision([5, 10, -5]) == solution_instance.asteroidCollision([5, 10, -5])
