class Solution:

    def taskSchedulerII(self, tasks: List[int], space: int) -> int:
        hashmap = {}
        day = 1
        i = 0
        while i < len(tasks):
            if tasks[i] not in hashmap:
                hashmap[tasks[i]] = day
                day += 1
                i += 1
                continue
            else:
                last_completed = hashmap[tasks[i]]
                if day > space + last_completed:
                    hashmap[tasks[i]] = day
                    day += 1
                    i += 1
                    continue
                else:
                    day = last_completed + space + 1
                    hashmap[tasks[i]] = day
                    day += 1
                    i += 1
        return day - 1
def test_simple_case():
    solution_instance = Solution()
    assert minDays([1, 2, 1, 2, 3, 1], 3) == solution_instance.taskSchedulerII([1, 2, 1, 2, 3, 1], 3)
def test_edge_case():
    solution_instance = Solution()
    assert minDays([5, 8, 8, 5], 2) == solution_instance.taskSchedulerII([5, 8, 8, 5], 2)
def test_difficult_case():
    solution_instance = Solution()
    assert minDays([1, 2, 1, 2, 3, 4, 1], 3) == solution_instance.taskSchedulerII([1, 2, 1, 2, 3, 4, 1], 3)

