class Solution:

    def scheduleCourse(self, courses: List[List[int]]) -> int:
        courses.sort(key=lambda x: x[1])
        totalDays = 0
        count = 0
        for i in range(len(courses)):
            if totalDays + courses[i][0] <= courses[i][1]:
                totalDays += courses[i][0]
                count += 1
            else:
                currCourseIndexWhichCantFit = i
                for j in range(i):
                    if courses[j][0] > courses[currCourseIndexWhichCantFit][0]:
                        currCourseIndexWhichCantFit = j
                if courses[currCourseIndexWhichCantFit][0] > courses[i][0]:
                    totalDays += courses[i][0] - courses[currCourseIndexWhichCantFit][0]
                courses[currCourseIndexWhichCantFit][0] = float('-inf')
        return count
def test_simple_case():
    sol_instance = Solution()
    courses = [[100, 200], [200, 400], [100, 300]]
    assert scheduleCourse(courses) == sol_instance.scheduleCourse(courses)
