from collections import Counter

def findShortestSubArray(nums):
    count = Counter(nums)
    degree = max(count.values())
    if degree == 1:
        return 1
    left, right = {}, {}
    for i, x in enumerate(nums):
        left.setdefault(x, i)
        right[x] = i
    return min(right[x] - left[x] + 1 for x in count if count[x] == degree)

