def minimum_boxes(n):
    dp = [float('inf')] * (n+1)
    dp[0] = 0
    for i in range(1, n+1):
        for j in range(1, int(i**(1/3))+1):
            cube = j**3
            dp[i] = min(dp[i], dp[i-cube]+1)
    return dp[n]

