from typing import *
from collections import *
from math import *

def minimum_boxes(n):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(1, int(i ** (1 / 3)) + 1):
            cube = j ** 3
            dp[i] = min(dp[i], dp[i - cube] + 1)
    return dp[n]
class Solution:

    def minimumBoxes(self, m: int) -> int:

        def cbrt(x):
            return x ** (1.0 / 3)
        x = cbrt(sqrt(3) * sqrt(243 * m ** 2 - 1) + 27 * m)
        n = ceil(x / cbrt(9) + 1 / (cbrt(3) * x) - 1)
        t_n = n * (n + 1) * (n + 2) // 6
        if m == t_n:
            return n * (n + 1) // 2
        ans = n * (n + 1) // 2
        j = t_n + 1
        while m < j:
            j -= n
            ans -= 1
            n -= 1
        return ans + 1
def test_simple_case():
    solution_instance = Solution()
    assert minimum_boxes(1) == solution_instance.minimumBoxes(1)
def test_medium_case():
    solution_instance = Solution()
    assert minimum_boxes(4) == solution_instance.minimumBoxes(4)
def test_complex_case():
    solution_instance = Solution()
    assert minimum_boxes(10) == solution_instance.minimumBoxes(10)

