class Solution:

    def minFlipsMonoIncr(self, s: str) -> int:

        def get_prefix(nums):
            res = []
            cur_sum = 0
            for num in nums:
                cur_sum += num
                res.append(cur_sum)
            return res

        def get_suffix(nums):
            res = []
            cur_sum = 0
            for num in reversed(nums):
                cur_sum += 1 - num
                res.append(cur_sum)
            return list(reversed(res))
