def radix_sort(arr):
    max_num = max(arr)
    exp = 1
    while max_num // exp > 0:
        buckets = [0] * 10
        for i in arr:
            buckets[(i // exp) % 10] += 1
        for i in range(1, 10):
            buckets[i] += buckets[i-1]
        res = [0] * len(arr)
        for i in reversed(arr):
            res[buckets[(i // exp) % 10] - 1] = i
            buckets[(i // exp) % 10] -= 1
        for i in range(len(arr)):
            arr[i] = res[i]
        exp *= 10
    return arr

