class Solution:

    def sortJumbled(self, mapping: List[int], nums: List[int]) -> List[int]:

        def getMappedNum(num):
            s = str(num)
            mappedNum = ''
            for c in s:
                mappedNum = mappedNum + str(mapping[int(c)])
            return int(mappedNum)
        sortedNums = []
        for num in nums:
            sortedNums.append((getMappedNum(num), num))
        sortedNums.sort(key=lambda x: x[0])
        for i, (_, num) in enumerate(sortedNums):
            nums[i] = num
        return nums
def test_simple_case():
    solution_instance = Solution()
    assert sort_by_mapping([991, 338, 38], [6, 6, 4, 2, 1, 0, 8, 10, 7, 1]) == solution_instance.sortJumbled([6, 6, 4, 2, 1, 0, 8, 10, 7, 1], [991, 338, 38])
