def validUtf8(data):
    """
    :type data: List[int]
    :rtype: bool
    """
    num_bytes_to_follow = 0

    for num in data:
        bin_num = format(num, '#010b')[-8:]
        if num_bytes_to_follow == 0:
            if bin_num[0] == '1':
                num_bytes_to_follow = len(bin_num.split('0')[0])
                if num_bytes_to_follow > 4 or num_bytes_to_follow == 1:
                    return False
                if num_bytes_to_follow > 1:
                    num_bytes_to_follow -= 1
            else:
                continue
        else:
            if not (bin_num[0] == '1' and bin_num[1] == '0'):
                return False
            num_bytes_to_follow -= 1
    return num_bytes_to_follow == 0

