def gardenFlower(n: int, paths: List[List[int]]) -> List[int]:
    answer = [0] * n
    graph = [[] for i in range(n)]
    for path in paths:
        graph[path[0]-1].append(path[1]-1)
        graph[path[1]-1].append(path[0]-1)
    for i in range(n):
        used_flower = [0,0,0,0]
        for j in graph[i]:
            used_flower[answer[j]] = 1
        for f in range(1,5):
            if used_flower[f-1] == 0:
                answer[i] = f
                break
    return answer

