class Solution:

    def gardenNoAdj(self, n: int, paths: List[List[int]]) -> List[int]:
        nodes = [x for x in range(n)]
        colour = [None] * n
        edges = {x: {} for x in range(n)}
        for x, y in paths:
            edges[x - 1][y - 1] = True
            edges[y - 1][x - 1] = True
        for node in range(n):
            adj = edges[node]
            blocked = [False] * n
            size = 4
            for x in adj:
                if colour[x] != None:
                    blocked[colour[x] - 1] = True
            if blocked[0] == False:
                colour[node] = 1
            elif blocked[1] == False:
                colour[node] = 2
            elif blocked[2] == False:
                colour[node] = 3
            elif blocked[3] == False:
                colour[node] = 4
        return colour
def test_simple_case():
    solution_instance = Solution()
    assert gardenFlower(3, [[1, 2], [2, 3], [3, 1]]) == solution_instance.gardenNoAdj(3, [[1, 2], [2, 3], [3, 1]])
