def exists_cycle(grid):
    visited = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if dfs(i, j, grid, visited, None, 0):
                return True
    return False

def dfs(i, j, grid, visited, prev, count):
    if count == 4 and (i, j) == prev:
        return True
    if (i, j) in visited:
        return False
    visited.add((i, j))
    if count == 0:
        prev = (i, j)
    if i > 0 and grid[i-1][j] == grid[i][j]:
        if dfs(i-1, j, grid, visited, (i, j), count+1):
            return True
    if i < len(grid)-1 and grid[i+1][j] == grid[i][j]:
        if dfs(i+1, j, grid, visited, (i, j), count+1):
            return True
    if j > 0 and grid[i][j-1] == grid[i][j]:
        if dfs(i, j-1, grid, visited, (i, j), count+1):
            return True
    if j < len(grid[0])-1 and grid[i][j+1] == grid[i][j]:
        if dfs(i, j+1, grid, visited, (i, j), count+1):
            return True
    visited.remove((i, j))
    return False

