from typing import *
from collections import *
from math import *

def nearestExit(maze: List[List[str]], entrance: List[int]) -> int:
    m, n = (len(maze), len(maze[0]))
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    q = deque()
    q.append(entrance)
    steps = 0
    while q:
        size = len(q)
        for i in range(size):
            curr = q.popleft()
            if curr[0] == 0 or curr[0] == m - 1 or curr[1] == 0 or (curr[1] == n - 1):
                return steps
            for direction in directions:
                r, c = (curr[0] + direction[0], curr[1] + direction[1])
                if 0 <= r < m and 0 <= c < n and (maze[r][c] == '.'):
                    maze[r][c] = '+'
                    q.append([r, c])
        steps += 1
    return -1
class Solution:

    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        queue = [(entrance, 0)]
        maze[entrance[0]][entrance[1]] = '+'
        while not len(queue) == 0:
            current, length = queue.pop(0)
            if current[1] + 1 < len(maze[0]):
                if maze[current[0]][current[1] + 1] == '.':
                    queue.append(([current[0], current[1] + 1], length + 1))
                    maze[current[0]][current[1] + 1] = '+'
            elif length > 0:
                return length
            if current[1] - 1 >= 0:
                if maze[current[0]][current[1] - 1] == '.':
                    queue.append(([current[0], current[1] - 1], length + 1))
                    maze[current[0]][current[1] - 1] = '+'
            elif length > 0:
                return length
            if current[0] + 1 < len(maze):
                if maze[current[0] + 1][current[1]] == '.':
                    queue.append(([current[0] + 1, current[1]], length + 1))
                    maze[current[0] + 1][current[1]] = '+'
            elif length > 0:
                return length
            if current[0] - 1 >= 0:
                if maze[current[0] - 1][current[1]] == '.':
                    queue.append(([current[0] - 1, current[1]], length + 1))
                    maze[current[0] - 1][current[1]] = '+'
            elif length > 0:
                return length
        return -1
def test_simple_case():
    s = Solution()
    maze = [['+', '+', '.', '+'], ['+', '.', '+', '+'], ['+', '.', '+', '.'], ['+', '.', '+', '+']]
    entrance = [1, 2]
    assert nearestExit(maze, entrance) == s.nearestExit(maze, entrance)
def test_edge_case():
    s = Solution()
    maze = [['.', '+', '.'], ['+', '.', '+'], ['+', '+', '.']]
    entrance = [1, 0]
    assert nearestExit(maze, entrance) == s.nearestExit(maze, entrance)
def test_difficult_case():
    s = Solution()
    maze = [['+', '+', '+'], ['.', '.', '.'], ['+', '+', '+']]
    entrance = [1, 0]
    assert nearestExit(maze, entrance) == s.nearestExit(maze, entrance)

