from math import *

def restoreMatrix(rowSum, colSum):
    m, n = (len(rowSum), len(colSum))
    res = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            res[i][j] = min(rowSum[i], colSum[j])
            rowSum[i] -= res[i][j]
            colSum[j] -= res[i][j]
    return res
class Solution:

    def restoreMatrix(self, rowSum: List[int], colSum: List[int]) -> List[List[int]]:
        ROW_SIZE = len(rowSum)
        COL_SIZE = len(colSum)
        mtx = [[0] * COL_SIZE for ri in range(ROW_SIZE)]
        for i, rs in enumerate(rowSum):
            mtx[i][0] = rs
        valid_row_set = set(list(filter(lambda ri: mtx[ri][0], range(ROW_SIZE))))
        for ci in range(1, COL_SIZE):
            cs = colSum[ci]
            empty_ri_list = []
            for ri in valid_row_set:
                if mtx[ri][0] < cs:
                    cs -= mtx[ri][0]
                    mtx[ri][ci] = mtx[ri][0]
                    mtx[ri][0] = 0
                    empty_ri_list.append(ri)
                elif mtx[ri][0] == cs:
                    mtx[ri][ci] = mtx[ri][0]
                    mtx[ri][0] = cs = 0
                    empty_ri_list.append(ri)
                    break
                elif mtx[ri][0] > cs:
                    mtx[ri][ci] = cs
                    mtx[ri][0] -= cs
                    break
            for eri in empty_ri_list:
                valid_row_set.remove(eri)
        return mtx
def test_simple_case():
    assert restoreMatrix([3, 8], [4, 7]) == Solution().restoreMatrix([3, 8], [4, 7])
def test_edge_case():
    assert restoreMatrix([5, 7, 10], [8, 6, 8]) == Solution().restoreMatrix([5, 7, 10], [8, 6, 8])
def test_difficult_case():
    assert restoreMatrix([14, 9], [7, 11, 2]) == Solution().restoreMatrix([14, 9], [7, 11, 2])

