def countDigitOne(n):
    count, x, k = 0, 1, 1
    while n >= x:
        d = int((n//x) % 10)
        count += (n//x//10 * x)
        if d > k:
            count += x
        elif d == k:
            count += n % x + 1
        k = d
        x *= 10
    return count

