    return radius
class Solution:

    def findRadius(self, houses: List[int], heaters: List[int]) -> int:
        houses.sort()
        heaters.sort()
        total, size = (len(houses), len(heaters))

        def valid_radius(r):
            house_offset = 0
            heater_offset = 0
            while house_offset < total:
                if abs(houses[house_offset] - heaters[heater_offset]) <= r:
                    house_offset += 1
                    continue
                if houses[house_offset] < heaters[heater_offset]:
                    return False
                    break
                while heater_offset < size and abs(houses[house_offset] - heaters[heater_offset]) > r:
                    heater_offset += 1
                if heater_offset >= size:
                    return False
                if abs(houses[house_offset] - heaters[heater_offset]) <= r:
                    house_offset += 1
                    continue
                else:
                    return False
                    break
            return True
        low, high = (0, max(abs(heaters[0] - houses[0]), abs(heaters[0] - houses[-1])))
        mid = (low + high) // 2
        while high - low > 1:
            if valid_radius(mid):
                high = mid
            else:
                low = mid
            mid = (low + high) // 2
        return low if valid_radius(low) else high
def test_simple_case():
    s = Solution()
    assert findRadius([1, 2, 3], [2]) == s.findRadius([1, 2, 3], [2])
