def addOperators(num, target):

    def backtrack(index, path, value, prev):
        nonlocal ans
        if index == len(num):
            if value == target:
                ans.append(path)
            return
        for i in range(index, len(num)):
            if i > index and num[index] == '0':
                break
            curr = int(num[index:i + 1])
            if index == 0:
                backtrack(i + 1, str(curr), curr, curr)
            else:
                backtrack(i + 1, path + '+' + str(curr), value + curr, curr)
                backtrack(i + 1, path + '-' + str(curr), value - curr, -curr)
                backtrack(i + 1, path + '*' + str(curr), value - prev + prev * curr, prev * curr)
    ans = []
    backtrack(0, '', 0, 0)
    return ans
class Solution:

    def addOperators(self, num: str, target: int) -> List[str]:
        exprs = []

        def recurse(idx, value, delta, exp):
            if idx == len(num):
                if value == target:
                    exprs.append(''.join(exp))
            for i in range(idx, len(num)):
                if num[idx] == '0' and i > idx:
                    return
                curr = int(num[idx:i + 1])
                curr_str = num[idx:i + 1]
                if idx == 0:
                    recurse(i + 1, curr, curr, exp + [curr_str])
                else:
                    recurse(i + 1, value + curr, curr, exp + ['+', curr_str])
                    recurse(i + 1, value - curr, -curr, exp + ['-', curr_str])
                    recurse(i + 1, value - delta + curr * delta, curr * delta, exp + ['*', curr_str])
        recurse(0, 0, 0, [])
        return exprs
def test_simple_case():
    solution_instance = Solution()
    assert sorted(addOperators('123', 6)) == sorted(solution_instance.addOperators('123', 6))
def test_edge_case():
