def maxIncreaseKeepingSkyline(grid):
    n = len(grid)
    row_maxes = [max(row) for row in grid]
    col_maxes = [max(col) for col in zip(*grid)]
    ans = 0
    for r in range(n):
        for c in range(n):
            ans += min(row_maxes[r], col_maxes[c]) - grid[r][c]
    return ans
class Solution:

    def maxIncreaseKeepingSkyline(self, grid: List[List[int]]) -> int:
        numOfTop = len(grid[0])
        numOfLeft = len(grid)
        topLimits = [0] * numOfTop
        leftLimits = [0] * numOfLeft
        for rowIdx in range(numOfLeft):
            leftLimits[rowIdx] = max(grid[rowIdx])
            for colIdx in range(numOfTop):
                topLimits[colIdx] = max(topLimits[colIdx], grid[rowIdx][colIdx])
        skySum = 0
        for rowIdx in range(numOfLeft):
            for colIdx in range(numOfTop):
                limit = min(topLimits[colIdx], leftLimits[rowIdx])
                skySum += limit - grid[rowIdx][colIdx]
        return skySum
def test_simple_case():
    solution_instance = Solution()
    assert maxIncreaseKeepingSkyline([[3, 0, 8, 4], [2, 4, 5, 7], [9, 2, 6, 3], [0, 3, 1, 0]]) == solution_instance.maxIncreaseKeepingSkyline([[3, 0, 8, 4], [2, 4, 5, 7], [9, 2, 6, 3], [0, 3, 1, 0]])
def test_edge_case():
    solution_instance = Solution()
    assert maxIncreaseKeepingSkyline([[0, 0, 0], [0, 0, 0], [0, 0, 0]]) == solution_instance.maxIncreaseKeepingSkyline([[0, 0, 0], [0, 0, 0], [0, 0, 0]])
