    sol_instance = Solution()
    assert count_valid_words(sentence) == sol_instance.countValidWords(sentence)
def test_complex_sentence_with_digits():
    sentence = 'cat-1  dog, cat!'
    sol_instance = Solution()
    assert count_valid_words(sentence) == sol_instance.countValidWords(sentence)

