def tribonacci(n):
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    else:
        t0, t1, t2 = 0, 1, 1
        for i in range(n-2):
            t3 = t0 + t1 + t2
            t0, t1, t2 = t1, t2, t3
        return t3

