def tribonacci(n):
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    else:
        t0, t1, t2 = (0, 1, 1)
        for i in range(n - 2):
            t3 = t0 + t1 + t2
            t0, t1, t2 = (t1, t2, t3)
        return t3
class Solution:

    def BottomUp(self, n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        elif n == 2:
            return 1
        first = 0
        second = 1
        third = 1
        for i in range(3, n + 1):
            current = first + second + third
            first = second
            second = third
            third = current
        return current

    def tribonacci(self, n: int) -> int:
        return self.BottomUp(n)
def test_simple_case():
    solution_instance = Solution()
    assert tribonacci(0) == solution_instance.tribonacci(0)
