from typing import *
from collections import *
from math import *

def maxDetonations(bombs):
    maxDet = 0
    for bomb in bombs:
        x, y, r = bomb
        count = 1
        for other in bombs:
            if other == bomb:
                continue
            ox, oy, orad = other
            if (ox - x) ** 2 + (oy - y) ** 2 <= r ** 2:
                count += 1
        if count > maxDet:
            maxDet = count
    return maxDet
class Solution:

    def maximumDetonation(self, bombs: List[List[int]]) -> int:
        connections = {idx: set() for idx in range(len(bombs))}
        for id1, (x1, y1, r1) in enumerate(bombs):
            for id2, (x2, y2, r2) in enumerate(bombs[id1 + 1:], id1 + 1):
                distance = (x1 - x2) ** 2 + (y1 - y2) ** 2
                if distance <= r1 ** 2:
                    connections[id1].add(id2)
                if distance <= r2 ** 2:
                    connections[id2].add(id1)
        self.max = 0
        self.solved = {}
        for idx in range(len(bombs)):
            visited = set([idx])
            self.dfs(idx, visited, connections)
            self.solved[idx] = visited
            self.max = max(self.max, len(visited))
        return self.max

    def dfs(self, current, visited, connections):
        if current in self.solved:
            visited.update(self.solved[current])
            return
        for idx in connections[current]:
            if idx not in visited:
                visited.add(idx)
                self.dfs(idx, visited, connections)
def test_simple_case():
    solution_instance = Solution()
    bombs = [[2, 1, 3], [6, 1, 4]]
    assert maxDetonations(bombs) == solution_instance.maximumDetonation(bombs)
def test_difficult_case():
    solution_instance = Solution()
