def maxNumberOfFamilies(n: int, reservedSeats: List[List[int]]) -> int:
    seats = {}
    for r, c in reservedSeats:
        if r in seats:
            seats[r].append(c)
        else:
            seats[r] = [c]
    count = (n - len(seats)) * 2
    for r in seats:
        left = right = middle = False
        for c in range(2, 10):
            if c in seats[r]:
                continue
            if c in [2, 3, 4, 5]:
                left = True
            elif c in [6, 7, 8, 9]:
                right = True
            elif c in [4, 5, 6, 7]:
                middle = True
        if not middle:
            if left and right:
                count += 1
            else:
                count += 2
    return count

