class Solution:

    def maxNumberOfFamilies(self, n: int, reservedSeats: List[List[int]]) -> int:
        count, reservedSeats, available_rows = (0, sorted(reservedSeats), n)
        row = reservedSeats[0][0]
        available_rows -= 1
        row_result = [0] * 10
        for seats in reservedSeats:
            sit = seats[1]
            if row == seats[0]:
                row_result[sit - 1] = 1
            else:
                spaces = 0
                for idx, chair in enumerate(row_result):
                    if chair == 0:
                        spaces += 1
                    else:
                        spaces = 0
                    if spaces >= 4 and idx in (4, 6, 8):
                        count += 1
                        spaces = 0
                row = seats[0]
                row_result = [0] * 10
                row_result[sit - 1] = 1
                available_rows -= 1
        spaces = 0
        for idx, chair in enumerate(row_result):
            if chair == 0:
                spaces += 1
            else:
                spaces = 0
            if spaces >= 4 and idx in (4, 6, 8):
                count += 1
                spaces = 0
        count = count + available_rows * 2
        return count
