from typing import *
from collections import *
from math import *

def smallestSum(arr):
    n = len(arr)
    dp = [[float('inf') for j in range(n)] for i in range(n)]
    for i in range(n):
        dp[i][i] = arr[i]
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            for k in range(i, j):
                left = dp[i][k]
                right = dp[k + 1][j]
                val = max(left, right)
                dp[i][j] = min(dp[i][j], val * arr[k])
    return dp[0][n - 1]
class Solution:

    def __init__(self):
        self.m = {}

    def mctFromLeafValues(self, arr: List[int]) -> int:

        def find_max(st, end, arr):
            if arr[st:end + 1] == []:
                return 0
            return max(arr[st:end + 1])

        def helper(st, en, arr):
            if st == en:
                self.m[str(st) + ' ' + str(en)] = 0
                return 0
            if en - st == 1:
                self.m[str(st) + ' ' + str(en)] = arr[st] * arr[en]
                return arr[st] * arr[en]
            if str(st) + ' ' + str(en) in self.m:
                return self.m[str(st) + ' ' + str(en)]
            ans = float('inf')
            for i in range(st, en):
                a = find_max(st, i, arr)
                b = find_max(i + 1, en, arr)
                temp = helper(st, i, arr) + helper(i + 1, en, arr)
                ans = min(ans, temp + a * b)
            self.m[str(st) + ' ' + str(en)] = ans
            return ans
        return helper(0, len(arr) - 1, arr)
def test_simple_case():
    solution_instance = Solution()
    assert smallestSum([6, 2, 4]) == solution_instance.mctFromLeafValues([6, 2, 4])
def test_edge_case():
    solution_instance = Solution()
    assert smallestSum([1, 2]) == solution_instance.mctFromLeafValues([1, 2])
def test_difficult_case():
    solution_instance = Solution()
    assert smallestSum([5, 4, 11]) == solution_instance.mctFromLeafValues([5, 4, 11])

