from typing import *
from collections import *
from math import *

def maxCoins(nums):
    nums = [1] + nums + [1]
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    for k in range(2, n):
        for left in range(0, n - k):
            right = left + k
            for i in range(left + 1, right):
                dp[left][right] = max(dp[left][right], nums[left] * nums[i] * nums[right] + dp[left][i] + dp[i][right])
    return dp[0][n - 1]
class Solution:

    def maxCoins(self, nums: List[int]) -> int:
        nums = [1] + nums + [1]
        size = len(nums)
        t = [[-1 for p in range(0, size + 1)] for q in range(0, size + 1)]
        return self.solve(nums, 1, size - 1, t)

    def solve(self, arr, i, j, t):
        if i >= j:
            return 0
        if t[i][j] > 0:
            return t[i][j]
        ans = float('-inf')
        for k in range(i, j):
            if t[i][k] != -1:
                left = t[i][k]
            else:
                left = self.solve(arr, i, k, t)
                t[i][k] = left
            if t[k + 1][j] != -1:
                right = t[k + 1][j]
            else:
                right = self.solve(arr, k + 1, j, t)
                t[k + 1][j] = right
            temp = left + right + arr[i - 1] * arr[k] * arr[j]
            ans = max(ans, temp)
        t[i][j] = ans
        return t[i][j]
def test_simple_case():
    solution_instance = Solution()
    assert maxCoins([3, 1, 5]) == solution_instance.maxCoins([3, 1, 5])
def test_edge_case():
