def recursive_bubble_sort(arr, n):
    if n == 1:
        return
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            arr[i], arr[i + 1] = (arr[i + 1], arr[i])
    recursive_bubble_sort(arr, n - 1)
def bubble_sort(list_data: list, length: int=0) -> list:
    length = length or len(list_data)
    swapped = False
    for i in range(length - 1):
        if list_data[i] > list_data[i + 1]:
            list_data[i], list_data[i + 1] = (list_data[i + 1], list_data[i])
            swapped = True
    return list_data if not swapped else bubble_sort(list_data, length - 1)
def test_simple_case():
    arr = [3, 2, 1]
    sorted_arr1 = recursive_bubble_sort(arr.copy(), len(arr))
    sorted_arr2 = bubble_sort(arr.copy(), len(arr))
