def longest_ideal_string(s: str, k: int) -> int:
    dp = [1] * len(s)
    for i in range(1, len(s)):
        for j in range(i):
            if abs(ord(s[i]) - ord(s[j])) <= k:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

