class Solution:

    def removeDuplicateLetters(self, s: str) -> str:
        n, lastIdx, insideStack, stack = (len(s), [0] * 26, [0] * 26, [])
        getIdx = lambda c: ord(c) - ord('a')
        for i in range(n):
            lastIdx[getIdx(s[i])] = i
        for i in range(n):
            currChar = s[i]
            if insideStack[getIdx(currChar)]:
                continue
            while stack and stack[-1] > currChar and (lastIdx[getIdx(stack[-1])] > i):
                insideStack[getIdx(stack.pop())] = 0
            stack.append(currChar)
            insideStack[getIdx(currChar)] = 1
        return ''.join(stack)
def test_simple_case():
    sol_instance = Solution()
    assert remove_duplicates('bcabc') == sol_instance.removeDuplicateLetters('bcabc')
