def is_palindrome(word):
    return word == word[::-1]
def first_palindromic_string(words):
    for word in words:
        if is_palindrome(word):
            return word
    return ''
class Solution:

    def firstPalindrome(self, words: List[str]) -> str:
        for word in words:
            word_length = len(word) // 2
            if not word_length:
                return word
            palindrome = True
            for idx in range(word_length):
                if word[idx] != word[-idx - 1]:
                    palindrome = False
                    break
            if palindrome:
                return word
        return ''
def test_simple_case():
    solution_instance = Solution()
    words = ['abc', 'car', 'racecar', 'cool']
    assert first_palindromic_string(words) == solution_instance.firstPalindrome(words)
def test_no_palindrome_case():
    solution_instance = Solution()
    words = ['hello', 'world', 'notepad']
    assert first_palindromic_string(words) == solution_instance.firstPalindrome(words)
def test_empty_input():
    solution_instance = Solution()
    words = []
    assert first_palindromic_string(words) == solution_instance.firstPalindrome(words)

