def findDisappearedNumbers(nums):
    """
    :type nums: List[int]
    :rtype: List[int]
    """
    result = []
    for i in range(len(nums)):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])
    for i in range(len(nums)):
        if nums[i] > 0:
            result.append(i + 1)
    return result
class Solution(object):

    def findDisappearedNumbers(self, nums):
        """
        :type nums: List[int]
        :rtype: List[int]
        """
        for i in range(len(nums)):
            x = abs(nums[i])
            if x - 1 < len(nums) and nums[x - 1] > 0:
                nums[x - 1] = -nums[x - 1]
        return [i + 1 for i in range(len(nums)) if nums[i] > 0]
def test_simple_case():
    solution_instance = Solution()
    assert findDisappearedNumbers([4, 3, 2, 7, 8, 2, 3, 1]) == solution_instance.findDisappearedNumbers([4, 3, 2, 7, 8, 2, 3, 1])
