class Solution:

    def countUnguarded(self, m: int, n: int, guards: List[List[int]], walls: List[List[int]]) -> int:
        mat = [['X' for _ in range(n)] for _ in range(m)]
        for row, col in guards:
            mat[row][col] = 'G'
        for row, col in walls:
            mat[row][col] = 'W'
        seen_guard = False
        ans = 0
        for i in range(m):
            seen_guard = False
            for j in range(n):
                if mat[i][j] == 'G':
                    seen_guard = True
                elif mat[i][j] == 'W':
                    seen_guard = False
                elif mat[i][j] == 'X':
                    if seen_guard:
                        mat[i][j] = 'O'
                    else:
                        ans += 1
        for i in range(m):
            seen_guard = False
            for j in range(n - 1, -1, -1):
                if mat[i][j] == 'O':
                    continue
                elif mat[i][j] == 'G':
                    seen_guard = True
                elif mat[i][j] == 'W':
                    seen_guard = False
                elif mat[i][j] == 'X':
                    if seen_guard:
                        mat[i][j] = 'O'
                        ans -= 1
        for j in range(n):
            seen_guard = False
            for i in range(m):
                if mat[i][j] == 'O':
                    continue
                elif mat[i][j] == 'G':
                    seen_guard = True
                elif mat[i][j] == 'W':
                    seen_guard = False
                elif mat[i][j] == 'X':
                    if seen_guard:
                        mat[i][j] = 'O'
                        ans -= 1
        for j in range(n):
            seen_guard = False
            for i in range(m - 1, -1, -1):
                if mat[i][j] == 'O':
                    continue
                elif mat[i][j] == 'G':
                    seen_guard = True
                elif mat[i][j] == 'W':
                    seen_guard = False
                elif mat[i][j] == 'X':
                    if seen_guard:
                        mat[i][j] = 'O'
                        ans -= 1
        return ans
