from typing import *
from collections import *
from math import *

def heapify(arr, n, i):
    largest = i
    l = 2 * i + 1
    r = 2 * i + 2
    if l < n and arr[i] < arr[l]:
        largest = l
    if r < n and arr[largest] < arr[r]:
        largest = r
    if largest != i:
        arr[i], arr[largest] = (arr[largest], arr[i])
        heapify(arr, n, largest)
def heapSort(arr):
    n = len(arr)
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)
    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = (arr[0], arr[i])
        heapify(arr, i, 0)
    return arr
def left(i):
    return 2 * i + 1
def right(i):
    return 2 * i + 2
def heapSize(A):
    return len(A) - 1
def MaxHeapify(A, i):
    l = left(i)
    r = right(i)
    if l <= heapSize(A) and A[l] > A[i]:
        largest = l
    else:
        largest = i
    if r <= heapSize(A) and A[r] > A[largest]:
        largest = r
    if largest != i:
        A[i], A[largest] = (A[largest], A[i])
        MaxHeapify(A, largest)
def BuildMaxHeap(A):
    for i in range(int(heapSize(A) / 2) - 1, -1, -1):
        MaxHeapify(A, i)
def HeapSort(A):
    BuildMaxHeap(A)
    B = list()
    heapSize1 = heapSize(A)
    for i in range(heapSize(A), 0, -1):
        A[0], A[i] = (A[i], A[0])
        B.append(A[heapSize1])
        A = A[:-1]
        heapSize1 = heapSize1 - 1
        MaxHeapify(A, 0)
def test_heap_sort_basic_case():
    arr1 = [3, 2, 1, 5, 4]
    assert heapSort(arr1[:]) == HeapSort(arr1[:])
def test_heap_sort_with_repeated_elements():
    arr2 = [5, 2, 4, 2, 3, 1]
    assert heapSort(arr2[:]) == HeapSort(arr2[:])
def test_heap_sort_with_negative_elements():
    arr3 = [5, -2, -4, 1, -3, 6]
    assert heapSort(arr3[:]) == HeapSort(arr3[:])

