from typing import *
from collections import *
from math import *

def productExceptSelf(nums):
    n = len(nums)
    answer = [1] * n
    for i in range(1, n):
        answer[i] = answer[i - 1] * nums[i - 1]
    suffix_prod = 1
    for i in range(n - 1, -1, -1):
        answer[i] *= suffix_prod
        suffix_prod *= nums[i]
    return answer
class Solution:

    def productExceptSelf(self, nums: List[int]) -> List[int]:
        ans = []
        prefix_prod = []
        prefix_prod.append(nums[0])
        for a in range(1, len(nums)):
            prefix_prod.append(prefix_prod[a - 1] * nums[a])
        suffix_prod = []
        suffix_prod.append(nums[len(nums) - 1])
        iterator = 0
        for b in range(len(nums) - 2, -1, -1):
            suffix_prod.append(suffix_prod[iterator] * nums[b])
            iterator += 1
        for i in range(len(nums)):
            if i == 0:
                prefix_product = 1
            else:
                prefix_product = prefix_prod[i - 1]
            diff = len(nums) - 1 - (i + 1)
            if i < len(nums) - 1:
                suffix_product = suffix_prod[diff]
            else:
                suffix_product = 1
            res = prefix_product * suffix_product
            ans.append(res)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert productExceptSelf([1, 2, 3, 4]) == solution_instance.productExceptSelf([1, 2, 3, 4])
def test_edge_case():
    solution_instance = Solution()
    assert productExceptSelf([-1, 1, 0, -3, 3]) == solution_instance.productExceptSelf([-1, 1, 0, -3, 3])
def test_difficult_case():
    solution_instance = Solution()
    assert productExceptSelf([-1, 2, -3, 4, -5]) == solution_instance.productExceptSelf([-1, 2, -3, 4, -5])

