def min_insertions_to_balance(s):
    """
    :type s: str
    :rtype: int
    """
    stack = []
    insertions = 0
    i = 0
    while i < len(s):
        if s[i] == '(':
            stack.append(s[i])
            i += 1
        else:
            if i + 1 < len(s) and s[i+1] == ')':
                if stack:
                    stack.pop()
                else:
                    insertions += 1
                i += 2
            else:
                if stack:
                    insertions += 1
                    stack.pop()
                else:
                    insertions += 2
                i += 1
    return insertions + len(stack) * 2

