class Solution:

    def minInsertions(self, s: str) -> int:
        stk = list()
        res = 0
        idx = 0
        while idx < len(s):
            c = s[idx]
            if c == '(':
                stk.append(c)
            else:
                if not stk:
                    res += 1
                    stk.append('(')
                if idx < len(s) - 1 and s[idx + 1] == ')':
                    idx += 1
                    stk.pop()
                else:
                    res += 1
                    stk.pop()
            idx += 1
        res += len(stk) * 2
        return res
