from typing import *
from collections import *
from math import *

def covered_by_range(ranges, left, right):
    for range in ranges:
        if range[0] <= left and range[1] >= right:
            return True
    return False
class Solution:

    def isCovered(self, ranges: List[List[int]], left: int, right: int) -> bool:
        ranges.sort(key=lambda x: x[0])
        inclusive_arr = []
        inclusive_arr.append(ranges[0])
        for i in range(1, len(ranges)):
            cur = ranges[i]
            cur_start = cur[0]
            last = inclusive_arr[-1]
            last_end = last[1]
            if cur_start <= last_end:
                if cur[1] > last_end:
                    inclusive_arr[-1][1] = cur[1]
                    continue
                else:
                    continue
            elif abs(cur_start - last_end) <= 1:
                inclusive_arr[-1][1] = cur[1]
                continue
            else:
                inclusive_arr.append(cur)
        for inc_arr in inclusive_arr:
            inc_start, inc_end = (inc_arr[0], inc_arr[1])
            if inc_start <= left <= inc_end and inc_start <= right <= inc_end:
                return True
        return False
def test_simple_case():
    solution_instance = Solution()
    assert covered_by_range([[1, 10]], 2, 7) == solution_instance.isCovered([[1, 10]], 2, 7)
def test_edge_case():
