class Solution:

    def subsetXORSum(self, nums: List[int]) -> int:
        ans = 0

        def helper(i, cur):
            nonlocal nums, ans
            if i == len(nums):
                if len(cur) == 0:
                    return
                elif len(cur) == 1:
                    ans += cur[0]
                    return
                else:
                    initial = cur[0]
                    for a in range(1, len(cur)):
                        initial = initial ^ cur[a]
                    ans += initial
                    return
            cur.append(nums[i])
            helper(i + 1, cur)
            cur.pop()
            helper(i + 1, cur)
        helper(0, [])
        return int(ans)
def test_simple_case():
    solution_instance = Solution()
    assert subsetXORSum([1, 2, 3]) == solution_instance.subsetXORSum([1, 2, 3])
