class Solution:

    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        canGo = defaultdict(list)
        red, blue = ({}, {})
        for i, j in redEdges:
            red[i, j] = True
            canGo[i].append(j)
        for i, j in blueEdges:
            blue[i, j] = True
            canGo[i].append(j)
        ans = [-1] * n
        ans[0] = 0
        for target in range(1, n):
            queue = [(0, 0, None)]
            visited = {(0, None): True}
            while queue:
                node, dis, color = queue.pop(0)
                if node == target:
                    ans[target] = dis
                    break
                for nodes in canGo[node]:
                    b, r = ((node, nodes) in blue, (node, nodes) in red)
                    if color == 1:
                        if r == False or (nodes, 0) in visited:
                            continue
                        visited[nodes, 0] = True
                        queue.append((nodes, dis + 1, 0))
                    elif color == 0:
                        if b == False or (nodes, 1) in visited:
                            continue
                        visited[nodes, 1] = True
                        queue.append((nodes, dis + 1, 1))
                    else:
                        if r == True and (nodes, 0) not in visited:
                            visited[nodes, 0] = True
                            queue.append((nodes, dis + 1, 0))
                        if b == True and (nodes, 1) not in visited:
                            visited[nodes, 1] = True
                            queue.append((nodes, dis + 1, 1))
        return ans
def test_simple_graph():
    solution_instance = Solution()
    assert shortestAlternatingPaths(3, [[0, 1], [1, 2]], []) == solution_instance.shortestAlternatingPaths(3, [[0, 1], [1, 2]], [])
def test_complex_graph():
    solution_instance = Solution()
    assert shortestAlternatingPaths(3, [[0, 1]], [[2, 1]]) == solution_instance.shortestAlternatingPaths(3, [[0, 1]], [[2, 1]])
def test_no_edges():
    solution_instance = Solution()
    assert shortestAlternatingPaths(3, [], []) == solution_instance.shortestAlternatingPaths(3, [], [])

