def rotate_box(box):
    n = len(box[0])
    m = len(box)
    new_box = [['.' for i in range(m)] for j in range(n)]
    for i in range(n):
        for j in range(m):
            if box[m-1-j][i] == '#':
                k = j
                while k >= 0 and box[m-1-k][i] == '.':
                    k -= 1
                if k >= 0 and box[m-1-k][i] != '#':
                    new_box[i][k+1] = '#'
                else:
                    new_box[i][0] = '#'
            elif box[m-1-j][i] == '*':
                new_box[i][j] = '*'
    return ["".join(row) for row in new_box]

