def rotate_box(box):
    n = len(box[0])
    m = len(box)
    new_box = [['.' for i in range(m)] for j in range(n)]
    for i in range(n):
        for j in range(m):
            if box[m - 1 - j][i] == '#':
                k = j
                while k >= 0 and box[m - 1 - k][i] == '.':
                    k -= 1
                if k >= 0 and box[m - 1 - k][i] != '#':
                    new_box[i][k + 1] = '#'
                else:
                    new_box[i][0] = '#'
            elif box[m - 1 - j][i] == '*':
                new_box[i][j] = '*'
    return [''.join(row) for row in new_box]
class Solution:

    def rotateTheBox(self, box: List[List[str]]) -> List[List[str]]:

        def rearrange(stones, arr):
            if len(arr) == stones:
                return arr
            if stones == 0:
                return arr
            empty = len(arr) - stones
            for i in range(empty):
                arr[i] = '.'
            for i in range(empty, len(arr)):
                arr[i] = '#'
            return arr

        def transpose(rows, cols, box):
            res = [['' for _ in range(rows)] for _ in range(cols)]
            for x in range(rows):
                for y in range(cols):
                    res[y][rows - x - 1] = box[x][y]
            return res
        rows, cols = (len(box), len(box[0]))
        r = 0
        while r < rows:
            c = 0
            while c < cols:
                stones = 0
                start = c
                while c < cols and box[r][c] != '*':
                    if box[r][c] == '#':
                        stones += 1
                    c += 1
                box[r][start:c] = rearrange(stones, box[r][start:c])
                c += 1
            r += 1
        return transpose(rows, cols, box)
def test_simple_case():
    instance = Solution()
    box1 = [['#', '*', '*', '.', '*', '.'], ['#', '#', '*', '*', '*', '.']]
