def longest_common_substring(str1, str2):
    m = len(str1)
    n = len(str2)

    # initialization of the table
    # table[i][j] contains the length of the longest common substring ending at i and j
    table = [[0] * (n + 1) for _ in range(m + 1)]
    max_length = 0  # to keep track of the maximum length encountered so far
    end_index = None  # to keep track of the ending index of the longest common substring

    # filling up the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                table[i][j] = table[i - 1][j - 1] + 1
                if table[i][j] > max_length:
                    max_length = table[i][j]
                    end_index = i
            else:
                table[i][j] = 0

    # extracting the longest common substring
    if end_index is not None:
        start_index = end_index - max_length
        return str1[start_index:end_index]
    else:
        return None

