class Solution:

    def minimumLength(self, s: str) -> int:
        """
        #Brute Force Solution -- O(N^2) &amp; O(N) ~2880ms
		#Using array ( Naive Approach )
        arr = list(s)
        while len(arr)>1:
            i = 0
            j = len(arr)-1
            if arr[i]!=arr[j]:
                break
            temp = arr[i]
            while len(arr)>0 and i<=j and arr[i]==temp:
                arr.pop(0) #Rearranging array takes O(N)
            j = len(arr)-1
            while len(arr)>0 and j>=i and arr[j]==temp:
                arr.pop()
                j-=1
        #print("".join(arr))
        return len(arr)
        """
        '\n        #10 times Faster than previous Solution ~216ms\n\t\t#Using Deque -- Level 1 Optimisation\n        #O(N) due to O(1) in popleft -- Time &amp; O(N) -- Space\n        arr = collections.deque()\n        for i in s:\n            arr.append(i)\n        while len(arr)>1:\n            i = 0\n            j = len(arr)-1\n            if arr[i]!=arr[j]:\n                break\n            temp = arr[i]\n            while len(arr)>0 and i<=j and arr[i]==temp:\n                arr.popleft() #O(1)\n            j = len(arr)-1\n            while len(arr)>0 and j>=i and arr[j]==temp:\n                arr.pop()\n                j-=1\n        return len(arr)\n        '
        if len(s) == 1:
            return 1
        i = 0
        j = len(s) - 1
        while i < j:
            if s[i] != s[j]:
                break
            temp = s[i]
            while i <= j and s[i] == temp:
                i += 1
            while j >= i and s[j] == temp:
                j -= 1
        return j - i + 1
