class Solution:

    def wordBreak(self, s: str, wordDict):
        output = []

        def backtracking(restString, candidate):
            if restString == '':
                output.append(candidate)
                return
            for i in range(len(restString) + 1):
                if restString[:i] in wordDict:
                    if candidate == '':
                        backtracking(restString[i:], restString[:i])
                    else:
                        backtracking(restString[i:], candidate + ' ' + restString[:i])
        backtracking(s, '')
        return output
def test_simple_case():
    solution_instance = Solution()
    assert wordBreak('applepenapple', set(['apple', 'pen'])) == sorted(solution_instance.wordBreak('applepenapple', ['apple', 'pen']))
