def is_happy_string(s):
    for i in range(len(s)-1):
        if s[i] == s[i+1]:
            return False
    return True

def generate_happy_strings(n):
    letters = ["a", "b", "c"]
    strings = []
    def backtrack(s):
        nonlocal strings
        if len(s) == n:
            if is_happy_string(s):
                strings.append(s)
            return
        for letter in letters:
            backtrack(s+letter)
    backtrack("")
    return sorted(strings)

def kth_happy_string(n, k):
    happy_strings = generate_happy_strings(n)
    if k > len(happy_strings):
        return ""
    else:
        return happy_strings[k-1]

