def reorder_string(s):
    sorted_str = ''.join(sorted(s))
    result = []
    i, j = 0, len(sorted_str) - 1
    last_appended_char = ""
    while i <= j:
        if (not last_appended_char or sorted_str[i] > last_appended_char) and sorted_str[i] not in result:
            result.append(sorted_str[i])
            last_appended_char = sorted_str[i]
            i += 1
        elif (not last_appended_char or sorted_str[j] < last_appended_char) and sorted_str[j] not in result:
            result.append(sorted_str[j])
            last_appended_char = sorted_str[j]
            j -= 1
        else:
            if sorted_str.count(sorted_str[i]) > sorted_str.count(sorted_str[j]):
                result.append(sorted_str[i])
                last_appended_char = sorted_str[i]
                i += 1
            else:
                result.append(sorted_str[j])
                last_appended_char = sorted_str[j]
                j -= 1
    return "".join(result)

