class Solution:

    def sortString(self, s: str) -> str:
        count = defaultdict(int)
        for c in s:
            count[c] += 1
        cnt = []
        for c in sorted(count.keys()):
            cnt.append([c, count[c]])
        n = len(cnt)
        s = sum(count.values())
        i = 0
        direc = 1
        res = []
        while s > 0:
            if direc == 1:
                if i < n - 1:
                    if cnt[i][1] > 0:
                        res.append(cnt[i][0])
                        cnt[i][1] -= 1
                        s -= 1
                        i += 1
                    else:
                        i += 1
                elif cnt[i][1] > 0:
                    res.append(cnt[i][0])
                    cnt[i][1] -= 1
                    s -= 1
                    direc = -1
                else:
                    direc = -1
            elif i > 0:
                if cnt[i][1] > 0:
                    res.append(cnt[i][0])
                    cnt[i][1] -= 1
                    s -= 1
                    i -= 1
                else:
                    i -= 1
            elif cnt[i][1] > 0:
                res.append(cnt[i][0])
                cnt[i][1] -= 1
                s -= 1
                direc = 1
            else:
                direc = 1
        return ''.join(res)
