class Solution:

    def maximumUniqueSubarray(self, nums: List[int]) -> int:
        L = 0
        hashmap = {}
        cur_sum = 0
        ans = 0
        for R in range(len(nums)):
            cur_sum += nums[R]
            if nums[R] in hashmap:
                hashmap[nums[R]] += 1
                while hashmap[nums[R]] > 1:
                    left_element = nums[L]
                    if left_element != nums[R]:
                        hashmap.pop(left_element)
                    else:
                        hashmap[nums[R]] -= 1
                    cur_sum -= left_element
                    L += 1
            else:
                hashmap[nums[R]] = 1
                ans = max(ans, cur_sum)
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert maxScore([1, 2, 3]) == solution_instance.maximumUniqueSubarray([1, 2, 3])
