from typing import *
from collections import *
from math import *

def longest_increasing_path(matrix):
    m, n = (len(matrix), len(matrix[0]))
    memo = [[0] * n for _ in range(m)]
    direction = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    res = 0

    def dfs(x, y):
        if memo[x][y]:
            return memo[x][y]
        memo[x][y] = 1
        for dx, dy in direction:
            nx, ny = ((x + dx) % m, (y + dy) % n)
            if matrix[nx][ny] > matrix[x][y]:
                memo[x][y] = max(memo[x][y], dfs(nx, ny) + 1)
        return memo[x][y]
    for i in range(m):
        for j in range(n):
            res = max(res, dfs(i, j))
    return res
class Solution:

    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        M, N = (len(matrix), len(matrix[0]))
        cellPathLengths = [[0] * N for _ in range(M)]

        def isValidCell(row: int, column: int) -> bool:
            return 0 <= row < M and 0 <= column < N

        def dfs(row: int, column: int) -> int:
            if cellPathLengths[row][column]:
                return cellPathLengths[row][column]
            cellValue = matrix[row][column]
            neighbors = ((row + 1, column), (row - 1, column), (row, column + 1), (row, column - 1))
            maxPathLength = 0
            for neighborRow, neighborColumn in neighbors:
                if not isValidCell(neighborRow, neighborColumn):
                    continue
                if not cellValue < matrix[neighborRow][neighborColumn]:
                    continue
                maxPathLength = max(maxPathLength, dfs(neighborRow, neighborColumn))
            cellPathLengths[row][column] = 1 + maxPathLength
            return cellPathLengths[row][column]
        maxPathLength = 0
        for row in range(M):
            for column in range(N):
                pathLength = dfs(row, column)
                maxPathLength = max(maxPathLength, pathLength)
        return maxPathLength
def test_simple_case():
    matrix = [[1, 2], [3, 4]]
    solution_instance = Solution()
    assert longest_increasing_path(matrix) == solution_instance.longestIncreasingPath(matrix)
