metadata.GPT Answer:
def longest_increasing_path(matrix):
    m, n = len(matrix), len(matrix[0])
    memo = [[0] * n for _ in range(m)]
    direction = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    res = 0

    def dfs(x, y):
        if memo[x][y]:
            return memo[x][y]
        memo[x][y] = 1
        for dx, dy in direction:
            nx, ny = (x + dx) % m, (y + dy) % n
            if matrix[nx][ny] > matrix[x][y]:
                memo[x][y] = max(memo[x][y], dfs(nx, ny) + 1)
        return memo[x][y]

    for i in range(m):
        for j in range(n):
            res = max(res, dfs(i, j))

    return res

