from typing import *
from collections import *
from math import *

def rearrangeSpaces(text):
    words = text.split()
    num_spaces = text.count(' ')
    if len(words) == 1:
        return words[0] + ' ' * num_spaces
    else:
        num_pairs = len(words) - 1
        space_between_pairs = num_spaces // num_pairs
        extra_spaces = num_spaces % num_pairs
        spaces = ' ' * space_between_pairs
        if extra_spaces > 0:
            spaces += ' '
            extra_spaces -= 1
        result = spaces.join(words)
        return result + ' ' * extra_spaces
class Solution:

    def reorderSpaces(self, text: str) -> str:
        space = 0
        for char in list(text):
            if char == ' ':
                space += 1
        words = text.split()
        num_words = len(words)
        spaces_per_word = space // (num_words - 1) if num_words > 1 else num_words
        output = []
        for idx in range(len(words) - 1):
            output.append(words[idx])
            for _ in range(spaces_per_word):
                output.append(' ')
                space -= 1
        if len(words) > 0:
            output.append(words[-1])
        while space > 0:
            output.append(' ')
            space -= 1
        return ''.join(output)
def test_simple_case():
    sol_instance = Solution()
    assert rearrangeSpaces('  this   is  a sentence ') == sol_instance.reorderSpaces('  this   is  a sentence ')
