    assert rearrangeSpaces(' practice  makes   perfect') == sol_instance.reorderSpaces(' practice  makes   perfect')
def test_difficult_case():
    sol_instance = Solution()
    assert rearrangeSpaces(' hello   world  ') == sol_instance.reorderSpaces(' hello   world  ')

