def find_gcd(num_list):
    # function to find gcd of a list of numbers
    # using Euclid's Algorithm
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a%b)

    res = num_list[0]
    for i in range(1, len(num_list)):
        res = gcd(res, num_list[i])
    return res

def count_gcd_subsequences(nums):
    gcd_set = set()
    n = len(nums)

    # generate all possible subsequences
    for i in range(n):
        for j in range(i, n):
            sub_seq = nums[i:j+1]
            if sub_seq:
                gcd_set.add(find_gcd(sub_seq))

    return len(gcd_set)

