class First_class:

    def isRobotBounded(self, instructions: str) -> bool:
        x, y = (0, 0)
        dx, dy = (0, 1)
        for i in instructions:
            if i == 'G':
                x, y = (x + dx, y + dy)
            elif i == 'L':
                dx, dy = (-dy, dx)
            elif i == 'R':
                dx, dy = (dy, -dx)
        return x == 0 and y == 0 or (dx != 0 or dy != 1)
class Solution:

    def isRobotBounded(self, instructions: str) -> bool:
        directions = {0: {'G': 0, 'L': 3, 'R': 1}, 1: {'G': 1, 'L': 0, 'R': 2}, 2: {'G': 2, 'L': 1, 'R': 3}, 3: {'G': 3, 'L': 2, 'R': 0}}
        start = (0, 0)

        def moveRobot(curr, direction):
            for instruction in instructions:
                if instruction == 'G':
                    if direction == 0:
                        curr = (curr[0], curr[1] + 1)
                    elif direction == 1:
                        curr = (curr[0] + 1, curr[1])
                    elif direction == 2:
                        curr = (curr[0], curr[1] - 1)
                    elif direction == 3:
                        curr = (curr[0] - 1, curr[1])
                    else:
                        pass
                direction = directions[direction][instruction]
            return (curr, direction)
        curr, direction = moveRobot(start, 0)
        if curr == start:
            return True
        if direction != 0:
            return True
        return False
def test_simple_case():
    fc_instance = First_class()
    sol_instance = Solution()
    assert fc_instance.isRobotBounded('GGLLGG') == sol_instance.isRobotBounded('GGLLGG')
