class Solution:

    def longestSubarray(self, nums: List[int]) -> int:
        ans = 0
        vmax = -1
        cmax = 0
        for i in range(len(nums)):
            if vmax == -1 or nums[vmax] < nums[i]:
                vmax = i
                cmax = 1
                ans = 1
            elif nums[vmax] == nums[i]:
                cmax = cmax + 1
                ans = max(ans, cmax)
            elif nums[vmax] > nums[i]:
                cmax = 0
        return ans
def test_simple_case():
