def findRestaurant(list1, list2):
    common = set(list1) & set(list2)
    idx_sum = {}
    for c in common:
        idx1 = list1.index(c)
        idx2 = list2.index(c)
        idx_sum[c] = idx1 + idx2
    min_sum = min(idx_sum.values())
    return [k for k, v in idx_sum.items() if v == min_sum]

