from typing import *
from collections import *
from math import *

def normalize_time(time):
    time_str = str(time)
    while len(time_str) < 4:
        time_str = '0' + time_str
    minutes = int(time_str[:2])
    seconds = int(time_str[2:])
    return (minutes, seconds)
def calculate_cost(current_time, target_time, start_at, push_cost, move_cost):
    current_minutes, current_seconds = normalize_time(current_time)
    target_minutes, target_seconds = normalize_time(target_time)
    cost = abs(start_at - int(str(target_time)[0]))
    cost += abs(current_minutes - target_minutes) * move_cost
    cost += abs(current_seconds - target_seconds) * move_cost
    cost += push_cost
    return cost
def minimum_cost(startAt, moveCost, pushCost, targetSeconds):
    min_cost = float('inf')
    for seconds in range(1, 5999):
        temp_time = startAt * 10000 + seconds
        cost = calculate_cost(0, temp_time, startAt, pushCost, moveCost)
        if seconds == targetSeconds:
            min_cost = min(min_cost, cost)
        else:
            remaining_seconds = abs(targetSeconds - seconds)
            cost += remaining_seconds * pushCost
            min_cost = min(min_cost, cost)
    return min_cost
class Solution:

    def minCostSetTime(self, startAt: int, moveCost: int, pushCost: int, targetSeconds: int) -> int:
        mins1, secs1 = (0, targetSeconds) if targetSeconds < 100 else (targetSeconds // 60, targetSeconds % 60)
        if mins1 > 99:
            mins1 -= 1
            secs1 += 60
        l = [(mins1, secs1)]
        if mins1 > 0 and secs1 < 40:
            mins2 = mins1 - 1
            secs2 = secs1 + 60
            l.append((mins2, secs2))
        if mins1 < 99 and secs1 >= 60:
            mins2 = mins1 + 1
            secs2 = secs1 - 60
            l.append((mins2, secs2))
        ret = inf
        for mins, secs in l:
            mins = str(mins) if mins > 0 else ''
            if secs >= 10:
                secs = str(secs)
            elif mins:
                secs = '0' + str(secs)
            else:
                secs = str(secs)
            t = mins + secs
            total = 0
            for i in range(len(t)):
                if i == 0 and t[i] == str(startAt):
                    total += pushCost
                elif i > 0 and t[i] == t[i - 1]:
                    total += pushCost
                else:
                    total += moveCost + pushCost
            ret = min(ret, total)
        return ret
def test_basic_case():
    assert minimum_cost(1, 2, 100, 600) == Solution().minCostSetTime(1, 2, 100, 600)
def test_boundary_case():
    assert minimum_cost(1, 1, 1, 60) == Solution().minCostSetTime(1, 1, 1, 60)
def test_complicated_case():
    assert minimum_cost(0, 15, 20, 3600) == Solution().minCostSetTime(0, 15, 20, 3600)

