    return max_palindrome_length
class Solution:

    def longestPalindrome(self, word1: str, word2: str) -> int:
        s1 = word1 + word2
        n = len(s1)
        dp = [[0] * n for i in range(n)]
        ans = 0
        for i in range(n - 1, -1, -1):
            dp[i][i] = 1
            for j in range(i + 1, n):
                if s1[i] == s1[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                    if i < len(word1) and j >= len(word1):
                        ans = max(ans, dp[i][j])
                else:
                    dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])
        return ans
def test_simple_case():
    sol_instance = Solution()
    assert longest_palindrome('aa', 'bb') == sol_instance.longestPalindrome('aa', 'bb')
def test_edge_case():
    sol_instance = Solution()
    assert longest_palindrome('abc', 'cba') == sol_instance.longestPalindrome('abc', 'cba')
def test_difficult_case():
    sol_instance = Solution()
    assert longest_palindrome('abcd', 'dcba') == sol_instance.longestPalindrome('abcd', 'dcba')

