from math import *

def find_repeated_sequences(dna_sequence):
    substrings = []
    for i in range(len(dna_sequence) - 9):
        substring = dna_sequence[i:i + 10]
        substrings.append(substring)
    repeated_substrings = []
    for substring in substrings:
        if substrings.count(substring) > 1 and substring not in repeated_substrings:
            repeated_substrings.append(substring)
    return repeated_substrings
class Solution:

    def findRepeatedDnaSequences(self, s: str) -> List[str]:
        nums = [-1] * len(s)
        for i in range(len(s)):
            if s[i] == 'A':
                nums[i] = 0
            elif s[i] == 'G':
                nums[i] = 1
            elif s[i] == 'C':
                nums[i] = 2
            elif s[i] == 'T':
                nums[i] = 3
        seen = set()
        res = set()
        digitPos = 10
        digitBase = 4
        hiDigit = pow(digitBase, digitPos - 1)
        left, right = (0, 0)
        windowHash = 0
        while right < len(s):
            windowHash = windowHash * digitBase + nums[right]
            right += 1
            if right - left >= digitPos:
                if windowHash in seen:
                    res.add(s[left:right])
                else:
                    seen.add(windowHash)
                windowHash = windowHash - nums[left] * hiDigit
                left += 1
        return res
def test_simple_case():
    sol_instance = Solution()
    assert find_repeated_sequences('AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT') == sorted(list(sol_instance.findRepeatedDnaSequences('AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT')))
def test_medium_case():
    sol_instance = Solution()
    assert find_repeated_sequences('AAAAAAAAAA') == sorted(list(sol_instance.findRepeatedDnaSequences('AAAAAAAAAA')))
def test_difficult_case():
