from typing import *
from collections import *
from math import *

def lengthLongestPath(input: str) -> int:
    stack = [0]
    max_len = 0
    for s in input.split('\n'):
        depth = s.count('\t')
        while depth < len(stack) - 1:
            stack.pop()
        length = stack[-1] + len(s) - depth + 1
        if '.' in s:
            max_len = max(max_len, length - 1)
        else:
            stack.append(length)
    return max_len
class Solution:

    def lengthLongestPath(self, input: str) -> int:
        longest = 0
        path = []
        i = 0
        while i < len(input):
            length = 0
            depth = 0
            is_file = False
            in_path_component = False
            whitespaces = 0
            while i < len(input) and input[i] != '\n':
                if input[i] == '\t':
                    depth += 1
                elif input[i] == ' ':
                    if in_path_component:
                        length += 1
                    else:
                        whitespaces += 1
                        if whitespaces == 4:
                            depth += 1
                            whitespaces = 0
                elif input[i] == '.':
                    in_path_component = True
                    is_file = True
                    length += 1
                elif input[i] != '\n' and input[i] != '\t':
                    in_path_component = True
                    length += 1
                i += 1
            while depth < len(path):
                path.pop()
            if is_file:
                length += (depth - len(path)) * 4
                length += whitespaces
                longest = max(longest, sum(path) + length)
            else:
                path.append(length + 1)
            i += 1
        return longest
def test_simple_case():
    solution_instance = Solution()
    input = 'dir\n\tsubdir1\n\tsubdir2\n\t\tfile.ext'
    assert lengthLongestPath(input) == solution_instance.lengthLongestPath(input)
def test_edge_case():
    solution_instance = Solution()
    input = 'dir\n\tsubdir1\n\t\tfile1.ext\n\t\tsubsubdir1\n\tsubdir2\n\t\tsubsubdir2\n\t\t\tfile2.ext'
    assert lengthLongestPath(input) == solution_instance.lengthLongestPath(input)
def test_difficult_case():
    solution_instance = Solution()
    input = 'a'
    assert lengthLongestPath(input) == solution_instance.lengthLongestPath(input)

