def sort_matrix(matrix):
    for i in range(len(matrix)):
        matrix[i].sort()

    flattened_matrix = [val for sublist in matrix for val in sublist]
    flattened_matrix.sort()

    output_matrix = []
    index = 0

    for row in matrix:
        output_row = []
        for val in row:
            output_row.append(flattened_matrix[index])
            index += 1

        output_matrix.append(output_row)

    return output_matrix

def count_index_value_equality(matrix):
    sorted_matrix = sort_matrix(matrix)
    count = 0

    for i in range(len(sorted_matrix)):
        for j in range(len(sorted_matrix[0])):
            if i == sorted_matrix[i][j]:
                count += 1

    return count

