def maxSubarraySumCircular(nums):
    max_ending_here = max_so_far = nums[0]
    min_ending_here = min_so_far = nums[0]
    total_sum = nums[0]
    for i in range(1, len(nums)):
        max_ending_here = max(nums[i], max_ending_here + nums[i])
        max_so_far = max(max_so_far, max_ending_here)
        min_ending_here = min(nums[i], min_ending_here + nums[i])
        min_so_far = min(min_so_far, min_ending_here)
        total_sum += nums[i]
    if max_so_far < 0:
        return max_so_far
    return max(max_so_far, total_sum - min_so_far)
class Solution:

    def maxSubarraySumCircular(self, A: List[int]) -> int:
        array_sum = 0
        local_min_sum, global_min_sum = (0, float('inf'))
        local_max_sum, global_max_sum = (0, float('-inf'))
        for number in A:
            local_min_sum = min(local_min_sum + number, number)
            global_min_sum = min(global_min_sum, local_min_sum)
            local_max_sum = max(local_max_sum + number, number)
            global_max_sum = max(global_max_sum, local_max_sum)
            array_sum += number
        if global_max_sum > 0:
            return max(array_sum - global_min_sum, global_max_sum)
        else:
            return global_max_sum
def test_simple_case():
    sol_instance = Solution()
    assert maxSubarraySumCircular([1, -2, 3, -2]) == sol_instance.maxSubarraySumCircular([1, -2, 3, -2])
