from typing import *
from collections import *
from math import *

def smallestDivisor(nums: List[int], threshold: int) -> int:

    def division_sum(divisor: int) -> int:
        return sum([(num - 1) // divisor + 1 for num in nums])
    left, right = (1, max(nums))
    while left < right:
        mid = (left + right) // 2
        if division_sum(mid) > threshold:
            left = mid + 1
        else:
            right = mid
    return left
class Solution:

    def smallestDivisor(self, nums: List[int], threshold: int) -> int:

        def helper(divisor):
            nonlocal nums
            accumulator = 0
            for e in nums:
                divided = e / divisor
                if divided.is_integer():
                    accumulator += int(divided)
                    continue
                else:
                    divided = int(divided)
                    divided += 1
                    accumulator += divided
            return accumulator
        L, H = (1, max(nums))
        ans = None
        while L <= H:
            cur = (L + H) // 2
            total_sum = helper(cur)
            if total_sum <= threshold:
                ans = cur
                H = cur - 1
                continue
            else:
                L = cur + 1
                continue
        return ans
def test_simple_case():
    solution_instance = Solution()
    assert smallestDivisor([44, 22, 33, 11, 1], 10) == solution_instance.smallestDivisor([44, 22, 33, 11, 1], 10)
def test_edge_case():
    solution_instance = Solution()
    assert smallestDivisor([19], 5) == solution_instance.smallestDivisor([19], 5)
def test_difficult_case():
    solution_instance = Solution()
    assert smallestDivisor([2147483647], 2) == solution_instance.smallestDivisor([2147483647], 2)

