from typing import *
from collections import *
from math import *

def is_sum_of_distinct_powers_three(n):
    powers_three = []
    i = 0
    while 3 ** i <= n:
        powers_three.append(3 ** i)
        i += 1
    return can_make_sum(n, powers_three)
def can_make_sum(n, powers):
    if n == 0:
        return True
    if len(powers) == 0:
        return False
    return can_make_sum(n, powers[1:]) or can_make_sum(n - powers[0], powers[1:])
class Solution:

    def checkPowersOfThree(self, n: int) -> bool:
        num = 1
        num_list = []
        while num <= n:
            num_list.append(num)
            num = num * 3
        powers = num_list
        memo = {}

        def run(amt, arr, n):
            key = (amt, n)
            if key in memo:
                return memo[key]
            if n < 0 or amt < 0:
                return False
            if amt == 0:
                return True
            memo[key] = run(amt - arr[n - 1], arr, n - 1) or run(amt, arr, n - 1)
            return memo[key]
        return run(n, powers, len(powers))
def test_simple_case():
    solution_instance = Solution()
    assert is_sum_of_distinct_powers_three(10) == solution_instance.checkPowersOfThree(10)
def test_edge_case():
    solution_instance = Solution()
    assert is_sum_of_distinct_powers_three(27) == solution_instance.checkPowersOfThree(27)
def test_difficult_case():
    solution_instance = Solution()
    assert is_sum_of_distinct_powers_three(13) == solution_instance.checkPowersOfThree(13)

