class Solution:

    def maxSatisfaction(self, sat):
        sat = sorted(sat)
        arr = [0]
        for i in range(len(sat)):
            time = 1
            arr2 = 0
            for j in range(i, len(sat)):
                arr2 += time * sat[j]
                time += 1
            arr.append(arr2)
            arr2 = 0
            time = 1
        return max(arr)
def test_simple_case():
