from typing import *
from collections import *
from math import *

class First_class:

    def isBoomerang(self, points: List[List[int]]) -> bool:
        return (points[2][1] - points[0][1]) * (points[1][0] - points[0][0]) != (points[1][1] - points[0][1]) * (points[2][0] - points[0][0])
class Solution:

    def isBoomerang(self, points: List[List[int]]) -> bool:
        pointer = []
        for c1, c0 in zip(points[1], points[0]):
            pointer.append(c1 - c0)
        visited = set([tuple(points[0]), tuple(points[1])])
        if len(visited) < 2:
            return False
        boomerang = False
        for point in points[2:]:
            factor = None
            if tuple(point) in visited:
                return False
            visited.add(tuple(point))
            if boomerang:
                continue
            for p, dire, start in zip(point, pointer, points[0]):
                if dire == 0:
                    if p != start:
                        boomerang = True
                        break
                elif factor is not None and factor != (p - start) / dire:
                    boomerang = True
                    break
                else:
                    factor = (p - start) / dire
        return boomerang
def test_simple_case():
    instance1 = First_class()
    instance2 = Solution()
    points = [[1, 2], [2, 3], [4, 5]]
    assert instance1.isBoomerang(points) == instance2.isBoomerang(points)
def test_edge_case():
    instance1 = First_class()
    instance2 = Solution()
    points = [[0, 0], [1, 1], [1, 2]]
    assert instance1.isBoomerang(points) == instance2.isBoomerang(points)
def test_difficult_case():
    instance1 = First_class()
    instance2 = Solution()
    points = [[1, 1], [2, 2], [3, 3]]
    assert instance1.isBoomerang(points) == instance2.isBoomerang(points)

