def max_depth(vps):
    depth = 0
    max_depth = 0
    for char in vps:
        if char == "(":
            depth += 1
            max_depth = max(max_depth, depth)
        elif char == ")":
            depth -= 1
    return max_depth

def split_vps(seq):
    n = len(seq)
    best_depth = -1
    for i in range(n):
        for j in range(i+1, n+1):
            a = seq[:i] + seq[j:]
            b = seq[i:j]
            depth = max(max_depth(a), max_depth(b))
            if depth > best_depth:
                best_depth = depth
                best_a = a
                best_b = b
    answer = [0] * n
    for i in range(n):
        if seq[i] in best_a:
            answer[i] = 0
        else:
            answer[i] = 1
    return answer

