class Solution:

    def maxDepthAfterSplit(self, seq: str) -> List[int]:
        m, c, n = (0, 0, len(seq))
        for i in range(n):
            if seq[i] == '(':
                c += 1
                m = max(c, m)
            elif seq[i] == ')':
                c -= 1
        a = []
        m //= 2
        for i in range(n):
            if seq[i] == '(':
                c += 1
                if c <= m:
                    a.append(0)
                else:
                    a.append(1)
            else:
                if c <= m:
                    a.append(0)
                else:
                    a.append(1)
                c -= 1
        return a
def test_simple_case():
    solution_instance = Solution()
    assert split_vps('()') == solution_instance.maxDepthAfterSplit('()')
