class Solution:

    def addDigits(self, num: int) -> int:
        num = [int(i) for i in str(num)]
        if len(num) == 1:
            return num[0]
        while len(num) != 1:
            sum = 0
            for i in range(len(num)):
                sum += num[i]
            num = sum
            num = [int(i) for i in str(num)]
        return num[0]
