from typing import *
from collections import *
from math import *

def smallerNumbersThanCurrent(nums):
    return [sum((i < j for j in nums)) for i in nums]
class Solution:

    def countElements(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0
        for i in range(n):
            currentMinIndex = i
            for j in range(i + 1, n):
                if nums[currentMinIndex] > nums[j]:
                    currentMinIndex = j
            x = nums[currentMinIndex]
            nums[currentMinIndex] = nums[i]
            nums[i] = x
        if nums[0] == nums[-1]:
            return 0
        l = 0
        while l < n - 1:
            if nums[l] != nums[l + 1]:
                break
            l += 1
        r = n - 1
        while r > 0:
            if nums[r] != nums[r - 1]:
                break
            r -= 1
        return r - (l + 1)
def test_simple_case():
    solution_instance = Solution()
    nums = [5, 4, 3, 2, 1]
    assert smallerNumbersThanCurrent(nums) == solution_instance.countElements(nums)
def test_edge_case():
    solution_instance = Solution()
    nums = [1, 2, 2, 3, 3, 3, 4, 4, 4, 4]
    assert smallerNumbersThanCurrent(nums) == solution_instance.countElements(nums)
def test_difficult_case():
    solution_instance = Solution()
    nums = [-1, 1, -6, 4, -7, 10]
    assert smallerNumbersThanCurrent(nums) == solution_instance.countElements(nums)

