def reverse_num(num):
    rev_num = int(str(num)[::-1])
    if rev_num >= 0:
        return True
    else:
        return False
class Solution:

    def sumOfNumberAndReverse(self, num: int) -> bool:
        if num <= 18:
            if num % 2 == 0:
                return True
            if num % 11 == 0:
                return True
            return False
        elif num <= 198:
            if num % 11 == 0:
                return True
            for b in range(10):
                newNum = num - 20 * b
                if newNum > 0 and newNum % 101 == 0 and (newNum // 101 != 19):
                    return True
            return False
        elif num <= 1998:
            for b in range(10):
                newNum = num - 20 * b
                if newNum > 0 and newNum % 101 == 0 and (newNum // 101 != 19):
                    return True
            for bc in range(19):
                newNum = num - 110 * bc
                if newNum > 0 and newNum % 1001 == 0 and (newNum // 1001 != 19):
                    return True
            return False
        elif num <= 19998:
            for c in range(10):
                for bd in range(19):
                    newNum = num - 200 * c - 1010 * bd
                    if newNum > 0 and newNum % 10001 == 0 and (newNum // 10001 != 19):
                        return True
            for bc in range(19):
                newNum = num - 110 * bc
                if newNum > 0 and newNum % 1001 == 0 and (newNum // 1001 != 19):
                    return True
            return False
        elif num <= 199998:
            for c in range(10):
                for bd in range(19):
                    newNum = num - 200 * c - 1010 * bd
                    if newNum > 0 and newNum % 10001 == 0 and (newNum // 10001 != 19):
                        return True
            for cd in range(19):
                for be in range(19):
                    newNum = num - 100100 * cd - 100010 * be
                    if newNum > 0 and newNum % 100001 == 0 and (newNum // 100001 != 19):
                        return True
            return False
def test_simple_case():
    solution_instance = Solution()
