def minDifficulty(jobDifficulty: List[int], d: int) -> int:
    n = len(jobDifficulty)
    if n < d:
        return -1
    dp = [[float('inf')] * n for _ in range(d + 1)]
    dp[1][0] = jobDifficulty[0]
    for j in range(1, n):
        dp[1][j] = max(dp[1][j - 1], jobDifficulty[j])
    for i in range(2, d + 1):
        for j in range(i - 1, n):
            curr_max = jobDifficulty[j]
            for k in range(j, i - 2, -1):
                curr_max = max(curr_max, jobDifficulty[k])
                dp[i][j] = min(dp[i][j], dp[i - 1][k - 1] + curr_max)
    return dp[d][n - 1]
class Solution:

    def minDifficulty(self, diff: List[int], d: int) -> int:
        n = len(diff)
        if n < d:
            return -1
        today = [None] * n
        yesterday = [diff[0]] + [None] * (n - 1)
        for i in range(1, n):
            yesterday[i] = max(yesterday[i - 1], diff[i])
        for day in range(1, d):
            stack = []
            for i in range(day, n):
                today[i] = yesterday[i - 1] + diff[i]
                while stack:
                    if diff[stack[-1]] < diff[i]:
                        j = stack.pop()
                        today[i] = min(today[i], today[j] - diff[j] + diff[i])
                    else:
                        if today[i] < today[stack[-1]]:
                            stack.append(i)
                        else:
                            today[i] = today[stack[-1]]
                        break
                else:
                    stack.append(i)
            yesterday = today.copy()
        return yesterday[-1]
def test_simple_case():
    solution_instance = Solution()
    assert minDifficulty([6, 5, 4, 3, 2, 1], 2) == solution_instance.minDifficulty([6, 5, 4, 3, 2, 1], 2)
