class Solution:

    def calculateTax(self, brackets: List[List[int]], income: int) -> float:
        taxes = 0
        prev = 0
        for upper, percent in brackets:
            dollars = upper - prev
            if dollars < income:
                taxes += dollars * (percent / 100)
                income -= dollars
            else:
                taxes += income * (percent / 100)
                break
            prev = upper
        return taxes
def test_simple_case():
    solution_instance = Solution()
    assert calculate_tax([[10, 20], [30, 50]], 40) == solution_instance.calculateTax([[10, 20], [30, 50]], 40)
