def minUniqueSub(s):
    count = {}
    for c in s:
        count[c] = count.get(c, 0) + 1

    partitions = []
    current_partition = set()

    for c in s:
        if count[c] == 1:
            current_partition.add(c)
            partitions.append(current_partition)
            current_partition = set()
        else:
            current_partition.add(c)
            count[c] -= 1
    if len(current_partition) > 0:
        partitions.append(current_partition)

    return len(partitions)

