class Solution(object):

    def partitionString(self, s):
        hashT = {}
        count = 0
        for i, ch in enumerate(s):
            if i == 0:
                hashT[count] = [ch]
            elif ch not in hashT[count]:
                hashT[count].append(ch)
            else:
                count += 1
                hashT[count] = [ch]
        return len(hashT)
