class Solution:

    def minimumEffort(self, tasks: List[List[int]]) -> int:
        rem_energy = min_energy = sum((task[0] for task in tasks))
        tasks = sorted(tasks, key=lambda x: x[0] - x[1])
        for task in tasks:
            if task[1] > rem_energy:
                min_energy += task[1] - rem_energy
                rem_energy += task[1] - rem_energy
            rem_energy -= task[0]
        return min_energy
def test_simple_case():
    s = Solution()
    assert minimum_energy([[10, 12], [15, 16], [20, 25]]) == s.minimumEffort([[10, 12], [15, 16], [20, 25]])
