from typing import *
from collections import *
from math import *

def isPalindrome(n):
    return str(n) == str(n)[::-1]
def nextPalindrome(n):
    while not isPalindrome(n):
        n += 1
    return n
def findPalindrome(queries, intLength):
    answer = []
    for i in range(len(queries)):
        count = 0
        current = 1
        while count < queries[i]:
            current = nextPalindrome(current + 1)
            if len(str(current)) == intLength:
                count += 1
        answer.append(current)
    return answer
class Solution:

    def kthPalindrome(self, queries: List[int], intLength: int) -> List[int]:
        result = []
        for i in queries:
            result.append(self.generatePalindrome(intLength, i))
        return result

    def generatePalindrome(self, length, num):
        index = num - 1
        if length % 2 == 0:
            cur = int('1' + '0' * (length // 2 - 1))
            maxLength = len(str(cur))
            cur += index
            if len(str(cur)) > maxLength:
                return -1
            else:
                cur = str(cur)
                cur = cur + cur[::-1]
                cur = int(cur)
                return cur
        else:
            cur = int('1' + '0' * (length // 2))
            maxLength = len(str(cur))
            cur += index
            if len(str(cur)) > maxLength:
                return -1
            else:
                cur = str(cur)
                temp = str(cur)[:-1]
                cur = cur + temp[::-1]
                cur = int(cur)
                return cur
def test_simple_case():
    sol_instance = Solution()
    assert findPalindrome([1, 2, 3], 3) == sol_instance.kthPalindrome([1, 2, 3], 3)
def test_edge_case():
    sol_instance = Solution()
    assert findPalindrome([2, 4, 6], 4) == sol_instance.kthPalindrome([2, 4, 6], 4)
def test_difficult_case():
    sol_instance = Solution()
    assert findPalindrome([1, 1, 1, 1], 5) == sol_instance.kthPalindrome([1, 1, 1, 1], 5)

