    nums = [1, 2, 3, 4, 4]
    assert contains_duplicates(nums) == test_duplicate(nums)
def test_difficult_case():
    nums = [9, 9, 9, 9, 9]
    assert contains_duplicates(nums) == test_duplicate(nums)

from typing import *
from collections import *
from math import *

def count_paths(rows, cols, holes):
    dp = [[0 for _ in range(cols + 1)] for _ in range(rows + 1)]
    dp[1][1] = 1
    for hole in holes:
        dp[hole[0]][hole[1]] = None
    for row in range(1, rows + 1):
        for col in range(1, cols + 1):
            if dp[row][col] is None:
                continue
            above = dp[row - 1][col] if dp[row - 1][col] is not None else 0
            left = dp[row][col - 1] if dp[row][col - 1] is not None else 0
            dp[row][col] += above + left
    return dp[-1][-1]
def count_paths(m, n, holes):
    """Return number of paths from (0, 0) to (m, n) in an m x n grid.

    holes is a list of tuples (x, y) where each tuple is a coordinate which is
    blocked for a path.
    """
    paths = [[-1] * (m + 1) for _ in range(n + 1)]
    if (0, 0) in holes:
        paths[0][0] = 0
    else:
        paths[0][0] = 1
    for x in range(1, n + 1):
        if (x, 0) in holes:
            paths[x][0] = 0
        else:
            paths[x][0] = paths[x - 1][0]
    for y in range(1, m + 1):
        if (0, y) in holes:
            paths[0][y] = 0
        else:
            paths[0][y] = paths[0][y - 1]
    for x in range(1, n + 1):
        for y in range(1, m + 1):
            if (x, y) in holes:
                paths[x][y] = 0
            else:
                paths[x][y] = paths[x - 1][y] + paths[x][y - 1]
    return paths[n][m]
def test_simple_case():
    holes = [(1, 1)]
    assert count_paths(3, 4, holes) == count_paths(3, 4, holes)
def test_with_holes_case():
    holes = [(1, 1), (2, 2)]
    assert count_paths(4, 4, holes) == count_paths(4, 4, holes)
def test_difficult_case():
    holes = [(1, 1), (2, 2), (3, 3)]
    assert count_paths(5, 5, holes) == count_paths(5, 5, holes)

from typing import *
from collections import *
from math import *

def remove_left_right(n, lst):
    return lst[n:-n]
def drop_left_right(a, n=1):
    return (a[n:], a[:-n])
def test_simple_case():
    result1 = remove_left_right(1, [1, 2, 3, 4, 5])
    result2 = list(drop_left_right([1, 2, 3, 4, 5], 1)[0])
    assert result1 == result2
def test_edge_case():
    result1 = remove_left_right(2, [1, 2, 3, 4, 5, 6])
    result2 = list(drop_left_right([1, 2, 3, 4, 5, 6], 2)[0])
    assert result1 == result2
def test_difficult_case():
    result1 = remove_left_right(3, [1, 2, 3, 4, 5, 6, 7])
    result2 = list(drop_left_right([1, 2, 3, 4, 5, 6, 7], 3)[0])
    assert result1 == result2

