from typing import *
from collections import *
from math import *

def check_sum_diff_equal_5(a, b):
    if a + b == 5 or abs(a - b) == 5:
        return True
    else:
        return False
def test_number5(x, y):
    if x == y or abs(x - y) == 5 or x + y == 5:
        return True
    else:
        return False
def test_simple_case():
    assert check_sum_diff_equal_5(2, 3) == test_number5(2, 3)
def test_difficult_case():
    assert check_sum_diff_equal_5(10, 5) == test_number5(10, 5)
def test_edge_case():
    assert check_sum_diff_equal_5(0, 5) == test_number5(0, 5)

